docstring:
Look for prey adjacent to the current location.
Only the first live prey is eaten.
@return Where food was found, or null if it wasn't.

function:
protected Location findFood(ArrayList<String> preyList)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object food = field.getObjectAt(where);
            if(food!= null) {
                if(preyList.contains(food.getClass().getName())) {
                    Organism prey = (Organism) food;
                    if(prey.isAlive()) { 
                        prey.setDead();
                        int increment = prey.getFoodValue() + this.getFoodLevel();
                        this.setFoodLevel(increment);
                        int newWaterLevel = getWaterLevel() + 5;
                        this.setWaterLevel(newWaterLevel);
                        return where;  
                    }
                }
            }
        }
        return null;
    }

private void stepAct(){
        if(showGrass && currentWeather instanceof Rain){     //If is rainning and there are grasses in the simulation
            List<Location> locations = field.getAllFreeLocations(0);
            for(Location l :locations){
                if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                    Plant grass = new Grass(true, field, l);
                    actors.add(grass);
                }
            }
        }
        if(timeCount.getIsDay()){      //If is day and depending on the kind of actor, it will perform different kind of actions.
            List<Actor> newActors = new ArrayList<>();
            view.setEmptyColor(Color.white);
            for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ){
                Actor actor = it.next();
                if(actor instanceof Animal){
                    Animal a = (Animal) actor;
                    a.act(newActors);
                }
                if(actor instanceof Plant){
                    if(currentWeather instanceof Rain){
                        Plant p = (Plant) actor;
                        p.act(newActors);
                    }
                }
                if (!actor.isAlive()) {
                    it.remove();
                }
            }
            actors.addAll(newActors);
        }
    }

