public List<Location> getPlantsFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getPlantsAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

