@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field, int hour, String month, String weather, String season)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        timeLabel.setText(TIME_PREFIX + hour +":00" + "  Month: " + month);
        weatherLabel.setText(WEATHER_PREFIX + weather + "  Season:" + season);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    // Increment Animal counter if object is not a Plant
                    if (!(animal instanceof Plant)) {
                        stats.incrementCount(animal.getClass());
                    }
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public void increaseAge(){
        age=age+1;
        //If the age exceeds the maxAge, the actor dies.
        if(age > maxAge) {
            setDead();
        }
    }

private void generateCounts(Field field) {
        reset();
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getLandAt(row, col).getPlant();
                if (animal != null) {
                    incrementCount(animal.getClass());
                }
            }
        }
        countsValid = true;
    }

private void grow(List<Plant> newPlants){
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Plant young = new Plant(false, field, loc);
            newPlants.add(young);
        }
    }

private void compete(Lion lion)
    {
        if(lion.getFoodLevel() < getFoodLevel()){
            //if the acting lion wins the encountered lion is set to dead
            lion.setDead();
            return;
        }
        // Otherwise the acting lion dies
        setDead();
    }

