docstring:
This is what the fox does most of the time: it hunts for
rabbits. In the process, it might breed, die of hunger,
or die of old age.

@param newFoxes  A list to return newly born foxes.
@param isDay     Whether it is currently day or night.
@param isRaining Whether it is raining.

function:
public void act(List<Animal> newFoxes, boolean isDay, boolean isRaining) {
        incrementAge();
        incrementHunger();

        if (isAlive())
            spreadInfection();

        if (!isDay) // foxes can only act during the night, they sleep during the day.
            if (isAlive()) {
                giveBirth(newFoxes);
                // Move towards a source of food if found.
                Location newLocation = findFood(getPreferredDiet());
                if (newLocation == null) {
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    // Overcrowding.
                    setDead();
                }
            }

        // randomly cure infection to prevent population dying too early
        clearInfection();
    }

docstring:
CHeck whether this plant is to propagate at this step.
New seeds will be dropped into free adjacent locations.
@param newSeeds A list to add the new seeds to.

function:
protected void dropSeeds(List<Actor> newSeeds, String currentWeather)
    {
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int seeds = propagate();

        if(currentWeather.equals("snow")){
            seeds = 0;
        }
        else if(currentWeather.equals("wind")){
            seeds = propagate()*2;
        }

        for(int i = 0; i < seeds && free.size() > 0; i++) {
            Location loc = free.remove(0);
            newSeeds.add(createPlant(false, field, loc));
        }
    }

protected void attemptInfection(Disease disease){
        // First check if this animal can be infected
        if (disease.isInfectable(this.getClass()) && getRandomDouble() <= disease.getInfectionChance()){
            if (this.disease != null && this.disease != disease){
                // Animal dies from having two diseases
                this.setDead();
            } else{
                // Animal catches the disease
                this.disease = disease;
            }
        }
    }

