docstring:
Look for prey adjacent to the current location.
Only the first live prey animal is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        if (weather!=null){
        weather = field.getWeather();
        }
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()&& !weather.equals("foggy")) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Corpse) {
                Corpse Corpse = (Corpse) animal;
                if(Corpse.isAlive()) { 
                    Corpse.setDead();
                    foodLevel = foodLevel + CORPSE_FOOD_VALUE;
                    if(where!=null)
                    {
                        field.clear(where);
                    }
                    return where;
                }
            }    
            if(animal instanceof Zebra) {
                Zebra Zebra = (Zebra) animal;
                if(Zebra.isAlive()) { 
                    Zebra.setDead();
                    foodLevel = foodLevel + ZEBRA_FOOD_VALUE;
                    return where;
                }
              }
            else if(animal instanceof ApricotTrees) {
                ApricotTrees ApricotTrees = (ApricotTrees) animal;
                if(ApricotTrees.isAlive()) { 
                    ApricotTrees.setDead();
                    return where;
                }

            }            
        }
        return null;
    }

public void algaeSpread(List<LivingOrganism> newAlgae)
    {
        // New algae is spread into adjacent locations.
        // Get a list of asjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());

        Random rand = new Random();
        int random_spread = rand.nextInt(2);     // max number of algae to grow out

        if(growthCheck()){
            for(int b = 0; b < random_spread && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Algae young = new Algae(field, loc);
