docstring:
Look for animals the shark can eat and is adjacent to the current location.
Finds the biggest animal first then eats them.
@return Where food was found, or null if it wasn't.

function:
public Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            if(animal instanceof Dolphin) {
                Dolphin dolphin = (Dolphin) animal;
                if(dolphin.isAlive()) { 
                    dolphin.setDead();
                    setFoodLevel (getFoodLevel() + DOLPHIN_FOOD_VALUE);
                    if(getFoodLevel() > MAX_HEALTH)
                    {
                        setFoodLevel (MAX_HEALTH);
                    }
                    return where;
                }
            }
            else if(animal instanceof Nemo) {
                Nemo nemo = (Nemo) animal;
                if(nemo.isAlive()) { 
                    nemo.setDead();
                    setFoodLevel (getFoodLevel() + NEMO_FOOD_VALUE);
                    if(getFoodLevel() > MAX_HEALTH)
                    {
                        setFoodLevel (MAX_HEALTH);
                    }
                    return where;
                }
            }
            else if(animal instanceof Dory) {
                Dory dory= (Dory) animal;
                if(dory.isAlive()) { 
                    dory.setDead();
                    setFoodLevel (getFoodLevel() + DORY_FOOD_VALUE);
                    if(getFoodLevel() > MAX_HEALTH)
                    {
                        setFoodLevel (MAX_HEALTH);
                    }
                    return where;
                }
            }
        }

        return null;
    }

private void sickness() {
        double chance = rand.nextDouble();
        if( chance <= IMMUNITY){
            //the animal has died from the sickness
            setDead(); 
        }
        else if (chance >= survivalRate){
            //the animal has recovered from the sickness
            setHealthy();
        }
        else{
            //the animal is still sick and can spread the deseas
            incrementHunger();
        }
    }

private boolean canBreed()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object Species = field.getObjectAt(where);
            if(Species instanceof Tarantula) {
                Tarantula Tarantula = (Tarantula) Species;
                if(Tarantula.getSex() != getSex()) { 
                    return true;
                }else{
                    return false;
                }
            }
        }
        return false;
    }

protected void diseaseImplementation(Animal newBorn, Random rand) {
        if(this.hasDeezZeezH) {
            // Check if the new born will get the disease
            if(rand.nextDouble() <= this.DEEZ_ZEEZ_H_INHERIT) {
