private EntityStats getRandomEntity(int limit) {
        int total = 0;
        int probability = rand.nextInt(limit);
        for (EntityStats entity : possibleEntities){
            total += entity.getCreationProbability()*10;
            if (probability <= total){
                return entity;
            }
        }
        return null;
    }

