            setStatus(FOOD_HUNTING_STATUS_ID);
            return;
        }

        if (field.isDark()) {
            setStatus(ASLEEP_STATUS_ID);
            return;
        }

        if (canMeet() && rand.nextDouble() < 0.4 || getStatus().equals(MATE_HUNTING_STATUS_ID)) {
            setStatus(MATE_HUNTING_STATUS_ID);
            return;
