This is what the shark does most of the time: it hunts for
fish and tuna. In the process, it might breed, die of hunger,
or die of old age.
@param newSharks A list to return newly born sharks.
@param isDay Indicator of whether it is day or night

function:
public void act(List<Animal> newSharks, boolean isDay)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            if(isDay){
            BREEDING_PROBABILITY = 0.6;
            giveBirth(newSharks); 
            spreadDisease(getField(),getLocation(),INFECTION_SPREAD_PROBABILITY);
            // Move towards a source of food if found.
            if("Storm".equals(weather.getWeather())){
            Location newLocation = findFoodStorm();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else{
                // Overcrowding.
                setDead();
            }
        }
        else
        {
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else{
                // Overcrowding.
                setDead();
            }

          }
        }

        else {
            BREEDING_PROBABILITY = 0.8;
            giveBirth(newSharks);
            spreadDisease(getField(),getLocation(),INFECTION_SPREAD_PROBABILITY);
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else{
                 //Overcrowding.
                setDead();
            }            
        }
      }
    }

