        weatherLabel.setText(WEATHER_PREFIX + weather); 
        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                LivingThing livingThing = field.getObjectAt(row, col);
                if(livingThing != null) {
                    stats.incrementCount(livingThing.getClass());
                    fieldView.clearMark(col, row, dayColor);
                    fieldView.fillMark(col, row, getColor(livingThing.getClass()));
                }
                else if (day) {
                    fieldView.clearMark(col, row, dayColor);
                    fieldView.fillMark(col, row, backgroundColor);
                }
                else {
                    fieldView.clearMark(col, row, dayColor);
                    fieldView.fillMark(col, row, backgroundColor);
                }
            }
        }
        stats.countFinished();
        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

protected void attemptInfection()
    {
        // If exceeded maximum steps when diseased, animal dies.
        if (diseasedSteps >= MAX_DISEASE_STEPS) {
            setDead();
            return;
        }

        // If already diseased, try to infect adjacent animals.
        if (isDiseased()) {
            diseasedSteps++;
            List<Location> surroundings = field.adjacentLocations(location);
            for (Location cell : surroundings) {
                Object actor = field.getObjectAt(cell);
                if (actor instanceof Animal && rand.nextDouble() <= DISEASE_SPREAD_PROBABILITY) {
                    ((Animal) actor).diseasedSteps++;
                }
            }
        }

        // Try to randomly infect the current animal.
        // (If already infected, animal will die sooner.)
        if (rand.nextDouble() <= DISEASE_PROBABILITY) {
            diseasedSteps++;
        }
    }

docstring:
This is what the moose does most of the time: it hunts for
plants. In the process, it might breed, die of hunger,
or die of old age.
@param field The field currently occupied.
@param newMooses A list to return newly born Mooses.

function:
public void act(List<Organism> newMooses, boolean day, boolean rain)
    {
        incrementAge(MAX_AGE);
        incrementHunger(foodLevel);
        if(isAlive()&& day) {
            Animal mate = foundMate();
            if(mate != null)
            {
                giveBirth(newMooses); 
                matedThisStep = true;
                mate.matedThisStep = true;
                if(mate.isDiseased == true)
                {   
                    this.isDiseased = true;
                }
            }           
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
                Object object = getField().getObjectAt(newLocation);
                if(object instanceof Animal)
                {
                    Animal animal = (Animal) object;
                    if(animal.isDiseased == true)
                    {   
                        this.isDiseased = true;
                    }
                }
            }
            else {
                // Overcrowding.
                setDead();
            }

            if(isDiseased)
            {
                double progress = new Random().nextDouble();
                //if(progress < 0.5){progress -= 0.5;}
                diseaseProliferation += progress;
                if(diseaseProliferation >= 0.01){setDead();}
            }
        }

    }

docstring:
Look for grass or trees adjacent to the current location.
Only the first live plant is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        if(foodLevel<5){
            Field field = getField();
            // Get nearby locations.
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext()) {
                Location where = it.next();
                // Check what is in each neighbouring cell.
                Object plant = field.getObjectAt(where);
                if(plant instanceof Grass) { // if there is grass nearby
                    Grass grass = (Grass) plant;
                    if(grass.isAlive()) { 
                        grass.setDead();
                        foodLevel = GRASS_FOOD_VALUE; // eat the grass
                        return where;
                    }

                }
                else if(plant instanceof Tree){
                    Tree tree = (Tree) plant;
                    if(tree.isAlive()) { 
                        tree.setDead();
                        foodLevel = TREE_FOOD_VALUE;
                        return where;
                    }
                }
            }
        }
        return null;
    }

