private void giveBirth(List<Animal> newMice)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Mouse) {
                Mouse mouse = (Mouse) animal;
                //Check if the gender of this mouse is opposite of the partner mouse. If is that the case than the breeding is true.
                if(mouse.getGender() != this.getGender()) { 
                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
                    int births = breed();
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        boolean genderSetter = setGender();
                        boolean isSick = Randomizer.isSick();
                        Mouse young = new Mouse(false, field, loc, genderSetter, isSick);
                        newMice.add(young);
                    }
                }      
            }
        }
    }

