docstring:
Look for plants adjacent to the current location.
Only the first live plant is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if(organism instanceof Plant) {
                Plant plant = (Plant) organism;
                if(plant.isAlive()) { 
                    plant.setDead();
                    foodLevel = PLANT_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

public Location findFood() {
        // Iterate through a list of adjacent locations
        Iterator<Location> it = adjacentIterator();
        Location newLoc = null;
        while(it.hasNext()) {
            Location location = it.next();
            // create an iterator for the adjacent locations of each adjacent location.
            Iterator<Location> it2= adjacentIterator(location);
            while (it2.hasNext()) {
                Location where = it2.next();
                Object object = getField().getObjectAt(where);
                // check if an object is food.
                if (canBeEaten(object)) {
                    // if so, consume.
                    consume(object);
                    increaseFoodLevel(FOOD_VALUE);
                    newLoc = where;
                }
            }
        }
        return newLoc;
    }

docstring:
Checks whether a location is within a bound.

@param location The location to be checked.
@param bound The bound to be considered.
@return true if the location is within the bound, false otherwise.

function:
public static boolean isWithinBound(Location location, Bound bound) 
    {
        boolean isWithin = false;
        boolean isWithinRow = false;
        boolean isWithinCol = false;

        int row = location.getRow();
        int col = location.getCol();

        if ((bound.getLocation1().getRow() <= row) && (row < bound.getLocation3().getRow())) {
            // Check whether the location's row is within the bound's row.
            isWithinRow = true;
        }

        if ((bound.getLocation1().getCol() <= col) && (col < bound.getLocation4().getCol())) {
            // Check whether the location's column is within the bound's column.
            isWithinCol = true;
        }

        if (isWithinRow && isWithinCol) {
            // Whether the location is within the bound's row and column.
            isWithin = true;
        }

        return isWithin;
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                //Create animals.
                if(rand.nextDouble() <= FOX_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Fox fox = new Fox(true, field, location, time, weather, false);
                    animals.add(fox);
                }
                else if(rand.nextDouble() <= RABBIT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Rabbit rabbit = new Rabbit(true, field, location, time, weather, false);
                    animals.add(rabbit);
                }
                else if(rand.nextDouble() <= OWL_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Owl owl = new Owl(true, field, location, time, weather, false);
                    animals.add(owl);
                }
                else if(rand.nextDouble() <= BLUEJAY_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    BlueJay blueJay = new BlueJay(true, field, location, time, weather, false);
                    animals.add(blueJay);
                }
                else if(rand.nextDouble() <= EAGLE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Eagle eagle = new Eagle(true, field, location, time, weather, false);
                    animals.add(eagle);
                }
                else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(field, location, time, weather);
                    plants.add(grass);
                }
                // else leave the location empty.
            }
        }
    }

