public void showStatus(int step, Field field)
    {
        if(!isVisible()){
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object actor = field.getObjectAt(row, col);
                if(actor != null) {
                    stats.incrementCount(actor.getClass());
                    fieldView.drawMark(col, row, getColor(actor.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, backgroundColor);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        weather.setText(WEATHER_PREFIX + field.getEnvironment().getWeatherStats());
        time.setText(TIME_PREFIX + field.getEnvironment().getTimeStats());
        fieldView.repaint();
    }

private Boolean findMate() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocationsWBorder(getLocation(),4);
        //If weather is foggy reduce the surrounding area the lions can mate in.
        if(weather.equals("fog")){
            adjacent = field.adjacentLocationsWBorder(getLocation(),1);
        }
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Lion) {
                Lion lion = (Lion) animal;
                if(lion.getSex() != sex) {
