docstring:
Calculates the breeding probability based
on factors such as season and weather

@return double - final breeding probability

function:
private double calculateBreedingProbability() {
        String currentSeason = Weather.getSeason();
        String currentWeather = Weather.getWeather();

        double breedingProbability = BREEDING_PROBABILITY;
        double accumulatedEffect = 0.00;
        // Add changes based on season
        switch(currentSeason) {
            case "winter":
                accumulatedEffect += 0.04;
                break;
            case "summer":
                accumulatedEffect -= 0.04;
                break;
            case "autumn":
                accumulatedEffect += 0.03;
                break;
        }

        // Add changes based on weather
        switch(currentWeather) {
            case "raining":
                accumulatedEffect += 0.02;
                break;
            case "dry":
                accumulatedEffect -= 0.01;
                break;
            case "hot":
                accumulatedEffect -= 0.02;
                break;
            case "snowing":
                accumulatedEffect += 0.04;
                break;
        }

        return breedingProbability += accumulatedEffect;
    }

docstring:
Apply the effects of a disease. This may affect the breeding probability, the maximum age,
or the maximum litter size.

@param disease The disease being affected.

function:
private void applyDisease(Disease disease) {
        DISEASE_TYPE diseaseType = disease.getDiseaseType();
        double reductionFactor = disease.getReductionFactor();
        switch (diseaseType) {
            case MAX_LITTER_SIZE_DISEASE:
                maxLitterSize = (int) Math.max(1.0, floor(maxLitterSize * reductionFactor));
                break;
            case BREEDING_PROBABILITY_DISEASE:
                breedingProbability = breedingProbability * reductionFactor;
                break;
            case MAX_AGE_DISEASE:
                maxAge = (int) floor(maxAge * reductionFactor);
                break;
        }
    }

public void act(List<Actor> newActors)
    {
        if (TimeOfDay.getInstance().getTime() == activeTime) {
            // Checks whether the animal is active at the current time.
            incrementAge();
            incrementHunger();
            // Increments age and hunger.
            if (isAlive()) {
                mate(newActors, this.getClass(), getBounds(), noiseValue);
                // Move towards food.
                Location newLocation = findPrey();

                if (newLocation == null) {
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation(), movementArea.getBounds(), 1);
                }
                // See if it was possible to move.
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    // Overcrowding.
                    setDamage();
                }
            }
        }
        // Else sleep.
    }

