private void giveBirth(List<Animal> newMouse)
    {
        // New Mice are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Mouse young = new Mouse(false, field, loc);
            newMouse.add(young);
        }
    }

public void setWeather(){
        int cycle = Simulator.getStep();
        Random rand = Randomizer.getRandom();
        if (cycle % 100 == 0) {
            if(rand.nextDouble() <= RAIN_PROBABILITY) {
                   rain = true;
                }
            if(rand.nextDouble() <= HIGHWINDS_PROBABILITY) {
                    winds= true;
                }
            if(rand.nextDouble() <= FOG_PROBABILITY) {
                    fog= true;
                }
            }
         if( cycle % 200 ==0){
        rain=false;
