docstring:
An animal can breed if it has reached the breeding age and there is
another animal of the same species but opposite gender in adjacent cells.
@return true if the animal can breed, false otherwise.

function:
protected boolean canBreed()
    {

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        boolean hasPartner = false;
        int partnerAge = 0;
        while(it.hasNext()) {
            Location where = it.next();
            Object neighbour = field.getObjectAt(where);
            if(neighbour != null && neighbour.getClass() == this.getClass()) {
                Animal animal = (Animal) neighbour;
                if((this.isFemale() && !animal.isFemale()) 
                || !this.isFemale() && animal.isFemale()) {
                    hasPartner = true;
                    partnerAge = animal.getAge();
                    if(this.isDiseased()) {
                        animal.setDiseased();
                    }
                    break;
                }
            }
        }

        return hasPartner && age >= BREEDING_AGE && partnerAge >= BREEDING_AGE;
    }

docstring:
An animal needs to look for a partner that is in the neighbouring cell to it, if they are opposite genders they have the
ability to breed.
@return true if they can breed.

function:
private boolean  canBreed(){
        Animal partner = null;
        for(Location otherLocation : field.adjacentLocations(location)){
            Object canditate = field.getAnimalAt(otherLocation);
            if(getClass().isInstance(canditate) && ((Animal) canditate).getGender() == Gender.male){
                partner = (Animal) field.getAnimalAt(otherLocation);
                break;
            }
        }
        return age>=getBreedingAge() && gender == Gender.female && partner != null && partner.getAge()>=partner.getBreedingAge();
     }

