        if (isAlive()) {
            createNewPlants(newGrasses);
            if (weatherManager.getWeather() == WeatherManager.Weather.RAINING) {
                waterLevel = Math.min(waterLevel + 1, WATER_CAPACITY);
            }
            if (getField().freeAdjacentLocation(getLocation()) == null) {
                // Overcrowding.
                setDead();
            }
        }
    }

