public void simulateDiseaseStep()
    {
        // fetch the animal per blocks eg : [block1 : [animal1,animal2, animal3]. block 2: [animal1, animal 2, animal3]...]
        List<List<Animal>> blocks = field.getAnimalsPerBlock();
        int infectionCount = 0;
        currentStep++;
        for (List<Animal> block : blocks) {
            int densityIndex = 0;
            List<Animal> uninfectedAnimals = new ArrayList<>();
            for(Animal animal : block) {
                if(animal.getInfectionTimestamp() != null && currentStep - animal.getInfectionTimestamp() < DISINFECTION_DURATION) {
                    // increase the counter of number of animals infected within this block.
                    densityIndex++;
                    continue;
                }
                if(animal.getInfectionTimestamp() == null) {
                    uninfectedAnimals.add(animal);
                }
            }
            // compute probability of being infected.
            double pValue = (double)((double)densityIndex/(double)block.size());
            for(Animal animal : uninfectedAnimals) {
                double randNumber = rand.nextDouble();
                if(randNumber < pValue ) {
                    animal.setInfectionTimestamp(currentStep);
                }
            }
            infectionCount += densityIndex;
        }
        count.put(currentStep, infectionCount);
    }

docstring:
This is what the Tiger does most of the time: it hunts for
tigers. In the process, it might breed, die of hunger,
or die of old age.
@param field The field currently occupied.
@param newTigeres A list to return newly born Tigeres.

function:
public void act(List<Animal> newTigers)
    {
        incrementAge();
        incrementHunger();
        time++;
        if(time > 24)
        {
            time = 0;
        }
         if(sleepAtNight && time <= 22 && time >=6)
        {
            if(isAlive()) {
            giveBirth(newTigers);            
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
        }
    }

public void act(List<Animal> newPredators)
    {

        incrementAge(); //increase age
        incrementHunger(); //increase hunger
        if(isAlive()) {
            giveBirth(newPredators); //give birth to new predators
            // Move towards a source of food if found.
            Location newLocation = findFood(); //search for food
            if(newLocation == null) {
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

public void act(List<Terrain> newTerrain) {
        if (getLayer().shouldFreezeRiver()) {
            if (rand.nextDouble() > 0.5) {
                freezeIfAtSurface();
            }
        } else if (isFrozen) {
            if (rand.nextDouble() > 0.5) {
                isFrozen = false;
            }
        }

        if (getLayer().shouldFloodRiver()) {
            flood(newTerrain);
        } else if (isFloodWater && getLayer().shouldUnfloodRiver()) {
             unFloodSlowly();
        }
    }

