function:
public Object getObjectAt(int row, int col)
    {
        if (animalField[row][col] != null) {
            return animalField[row][col];
        }
        return plantField[row][col];
    }

protected void processInfection(){
        if(isInfected()){
            float probability = rand.nextFloat();

            if(probability <= mortalityRate){
                setDead();
            }
            else if(probability <= recoveryRate){
                toggleInfected();
            }
        }
    }

private void incrementAge() {
        age++;
        if (age > MAX_AGE) {
            setDead();
        }
    }

protected boolean ableToPropagate()
    {
        List<Location> locations = getField().adjacentLocations(getLocation()); //gets all locations around the animal
        boolean sameSpecies = false;
        for (int i=0; i < locations.size(); i++){
            Object potentialMate = getField().getObjectAt(locations.get(i));
            if (potentialMate instanceof Animal){
                Animal mate = (Animal) potentialMate;
                if (getClass().equals(potentialMate.getClass())){       
                    sameSpecies = true;
                }
                if (sameSpecies){
                    //compares current animals gender to the potential mate. If opposite, they're able to mate
                    if (getGender() != mate.getGender()){
                        return true;
                    }
                    else {
                        sameSpecies = false; //otherwise, although they're the same species, they are the same gender. Moves on to check the next location
                    }
                }
            }
        }
        return false;
    }

docstring:
Provides the actor with the furthest location away from something that they
can move to is. Useful for fleeing predators.

@param location
Location of the actor wishing to move
@param locationDirection
Location of the actor that it is moving away from.
@param moveDistance
The largest distance to which the actor can move.
@param field
The field that the actors are on
@return The location the actor should move to

function:
public static Location getFurthestLocationAway(Location location, Location locationDirection, double moveDistance,
			Field field) {

		List<Location> availableLocationsAway = getLocationsNotInDirection(location, locationDirection, moveDistance,
				field);

		if (availableLocationsAway == null || availableLocationsAway.size() == 0) {
			return null;
		}

		Location furthest = availableLocationsAway.get(0);
		int furthestDistance = (int) Math.floor(getDistance(furthest, location));

		for (int i = 1; i < availableLocationsAway.size(); i++) {
			int distance = (int) Math.floor(getDistance(availableLocationsAway.get(i), location));
			if (distance > furthestDistance) {
				furthest = availableLocationsAway.get(i);
				furthestDistance = distance;
			}
		}

		return furthest;
	}

