private void giveBirth(List<Animal> newBadgers)
    {
        // New badgers are born into adjacent locations.
        // Get a list of adjacent free locations.
        Forest forest = getForest();
        List<Location> free = forest.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Badger young = new Badger(false, forest, loc);
            newBadgers.add(young);
        }
    }

