public void populate(Field field, List<Actor> actors, 
    Field plantField, Timer timer)
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= TIGER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Tiger tiger = new Tiger(true, field, location, timer);
                    actors.add(tiger);
                }
                else if(rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Deer deer = new Deer(true, field, plantField, 
                            location, timer);
                    actors.add(deer);
                }
                else if(rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Mouse mouse = new Mouse(true, field, plantField, 
                            location, timer);
                    actors.add(mouse);
                }
                else if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lion lion = new Lion(true, field, location, timer);
                    actors.add(lion);
                }
                else if(rand.nextDouble() <= SNAKE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Snake snake = new Snake(true, field, location, timer);
                    actors.add(snake);
                } 
                else if(rand.nextDouble() <= HUNTER_CREATION_PROBABILITY){
                    Location location = new Location(row, col);
                    Hunter hunter = new Hunter(field, location);
                    actors.add(hunter);
                }

                // Randomly populate the field with plants.
                Location location = new Location(row, col);
                Plants plant = new Plants(rand.nextBoolean(), timer, 
                plantField, location);
                actors.add(plant);
            }
        }
    }

public void simulateOneStep()
    {
        step ++;

        weather = Weather.changeWeather();

        // Provide space for newborn animals.
        List<Actor> newActors = new ArrayList<>();
        // Let all rabbits act.
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actors = it.next();
            if(!isAtNight() && actors instanceof Animal) {
                actors.act(newActors,weather);
            }
            if(weather.name() == "RAIN" && actors instanceof Plant) {
                actors.act(newActors,weather);
            }
            if(! actors.isActive()) {
                    it.remove();
                }
        }

        // Add the newly born animals to the main lists.
        actors.addAll(newActors);

        view.showStatus(step, field, isAtNight(), weather.name());
    }

public String getPopulationDetails(Field field) {
        StringBuffer buffer = new StringBuffer();
        if (!countsValid) {
            generateCounts(field);
        }
        for (Class key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

