private void changeTime(){
        if(step%24==0){
            //changes the time label on gui
            if(time.equals("Day")){
                time="Night";
            }
            else{
                time="Day";
            }

            //changes the awake value in each organisms except small fish and octopus's
            for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
                Organism organism = it.next();
                if (organism instanceof Animal){
                    Animal animal = (Animal) organism;
                    if(step%24==0 && !(animal instanceof SmallFish) && !(animal instanceof Octopus)){
                        animal.changeAwake();
                    }
                }
            }

        }
    }

