docstring:
This is what the fox does most of the time: it hunts for
prey. In the process, it might breed, die of hunger,
or die of old age or of a disease.
@param newFoxes A list to return newly born foxes.
@param timeOfDay The time of day where the animal will act differently.
@param weather The current weather during the simulation

function:
public void act(List<Actor> newFoxes, int timeOfDay,Weather weather)
    {
        increaseAge();
        incrementHunger();
        if (getDiseases().contains(Disease.LUPUS)){
            //Lupus causes animals to have a shorter lifespan.
            changeMaxAgeTo(MAX_AGE-10);
        }

        if ((timeOfDay<9 || timeOfDay>18) || (getFoodLevel()<10)){
            if(isAlive()) {
                //Infect nearby foxes.
                infect();
                giveBirth(newFoxes);
                // Move towards a source of food if found.
                Location newLocation=null;
                //Cannot hunt in the fog
                if (!weather.equals(Weather.FOG)){
                    newLocation = findFood();
                }
                // See if it was possible to move. Otherwise stay in the same spot.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
            }
        }
    }

protected void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }

private void giveBirth(List<Organism> newHares)
    {
        boolean currentFemale = this.isFemale;
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if(organism instanceof Hare) {
                Hare hare = (Hare) organism;
                if(currentFemale != hare.isFemale) {
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Hare young = new Hare(false, field, loc, true);
                        newHares.add(young);
                    }
                }
            }
        }
    }

