        String currentWeather = weather.getRandomWeather(step);
        Random rand = Randomizer.getRandom();
        int row = rand.nextInt(field.getDepth());
        int col = rand.nextInt(field.getWidth());
        while(!(field.getObjectAt(row, col) instanceof Animal)){
            row = rand.nextInt(field.getDepth());
