function:
public void act(List<Species> newAlphaPredators)
    {
        age = incrementAgee(age ,MAX_AGE); //increments age
        foodLevel = incrementHunger(foodLevel); //changes the food level
        if(isAlive()) {
            giveBirth(newAlphaPredators);            
            // Move towards a source of food if found.
            Location newLocation = findFood();
            //foodLevel = GetFoodLevel();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

docstring:
Look for zebras adjacent to the current location.
Only the first live zebra is eaten.
@return Where food was found, or null if it wasn't.

function:
protected Location findFood()
    {
        if(isFull() == false) {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext()) {
                Location where = it.next();
                Object plant = field.getObjectAt(where);
                if(plant instanceof Grass) {
                    Grass grass = (Grass) plant;
                    if(grass.isAlive()) {
                        grass.setDead();
                        foodLevel = GRASS_FOOD_VALUE;
                        return where;
                    }
                }
            }
        }
        return null;
    }

