New births will be made into free adjacent locations.
@param newMountainLions A list to return newly born MountainLions.

function:
private void giveBirth(List<Food> newMountainLions)
    {
        // New MountainLions are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        if (getGender().equals("female")){
            List<Location> nearbyAnimals = field.adjacentLocations(getLocation());
            Iterator<Location> it = nearbyAnimals.iterator();
            while(it.hasNext()){
                Object animal = field.getObjectAt(it.next());
                if(animal instanceof MountainLion){
                    MountainLion nearbyMountainLion = (MountainLion) animal;
                    if(nearbyMountainLion.getGender().equals("male")){
                        List<Location> free = field.getFreeAdjacentLocations(getLocation());
                        int births = breed();
                        for(int b = 0; b < births && free.size() > 0; b++) {
                            Location loc = free.remove(0);
                            Object food = field.getObjectAt(loc);
                            if(food instanceof Grass) {
                                Grass grass = (Grass) food;
                                grass.setDead();
                            }
                            MountainLion young = new MountainLion(false, field,loc);
                            newMountainLions.add(young);
                        }
                        return;
                    }
                }
            }
        }
    }

