public void simulateOneStep()
    {
        step++;

        // Provide space for newborn actors.
        List<Actor> newActors = new ArrayList<>();
        //Chance the weather changes every 6 steps;
        if (step%6==0){
            currentWeather=Weathers.get(rand.nextInt(Weathers.size()));
        }
        // Let all actors act.
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            //The timeOfDay is found by taking the modulo of 24 of the step variable. This value will
            //be used to determine the behaviour of different actors at different times.
            actor.act(newActors,step%24,currentWeather);
            if(! actor.isAlive()) {
                it.remove();
            }
        }

        // Add the newly created actors to the main lists.
        actors.addAll(newActors);

        view.showStatus(step, field);
    }

private void linearSolver(int b, float[] x, float[] x0, float a, float c) {
        float cRecip = 1.0f / c;
        int iter = 16;
        for (int k = 0; k < iter; k++) {
            for (int j = 1; j < N - 1; j++) {
                for (int i = 1; i < N - 1; i++) {
                    x[weatherGrid(i, j)] =
                            (x0[weatherGrid(i, j)]
                                    + a*(    x[weatherGrid(i+1, j)]
                                    +x[weatherGrid(i-1, j)]
                                    +x[weatherGrid(i, j+1)]
                                    +x[weatherGrid(i, j-1)]
                            )) * cRecip;
                }
            }

            setBoundary(b, x);
        }
    }

