public void act(List<Animal> newEagles, boolean isDay, boolean isRaining) {
        incrementAge();
        incrementHunger();

        if (isAlive())
            spreadInfection();

        if (isDay) // the eagle acts only during the day.
            if (isAlive()) {
                giveBirth(newEagles);
                // Move towards a source of food if found.
                Location newLocation = isRaining ? null : findFood(getPreferredDiet());

                if (newLocation == null) {
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    // Overcrowding.
                    setDead();
                }
            }

        // randomly cure infection to prevent population dying too early
        clearInfection();
    }

