protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location location = it.next();
            Object meal = field.getObjectAt(location);
            if(meal instanceof Mouse) {
                Mouse mouse = (Mouse) meal;
                if(mouse.isAlive()) { 
                    mouse.setDead();
                    foodLevel = mouse.getFoodValue();
                    return location;
                }
            } else if(meal instanceof Cricket) {
                Cricket cricket = (Cricket) meal;
                if(cricket.isAlive()) { 
                    cricket.setDead();
                    foodLevel = cricket.getFoodValue();
                    return location;
                }
            }
        }
        return null;
    }

protected void setFoodLevel(double foodlevel){
        this.foodLevel += foodlevel ; 
    }

public void giveBirth(List<Actor> newSharks)
    {
        // New Sharkes are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation(), BREEDING_DISTANCE);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Shark) {
                Shark shark = (Shark) animal;
                if(shark.getIsFemale() != getIsFemale()) { 
                    List<Location> free = field.getFreeAdjacentLocations(getLocation(), 2);
                    int births = breed();
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Shark young = new Shark(false, field, loc, isDiseased()|shark.isDiseased());
                        newSharks.add(young);
                    }
                }
            }
        }
    }

