New births will be made into free adjacent locations.
@param newKillerWhales A list to return newly born KillerWhales.

function:
private void giveBirth(List<Animal> newKillerWhales)
    {
        Field field = getField();
        // Get a list of adjacent locations.
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> iterator = adjacent.iterator();

        while(iterator.hasNext()) {
            Object animal = field.getObjectAt(iterator.next());

            if (animal instanceof KillerWhale) {
                KillerWhale adjacentKillerWhale = (KillerWhale)animal;
                // Checks whether the gender of the adjacent KillerWhale is of the opposite
                if (adjacentKillerWhale.isMale() != isMale()) {
                    // Get a list of adjacent free locations.
                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
                    int births = breed();
                    // New KillerWhales are born into adjacent locations.
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        KillerWhale young = new KillerWhale(false, field, loc);
                        newKillerWhales.add(young);
                    }
                }
            }
        }
    }

