private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(checkDiet(animal)) {
                Prey food = (Prey) animal;
                if(food.isAlive()) { 
                    food.setDead();
                    foodLevel = getPreyFoodValue(food);
                    return where;
                }
            }
        }
        return null;
    }

public void simulateOneStep()
    {
        step++;
        this.time++;
        if(time % 50 == 0)
        {
            state.setRandomWeather();
        }
        checkAndSetWeatherLabel();
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all Antelopes act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born Liones and Antelopes to the main lists.
        animals.addAll(newAnimals);

        if(night == false & time == 50){
            time = 0;
            this.night = true;
        }

        if(night == true & time == 50){
            time = 0;   
            this.night = false;
        }
        //Setup time info
        setTime();
        view.showStatus(step, field, timeStatus);
    }

