public void showStatus(int step, Field field, int weatherInt, Weather weather)
    {

        String weatherString = weather.getStringWeather(weatherInt);
        boolean dayCheck = weather.isDay(step);
        String dayString = "Night";
        //day check
        if(dayCheck)
            dayString = "Day";

        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        dayLabel.setText(DAY_PREFIX + dayString);
        seasonLabel.setText(SEASON_PREFIX + weatherString);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

