private void giveBirth(List<Animal> newZebras)
    {
        // New Zebras are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        List<Location> adjacent = field.adjacentLocations(getLocation());
        boolean animalNearby = false;
        for(int i = 0; i < adjacent.size(); i++){
            Location loc = adjacent.get(i);
            if(field.getObjectAt(loc) != null){
                Object animal = field.getObjectAt(loc);
                if(animal instanceof Zebra){
                    Zebra zebra = (Zebra) animal; 
                    if(zebra.getIsMale() != this.getIsMale()){
                        animalNearby = true;
                    }
                    //Infection spreads through contact.
                    if((this.getIsInfected() == true) || zebra.getIsInfected()) {
                         setInfected();
                         zebra.setInfected();
                    }                                   
                }
            }
        }
        int births = breed();
        // if another Zebra is nearby, give birth.
        if(animalNearby == true){
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Zebra young = new Zebra(false, field, loc);
                if(getIsInfected() == true) {
                    young.setInfected(); //Infected adults pass on disease to young.
                }
                newZebras.add(young);
            }
        }
    }

