            if(animal instanceof Eagle) {
                Eagle eagle = (Eagle) animal;
                if(!eagle.isFemale()) { 
                    hasMate = true;
                }
            }
        }   

        //isFemale() checked first for shortcutting
        return ( isFemale() &&getAge() >= BREEDING_AGE && hasMate);
    }

