public void grow(int newWeather, PlantsField plantsField) {
        // Find adjacent location and see if other plants have got disease
        // If there is more than 4 plants then get infected as well
        switch(newWeather) {
            case 0:
                // Rainy waether. Plants grow more.
                foodValue += 7;
                break;
            case 1:
                // Sunny weather. The infection may spread between plants.
                foodValue += 5;
                spreadDisease(plantsField, 4);
            case 2: 
                // Foggy weather. Plants grow less.
                foodValue += 4;
                break;
            default:
                foodValue += 5;
                break;
        }
    }

private boolean checkMeet()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        String gender_meet = "";
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if (animal instanceof Lion)
            {
                Lion Lion = (Lion) animal;
                gender_meet = Lion.getGender(); 
                //This is how living diseased Lions can infect other lions.
                if(disease = true)
                {
                    //Inserts a ratio of a Lion passing on a disease of 0.5
                    Lion.gainDisease(0.5);
                }
            }
        }
        return (gender_meet != gender);

    }

