public void act(List<Animal> newOwls, int time)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            infect();
            if(isAlive()) {
                if(time >= 3) {
                    giveBirth(newOwls);
                    // Move towards a source of food if found.
                    Location newLocation = findFood();
                    if(newLocation == null) { 
                        // No food found - try to move to a free location.
                        newLocation = getField().freeAdjacentLocation(getLocation());
                    }
                    // See if it was possible to move.
                    if(newLocation != null) {
                        setLocation(newLocation);
                    }
                    else {
                        // Overcrowding.
                        setDead();
                    }
                }
            }
        }
    }

docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        int countInf = 0;
        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object object = field.getObjectAt(row, col);
                Living living = (Living) object;
                if(living != null) {
                    stats.incrementCount(living.getClass());
                    fieldView.drawMark(col, row, getColor(living.getClass()));
                    if(living.isInfected()){
                        fieldView.drawMark(col, row, INFECTED_COLOR);
                        countInf++;
                    }
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field) + "Infected: " + countInf + "  Weather: " + field.getWeather() + " Time : " + field.getTime());
        fieldView.repaint();
    }

docstring:
Look for food adjacent to the current location.
Only the first live mouse or lizard is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Mouse) {
                Mouse mouse = (Mouse) animal;

                if(mouse.isAlive()) { 
                    if (mouse.isDiseased()){ 
                        setDiseased();
                    }
                    mouse.setDead();
                    foodLevel = MOUSE_FOOD_VALUE;
                    return where; 
                }

            }
            if(animal instanceof Lizard) {
                Lizard lizard = (Lizard) animal;
                if (lizard.isAlive()){
                    if (lizard.isDiseased()){ 
                        setDiseased();
                    }
                    lizard.setDead();
                    foodLevel = LIZARD_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

