docstring:
Look for food adjacent to the current location.
Only the first live Animal is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object food = field.getObjectAt(where);
            if(food instanceof Sheep) {
                Sheep sheep = (Sheep) food;
                if(sheep.isAlive()) {
                    sheep.setDead();
                    foodLevel = SHEEP_FOOD_VALUE;
                    return where;

                }
            }
            else if(food instanceof Chicken) {
                Chicken chicken = (Chicken) food;
                if(chicken.isAlive()) {
                    chicken.setDead();
                    foodLevel = CHICKEN_FOOD_VALUE;
                    return where;
                }
            }
            else if(food instanceof MountainLion) {
                MountainLion MountainLion = (MountainLion) food;
                if(MountainLion.isAlive()) {
                    MountainLion.setDead();
                    foodLevel = MOUNTAIN_LION_FOOD_VALUE;
                    return where;
                }
            }
            else if(food instanceof Wolf) {
                Wolf wolf = (Wolf) food;
                if(wolf.isAlive()) {
                    wolf.setDead();
                    foodLevel = WOLF_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

private int breed()
    {
      int births=0;
      if(canBreed() && rand.nextDouble()<=SEED_PRODUCING_PROBABILITY)
      {
          births=rand.nextInt(MAX_SEEDS)+1;
      }
      return births;
    }

protected double breedingProbability()
    {
        return 0.10;
    }

public void setDead()
    {
