docstring:
Check whether or not this seal is to give birth at this step.
New births will be made into free adjacent locations.
@param newSeals A list to return newly born seals.

function:
private void giveBirth(List<Animal> newSeals)
    {
        Field field = getField();
        // Get a list of adjacent locations.
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> iterator = adjacent.iterator();

        while(iterator.hasNext()) {
            Object animal = field.getObjectAt(iterator.next());
            if (animal instanceof Seal) {
                Seal adjacentSeal = (Seal)animal;
                // Checks whether the gender of the adjacent tunas is of the opposite
                if (adjacentSeal.isMale() != isMale()) {
                    // Get a list of adjacent free locations.
                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
                    int births = breed();
                    // New tunas are born into adjacent locations.
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Seal young = new Seal(false, field, loc);
                        newSeals.add(young);
                    }
                }
            }
        }
    }

protected int breed()
    {
        int births = 0;
