private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) 
        {
            for(int col = 0; col < field.getWidth(); col++) 
            {
                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) 
                {
                    Location location = new Location(row, col);
                    Lion lion = new Lion(true, field, location);
                    animals.add(lion);
                }
                else if(rand.nextDouble() <= HYENA_CREATION_PROBABILITY) 
                {
                    Location location = new Location(row, col);
                    Hyena hyena = new Hyena(true, field, location);
                    animals.add(hyena);
                }
                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) 
                {
                    Location location = new Location(row, col);
                    Zebra zebra = new Zebra(true, field, location);
                    animals.add(zebra);
                }
                else if(rand.nextDouble() <= PORCUPINE_CREATION_PROBABILITY) 
                {
                    Location location = new Location(row, col);
                    Porcupine porcupine = new Porcupine(true, field, location);
                    animals.add(porcupine);
                }
                else if(rand.nextDouble() <= BUFFALO_CREATION_PROBABILITY) 
                {
                    Location location = new Location(row, col);
                    Buffalo buffalo = new Buffalo(true, field, location);
                    animals.add(buffalo);
                }

                Location location = new Location(row, col);
                Plant plant = new Plant(field.getPlantField(), location);
                plants.add(plant);          //add the plants to the field
            }
        }
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) 
        {
            for(int col = 0; col < field.getWidth(); col++) 
            {
                if(rand.nextDouble() <= DRAGONFLY_CREATION_PROBABILITY) 
                {
                    Location location = new Location(row, col);
                    Dragonfly drangonfly = new Dragonfly(true, field, location);
                    creatures.add(drangonfly);
                }
                else if(rand.nextDouble() <= BUTTERFLY_CREATION_PROBABILITY) 
                {
                    Location location = new Location(row, col);
                    Butterfly butterfly = new Butterfly(true, field, location);
                    creatures.add(butterfly);
                }
                else if(rand.nextDouble() <= GRASSHOPPER_CREATION_PROBABILITY)
                {
                    Location location = new Location(row , col);
                    Grasshopper grasshopper = new Grasshopper(true , field , location);
                    creatures.add(grasshopper);
                }
                else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY)
                {
                    Location location = new Location(row , col);
                    Grass grass = new Grass(true , field , location);
                    creatures.add(grass);
                }
                else if(rand.nextDouble() <= SPARROW_CREATION_PROBABILITY)
                {
                    Location location = new Location(row , col);
                    Sparrow sparrow = new Sparrow(true , field , location);
                    creatures.add(sparrow);
                }
                else if(rand.nextDouble() <= EAGLE_CREATION_PROBABILITY)
                {
                    Location location = new Location(row ,col);
                    Eagle eagle = new Eagle(true , field , location);
                    creatures.add(eagle);
                }
                // else leave the location empty.
            }
        }
    }

private Location Move()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        //Retrieve the time from "Time" class
        Time time= new Time();
        boolean x= time.DayTime;


       //If time is day,check neibouring cell for what animal occupies it
    if(x){
        while(it.hasNext()) {

            //If the occupying cell is a rabbit, eat it
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Zebra) {
                Zebra zebra = (Zebra) animal;
                if(zebra.isAlive()) { 
                    zebra.setDead();
                    foodLevel = RABBIT_FOOD_VALUE;
                    return where;
                }
            }

            //If the current tiger object is infected, the neibouring cell if it is a tiger is given a random chance 
            //of catching the disease
             else if(animal instanceof Tiger) {
                Tiger tiger = (Tiger) animal;
                if(tiger.isAlive()&& disease.returnInfected()) { 

                      tiger.setInfect();

                    return where;
                }
            }
            //If the current tiger object is infected, the neibouring cell if it a lion is given a random chance 
            //of catching the disease

            else if(animal instanceof Lion) {
                Lion lion = (Lion) animal;
                if(lion.isAlive()&& disease.returnInfected()) { 

                      lion.setInfect();

                    return where;
                }
            }

        }
    }
    // If the time is night it will look for other tigers to breed with
    else{

     while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Tiger) {
                Tiger tiger = (Tiger) animal;
                if(tiger.isAlive()) {

                    return where;
                }
            }
        }

    }

        return null;
    }

