Check whether there is a compatible mate in an adjacent location.
@return True if the adjacent deer is of the oppposite gender and
can breed, and False otherwise.

function:
public boolean adjCompatibleMate()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()){
            Location location = it.next();
            Object animal = field.getObjectAt(location);
            if(animal instanceof Deer){
                Deer deer = (Deer) animal;
                if(deer.isFemale() != isFemale() && deer.canBreed()){
                    return true;
                }
            }            
        }
        return false;
    }

private Location findFood()
    {
        if(foodLevel < (ANTELOPE_FOOD_VALUE * 0.9)) {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext()) {
                Location where = it.next();
                Object animal = field.getObjectAt(where);
                if(animal instanceof Buffalo) {
                    Buffalo buffalo = (Buffalo) animal;
                    if(buffalo.isAlive()) {
                        buffalo.setDead();
                        foodLevel = BUFFALO_FOOD_VALUE;
                        return where;
                    }
                }
                else if(animal instanceof Antelope){
                    Antelope antelope = (Antelope) animal;
                    if(antelope.isAlive()) { 
                        antelope.setDead();
                        foodLevel = ANTELOPE_FOOD_VALUE;
                        return where;
                    }
                }            
            }
        }
        return null;
    }

