private void checkRaining()
    {
        if(!isRaining){
            if(rand.nextDouble() <= RAINING_PROBABILITY){
                isRaining = true;
                rainLength = rand.nextInt(MAX_RAIN_LENGTH) + 1;
            }//end of if start raining
        }//end of if not raining
        else{
            if(rainLength == 0){
                isRaining = false;
            }//end if raining ended
            else{
                rainLength--;
            }//end of else reduce rain length
        }//end of else raining

    }

