private void storm()
    {
        int fractionOfPopulation = actors.size() / 12;
        int count = 0;

        Collections.shuffle(actors);
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = (Actor) it.next();
            actor.setDead();
            it.remove();
            if (count == fractionOfPopulation) break;
            count++;
        }

    }

