function:
public void act(List<Animal> newBears, boolean isNight, String weather)
    {
        incrementAge();
        incrementHunger();

        if(isAlive()) {
            if(weather.equals("thunderstorm")){
                if(rand.nextDouble()<= LIGHTNING_DEATH){
                    setDead();  // Kill the bear if it is struck by lightning.
                }
                else{
                    defaultAct(newBears, isNight, false);
                }
            }
            else if(weather.equals("fog")) {
                defaultAct(newBears, isNight, true);
            }
            else if(!weather.equals("snow")){
                defaultAct(newBears, isNight, false);   // Act normally if it is not snowing due to hibernation.
            }
        }
    }

public void decreaseWaterLevel(){
        //newWaterLevel - passes updated value to set method in Organism class
        int newWaterLevel = getWaterLevel() - 1;
        setWaterLevel(newWaterLevel);
        if(getWaterLevel() <=0) {
            setDead();
        }
    }

public int breed(){
        int births = 0;
        // Each male animal could breed with any/all of the females of the same species around him.
        for ( int i = 0; i <= mates(); i++){
            if (canBreed() && getRand().nextDouble() <= getBreedingProb()) {
                births = getRand().nextInt(getMaxLitter()) + 1;
            }
        }
        return births;
    }

