@Override
    public boolean canBreed() {
        if (getAge() < getBreedingAge()) {
            return false;
        }

        for (Location loc : getField().adjacentLocations(getLocation())) {
            Object animal = getField().getObjectAt(loc);
            if (animal instanceof Elephant) {
                Elephant zebra = (Elephant) animal;
                if (!(((zebra.isMale() && isMale())) || ((!zebra.isMale() && !isMale())))) {
                    return true;
                }
            }
        }
        return false;
    }

private void putOutFire()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getWeatherLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object weather = field.getWeatherObjectAt(where);
            if(weather instanceof Fire) {
                Fire fire = (Fire) weather;
                if(fire.isActive()) {
                    fire.setInactive();        
                }
            }
        }
    }

