private String generateWeather()
    {
        Double probability = rand.nextDouble();

        if(probability < 0.4){
            weather = "sunny";
        }
        else if(0.4 <= probability && probability < 0.6){
            weather = "rain";
        }
        else if(0.6 <= probability && probability < 0.7){
            weather = "thunderstorm";
        }
        else if(0.7 <= probability && probability < 0.9){
            weather = "fog";
        }
        else{
            weather = "snow";
        }

        return weather;
    }

private boolean mateNearby(){
        boolean mateNearby = false;
        List<Location> adjacent = getField().adjacentLocations(getLocation());
        for(int i = 0; i < adjacent.size(); i++){
            Object nearbyAnimal = getField().getObjectAt(adjacent.get(i));
            if (nearbyAnimal instanceof Wolf) {
                Animal nearbyAnimal2 = (Wolf) nearbyAnimal;
                if (isMale() != nearbyAnimal2.isMale()){
                    mateNearby= true;
                }
            }
        }
        return mateNearby;
