private void tryAddRandomStructure(Location location) {
        for (Class<? extends EnvironmentalStructure> structureClass : parameters.getSimulatedStructures()) {
            try {
                EnvironmentalStructure instance = structureClass.getDeclaredConstructor(Field.class).newInstance(field);
                if (instance.createInstance(field.getCurrentWeather().getClass())) {
                    field.getStructuresAt(location).add(instance);
                }
            } catch (InvocationTargetException | InstantiationException | IllegalAccessException | NoSuchMethodException e) {
                e.printStackTrace();
            }
        }
    }

private void giveBirth(List<Animal> newSquirrels) {
        boolean containsMale = false;
        boolean maleInfected = false;
        Field field = getField();
        List<Location> free = field.adjacentLocations(getLocation());
        if (this.isFemale) {
            Iterator<Location> it = free.iterator();
            while (it.hasNext()) {
                Location where = it.next();
                Object animal = field.getObjectAt(where);
                if (animal instanceof Squirrel) {
                    Squirrel squirrel = (Squirrel) animal;
                    if (!squirrel.isFemale) {
                        containsMale = true;
                        if (squirrel.isInfected()) {
                            maleInfected = true;
                        }
                        break;
                    }
                }
            }
            if (containsMale) {
                int births = breed();
                List<Location> free1 = field.getFreeAdjacentLocations(getLocation());
                for (int b = 0; b < births && free1.size() > 0; b++) {
                    Location loc = free1.remove(0);
                    Squirrel young = new Squirrel(false, field, loc);
                    if (this.isInfected || maleInfected) {
                        young.getInfection();
                    }
                    newSquirrels.add(young);
                }
            }
        }
    }

public void simulateOneStep()
    {
        if(field.isNext()) {
            step++;
            field.loadNext();
            previousEntities.push(entities);
            entities = nextEntities.pop();
            view.showStatus(step, field);
            mapView.showStatus(field);
        } else {
            step++;
            // Provide space for newborn animals.
            List<Entity> newEntities = new ArrayList<>();
            // Let all entities act.
            for (Iterator<Entity> it = entities.iterator(); it.hasNext(); ) {
                Entity entity = it.next();
                entity.act(newEntities, clock.getCurrentTime(step));
                if (!entity.isAlive()) {
                    it.remove();
                }
            }

            // Add the newly born foxes and rabbits to the main lists.
            entities.addAll(newEntities);
            previousEntities.push(entities);
            view.showStatus(step, field);
            mapView.showStatus(field);

            //place current items in the stack
            field.savePrev();
        }
    }

