private void updateItemField()
    {
        for(int row = 0; row < itemField.getDepth(); row++){
            for(int col = 0; col < itemField.getWidth(); col++){
                ArrayList<Item> items = itemField.getItems(row, col);
                Iterator<Item> it = items.iterator();
                while(it.hasNext()){
                    Item item = it.next();
                    if(!item.everlasting()){
                        if(item.hasExpire()){
                            it.remove();
                        }else{
                            item.timeDecrement();
                        }
                    }
                }
            }
        }
    }

