private void setTerrainPath(Location place) {


        Terrain adjacent;

        Terrain epicentre;

        List<Location> locations;

        List<Location> epicentres = new LinkedList<>();

        epicentres.add(place);

        List<Location> newLocation = adjacentLocations(place) ;



        // make a mountain

        while(epicentres.size()>0){

            newLocation.clear();

            for(Location epicentreLoc : epicentres){

                epicentre = getTerrainAt(epicentreLoc);
                locations = adjacentLocations(epicentreLoc);

                for(Location next : locations){


                    adjacent = getTerrainAt(next.getRow(),next.getCol());

                    if(epicentre.getElevation() != 0 && adjacent.getElevation() == 0 && place.getRow() != 0 && place.getCol() !=0){


                        if(rand.nextDouble() <= getMaxCliffChance()){
                            adjacent.setElevation(epicentre.getElevation()-1);
                        }

                        else{
                            adjacent.setElevation(epicentre.getElevation());
                        }

                        if(adjacent.getElevation()>0){
                            if(!newLocation.contains(next)){
                             newLocation.add(next);
                            }
                        }


                    }

                }
            }
            epicentres.clear();
            for(Location plot : newLocation){
                epicentres.add(plot);
            }



        }

    }

docstring:
This is what the Reddy does most of the time: it hunts for
all animals except itself. In the process, it might breed, die of hunger,
die of old age, or sleep at night.
@param newReddies A list to return newly born Reddies.
@param isThereFog Whether fog is currently present in the environment.

function:
public void act(List<Animal> newReddies, boolean isThereFog)
    {
        incrementAge(MAX_AGE);
        if((Simulator.HOURS >= 5 && Simulator.HOURS < 16) || Simulator.HOURS > 20 || Simulator.HOURS < 1) {
            incrementHunger();
            if(isAlive()) {
                giveBirth(newReddies);
                Location newLocation;

                // Move towards a source of food if found.
                newLocation = findFood(preyList, REDDY_FOOD_VALUE);

                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }

                if(isThereFog) {
                    newLocation = getField().randomAdjacentLocation(getLocation());
                    eatRandomPrey(newLocation, preyList, REDDY_FOOD_VALUE);
                }

                if(getIsInfected()) {
                    spreadInfection(ADJACENT_SPREAD_PROBABILITY);
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setFieldLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

