@Override
    public void act(List<Actor> newCodds, boolean isDay, Weather weather) {

        if(isDay) {
            super.act(newCodds);

            if (weather == Weather.SUNNY) super.act(newCodds);

        }

        if(weather == Weather.STORM){
            if(isDay != DAY) {
                if (rand.nextDouble() < 0.1) setDead();
            }else{
                super.act(newCodds);
                if (rand.nextDouble() < 0.05) setDead();
            }
        }
    }

