private Location findFoodStorm()
        {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext()) {
                Location where = it.next();
                Object tempPlant = field.getObjectAt(where);
                if(tempPlant instanceof Plant) {
                    Plant plant = (Plant) tempPlant;
                    if(plant.isAlive()) { 
                        if(plant.getHeight() == 3){
                        plant.setDead();
                        foodLevel = PLANT_FOOD_VALUE+3;
                        return where;
                    }
                    else {

                        incrementHunger();
                        return null;

                         }
                    }
                }            
            }
            return null;
        }

