private boolean canBreed()
    {
        Field field = getField();
        Whale currentWhale = (Whale) field.getObjectAt(getLocation());
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Whale) {
                Whale matingWhale = (Whale) animal;
                if(currentWhale.isMale != matingWhale.isMale){
                    if(currentWhale.age >= BREEDING_AGE && matingWhale.age >= BREEDING_AGE){
                        return true;
                    }
                }
            }
        }
        return false;
    }

