function:
public Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        if(weather.equals("Fog")) //fish cannot eat when there is fog
        {
            return null;
        }
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Plants) {
                Plants plant = (Plants) animal;
                if(plant.isExisting()) { 
                    plant.remove();
                    foodLevel = PLANT_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object species1 = field.getObjectAt(where);
            Species species = (Species) species1;
            if( species != null && this.getFoodType().contains(species.getName())) {
                if(species.isAlive()) {

                    species.setDead();
                    foodLevel += species.getHealthValue();
                    if(species.isInfected())
                    {
                        this.getInfected();
                        FieldStats.incrementInfectionNumber();
                    }
                    return where;
                }
            }

        }
        return null;
    }

public void incrementHunger(){
        foodLevel--;
        if(foodLevel<=0){
