            Object animal = field.getObjectAt(where);
            if(animal instanceof Rhizomys) {
                Rhizomys rhizomys = (Rhizomys) animal;
                if(rhizomys.isAlive() && currentGender != rhizomys.getGender()){
                    giveBirth(newRhizomys);
                    return where;
                }
            }
        }
        return null;
    }

