docstring:
Try to decode details of the artist and the title
from the file name.
It is assumed that the details are in the form:
artist-title.mp3
@param file The track file.
@return A Track containing the details.

function:
private Track decodeDetails(File file)
    {
        // The information needed.
        String artist = "unknown";
        String title = "unknown";
        String filename = file.getPath();

        // Look for artist and title in the name of the file.
        String details = file.getName();
        String[] parts = details.split("-");

        if(parts.length == 2) {
            artist = parts[0];
            String titlePart = parts[1];
            // Remove a file-type suffix.
            parts = titlePart.split("\\.");
            if(parts.length >= 1) {
                title = parts[0];
            }
            else {
                title = titlePart;
            }
        }
        return new Track(artist, title, filename);
    }

docstring:
Look for any animal adjacent to the current location.
This can lead to the jaguar contracting the disease
@return Where disease was found, or null if it wasn't.

function:
private void isInfected()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Capybara) {
                Capybara capybara = (Capybara) animal;
                if(capybara.hasDisease() == true) { 
                    int chance= rand.nextInt(CHANCE_OF_INFECTION);
                    if(chance == 1)
                    {
                        disease = true;
                    } 

                }
            }
            if(animal instanceof Rat) {
                Rat rat = (Rat) animal;
                if(rat.hasDisease() == true) { 
                    int chance= rand.nextInt(CHANCE_OF_INFECTION);
                    if(chance < 1)
                    {
                    disease = true;
                    }   
                }
            }
            else if(animal instanceof Jaguar) {
                Jaguar jaguar = (Jaguar) animal;
                if(jaguar.hasDisease() == true) { 
                    int chance= rand.nextInt(CHANCE_OF_INFECTION);
                    if(chance < 1)
                    {
                    disease = true;
                    }   
                }
            }
            else if(animal instanceof Owl) {
                Owl owl = (Owl) animal;
                if(owl.hasDisease() == true) { 
                    int chance= rand.nextInt(CHANCE_OF_INFECTION);
                    if(chance < 1)
                    {
                    disease = true;
                    }   
                }
            }
            else if(animal instanceof Anaconda) {
                Anaconda anaconda = (Anaconda) animal;
                if(anaconda.hasDisease() == true) { 
                    int chance= rand.nextInt(CHANCE_OF_INFECTION);
                    if(chance < 1)
                    {
                    disease = true;
                    }   
                }    
            }
        }

    }

