public void simulateOneStep()
    {
        step++;
        time.incrementTimeCounter();

        // Provide space for newly created organisms (born or grown).
        List<Organism> newOrganism = new ArrayList<>();        
        // Let all organisms act.
        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
            Organism organism = it.next();
            organism.act(newOrganism, time.getIsDay());
            if(! organism.isAlive()) {
                it.remove();
            }
        }

        //checks all the empty cells after everyone has acted, if it is, chance to grow grass
        if(time.getIsDay()){
            for(int row = 0; row < field.getDepth(); row++) {
                for(int col = 0; col < field.getWidth(); col++) {
                    if(field.getObjectAt(row, col) == null){
                        if (rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                            Location location = new Location(row, col);
                            Grass grass = new Grass(field, location);
                            organisms.add(grass);
                        }
                    }
                }
            }
        }

        // Add the newly created animals to the main lists.
        organisms.addAll(newOrganism);

        //checks for changes to class variables which symbolise there has been a button click event
        if(weather.isStorm()){
            List<Organism> temp = weather.storm(organisms);
            organisms = temp;
            weather.setStormFalse();
        }

        if(disease.isOutbreak()){
            List<Organism> temp = disease.createOutbreak(organisms);
            organisms = temp;
            disease.setOutbreakFalse();
        }

        if(disease.isCure()){
            List<Organism> temp = disease.createCure(organisms);
            organisms = temp;
            disease.setOutbreakFalse();
        }

        //updates the display to show changes during step
        view.showStatus(step, field);
    }

