            if (isEdible(organism)) {
                return organism;
            }
        }
        return null;
    }

public void nextStep()
    {
        Random rng = new Random();

        // Rain Probabilities
        // Complete Drought: 0.5%;
        // No Rain = 15%;
        // Little Rain = 77%
        // Lot of Rain = 8%
        if (rng.nextDouble() < 0.005) {
            // complete drought
            rain = -1;
        }
        else if (rng.nextDouble() < 0.08) {
            // Lots of rain
            rain = 2 + rng.nextInt(3); // random number between 2 and 4
        } else if (rng.nextDouble() < 0.78) {
            // Little bit of rain
            rain = 1;
        } else {
            // No rain
            rain = 0;
        }


        // Sunlight Probabilities
        // No Sunlight = 4.5%;
        // Little Sunlight = 45%
        // Lot of Sunlight = 50%
        if (rng.nextDouble() < 0.05) {
            // No sunlight
            sunlight = 0;
        } else if (rng.nextDouble() < 0.5) {
            // Little bit of sunlight
            sunlight = 1;
        } else {
            // Lots of sunglight
            sunlight = 2 + rng.nextInt(3); // random number between 2 and 4
        }
    }

