public void showStatus(int step, Field field, WeatherGenerator weathergen) {
        if (!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object organism = field.getObjectAt(row, col);
                Location location = field.getLocationFromCoords(row, col);
                if (location.getCellType().equals("Water")) {
                    fieldView.drawMark(col, row, Color.BLUE);
                } else if (location.getCellType().equals("Shallow")) {
                    fieldView.drawMark(col, row, Color.CYAN);
                } else if (location.getCellType().equals("Grass")) {
                    fieldView.drawMark(col, row, Color.green);
                } else if (location.getCellType().equals("Mountain")) {
                    fieldView.drawMark(col, row, Color.DARK_GRAY);
                }

                if (organism != null) {
                    stats.incrementCount(organism.getClass());
                    fieldView.drawEntity(col, row, getColor(organism.getClass()));
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field) + "|| Weather " + weathergen.getWeather());
        fieldView.repaint();
    }

