public void reset()
    {
        step = 0;
        animals.clear();
        plants.clear();
        populateAnimal();
        populatePlant();
        time.reset();

        // Show the starting state in the view.
        view.showStatus(step, field, weather, time);
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= SALMON_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Salmon salmon = new Salmon(true, field, location);
                    creatures.add(salmon);
                }
                else if(rand.nextDouble() <= COD_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Cod cod = new Cod(true, field, location);
                    creatures.add(cod);
                }
                else if(rand.nextDouble() <= SEAWEED_CREATION_PROBABILITY){
                    Location location = new Location (row, col);
                    Seaweed seaweed = new Seaweed(true, field, location);
                    creatures.add(seaweed);
                }
                // else leave the location empty.
            }
        }
    }

public synchronized void simulateOneStep()
    {
        if(isRunning) {
            return;
        }

        isRunning = true;
        step++;

        Weather weather = Weather.getWeather();
        Time time = Time.getTimeOfDay(step);

        // Provide space for newborn organisms.
        List<Organism> newOrganisms = new ArrayList<Organism>();        
        // Let all organisms act.
        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
            Organism organism = it.next();
            organism.act(newOrganisms, weather, time);
            if(! organism.isAlive()) {
                it.remove();
            }
        }

        // Add the newly organisms to the main lists.
        organisms.addAll(newOrganisms);

        view.showStatus(step, field);
        isRunning = false;
    }

docstring:
Look for rabbits and hares adjacent to the current location.
Only the first live rabbit/hare is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object preyActor = field.getObjectAt(where);
            //Check whether object found is of appropriate food type.
            if(preyActor!= null && foodTypes.contains(preyActor.getClass().getSimpleName())) 
            {
                Actor prey = (Actor) preyActor;
                if(prey.isAlive()) { 
                    prey.setDead();
                    foodLevel = prey.getFoodValue();
                    return where;
                }
            }
        }
        return null;
    }

