public void act(List<Organism> newDolphins)
    {
        incrementAge();
        if (!isAwake()){
            return;
            //doesn't do anything if it's sleeping
        }

        incrementHunger();
        if(isAlive()) {
            // Check if it has ingested the max number of plastic it can handle
            if(plasticIntake>=MAX_PLASTIC_INTAKE){
                setDead();
                return;
            }
            giveBirth(newDolphins);
            // Move towards a source of food if found.
            Location newLocation = findFood();


            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

docstring:
Look for rabbits adjacent to the current location.
Only the first live rabbit is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            // Check if null:
            if (Objects.isNull(animal)) continue;

            if (foodChain.canEat((Organism<?>) animal)) {
                // if not hungry don't eat
                if (!this.isHungry()) continue;

                // Dynamic downcasting?
                Animal targetAnimal = (Animal) animal;
                if (targetAnimal.isAlive()) {
                    targetAnimal.setDead();
                    this.setFoodLevel(foodLevel += targetAnimal.getFoodValue());
                    return where;
                }
            }
        }
        return null;
    }

public boolean isViable()
    {
        return stats.isViable(animalManager.getField());
