private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Hyena) {
                Hyena hyena = (Hyena) animal;
                if(hyena.isAlive()) { 
                    hyena.setDead();
                    foodLevel = HYENA_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if(deer.isAlive()) { 
                    deer.setDead();
                    foodLevel = DEER_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Wildebeast) {
                Wildebeast wildebeast = (Wildebeast) animal;
                if(wildebeast.isAlive()) { 
                    wildebeast.setDead();
                    foodLevel = WILDEBEAST_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

