private void giveBirth(List<Animal> newSharks)
    {

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        int births = breed();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Shark) {
                Shark adjacentShark = (Shark) animal;
                if (adjacentShark.getIsMale() != getIsMale()) {
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Shark young = new Shark(false, field, loc);
                        newSharks.add(young);
                    }
                }
            }
        }
    }

public void incrementCount(Class organismClass)
    {
        Counter count = counters.get(organismClass);
        if(count == null) {
            // We do not have a counter for this organism yet.
            // Create one.
            count = new Counter(organismClass.getName());
            counters.put(organismClass, count);
        }
        count.increment();
    }

