This is what the Deer does most of the time - it runs
around and eats plants. Sometimes it will breed or die of old age or disease.
Deer can also be eaten by predators.
@param eventManager Object to check occuring events.
@param newDeers A list to return newly born Deer.

function:
public void act(List<Animal> newDeers, EventManager eventManager)
    {
        checkDisease();
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            findMate(newDeers); 
            // Try to move into a free location.
            Location newLocation = findFood(eventManager);
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                List<Location> free = getField().getFreeAdjacentLocations(getLocation());
                for(int i = 0; i < free.size() && newLocation == null; i++){
                    if(eventManager.isHabitableLocation(free.get(i))){
                        newLocation = free.get(i);
                    }//end of if is habitable
                }//end of for loop of free locations

                //debug 
                if(newLocation != null) {
                    Plant p = (Plant) getPlantField().getObjectAt(newLocation);
                    p.debugTriedEaten();
                }//end of if location is not null

            }//end of if location is null
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }//end if new location is not null
            else {
                // Overcrowding.
                setDead();
                death[1]++;
            }//end of else location is null
        }//end of if alive
    }

