public double act(List<Creature> newCods, boolean atDayTime, double oxygenLevel, boolean existDisease, int step)
    {   
        if(oxygenLevel < ANIMAL_OXYGEN_REQUIRED){
            setDead();
            return 0;
        }     

         // if disease occurs, the animal may be infected
        if((existDisease || checkNearbyInfected())){
            if(!getIsImmuned() && Math.random() <= INFECTION_RATE){
                setIsInfected(true);
                infectionStartStep = step;
            }
        }

        // if an animal is infected, it may die. Otherwise assume it gets immuntity from that disease.
        if(getIsInfected() && !getIsImmuned()){
            if(Math.random() <= MORTALITY_RATE  ){
                setDead();
                return 0;
            }
            else if(step-infectionStartStep>= 5){
                setIsImmuned(true);
            }
        }

        incrementAge();
        incrementHunger();

        if(isAlive() && !needSleep(atDayTime)) {
            giveBirth(newCods);            
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }

        }
        return -ANIMAL_OXYGEN_REQUIRED;
    }

