public void act(List<Actor> newTree, boolean day, WeatherType weather)
    {
        if(isAlive()) {
            switch(weather){
                case RAINY:
                incrementHeight(4);
                break;

                case CLEAR:
                incrementHeight(2);
                break;

                case CLOUDY:
                incrementHeight(1);
                break;
            }
        }
    }

