            else if(organism instanceof Turtle) {
                Turtle turtle = (Turtle) organism;
                if(turtle.isAlive()) { 
                    turtle.setDead();
                    foodLevel = PREY_FOOD_VALUE;
                    return where;
                }
            }

        }
        return null;
    }

