      }
    }
  }

private void setBoundary(int b, float[] x) {
        for (int i = 1; i < N - 1; i++) {
            x[weatherGrid(i, 0  )] = b == 2 ? -x[weatherGrid(i, 1  )] : x[weatherGrid(i, 1 )];
            x[weatherGrid(i, N-1)] = b == 2 ? -x[weatherGrid(i, N-2)] : x[weatherGrid(i, N-2)];
        }
        for (int j = 1; j < N - 1; j++) {
            x[weatherGrid(0, j)] = b == 1 ? -x[weatherGrid(1, j)] : x[weatherGrid(1, j)];
            x[weatherGrid(N-1, j)] = b == 1 ? -x[weatherGrid(N-2, j)] : x[weatherGrid(N-2, j)];
        }

        x[weatherGrid(0, 0)] = 0.5f * (x[weatherGrid(1, 0)] + x[weatherGrid(0, 1)]);
        x[weatherGrid(0, N-1)] = 0.5f * (x[weatherGrid(1, N-1)] + x[weatherGrid(0, N-2)]);
        x[weatherGrid(N-1, 0)] = 0.5f * (x[weatherGrid(N-2, 0)] + x[weatherGrid(N-1, 1)]);
        x[weatherGrid(N-1, N-1)] = 0.5f * (x[weatherGrid(N-2, N-1)] + x[weatherGrid(N-1, N-2)]);
    }

