private void giveBirth(List<Animal> newReddies)
    {
        Animal breedingAnimal = getBreedingAnimalAdjacent(breedingTypeList);

        if (breedingAnimal != null) {
            // New Reddies are born into adjacent locations.
            // Get a list of adjacent free locations.
            Field field = getField();
            List<Location> free = field.getFreeAdjacentLocations(getLocation());
            int births = getBreedNumber(age, BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);

            if (breedingAnimal instanceof Reddy) {
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    Reddy young = new Reddy(false, field, loc);
                    newReddies.add(young);
                }
            }
            else if (breedingAnimal instanceof Greeny) {
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    Yellowy young = new Yellowy(false, field, loc);
                    newReddies.add(young);
                }
            }
            else if (breedingAnimal instanceof Bluy) {
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    Purply young = new Purply(false, field, loc);
                    newReddies.add(young);
                }
            }

            // When an nfected aniaml breeds, it can spread the disease.
            if(getIsInfected()) {
                spreadInfection(BREED_SPREAD_PROBABILITY);
            }
        }
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();        
        field.clear();
        // Populate the field with animals.
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) { 
                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col, field.getAnimalLayer());
                    Lion lion = new Lion(true, field, location);
                    lion.setDisease(BORN_WITH_DISEASE_PROBABILITY);
                    lion.getDisease();
                    if(lion.getDisease()){
                        sickAnimals.add(lion);
                    }
                    animals.add(lion);
                }

                else if(rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
                    Location location = new Location(row, col, field.getAnimalLayer());
                    Wolf wolf = new Wolf(true, field, location);
                    wolf.setDisease(BORN_WITH_DISEASE_PROBABILITY);
                    wolf.getDisease();
                    if(wolf.getDisease()){
                        sickAnimals.add(wolf);
                    }
                    animals.add(wolf);
                }

                else if(rand.nextDouble() <= RINGTAIL_CREATION_PROBABILITY) {
                    Location location = new Location(row, col, field.getAnimalLayer());
                    Ringtail ringtail = new Ringtail(true, field, location);
                    ringtail.setDisease(BORN_WITH_DISEASE_PROBABILITY);
                    if(ringtail.getDisease()){
                        sickAnimals.add(ringtail);
                    }
                    animals.add(ringtail);
                }

                else if(rand.nextDouble() <= RAT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col, field.getAnimalLayer());
                    Rat rat = new Rat(true, field, location);
                    rat.setDisease(BORN_WITH_DISEASE_PROBABILITY);
                    if(rat.getDisease()){
                        sickAnimals.add(rat);
                    }
                    animals.add(rat);
                }
                else if(rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col, field.getAnimalLayer());
                    Deer deer = new Deer(true, field, location);
                    deer.setDisease(BORN_WITH_DISEASE_PROBABILITY);
                    if(deer.getDisease()){
                        sickAnimals.add(deer);
                    }
                    animals.add(deer);
                }

                // else leave the location empty.
            }
        }

        // Populate the field with plants.
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) { 
                if(rand.nextDouble() <= PLANTR_CREATION_PROBABILITY){
                    Location location = new Location(row, col, field.getPlantLayer());
                    PlantR plantR = new PlantR(true, field, location);
                    plants.add(plantR);
                    if(plantR.getHeight() >= plantR.getTallHeight()){
                        tallPlantCount ++;
                    }
                }

                else if(rand.nextDouble() <= PLANTD_CREATION_PROBABILITY){
                    Location location = new Location(row, col, field.getPlantLayer());
                    PlantD plantD = new PlantD(true, field, location);
                    plants.add(plantD);
                    if(plantD.getHeight() >= plantD.getTallHeight()){
                        tallPlantCount ++;
                    }
                }
            }
        }
    }

public void countFinished() {
		countsValid = true;
	}

public void act(List<Organism> newDDeer, boolean day)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            Location newLocation = null;
            giveBirth(newDDeer);
            if(day == false){
                // Move towards a source of food if found
                newLocation = findFood();
            }
            else{
                // Stay in the same location
                newLocation = this.getLocation();
            }
            if(newLocation == null) { 
                // Try to move to a free location
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                // Move to new location
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }

        }
        hydrated = false;
        bred = false;
    }

