private void giveBirth(List<Food> newBears)
    {
        // New Bears are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        if (getGender().equals("female")){
            List<Location> nearbyAnimals = field.adjacentLocations(getLocation());
            Iterator<Location> it = nearbyAnimals.iterator();
            while(it.hasNext()){
                Object animal = field.getObjectAt(it.next());
                if(animal instanceof Bear){
                    Bear nearbyBear = (Bear) animal;
                    if(nearbyBear.getGender().equals("male")){
                        List<Location> free = field.getFreeAdjacentLocations(getLocation());
                        int births = breed();
                        for(int b = 0; b < births && free.size() > 0; b++) {
                            Location loc = free.remove(0);
                            Object food = field.getObjectAt(loc);
                            if(food instanceof Grass) {
                                Grass grass = (Grass) food;
                                grass.setDead();
                            }
                            Bear young = new Bear(false, field,loc);
                            newBears.add(young);
                        }
                        return;
                    }
                }
            }
        }
    }

public void simulateOneStep()
    {
        step++;
        sim_weather();

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals, step, weather);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born foxes and rabbits to the main lists.
        animals.addAll(newAnimals);

        // Let all plants act.
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            plant.act(step, weather);
            if(! plant.isAlive()) {
                it.remove();
            }
        }

        view.showStatus(step, field, weather);
    }

private void randomizeTemperature()
    {
        int randomize = rand.nextInt(2);
        int change = rand.nextInt(currentSeason.getTempChange() + 1);
        Thermometer currentTemp = currentSeason.getCurrentTemp();

        // make sure that the temperature doesn't go beyond the temperature upper limit
        if (randomize == 0 && (getCurrentTemperature() + change) <= currentSeason.getUpperLimitTemp()) {
            currentTemp.incrementTemperature(change);
        }
        // make sure that the temperature doesn't go below the temperature lower limit
        else if(randomize == 1 && (getCurrentTemperature() - change) >= currentSeason.getLowerLimitTemp()) {
            currentTemp.incrementTemperature(- change);
        }
    }

