            int births = breed();
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                boolean sex = rand.nextBoolean();
                Predator young = new Dragon(false, field, loc, sex);
                newDragons.add(young);
            }
        }
    }

