private void populate()
    {
        Random random = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(random.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Plant plant = new Plant(field, location);
                    plants.add(plant);
                }
                else if(random.nextDouble() <= EAGLE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Eagle eagle = new Eagle(true, field, location);
                    animals.add(eagle);
                }
                else if(random.nextDouble() <= HAWK_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hawk hawk = new Hawk(true, field, location);
                    animals.add(hawk);
                    // else leave the location empty.
                }
                else if(random.nextDouble() <= SNAKE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Snake snake = new Snake(true, field, location);
                    animals.add(snake);

                }
                else if(random.nextDouble() <= LIZARD_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lizard lizard = new Lizard(true, field, location);
                    animals.add(lizard);
                }
                else if(random.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Mouse mouse = new Mouse(true, field, location);
                    animals.add(mouse);
                }
            }
        }
    }

protected void battleSickness() {
		if (sick) {
			if (sickStep >= maxSickStep) {
				setDead();
				return;
			}
			sickStep++;
			Field field = getField();
			if (field != null) {
				List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
				Iterator<Location> it = adjacent.iterator();
				while (it.hasNext()) {
					Location where = it.next();
					Object animal = field.getAnimalAt(where);
					if (animal instanceof Animal) {
						Animal nearAnimal = (Animal) animal;
						if (nearAnimal.getClass().equals(this.getClass())) {
							nearAnimal.becomeSick();
						}
					}
				}
				this.notSick();
			}
		} else {
			becomeSick();
		}
	}

public void propagate(List<Actor> newPlants)
    {
        if (!(getEvents().weather.SNOWY == getEvents().getWeather())) //Plants can't reproduce in the snow
        {
            List<Location> free = getLandscape().getFreeAdjacentLocations(getLocation()); //Generates the free locations around the plant
            if(free.size() > 1){
                Location loc = free.get(getRand().nextInt(free.size()-1)); //Gets a random location from the ones that are free
                try
                {
                    //Obtains the class of the plant
                    Class cls = this.getClass(); 
                    //Creates a constructor for the class of the plant
                    Constructor ct = cls.getConstructor(Field.class,Location.class,Field.class,Events.class);
                    //Creates an actor using the constructor
                    Actor retObj = (Actor) ct.newInstance(getField(),loc,getLandscape(), getEvents());
                    //Adds it to newPlants
                    newPlants.add(retObj);
                }
                catch(Throwable e)
                {
                    System.out.println(e);
                }
            }
        }
    }

public void giveBirth(List<Animal> newLeopard) {


        //find locations nearby which are free
        Field field = getField();
        List<Location> adjacentLocations = field.adjacentLocations(getLocation());
        List<Location> freeAdjacentLocations = field.getFreeAdjacentLocations(getLocation());
        boolean mateNearby = false;


        //get animals nearby that are ready to breed
        for (Location next : adjacentLocations) {
            if (field.getObjectAt(next) != null) {

                if (canBreed(this, (Animal) field.getObjectAt(next))) {
                    mateNearby = true;
                }
            }
        }

        //randomly give birth to offspring
        if (mateNearby) {
            int births = rand.nextInt(MAX_LITTER_SIZE) + 1;

            //add new offspring to new animal list
            for (int i = 0; i < births && freeAdjacentLocations.size() > 0; i++) {
                Location loc = freeAdjacentLocations.remove(0);
                Leopard young = new Leopard(false, field, loc);
                newLeopard.add(young);


            }
        }
    }

