public void simulateOneStep()
    {
        step++;

        int hourOfDay = time.getHour();
        // Provide space for newborn actors.
        List<Actor> newActors = new ArrayList<>();        
        // Let all actors act.
        actors.forEach(actor -> actor.act(newActors, hourOfDay, animals));
