if it can breed.
@return The number of births (may be zero).
@overrdie from actor super-class

function:
protected int breed()
    {
        int births = 0;
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Coyote) {
                Coyote coyote = (Coyote) animal;
                //check of the mate or this animal itself has more virus than the thresold
                //if true then kill both animals
                if (coyote.VIRUS_PROBABILITY>=coyote.Virus || VIRUS_PROBABILITY>=Virus){
                    setDead();
                    coyote.setDead();
                }else{
                    if(getWhetherAMale() && !coyote.getWhetherAMale()){
                        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
                            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
                        }
                    }else if(!getWhetherAMale() && coyote.getWhetherAMale()){
                        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
                            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
                        }
                    }
                }
            }
        }
        return births;
    }

