function:
public void act(List<Organism> newBears)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            giveBirth(newBears);
            if(Simulator.dayCycle != 3) {
                // Move towards a source of food if found.
                Location newLocation = findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

public void act(List<Organism> newDeer, boolean day)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            Location newLocation = null;
            if(day == true) {
                // Move towards a source of food if found
                newLocation = findFood();
                // Give birth if possible
                giveBirth(newDeer);
            }
            else {
                // Stay in the same location
                newLocation = this.getLocation();
            }
            if(newLocation == null) { 
                // Try to move to a free location
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            // Check whether new location has disease in it
            if(newLocation !=null && checkIfDiseased(newLocation)) {
                    // Check whether this disease has an effect
                    becomeDiseased(newDeer,newLocation);
                }
            else if(newLocation !=null) {
                    // Move to new location
                    setLocation(newLocation);
                }
            else {
                // Overcrowding.
                setDead();
            }
        }
        hydrated = false;
        bred = false;
    }

