public void incrementCount(Class animalClass, Object object)
    {
        Counter count = counters.get(""  + animalClass);
        Counter diseaseCount = counters.get("" + animalClass + " Diseased");
        if(count == null && diseaseCount == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(animalClass.getName());
            diseaseCount = new Counter(animalClass.getName() + " Diseased");
            counters.put("" + animalClass , count);
            counters.put("" + animalClass + " Diseased", diseaseCount);
        }

        if (object instanceof Lethal) {
            Lethal diseaseCarrier = (Lethal) object;
            if (diseaseCarrier.getIsDiseased()) {
                diseaseCount.increment();
            }
        }

        count.increment();
    }

