public String getInfectedPopulationDetails(Field field, Class animalKey)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field);
        }

        int temp=0;
        for(Class key: infectedCounters.keySet()) {
            if(key==animalKey) {
                Counter info = infectedCounters.get(key);
                buffer.append(info.getInfectedCount());
                temp++;
            }
        }   
        if(temp == 0) {
            buffer.append(0);
        }
        temp = 0;

        return buffer.toString();
    }

