protected int reproduce()
    {
        int births = 0;
        double chance = rand.nextDouble();

        // Increase the chance of new plants if raining.
        if (isRaining) {
            chance = chance * 0.9;
        }
        if(chance <= getPollinationProbability()) {
            births = rand.nextInt(getMaxOffspring()) + 1;
        }
        return births;
    }

