New births will be made into free adjacent locations.
@param newOctopus A list to return newly born octopus.

function:
private void giveBirth(List<Animal> newOctopus)
    {
        // New rabbits are born into adjacent locations.
        // Get a list of adjacent free locations.
        List<Octopus> adjacentOctopus = new ArrayList<>();
        Field field = getField();
        List<Location> octopusCheck = field.adjacentLocations(getLocation());
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();

        for (int i = 0; i < octopusCheck.size(); i++) {  
            if(field.getObjectAt(octopusCheck.get(i)) instanceof Octopus) {
                Octopus newoctopus = Octopus.class.cast(field.getObjectAt(octopusCheck.get(i)));
                adjacentOctopus.add(newoctopus);
            }
        }

        for (int j = 0; j < adjacentOctopus.size(); j++) {            
            if (adjacentOctopus.get(j).IS_FEMALE != this.IS_FEMALE) {
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    if(this.disease == true){
                        Octopus young = new Octopus(false, true, false, field, loc);
                        newOctopus.add(young);
                    }
                    else{
                        Octopus young = new Octopus(false, true, true, field, loc);
                        newOctopus.add(young);
                    }
                }    
            }
        }
    }

