docstring:
Look for food adjacent to the current location.
Only the first live animal is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location search(Disease disease)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object creature = field.getObjectAt(where);
            // Infect nearby animal if this animal has already been infected.
            if(creature instanceof Animal) {
                Animal animal = (Animal) creature;
                if(animal.getInfectionStatus() == true) {
                    infectAnimal(disease);
                }
            }
            if(creature instanceof Rat) {
                Rat rat = (Rat) creature;
                if(rat.isAlive()) { 
                    rat.setDead();
                    foodLevel = RAT_FOOD_VALUE;
                    return where;
                }
            }
            if(creature instanceof Deer) {
                Deer deer = (Deer) creature;
                if(deer.isAlive()) { 
                    deer.setDead();
                    foodLevel = DEER_FOOD_VALUE;
                    return where;
                }
            }
            if(creature instanceof Hayena) {
                Hayena hayena = (Hayena) creature;
                if(hayena.isAlive()) { 
                    hayena.setDead();
                    foodLevel = HAYENA_FOOD_VALUE;
                    return where;
                }
            }
            if(creature instanceof Wolf) {
                Wolf wolf = (Wolf) creature;
                if(wolf.isAlive()) { 
                    wolf.setDead();
                    foodLevel = WOLF_FOOD_VALUE;
                    return where;
                }    
            }
            if(creature instanceof Grass) {
                Grass grass = (Grass) creature;
                if(grass.isAlive()) { 
                    grass.setDead();
                    return where;
                }
            }
        }
        return null;
    }

private void reactToWeather()
    {
        double temperature = plantField.getWeathers().get(0).
            getTemperature();
        double humidity = plantField.getWeathers().get(0).
            getHumidity();
        height = height + (humidity * temperature);
    }

