@Override
	public List<Moss> act(Weather currentWeather)
	{
		ArrayList<Moss> newMosses = new ArrayList<>();

		switch(currentWeather) {
			case RAINING:
				newMosses.addAll(spread(rand.nextInt(MAX_SPREAD + 1)));
				break;
			case DROUGHT:
				dry(); // dries up in drought
				break;
			default:
				dry();
				break;
		}

		return newMosses;
	}

