protected double getActivity() {
        double activity = 1.0;

        Environment environment = getEnvironment();
        Environment.Weather weather = environment.getWeather();
        switch (weather) {
            case SUN:
                break;
            case FOG:
                activity *= 0.75;
                break;
            case RAIN:
                activity *= 0.75;
                break;
            default:
                break;
        }

        if (hasDisease(Flu.class)) {
            activity *= 0.6;
        }

        if (!environment.isDaytime()) {
            activity *= 0.5;
        }
        return activity;
    }

protected Location findFood (){
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Species specimen = field.getObjectAt(where);
            if(isFoodType(specimen) && specimen.isAlive()) {
                incrementGerms(specimen.getGerms());
                eatFood(specimen.getNutrients());
                specimen.setDead();
                return where;
            }
        }
        return null;
    }

