private Location findFood(List<Species> newzombiees)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Human) {
                Human human = (Human) animal;
                if(human.isAlive()&&(rand.nextDouble() <= BREEDING_PROBABILITY)) {
                    human.setDead();
                    Zombie young = new Zombie(false, getField(), this.getLocation());
                    newzombiees.add(young);
                    return where;
                }
            }
        }
        return null;
    }

