public void showStatus(int step, Field field, String weather)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        weatherLabel.setText(WEATHER_PREFIX + weather);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public void simulateOneStep()
    {
        step++;
        time.incrementTime();
        int currentTime = time.getHour();

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Animals act only during the specific time.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            if(animal instanceof Bear){
                if((currentTime >= 8) && (currentTime <= 21)){
                    animal.act(newAnimals);
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }
            }else if(animal instanceof Tiger){
                if(currentTime >= 18 || currentTime <= 5){
                    animal.act(newAnimals);
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }
            }else if(animal instanceof Wolf){
                if(currentTime >= 20 || currentTime <= 9){
                    animal.act(newAnimals);
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }
            }else if(animal instanceof Deer){
                if(currentTime >= 4 && currentTime <= 20){
                    animal.act(newAnimals);
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }
            }else if(animal instanceof Rabbit){
                if(currentTime >= 8 && currentTime <= 21){
                    animal.act(newAnimals);
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }
            }
        }

        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);

        view.showStatus(step, field, currentTime);
    }

