function:
private Location findFood()
    {
        Field field = getPlantsField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
                Location where = it.next();
                Object plant = field.getObjectAt(where);
                if(plant instanceof Grass) {
                    Grass grass = (Grass) plant;
                    if(grass.isAlive()) {
                        grass.setDead();
                        grassFoodValue = grass.getFoodValue();
                        foodLevel = (int) Math.round(grassFoodValue);
                        return where;
                    }
                }
                else if(plant instanceof Corn) {
                    Corn corn = (Corn) plant;
                    if(corn.isAlive()) {
                        corn.setDead();
                        cornFoodValue = corn.getFoodValue();
                        foodLevel = (int) Math.round(cornFoodValue);
                        return where;
                    }
                }
        }
        return null;
    }

