public void simulateOneStep()
   {
      step++;  

      Random rand = Randomizer.getRandom();
      // Generate a random weather.
      rain = rand.nextBoolean();


      // Provide space for new organisms.
      List<Organism> newOrganisms= new ArrayList<>();        
      // Let all Organisms act.

      for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
          Organism organism = it.next();
          organism.act(newOrganisms,view.dayTime(), rain);
          if(!organism.isAlive()) {
             it.remove();
          }        
          if(organism instanceof Animal)
          {
              Animal animal = (Animal) organism;
              animal.matedThisStep = false;
          }
          if(organism instanceof Plant)
          {
              Plant plant = (Plant) organism;                    
          }
      }

      if(rain && view.dayTime()&& step%2 == 0) {
          populatePlants();
      }

      if(step%10 == 0) {
         view.changeEmptyColor();              
      }

      // Add the newly born wolves and mooses to the main lists.
      organisms.addAll(newOrganisms);

      view.showStatus(step, field, rain);
   }

