public void simulateOneStep()
    {
        Timer.increment();

        // Provide space for newborn animals.
        for (int i = 0; i < field.getDepth(); i++) {
            for (int j = 0; j < field.getWidth(); j++) {
                Tile tile = field.getTileAt(i, j);
                tile.update();
            }
