private Location chargePredator()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        List<Location> charge = new ArrayList<>();

        adjacent.forEach(where ->{
                Object actor = field.getObjectAt(where);
                HashSet<Class> setOfPredators = MAP_OF_PREDATORS.get(this.getClass());
                if(actor!=null && setOfPredators.contains(actor.getClass())){
                    if(rand.nextDouble() <= ATTACK_CHANCE){
                        Animal prey = (Animal) actor;
                        if(prey.isAlive()) { 
                            prey.setDead();
                            foodLevel += prey.getFoodValue();
                            charge.add(where);
                        }
                    }
                }
            });

        if(!charge.isEmpty()){
            return charge.get(0);
        }

        return null;
    }

private void tryAddRandomDisease(Location location) {
        for (Class<? extends EnvironmentalFactor> diseaseClass : parameters.getSimulatedDiseases()) {
            try {
                Disease instance = (Disease) diseaseClass.getDeclaredConstructor().newInstance();
                if (instance.createInstance()) {
                    field.getFactorsAt(location).add(instance);
                }
            } catch (InvocationTargetException | InstantiationException | IllegalAccessException | NoSuchMethodException e) {
                e.printStackTrace();
            }
        }
    }

