public void act(List<Animal> newAnimals, ClockDisplay clock){
        incrementAge();
        incrementHunger();
        if (timeAffect(clock)){
            if (hasDisease()){
               disease.act(this);
               }
            Location newLocation = null;
            if(isAlive()) {           
                // Move towards a source of food if found.
                if ((double)foodLevel / get_MAX_FOOD_LEVEL() <= 0.6){   //only hunt for food if the animal is hungry by 40%
                    newLocation = findFood();
                }

                if ((double)foodLevel / get_MAX_FOOD_LEVEL() >= 0.6 && findMate()){   //only look for mate if animal is at least 60% full
                    giveBirth(newAnimals);
                }

                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

docstring:
Make animal do whatever it needs to

@param newAnimals  A list to receive newly born animals
@param isDay       Is it day or night

function:
public void act(List<Organism> newAnimals, boolean isDay) {
        incrementAge();
        incrementHunger();
        incrementMoveBufferProgress();
        // If animal is alive and active (some are inactive at night)
        if (isAlive() && isActive(isDay)) {
            // Only females search for a mate for efficiency
            if (isFemale && canMove()) {
                findMate(newAnimals);
            } else if (getAsexualBreedingProbability() != 0) {
                //System.out.println(getName() + " is trying to give birth asexually");
                giveBirth(newAnimals);
            }
            // Move towards a source of food if found.
            // If animal can't move, will search for plants 
            // in its current location (if the aninmal eats plants)
            Location newLocation = findFood();
            if (canMove()) {
                if (newLocation == null) {
                    // No food found - try to move to a free location.
                    newLocation = getPhysicalField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

