protected double getActivity() {
        double activity = 1.0;

        Environment environment = getEnvironment();
        Environment.Weather weather = environment.getWeather();
        switch (weather) {
            case SUN:
                break;
            case FOG:
                activity *= 0.7;
                break;
            case RAIN:
                activity *= 0.7;
                break;
            default:
                break;
        }

        if (hasDisease(Flu.class)) {
            activity *= 0.5;
        }

        if (!environment.isDaytime()) {
            activity *= 0.4;
        }
        return activity;
    }

