            if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if(deer.isAlive()) { 
                    deer.setDead();
                    foodLevel = TOTAL_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

