private void giveBirth(List<Organism> newDeer)
    {
        // New Deer are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> adjacent = field.surroundingLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        while(it.hasNext()) {
            Location where = it.next();
            Object Organism = field.getObjectAt(where);
            if(Organism instanceof Deer) {
                Deer organism = (Deer) Organism;
                if(isMale!=organism.getGender()) {
                    if(organism.isAlive()) { 
                        organism.setBred();//means this organism cannot breed twice
                        int births = breed();
                        for(int b = 0; b < births && free.size() > 0; b++) {
                            Location loc = free.remove(0);
                            Deer young = new Deer(false, field, loc);
                            newDeer.add(young);
                        }
                    }
                }
            }
        }
    }

