private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) {
            Location where = it.next();
            Object plantNear = field.getObjectAt(where);
            if(plantNear instanceof Plant) {
                Plant plant = (Plant) plantNear;
                competeForfood(plant);
                if(plant.isAlive()) {
                    plant.decreaseFoodLevel();
                    if (!plant.isAlive())
                        return where;
                    break;
                }
            }
        }
        return null;
    }

