public void incrementTime()
    {
        minute = minute + step;

        // While loop is there to allow steps of more than 60 minutes.
        while(minute >= 60) {
            minute = minute - 60;
            hour++;
        }

        // ... and in this case, multi-day steps.
        while(hour >= 24) {
            hour = hour - 24;
            dayNumber++;
        }

        if(dayNumber >= seasonDuration) { // Do season change.
            season = (season + 1) % 4;
            dayNumber = 0;
        }
    }

