        switchWeather();

        // Provide space for newborn newAnimals.
        List<NewAnimal> newnewAnimals = new ArrayList<>();
        // Provide space for newborn plants.
        List<Plant> newPlants = new ArrayList<>();
        // Let all plants act.
        for(Iterator<Plant> myPlant = plants.iterator(); myPlant.hasNext(); ) {
            Plant plant = myPlant.next();
            plant.act(newPlants);
            if(! plant.isAlive()) {
                myPlant.remove();
            }
        }
        // Let all newAnimals act.
        for(Iterator<NewAnimal> myAnimal = newAnimals.iterator(); myAnimal.hasNext(); ) {
            NewAnimal animal = myAnimal.next();
            animal.act(newnewAnimals);
            if(! animal.isAlive()) {
                myAnimal.remove();
            }

        }

        // Add the newly born foxes and rabbits to the main lists.
        newAnimals.addAll(newnewAnimals);
        // Add the newly plants to the main lists.
        plants.addAll(newPlants);


        view.showStatus(step, field);
    }

