Only the first live rabbit is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object foodSource = field.getObjectAt(where);
            if(foodSource instanceof Shrimp) {
                Shrimp shrimp = (Shrimp) foodSource;
                if(shrimp.isAlive()) { 
                    shrimp.setDead();
                    foodLevel += SHRIMP_FOOD_VALUE;
                    return where;
                }
            }
            if(foodSource instanceof SeaWeed) {
                SeaWeed seaWeed = (SeaWeed) foodSource;
                if(seaWeed.isAlive()) { 
                    seaWeed.setDead();
                    foodLevel += SEA_WEED_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

public void step(){
        simulationField.clear(location);
        if (validAge()){
            environmentField.place(this, location);
            age = age + 1;
        } else {
            isPolluting = false;
        }
    }

private int breed()
    {
        int births = 0;
        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) {
            Field field = getField();
            boolean genderNow = checkGender();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext()) {
                Location where = it.next();
                Object animal = field.getObjectAt(where);

                if(animal instanceof Deer) {
                    Deer deer = (Deer) animal;
                    if(deer.checkGender() != genderNow) {
                        births = rand.nextInt(MAX_LITTER_SIZE) + 1;
                    }
                }
            }
        }
        return births;
    }

private void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
