private void findPartner(List<Actor> newAnimal)
    {        
        Field field = getField();
        List<Location> adjacent = field.rangeLocations(getLocation());

        Object currentAnimal = field.getObjectAt(getLocation()); 

        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object potentialPartner = field.getObjectAt(where);

            if(potentialPartner instanceof Giraffe){
                Giraffe partnerGiraffe = (Giraffe) potentialPartner;
                Giraffe thisGiraffe = (Giraffe) currentAnimal;

                if (thisGiraffe.checkForFemale() != partnerGiraffe.checkForFemale()){
                    giveBirth(newAnimal);
                }
            }
        }
    }

