public void simulateOneStep() {
        step++;
        boolean nightTime = environment.incrementTime();
        int dayNumber = environment.getDayNumber();
        String seasonName = environment.getSeasonName();
        environment.generateWeather();
        boolean sunny = environment.isSunny();
        boolean raining = environment.isRaining();

        // Provide space for new wildlife
        List<Wildlife> newWildlife = new ArrayList<>();
        // Let all wildlife act.
        for (Iterator<Wildlife> it = wildlife.iterator(); it.hasNext(); ) {
            Wildlife wildlife = it.next();
            if (!wildlife.isAlive()) {
                it.remove();
            } else {
                if (nightTime && wildlife.isNocturnal() || !nightTime && !wildlife.isNocturnal())
                    wildlife.act(newWildlife, sunny, raining);
            }

        }

        // Add the newly born wildlife to the main lists.
        wildlife.addAll(newWildlife);

        view.showStatus(step,dayNumber, seasonName, field);
    }

