@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, boolean timeOfDay, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }
        String displayTime = "";
        if (timeOfDay == true){
            displayTime = "Day";
        }
        else{
            displayTime = "Night";
        }

        stepLabel.setText(STEP_PREFIX + step);
        dayLabel.setText(DAY_PREFIX + displayTime);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object organism = field.getObjectAt(row, col);
                if(organism != null) {
                    stats.incrementCount(organism.getClass());
                    fieldView.drawMark(col, row, getColor(organism.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

protected void giveBirth(List<Actor> newActor)
    {
        List<Location> free = field.getFreeAdjacentLocations(location);
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) 
        {
            Location loc = free.remove(0);
            try
            {
                Constructor constructor = getClass().getConstructor(new Class[]{boolean.class,Field.class,Location.class,Ground.class});
                Actor actor = (Actor)constructor.newInstance(true,field,location,ground);
                newActor.add(actor);
                setGender(actor);
            }
            catch (InstantiationException e) 
            {
                e.printStackTrace();
            }
            catch (NoSuchMethodException e) 
            {
                e.printStackTrace();
            }
            catch (IllegalAccessException e) 
            {
                e.printStackTrace();
            } catch (IllegalArgumentException e) 
            {
                e.printStackTrace();
            } catch (InvocationTargetException e) 
            {
                e.printStackTrace();
            }
        }
    }

