public void showStatus(int step, Field field)
    {
        if(!isVisible()) 
        {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();
        //String for weather condition
        String weather;
        if (Condition.getWeather() == 0)
            weather = "drought";
        else if (Condition.getWeather() == 1)
            weather = "normal";
        else 
            weather = "wet";

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) 
        {
            for(int col = 0; col < field.getWidth(); col++) 
            {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) 
                {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else 
                {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();
        //add time and weather information at the bottom of the window.
        downwardinfo.setText(POPULATION_PREFIX + stats.getPopulationDetails(field)+ WEATHER_PREFIX + weather + " " + TIME_PREFIX + Condition.getHours());
        fieldView.repaint();
    }

