public void act(List<Animal> newAntelopes)
        {
            super.incrementAge();
        super.incrementHunger();
        if(isAlive()) {
            if(super.male==true){
                Field field = getField();
                List<Location> adjacent = field.adjacentLocations(getLocation());
                Iterator<Location> it = adjacent.iterator();
                while(it.hasNext()) {
                    Location where = it.next();
                    Object animal = field.getObjectAt(where);
                    if(animal instanceof Prey) {
                        Prey antelopes = (Prey) animal;
                        if(antelopes.male==false) { 
                            giveBirth(newAntelopes);
                        }
                    }
                }
            }
            if(super.male==false){
                Field field = getField();
                List<Location> adjacent = field.adjacentLocations(getLocation());
                Iterator<Location> it = adjacent.iterator();
                while(it.hasNext()) {
                    Location where = it.next();
                    Object animal = field.getObjectAt(where);
                    if(animal instanceof Prey) {
                        Prey antelopes = (Prey) animal;
                        if(antelopes.male==true) { 
                            giveBirth(newAntelopes);
                        }
                    }
                }
            }          
            // Try to move into a free location.
            if (Weather.getWinds() == true && Simulator.getStep() % 2 ==0) {//antalope does not move in the high winds 
            }
            else{
                // Move towards a source of food if found.
                Location newLocation = super.findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

protected boolean findCouple()
    {
        if(field == null){
            return false;
        }
        // find couple in larger range if failed breed
        List<Location> adjacent = field.adjacentLocations(getLocation(), failBreed * speed + 1);
        for(Location where : adjacent) {
            Species species = (Species)field.getObjectAt(where);
            if(species != null && species.getClass() == this.getClass() && species.gender == gender){
                failBreed = 0;
                return true;
            }
        }
        failBreed++;
        return false;
    }

