public void act(List<Organism> newHawks, Weather weather, Time time)
    {
        incrementAge();
        decrementFoodLevel();
        decrementPower();
        if (isAlive()) {
            giveBirth(newHawks);
            // Move towards a source of food if found.
            Location newLocation = findFood();
            // Check if the hawk is still alive, otherwise don't move.
            if (newLocation == null && isAlive()) {
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if (newLocation != null) {
                setLocation(newLocation);
                if(isInfected()) {
                    infectOthers();
                }
            } else {
                // Overcrowding.
                setDead();
            }
        }

        heal();
    }

