public void simulateOneStep()
    {
        step++;
        timeOfDay = setTime(step);
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all animals act. Their behaviour may change in the Day and at Night
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            if((timeOfDay.equals("Day")) && (animal.isAlive())){
                animal.act(newAnimals);
            }

            if ((timeOfDay.equals("Night")) && (animal.isAlive())){
                animal.Nightact(newAnimals);
            }

            if(! (animal.isAlive())) {
                it.remove();
            }
        }
        //add new born animals to the list
        animals.addAll(newAnimals);

        List<Grass> newPlants = new ArrayList<>();        
        // Let all plants grow.
        for(Iterator<Grass> it = plants.iterator(); it.hasNext(); ) {
            Grass grass = it.next();
            grass.grow(newPlants);
            if(! (grass.isAlive())) {
                it.remove();
            }
        }
        //add new plants to the list.
        plants.addAll(newPlants);

        view.showStatus(step, field,timeOfDay);
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Plant plant = new Plant(field, location);
                    organisms.add(plant);
                }
                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Zebra zebra = new Zebra(field,location,rand.nextBoolean());
                    organisms.add(zebra);
                }
                else if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lion lion = new Lion(field,location,rand.nextBoolean());
                    organisms.add(lion);
                }
                else if(rand.nextDouble() <= LEOPARD_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Leopard leopard = new Leopard(field,location,rand.nextBoolean());
                    organisms.add(leopard);
                }
                else if(rand.nextDouble() <= HYENA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hyena hyena = new Hyena(field,location,rand.nextBoolean());
                    organisms.add(hyena);
                }
                else if(rand.nextDouble() <= ANTELOPE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Antelope antelope = new Antelope(field,location,rand.nextBoolean());
                    organisms.add(antelope);
                }
                // else leave the location empty.
            }
        }
    }

