private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Wolf wolf = new Wolf(true, field, location);
                    Actors.add(wolf);
                }
                else if(rand.nextDouble() <= LYNX_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lynx lynx = new Lynx(true, field, location);
                    Actors.add(lynx);
                }
                else if(rand.nextDouble() <= RABBIT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Rabbit rabbit = new Rabbit(true, field, location);
                    Actors.add(rabbit);
                }
                else if(rand.nextDouble() <= HARE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hare hare = new Hare(true, field, location);
                    Actors.add(hare);
                }

                else if(rand.nextDouble() <= TREE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Tree tree = new Tree(true, field, location);
                    Actors.add(tree);
                }
                else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(true, field, location);
                    Actors.add(grass);
                }
                // else leave the location empty.
            }
        }
    }

private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object plant = field.getObjectAt(where);
            if(plant instanceof Seaweed) {
                Seaweed seaweed = (Seaweed) plant;
                if(seaweed.isAlive()) { 
                    seaweed.reduceAmount();
                    foodLevel = SEAWEED_FOOD_VALUE;
                    return where;
                }
            } 
        }
        return null;
    }

protected void findMate(List<Animal> newSeaLions)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof SeaLion) {
                SeaLion mate = (SeaLion) animal;
                if(mate.isAlive() && mate.isMale() != this.isMale()) { 
                    giveBirth(newSeaLions);
                }
            }
        }
    }

