private void infectNearbyAnimals() 
    {
        // don't run the method with invalid field and location
        if (location == null || field == null) {
            return;
        }
        // return if the disease is only spread by birth
        if (disease.getTransmissionType() == Disease.TransmissionType.BIRTH) {
            return;
        }
        // get nearby animals
        List<Animal> nearbyAnimals = field.getNearbyAnimals(field, location);
        int diseaseProbability = Simulator.rand.nextInt(3);
        if (diseaseProbability >= 1) {
            // infect all nearby animals
            for (Animal animal : nearbyAnimals) {
                if (disease.getIsSpeciesDependent()) {
                    // infect only the animals which are the same species as this animal
                    if (animal.animalType == this.animalType) {
                       animal.setDiseased(this.disease);
                    }
                } else {
                    // infect everything
                    animal.setDiseased(this.disease);
                }
            }
        }
    }

