function:
public void showStatus(int step, Field field, NatureField natureField, String time)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        timeLabel.setText(TIME_PREFIX + time);
        weatherLabel.setText(WEATHER_PREFIX + weather.getWeatherInformation());
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    if(animal instanceof Animal) {
                        Animal currentAnimal = (Animal) animal;
                        if (currentAnimal.getIsInfected()) {
                            stats.infectedIncrementCount(animal.getClass());
                        }
                    }
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    Object nature = natureField.getObjectAt(row, col);
                    if (nature instanceof Weed) {
                        fieldView.drawMark(col, row, getColor(nature.getClass()));
                    }
                    else {
                        fieldView.drawMark(col, row, EMPTY_COLOR);
                    }
                }
            }
        }
        stats.countFinished();


        populationTable.setValueAt(stats.getPopulationDetails(field, new Reddy().getClass()), 0, 1);
        populationTable.setValueAt(stats.getPopulationDetails(field, new Purply().getClass()), 0, 2);
        populationTable.setValueAt(stats.getPopulationDetails(field, new Yellowy().getClass()), 0, 3);
        populationTable.setValueAt(stats.getPopulationDetails(field, new Greeny().getClass()), 0, 4);
        populationTable.setValueAt(stats.getPopulationDetails(field, new Cyany().getClass()), 0, 5);
        populationTable.setValueAt(stats.getPopulationDetails(field, new Bluy().getClass()), 0, 6);
        populationTable.setValueAt(stats.getPopulationDetails(field, new Tree().getClass()), 0, 7);

        populationTable.setValueAt(stats.getInfectedPopulationDetails(field, new Reddy().getClass()), 1, 1);
        populationTable.setValueAt(stats.getInfectedPopulationDetails(field, new Purply().getClass()), 1, 2);
