private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lion lion = new Lion(true, field, location);
                    species.add(lion);
                }
                else if(rand.nextDouble() <= TIGER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Tiger tiger = new Tiger(true, field, location);
                    species.add(tiger);
                }
                else if(rand.nextDouble() <= FOX_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Fox fox = new Fox(true, field, location);
                    species.add(fox);
                }
                else if(rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Deer deer = new Deer(true, field, location);
                    species.add(deer);
                }
                else if(rand.nextDouble() <= RABBIT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Rabbit rabbit = new Rabbit(true, field, location);
                    species.add(rabbit);
                }
                else if(rand.nextDouble() <= PLANTS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Plants plant = new Plants(field, location);
                    if(rand.nextInt(2) == 1)
                        plant.getInfected();
                    species.add(plant);
                }
                // else leave the location empty.
            }
        }
    }

public void act(List<Actor> newPlants, boolean isDay, Weather weather) {
        if (isDay && weather == Weather.SUNNY && foodLevel < food_step)
            foodLevel = Math.max(rand.nextInt(food_step), foodLevel);

        if (isDay == day) {
            makeDisease();

            if (isAlive()) {
                if (weather == Weather.SUNNY) {
                    giveBirth(newPlants);
                } else if (weather == Weather.STORM) {
                    giveBirth(newPlants);
                    giveBirth(newPlants);
                }
            }
        }
    }

private boolean generateDisease()
    {
        int i = rand.nextInt(10);
        return i <= 1;
    }

