docstring:
Look for raccoons, beavers and squirrels adjacent to the current location.
Only the first live animal is eaten.

@return Where food was found, or null if it wasn't.

function:
private Location findFood() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (organism instanceof Raccoon) {
                Raccoon raccoon = (Raccoon) organism;
                if (raccoon.isAlive()) {
                    raccoon.setDead();
                    foodLevel = Math.min(foodLevel + RACCOON_FOOD_VALUE, FOOD_CAPACITY);
                    return where;
                }
            }
            if (organism instanceof Beaver) {
                Beaver beaver = (Beaver) organism;
                if (beaver.isAlive()) {
                    beaver.setDead();
                    foodLevel = Math.min(foodLevel + BEAVER_FOOD_VALUE, FOOD_CAPACITY);
                    return where;
                }
            }
            if (organism instanceof Squirrel) {
                Squirrel squirrel = (Squirrel) organism;
                if (squirrel.isAlive()) {
                    squirrel.setDead();
                    foodLevel = Math.min(foodLevel + SQUIRREL_FOOD_VALUE, FOOD_CAPACITY);
                    return where;
                }
            }
        }
        return null;
    }

public void changeWeather(int step)
    {
        Random rand = Randomizer.getRandom();

        // Creates a possibility of changing the weather every 25 steps.
        if (step % 25 == 0) {
            if (rand.nextDouble() <= RAIN_CREATION_PROBABILITY) {
                displayWeather = "Rain";
            }
            else if (rand.nextDouble() <= FOG_CREATION_PROBABILITY) {
                displayWeather = "Foggy";
            }
            else if (rand.nextDouble() <= STORM_CREATION_PROBABILITY) {
                displayWeather = "Thunderstorm";
            }
            else {
                displayWeather = "Clear";
            }
