public void draw() {
        background(0);
        int cx = PApplet.parseInt(0.5f * width / SCALE);
        int cy = PApplet.parseInt(0.5f * height / SCALE);
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
            	float randomNum = random(50, 150);
                density = randomNum;
            	heat.addDensity(cx + i, cy + j, randomNum);



            }
        }
        //vector objects that determines the trajectory of the heat
        for (int i = 0; i < 2; i++) {
            float angle = noise(t) * TWO_PI * 2;
            PVector v = PVector.fromAngle(angle);
            v.mult(0.2f);
            t += 0.01f;
            heat.addVelocity(cx, cy, v.x, v.y);
        }

        //iterates the heat object
        heat.step();
        //renders the output
        heat.renderD();
    }

