public boolean isMate(Object object) {
        boolean result = false;

        if (object instanceof Deer) {
            Deer deer = (Deer) object;
            if (deer.isAlive() && deer.canBreed(BREEDING_AGE) && !(deer.getGender().getName().equals(this.getGender().getName()))) {
