public void act(List<Plant> newBamboo)
    {
        increaseHeight(MAX_HEIGHT);
        incrementAge(MAX_AGE);
        if (isAlive() && Simulator.getSeason() == Weather.Season.Spring)//Spring
        {
            getWaterAndNutrients(waterLevel);
            increaseHeight(MAX_HEIGHT);//start growing
            spread(newBamboo);
        }
        else if(isAlive() && Simulator.getSeason()== Weather.Season.Summer)//Summer
        {
            getWaterAndNutrients(waterLevel);
            increaseHeight(MAX_HEIGHT);//grow
        }
        else if(isAlive() && Simulator.getSeason()== Weather.Season.Autumn)//Autumn
        {
            decrementWaterLevel(waterLevel);
            spread(newBamboo);
        }
        else if(isAlive() && Simulator.getSeason()== Weather.Season.Winter)//Winter
        {
            decrementWaterLevel(waterLevel);
        }
    }

protected void tryChangeStatus() {

        if (field.isDark()) {
            if (location.equals(nearestAvailableTree) || (getStatus().equals(TRAVEL_HOME_STATUS_ID) && rand.nextDouble() > 0.6)) {
                setStatus(ASLEEP_STATUS_ID);
                return;
            } else {
                setStatus(TRAVEL_HOME_STATUS_ID);
                return;
            }
        }

         if (getHungerLevel() > 7 || rand.nextDouble() < 0.2 || (getStatus().equals(FOOD_HUNTING_STATUS_ID) && rand.nextDouble() < 0.4)) {
            setStatus(FOOD_HUNTING_STATUS_ID);
            return;
        }


        if (canMeet() && rand.nextDouble() < 0.8 || (getStatus().equals(MATE_HUNTING_STATUS_ID) && rand.nextDouble() < 0.4)) {
            setStatus(MATE_HUNTING_STATUS_ID);
            return;
        }

        setStatus(IDLE_STATUS_ID);
    }

