public boolean hasOppositeGenderNeighbours(Animal animal){
        List<Location> neighbours = adjacentLocations(animal.getLocation());
        for(Location next : neighbours) {
            Animal neighbour = (Animal) getObjectAt(next);
            if(neighbour != null && neighbour.getClass() == animal.getClass()) {
