private void addWeather(List<Location> weatherList)
    {
        int randomWeather = rand.nextInt(5)+1;
        Weather weather = Weather.SUNNY;
        switch(randomWeather){
            case 1:
                weather = Weather.FOG;
                break;       
            case 2:
                weather = Weather.RAIN;
                break;
            case 3:
                weather = Weather.SNOW;
                break;
            case 4:
                weather = Weather.WIND;
                break;
            case 5:
                weather = Weather.SUNNY;
                break;
        }

        for (Location l: weatherList){
            l.addWeather(weather);
        }
    }

