docstring:
Look for food adjacent to the current location.
Only the first food found is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        Weather weather = getWeather();
        Time time = getTime();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            //can't eat if it is night or it is foggy.
            if(time.getDay() && !weather.getCurrentWeather().equals("foggy")){
                if(animal instanceof Rabbit) {
                    Rabbit rabbit = (Rabbit) animal;
                    if(rabbit.isAlive()) { 
                        setSick((rabbit.getSick()));
                        rabbit.setDead();
                        foodLevel = RABBIT_FOOD_VALUE;
                        return where;
                    }
                }
                else if(animal instanceof BlueJay) {
                    BlueJay blueJay = (BlueJay) animal;
                    if(blueJay.isAlive()) { 
                        setSick((blueJay.getSick()));
                        blueJay.setDead();
                        foodLevel = BLUEJAY_FOOD_VALUE;
                        return where;
                    }
                }
                else if(animal instanceof Owl) {
                    Owl owl = (Owl) animal;
                    if(owl.isAlive()) {
                        setSick((owl.getSick()));
                        owl.setDead();
                        foodLevel = OWL_FOOD_VALUE;
                        return where;
                    }
                }
            }
        }
        return null;
    }

