private void populateAnimal()
    {
        field.clearAnimal();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                int probability = rand.nextInt(AnimalCreationProbability.getTotal());
                if(probability >= AnimalCreationProbability.TIGER.getLowerBound() && 
                probability < AnimalCreationProbability.TIGER.getUpperBound()) {
                    Location location = new Location(row, col);
                    Tiger tiger = new Tiger(true, field, location);
                    animals.add(tiger);
                }
                else if(probability >= AnimalCreationProbability.SNAKE.getLowerBound() && 
                probability < AnimalCreationProbability.SNAKE.getUpperBound()) {
                    Location location = new Location(row, col);
                    Snake snake = new Snake(true, field, location);
                    animals.add(snake);
                }
                else if(probability >= AnimalCreationProbability.WOLF.getLowerBound() && 
                probability < AnimalCreationProbability.WOLF.getUpperBound()) {
                    Location location = new Location(row, col);
                    Wolf wolf = new Wolf(true, field, location);
                    animals.add(wolf);
                }
                else if(probability >= AnimalCreationProbability.DEER.getLowerBound() && 
                probability < AnimalCreationProbability.DEER.getUpperBound()) {
                    Location location = new Location(row, col);
                    Deer deer = new Deer(true, field, location);
                    animals.add(deer);
                }
                else if(probability >= AnimalCreationProbability.SHEEP.getLowerBound() && 
                probability < AnimalCreationProbability.SHEEP.getUpperBound()) {
                    Location location = new Location(row, col);
                    Sheep sheep = new Sheep(true, field, location);
                    animals.add(sheep);
                }
                else if(probability >= AnimalCreationProbability.MICE.getLowerBound() && 
                probability < AnimalCreationProbability.MICE.getUpperBound()) {
                    Location location = new Location(row, col);
                    Mice mice = new Mice(true, field, location);
                    animals.add(mice);
                }
                // else leave the location empty.
            }
        }
    }

protected void setFoodLevel(int foodAmount) {
        foodLevel = foodAmount;
    }

docstring:
This is what the mouse does most of the time - it runs
around. Sometimes it will breed or die of old age.
@param newMice A list to return newly born mices.

function:
public void act(List<Animal> newMice)
    {
        incrementAge();
        incrementHunger();
        //check whether the animal has disease.
        //after 4 days they will die.
        if(rand.nextDouble() <= getDiseaseRate() && !HasDisease) {
             HasDisease = true;
        }
        if(HasDisease){
             DaysAfterDisease ++;
             if(DaysAfterDisease >= 5){
             setDead();
             }
        }
        if(isAlive()) {
            //check whether neigbour of female has male animal and birth if so.
            //check whether neigbour of animal can be infected.
            if(gender == "female"){
                Field field = getField();
                List<Location> adjacent = field.adjacentLocations(getLocation());
                Iterator<Location> it = adjacent.iterator();
                while(it.hasNext()) {
                   Location where = it.next();
                   Object animal = field.getObjectAt(where);
                   if(animal instanceof Mouse) {
                       Mouse mouse = (Mouse) animal;
                       if(mouse.gender == "male"){
                           giveBirth(newMice);
                       }
                       if(HasDisease){
                           mouse.HasDisease = true;
                       }
                   }
                }
            }
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
            // No food found - try to move to a free location.
            newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
            setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

