private boolean canBreed()
    {
        Field field = getField();
        Shrimp currentShrimp = (Shrimp) field.getObjectAt(getLocation());
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Shrimp) {
                Shrimp matingShrimp = (Shrimp) animal;
                if(currentShrimp.isMale != matingShrimp.isMale){
                    if(currentShrimp.age >= BREEDING_AGE && matingShrimp.age >= BREEDING_AGE){
                        return true;
                    }
                }
            }
        }
        return false;
    }

docstring:
An eagle can breed if it has reached the breeding age and meets an owl of the opposite gender
that has also reached the breeding age.
@return True if they can breed, false otherwise.

function:
protected boolean canBreed()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Eagle) {
                Eagle a = (Eagle) animal;
                return a.getGender() != this.getGender() && a.age >= BREEDING_AGE && 
                        this.age >= BREEDING_AGE;
            }
        }
        return false;
    }

docstring:
Determine whether the simulation is still viable.
I.e., should it continue to run.

@param field the field
@return true If there is more than one species alive.

function:
public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

