public void act(List<Animal> newWolves, boolean isDay) {  
            incrementAge();
            incrementHunger();
            if(isAlive()) {
                giveBirth(newWolves);
                // Move towards a source of food if found.
                Location newLocation = findFood();
                if (newLocation == null) {
                    // No food found - try to move to a free location.
