private void meet(List<Animal> newSnakes){
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        Object animal1 = field.getObjectAt(getLocation());
        while(it.hasNext()){
            Location occupied = it.next();
            Object animal2 = field.getObjectAt(occupied);
            if (animal1 instanceof Snake && animal2 instanceof Snake){
                Snake breeder = (Snake) animal1;
                Snake breedingMate = (Snake) animal2;
                if((breeder.isFemale() && !breedingMate.isFemale()) 
                || (!breeder.isFemale() && breedingMate.isFemale())){
                    giveBirth(newSnakes);
                }
            }
        }
    }

public void simulateOneStep()
    {
        step++;
        double totalOxygenInvolved= 0; //oxygen that is generated or consumed in total for this step


        if(Math.random() <= DISEASE_PROBABILITY){
            existDisease = true;
        }

        // Provide space for newborn animals.
        List<Creature> newCreatures = new ArrayList<>();        
        // Let all rabbits act.
        for(Iterator<Creature> it = creatures.iterator(); it.hasNext(); ) {
            Creature creature = it.next();
            totalOxygenInvolved += creature.act(newCreatures, timeOfDay(), oxygenLevel, existDisease, step);
            if(!creature.isAlive()) {
                it.remove();
            }
        }

        // calculate the oxygen left
        oxygenLevel += totalOxygenInvolved;

        //identify if disease stops
        if(existDisease){
            existDisease = identifyIfDiseaseStops();
        }



        // Add the newly born creatures to the main lists.
        creatures.addAll(newCreatures);
        view.showStatus(step, field);
    }

