protected void generateAge(boolean randomAge, int maxAge, int foodLevelLimit)
    {
        if(randomAge) {
            age = rand.nextInt(maxAge);
            foodLevel = rand.nextInt(foodLevelLimit);
        }
        else {
            age = 0;
            foodLevel = foodLevelLimit;
        }
