function:
@Override
    public void act(List<Animal> newHolves, Season season) {

        incrementAge();
        incrementHunger();

        if (isAlive()) {

            if (super.getSex() == 0)
                reproduce(newHolves, season);

            Location newLocation;
            if (foodLevel < MAX_STOMACH_VALUE) {
                // Move towards a source of food if found.
                newLocation = eat(BASE_SCOPE_VISION + heightEffectsOnVisionScope());
                if (newLocation == null) {
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
            }else{
                // See if it was possible to move.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            if (newLocation != null) {
                setLocation(newLocation);
            } else {
                // Overcrowding.
                super.destruct();
                setDead();
            }

            if (isAlive())
                super.invokeImmuneSystem();


        }
    }

public void actNight(List<Animal> newDeer)
    {
        incrementAge();
        incrementHunger();
         if(isAlive()) {
            // Give birth if Hamsters of opposite gender meet.
            if (meet()==true){
                giveBirth(newDeer);
            }

            // Try to move into a free location.
            Location newLocation = getField().freeAdjacentLocation(getLocation());
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else{
                // Overcrowding.
                setDead();
            }
        }
    }

docstring:
Determine whether the simulation is still viable.
I.e., should it continue to run.
@return true If there is more than one species alive.

function:
public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field);
        }
        if (noAnimalsLeft(field))
        	return false;
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

