protected boolean isInRange(Location origin, int range)
    {
        int deltaCol = Math.abs(origin.getCol() - getLocation().getCol());
        int deltaRow = Math.abs(origin.getRow() - getLocation().getRow());

        if(deltaCol > range) {
            return false;
        }

        if(deltaRow > range) {
            return false;
        }

        return true;
    }

