private void generateCounts(Field field)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object organism = field.getObjectAt(row, col);
                Object waterSource = field.getObjectAt(row, col);
                Object plants = field.getObjectAt(row, col);
                if(organism != null) {
                    incrementCount(organism.getClass());
                }
                if(waterSource != null) {
                    incrementCount(waterSource.getClass());
                }
                if(plants != null) {
                    incrementCount(plants.getClass());
                }
            }
        }
        countsValid = true;
    }

docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param weather The weather to be displayed.
@param time The time of day to be displayed.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, String weather, String time, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        weatherLabel.setText(WEATHER_PREFIX + weather);
        timeLabel.setText(TIME_PREFIX + time);
        stats.reset();


        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object actor = field.getObjectAt(row, col);
                if(actor != null) {
                    stats.incrementCount(actor.getClass());
                    fieldView.drawMark(col, row, getColor(actor.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

