docstring:
Generate a number representing the number of births,
if it can breed.
@return The number of births (may be zero).

function:
private int breed()
    {
        rand = Randomizer.getRandom();
        int births = 0;
        double breedingProbability = getBreedingProbability();
        int maxLitterSize = getMaxLitterSize();

        if(isInfected()){
            breedingProbability *= getDiseaseModifier();
            maxLitterSize = (int)(maxLitterSize*getDiseaseModifier());
        }

        else if(canBreed() && rand.nextDouble() <= breedingProbability) {
            births = rand.nextInt(maxLitterSize) + 1;
        }
        return births;
    }

public void simulateOneStep()
    {
        int newWeather = weather.newWeather();
        partOfDay = step%PARTS_OF_DAY;
        step++;
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            plant.grow(newWeather, plantField);
        } 

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals, partOfDay, CHANCE_OF_ANIMAL_DYING, newWeather);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born lions, crocodiles, antelopes, giraffes, and elephants to the main lists.
        animals.addAll(newAnimals);

        updateViews();

    }

