function:
protected int breed(int breedingAge, double breedingProbability, int maxLitterSize) 
    {
        int births = 0;
        Animal male = findMale();
        if(canBreed(breedingAge,breedingProbability, male)) {
            births = rand.nextInt(maxLitterSize) + 1;
            spreadDisease(male);
        }
        return births;
    }

private void changeDelay(ChangeEvent changeEvent)
    {
        // Get the slider's current value.
        JSlider slider = (JSlider) changeEvent.getSource();
        int delay = slider.getValue();

        // Update the text above the slider.
        delayLabel.setText(DELAY_PREFIX + delay + "ms");

        // Send the delay value to the controller.
        if (controller != null) {
            controller.setDelay(delay);
        }
    }

