private void giveBirth(List<Animal> newSnakes)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Snake) {
                Snake snake = (Snake) animal;
                //Check if the gender of this snake is opposite of the partner snake. If is that the case than the breeding is true.
                if(snake.getGender() != this.getGender()) { 
                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
                    int births = breed();
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        boolean genderSetter = setGender();
                        Snake young = new Snake(false, field, loc, genderSetter);
                        newSnakes.add(young);
                    }
                }      
            }
        }
    }

