            }
        }

    }

docstring:
Look for rabbits adjacent to the current location.
Only the first live prey is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext() && rand.nextDouble() <= SUCCESS_PROBABILITY) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Insect) {
                Insect insect = (Insect) animal;
                if(insect.isAlive() ) { 
                    insect.setDead();
                    foodLevel = MOUSE_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Owl) {
                Owl owl = (Owl) animal;
                if(owl.isAlive() && rand.nextDouble() <= SUCCESS_PROBABILITY ) { 
                    owl.setDead();
                    foodLevel = MOUSE_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Monkey)
            {
                Monkey monkey = (Monkey) animal;
                if(monkey.isAlive() && rand.nextDouble() <= SUCCESS_PROBABILITY)
                {
                    monkey.setDead();
                    foodLevel = MONKEY_FOOD_VALUE;
                    return where;
                }
            }

            else if(animal instanceof Anaconda)
            {
                Anaconda anaconda = (Anaconda) animal;
                if(anaconda.isAlive()&& rand.nextDouble() <= NOTSUCCESS_PROBABILITY)
                {
                    anaconda.setDead();
                    foodLevel = ANACONDA_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

