docstring:
Check whether or not this predator is to give birth at this step.
New births will be made into free adjacent locations.
@param newPredators A list to return newly born predator.

function:
private void giveBirth(List<Animal> newPredators)
    {
        // New foxes are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Predator young = new Predator(false, field, loc);
            newPredators.add(young);
        }
    }

public void act()
    {
        incrementAge();
        incrementHunger();
        if(alive && Timer.isDay()) {
            giveBirth();
            if (foodLevel < STARTING_FOOD_LEVEL - GRASS_FEED_VALUE) {
                Terrain terrain = field.getTileAt(location).getTerrain();
                if (terrain instanceof Grass) {
                    Grass grass = (Grass) terrain;
                    if (grass.getFoodValue() >= GRASS_FEED_VALUE) {
                        grass.setFoodValue(grass.getFoodValue() - GRASS_FEED_VALUE);
                        foodLevel += GRASS_FEED_VALUE;
                    }
                }
            }
            // Try to move into a free location.
            Location newLocation = getNewLocation();
            if(newLocation != null) {
                setLocation(newLocation);
                spreadDisease();
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

