docstring:
Generate a number representing the number of births,
if it can breed.
@return The number of births (may be zero).

function:
private int breed() {
        int births = 0;
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        // check if there is a partner in an adjacent location
        while (it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            // checks if it is also a shark
            if (animal instanceof Shark) {
                Shark shark = (Shark) animal;
                // checks if both sharks have different gender are alive and can breed
                // randomizer to make sure they only breed certain times
                if (shark.isAlive() && shark.canBreed() && shark.isMale() && canBreed() && (rand.nextDouble() <= breedingProb)) {
                    births = rand.nextInt(MAX_LITTER_SIZE) + 1;
                    return births;
                }
            }
        }
        return births;
    }

