docstring:
Get a shuffled list of the free adjacent disease locations.
These are locations free of disease.
@param location Get locations adjacent to this.
@return A list of free adjacent locations.

function:
public List<Location> getFreeDiseaseLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getObjectAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

public boolean checkNearbyInfected(){
         List<Location> adjacentLocation = getField().adjacentLocations(getLocation());

        for(Location loc: adjacentLocation){
            Object creatureAtThisLoc = getField().getObjectAt(loc);
            if(creatureAtThisLoc != null && creatureAtThisLoc instanceof Animal){
                Animal animalAtThisLoc = (Animal)creatureAtThisLoc;
                if(animalAtThisLoc.getIsInfected())
                    return true;
            }   
        }
        return false;
    }

private void pickWeather()
    {
        Collections.shuffle(weather);
        currentWNum = weather.get(0);
        Weather currentWeather = currentWNum.getWeatherType();
        switch (currentWNum) {
            case STANDARD:
                break;

            case RAIN:
                currentWeather.effect();
                recordedWeather.add(currentWeather);
                // Plants can only grow when it rains
                for (Actor actor: actors) {
                    if (actor instanceof Plant) {
                        Plant plant = (Plant) actor;
                        if (!plant.isSpreadable()) {
                            plant.toggleSpreadable();
                        }
                    }
                }
                break;

            case FOG:
                currentWeather.effect();
                recordedWeather.add(currentWeather);
                // Fog reduces all animals' mating distances
                for (Actor actor: actors) {
                    if (actor instanceof Animal) {
                        Animal animal = (Animal) actor;
                        animal.changeMatingDistance(FOG_MATING_DISTANCE);
                    }
                }
                break;

            case SNOW:
                Random rand = new Random();
                currentWeather.effect();
                recordedWeather.add(currentWeather);
                // When it snows there is a chance that any actor can freeze and die
                for (Actor actor: actors) {
                    if (rand.nextDouble()<FREEZE_CHANCE) actor.setDead("Freeze");
                }
        }
    }

docstring:
Returns the color an animal with a certain color will have if sick.
@param color The color of the animal.
@return Color of the sick animal.

function:
private Color getSickColor(Color color)
    {
        if(color == null) {
            return null;
        }

        float r = (float) color.getRed();
        r = r / 255;

        float g = (float) color.getGreen();
        g = g / 255;

        float b = (float) color.getBlue();
        b = b / 255;

        // Set the transparency of a sick animal.
        // 0.0 completely transparent, 1.0 fully opaque.
        // Healthy animals - 1.0
        float a = (float) 0.3;

        return new Color(r, g, b, a);
    }

