docstring:
Look for animals to eat adjacent to the current location.
Only the first live animal is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Fish) {
                Fish fish = (Fish) animal;
                if(fish.isAlive()) { 
                    fish.setDead();
                    foodLevel = FISH_FOOD_VALUE;
                    return where;
                }
            }
            else if (animal instanceof Tuna){
                Tuna tuna = (Tuna) animal ;
                if(tuna.isAlive()){
                    tuna.setDead();
                    foodLevel = TUNA_FOOD_VALUE;
                }
            }
            else if(animal instanceof Shark){
                Shark shark = (Shark) animal ;
                if(shark.isAlive()){
                    shark.setDead();
                    foodLevel = SHARK_FOOD_VALUE;
                }
            }
        }
        return null;
    }

protected void mutate() {
        if (rand.nextDouble() <= DISEASE_PROBABILITY) {
            sick = true;
        }
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Object object = getField().getObjectAt(it.next());
            if (object instanceof Animal) {
                Animal animal = (Animal) object;
                if (animal.isSick()) {
                    if (rand.nextDouble() <= INFECTION_PROBABILITY) {
                        sick = true;
                    }
                }
            }        
        }
    }

private void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }

