docstring:
Look for Deers adjacent to the current location.
Only the first live Deer is eaten.
@return Where food was found, or null if it wasn't.

function:
protected Location findFood()
    {
        Field field = getField();
        if (getWeather().hasStatus("foggy") == true) // Leopards can't hunt if weather is foggy
        {
            return null;
        }

        List<Location> adjacent = field.adjacentLocations(getLocation());
        // Check if there are any nearby Deers, move towards them (by returning their location)
        // and eat them if there are any, return null if there are none.
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Deer) {
                Deer Deer = (Deer) animal;
                if(Deer.isAlive()) { 
                    Deer.setDead();
                    foodLevel = foodLevel + Deer.getFoodValue(); // Set the hunted Deer dead and add it's food value to Leopard's food level.
                    if (foodLevel > MAX_FOOD_LEVEL) 
                    {
                        foodLevel = MAX_FOOD_LEVEL;
                    }
                    return where;
                }
            }
        }
        return null;
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= SHARK_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Shark shark = new Shark(true, field, location);
                    animals.add(shark);
                }
                else if(rand.nextDouble() <= WHALE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    KillerWhale whale = new KillerWhale(true, field, location);
                    animals.add(whale);
                }
                else if(rand.nextDouble() <= SEA_LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    SeaLion sealion = new SeaLion(true, field, location);
                    animals.add(sealion);
                }
                else if(rand.nextDouble() <= SQUID_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Squid squid = new Squid(true, field, location);
                    animals.add(squid);
                }
                else if(rand.nextDouble() <= CRAB_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Crab crab = new Crab(true, field, location);
                    animals.add(crab);
                }
                // else leave the location empty.
            }
        }
    }

