public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int zeroPopulations = 0;

        if(!countsValid) {
            generateCounts(field);
        }//end of if invalid count recount

        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() == 0) {
                zeroPopulations++;
            }//end of if count for animal is zero
        }//end of for all classes in hashmap

        return zeroPopulations < 1;
    }

