public List<Location> getPercantageOfField(double percantage)
    {
        List<Location > locations = new ArrayList<>();
        locations = getAllLocations();//List of all locations
        List<Location> selectedLocation = new ArrayList<>();
        Random random = new Random(); 
        double number =  depth * width * percantage ;//Number of locations returned when percetage applied.
        while(number > 0)
        {
            number --;  
            int index = random.nextInt(locations.size());
            selectedLocation.add(locations.get(index)); //selects a random location and adds it to list 
        }
        return selectedLocation;
    }

