private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object foodSource = field.getObjectAt(where);
            if(foodSource instanceof Shrimp) {
                Shrimp shrimp = (Shrimp) foodSource;
                if(shrimp.isAlive()) { 
                    shrimp.setDead();
                    foodLevel += SHRIMP_FOOD_VALUE;
                    return where;
                }
            }
             if(foodSource instanceof SeaWeed) {
                SeaWeed seaWeed = (SeaWeed) foodSource;
                if(seaWeed.isAlive()) { 
                    seaWeed.setDead();
                    foodLevel += SEAWEED_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

