        while(it.hasNext()) {
            Location where = it.next();
            Object creature = field.getObjectAt(where);
            if(creature instanceof Cheetah) {
                Cheetah Cheetah = (Cheetah) creature;
                if(Cheetah.isAlive() && !Cheetah.getIsFemale() && Cheetah.getAge() >= BREEDING_AGE){
                    return true;
                }
            }
        }
        return false;
    }

