public static void increment() {
        step += 1;
        time += 1;
        time %= DAY_NIGHT_LENGTH * 2;
        if(rnd.nextDouble() <= WEATHER_CHANGE_CHANCE){
            switch (currentWeather) {
                case SUNNY:
                    currentWeather = Weather.RAINING;
                    break;
                case RAINING:
                    currentWeather = Weather.SUNNY;
                    break;
            }
        }
    }

private void spreadLove(List<Organism> newDHuman)
    {
        // New DHuman are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> adjacent = field.surroundingLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        while(it.hasNext()) {
            Location where = it.next();
            Object Organism = field.getObjectAt(where);
            if(Organism instanceof Human) {
                Human organism = (Human) Organism;
                if(!(organism instanceof DHuman)) {
                    if(organism.isAlive() && canSpread()) { 
                        organism.becomeDiseased(newDHuman, organism.getLocation());
                    }
                }
            }
        }
    }

docstring:
Look for rabbits and hares adjacent to the current location.
Only the first live rabbit/hare is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object preyActor = field.getObjectAt(where);
            //Check whether object found is of appropriate food type.
            if(preyActor!= null && foodTypes.contains(preyActor.getClass().getSimpleName()))
            {
                Actor prey = (Actor) preyActor;
                if(prey.isAlive()) { 
                    prey.setDead();
                    foodLevel = prey.getFoodValue();
                    return where;
                }
            }
        }
        return null;
    }

