@Override
    public void act(List<Actor> newLions, double weatherEffect)
    {
        super.incrementAge();
        incrementHunger();
        if(isActive()) {
            if (super.getGender() && meet(this)){
                giveBirth(newLions); 
            } 

            Location newLocation = null;
            newLocation = findFood();      

            // Move towards a source of food if found.
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

public boolean identifyIfDiseaseStops(){

        List<Creature> newCreatures = new ArrayList<>();   

        boolean existDisease = true;

        for(Iterator<Creature> it = creatures.iterator(); it.hasNext(); ) {
            Creature creature = it.next();
            if(creature instanceof Animal){
                Animal ani = (Animal)creature;
                if(!ani.getIsInfected() || ani.getIsImmuned()){
                    existDisease = false;
                }
                else{
                    existDisease = true;
                }
            }
        }

        return existDisease;
    }

