docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field, int hour)
    {

        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                boolean occupied = false;
                for (int i = 0; i < field.getLayerCount(); i++) {
                    Object creature = field.getObjectAt(Location.at(row,col),i);
                    if(creature != null) {
                        stats.incrementCount(creature.getClass());
                        if(viewLayer == -1 || viewLayer == i){
                            occupied = true;
                            fieldView.drawMark(col, row, getColor(creature.getClass()));
                        }
                        if(creature instanceof Infectable){
                            for(Disease disease : ((Infectable) creature).getDiseases()){
                                stats.incrementCount(disease.getClass());
                                if(viewLayer == Disease.getLayer()){
                                    occupied = true;
                                    fieldView.drawMark(col, row, getColor(disease.getClass()));
                                };
                            }
                        }
                    }
                }
                if(!occupied){
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }


            }
        }
        stats.countFinished();


        statisticsPanel.setRecord("Step",Integer.toString(step));
        statisticsPanel.setRecord("Weather",field.getWheather().name());
        statisticsPanel.setRecord("Time",Integer.toString(hour));
        statisticsPanel.setCountRecords(stats.getCounters(field));

        fieldView.repaint();

    }

