public List<Actor> populate() {        
        actors.clear();

        // Iterate through all the positions on the field and check
        // if we should add an animal at this location.
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= FOX_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Fox fox = new Fox(true, field, location, tryInfectAnimal());
                    actors.add(fox);
                    // drawables.add(fox);
                }
                else if(rand.nextDouble() <= RABBIT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Rabbit rabbit = new Rabbit(true, field, location, tryInfectAnimal());
                    actors.add(rabbit);
                    // drawables.add(rabbit);
                }
                else if (rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lion lion = new Lion(true, field, location, tryInfectAnimal());
                    actors.add(lion);
                    // drawables.add(lion);
                }
                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Cheetah cheetah = new Cheetah(true, field, location, tryInfectAnimal());
                    actors.add(cheetah);
                    // drawables.add(cheetah);
                }
                else if(rand.nextDouble() <= HUNTER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hunter hunter = new Hunter(true, field, location);
                    actors.add(hunter);
                    // drawables.add(hunter);
                }

                if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(true, field, location);
                    actors.add(grass);
                }
                // else leave the location empty.            
            }
        }        
        return actors;
    }

public void weatherEffects(Actor actor)
    {
        Random rand = Randomizer.getRandom();
        if (rand.nextDouble() <= SNOW_DEATH_PROBABILITY) { 
            if (actor instanceof Plant) {
                Plant plant = (Plant) actor;
                plant.setInactive(); //plants die from snow
            }
        }
        if (actor instanceof Animal) {
            Animal animal = (Animal) actor;
            animal.setHibernate(); //all animals hibernate in snowy weather
        }
    }

docstring:
Checks surrounding cells for a viable breeding partner
If one is present, a randomised number of whale offspring are spawned

@param newWhale A list to return newly born whales

function:
protected void findMate(List<Animal> newWhale) {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while (it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if (animal instanceof Whale) {
                Whale mate = (Whale) animal;
                if (mate.isAlive() && mate.getAge()>getBaseValue("whaleBreedingAge")) {
                    int births = rand.nextInt(MAX_LITTER) + 1;
                    for (int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Whale young = new Whale(field, loc);
                        newWhale.add(young);

                    }
                }
            }
            return; // can only breed once per time unit
        }
    }

