private int nextIntBetween(int origin, int bound, Random rander) {
        int n = bound - origin;
        if (n > 0) {
            return rander.nextInt(n) + origin;
        }
        else {  // range not representable as int
            int r;
            do {
                r = rander.nextInt();
            } while (r < origin || r >= bound);
            return r;
        }
    }

