function:
protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object object = field.getObjectAt(where);
            if(object instanceof Plant) {
                Plant plant = (Plant) object;
                if(plant.isAlive() && plant.isReadyToBeEaten()) { 
                    plant.setDead();
                    if(plant.isPoisonous()) {
                        foodLevel = 0; // if the plant is poisonous, it will kill the frog
                    }
                    else {
                        foodLevel = PLANT_FOOD_VALUE;
                    }
                    return where;
                }
            }
        }
        return null;
    }

public void simulateStep() {
        // Update weather.
        weatherState.updateWeather();
        weatherController.updateTemperature();

        // Randomly insert Actors
        addActors();

        // Actors
        List<Actor> newActors = new ArrayList<>();
        for (Iterator<Actor> it = actors.iterator(); it.hasNext();) {
            Actor a = it.next();

            if (!a.isAlive()) {
                it.remove();
                continue;
            }

            a.act(newActors);
        }

        actors.addAll(newActors);
        field.incrementStep();
        fieldStatistics.update();
        //fieldStatistics.print();

        updateGUI();
    }

