docstring:
Chance that a natural disaster occurs and wipes out a large portion
of the simulation.
@param probability The probability of the natural disaster occuring

function:
private void naturalDisaster(double probability)
    {
        Random rand = Randomizer.getRandom();

        if(rand.nextDouble() <= probability) {
            for(Iterator<Species> it = species.iterator(); it.hasNext(); ) {
                Species specie = it.next();

                if(specie instanceof Hyena || specie instanceof Lion || specie instanceof Tiger) {
                    if(rand.nextDouble() <= 0.91) {
                        specie.setDead();
                    }
                }
                else if (specie instanceof Antelope || specie instanceof Buffalo){
                    if(rand.nextDouble() <= 0.5) {
                        specie.setDead();
                    }
                }
                else {
                    if(rand.nextDouble() <= 0.1) {
                        specie.setDead();
                    }
                }

            }
        }
    }

@Override
    public Location findFood() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object Organism = field.getObjectAt(where);
            if (Organism instanceof Plant) {
                Plant plant = (Plant) Organism;
                if (plant.isAlive()) {
                    plant.setDead();
                    foodLevel = FROG_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

