protected void incrementAge()
    {
        changeAge();
        if(getAge() > getMaxAge()) {
            setDead();
            return; // no need to check for other conditions
        }

        if(getAge() >= getReadyToBeEatenAge() && !isReadyToBeEaten()) {
            isReadyToBeEaten = true;
        }
