This is what the Lizard does most of the time - it runs and searches for Cacti.
around. Sometimes it will breed or die of old age. It breed more effectively when it doesn't rain.
@param newLizards A list to return newly born Lizards.
@param isNight A boolean value when true it is night time and Lizards are dormant.
@param weather The current weather effects birth of Lizards.

function:
public void act(List<Species> newLizards, Boolean isNight, String weather)
    {
        if(!isNight){
            incrementAge();
            incrementHunger();
            if (isAlive()){
                if(weather != "raining") {
                    giveBirth(newLizards);
                }else{
                    Random rand = new Random();
                    int chance = rand.nextInt(100);
                    if (chance > 40){
                        giveBirth(newLizards); 
                    } 
                }
                Location newLocation = findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }
        } 

    }

public void simulateOneStep() {
        step++;

        if(weather.equals("rain")){
            resetWeather();
            for (int i = 0; i < plants.size(); i++) {
                plants.get(i).setRain();
            }
        }
        else if(weather.equals("flood")){
            resetWeather();
            List<Animal> randomRatsAnts = new ArrayList<>();
            for (int i = 0; i < animals.size(); i++){
                if ((animals.get(i) instanceof Ant || (animals.get(i) instanceof Rat))) {
                    randomRatsAnts.add(animals.get(i));
                }
            }
            Collections.shuffle(randomRatsAnts);
            for (int i = 0; i < ((randomRatsAnts.size())/5); i++){
                animals.get(i).setDead();
            }
        }
        else if (weather.equals("drought")){
            resetWeather();
            List<Plant> randomPlants = new ArrayList<>();
            for (int i = 0; i < plants.size(); i++){
                randomPlants.add(plants.get(i));
            }
            Collections.shuffle(randomPlants);
            for (int i = 0; i < ((plants.size())/5); i++){
                plants.remove(plants.get(i));
            }
        }
        else if (weather.equals("fog")) {
            resetWeather();
            for (int i = 0; i < animals.size(); i++) {
                animals.get(i).setFog();
            }
        }

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all ants act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals,time);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        //provide space for new created plants
        List<Plant> newPlants = new ArrayList<>();
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            plant.act(newPlants);
            if(! plant.isAlive()) {
                it.remove();
            }
        }


        // Add the newly born animals and plants to the main lists.
        animals.addAll(newAnimals);
        plants.addAll(newPlants);

        view.showStatus(step, field, time, weather);
    }

private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
