public void showStatus(int dayNumber, int hourOfDay, String dayStatus,String AMStatus,String weather, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(DAY_PREFIX + dayNumber 
            + " " + HOUR_PREFIX + hourOfDay + AMStatus 
            + " " + dayStatus + "  "+ WEATHER_PREFIX+ weather);
        stats.reset();

        //defines the action when the user's clicks on "Quit" button.
        //Quit button exits the simulator and VM.
        quitButton.addActionListener(e -> System.exit(0));

        fieldView.preparePaint();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object entity = field.getObjectAt(row, col);
                if(entity != null) {
                    if (entity instanceof Animal) {
                        Animal animal = (Animal) entity;
                        if (animal.isInfected()){stats.incrementInfectedCounter();}
                    }
                    stats.incrementCount(entity.getClass());
                    fieldView.drawMark(col, row, getColor(entity.getClass()));
                } else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        diseaseLabel.setText(INFECTION_PREFIX + stats.getInfectedCounter());
        fieldView.repaint();
    }

