function:
protected Location hunt()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Cricket) {
                Cricket cricket = (Cricket) animal;
                if(cricket.isAlive()) { 
                    cricket.setDead();
                    eat(CRICKET_FOOD_VALUE, HUNGER_LIMIT, foodLevel);
                    return where;
                }
            }
        }
        return null;
    }

private void spreadDisease(Animal male)
    {
        if(isInfected && rand.nextDouble() <= PROBABILITY_OF_DISEASE_SPREAD) {
            // A chance the male gets infected if the female is infected.
            male.setIsInfected(true);
        }
        else if(male.getIsInfected() && rand.nextDouble() <= PROBABILITY_OF_DISEASE_SPREAD) {
            // A chance the female gets infected if the male is infected
            isInfected  = true;
        }
    }

public void act(List<Actor> newSnakes, Weather weather)
    {
        incrementAge();
        incrementHunger();
        infectOthers();
        deathByInfection();
        heal();
        if(isActive()) {
            giveBirth(newSnakes);            
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

