public List<Location> getFreeOrPlantAdjacentLocations(Location location, int range)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location, range);
        for(Location next : adjacent) {
            if(getObjectAt(next) == null || getObjectAt(next) instanceof Plant) {
                free.add(next);
            }
        }
        return free;
    }

public String getPopulationDetails(Field field)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field);
        }

        // Sort the stats in alphabetical order.
        TreeMap<String,Integer> sortedKeys = new TreeMap<String,Integer>();
        for(Class key : counters.keySet()){
            Counter info = counters.get(key);
            sortedKeys.put(info.getName(), info.getCount());
        }

         for(Map.Entry<String,Integer> entry : sortedKeys.entrySet()) {
            String name = entry.getKey();
            Integer info = entry.getValue();

            buffer.append(name);
            buffer.append(": ");
            buffer.append(info);
            buffer.append(" | ");
        }
        return buffer.toString();
    }

