        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Unicorn) {
                Unicorn unicorn = (Unicorn) animal;
                if(isOpposingSex(unicorn) && canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY) { 
                    births = rand.nextInt(MAX_LITTER_SIZE) + 1;
                }
                return births;
            }

        }
        return 0;
    }

public void act(List<Actor> newActors)
    {
        if (TimeOfDay.getInstance().getTime() == activeTime) {
            // Checks if the current time matches the active hours of the sloth.
            incrementAge();
            incrementHunger();
            if (isAlive()) {
                mate(newActors, this.getClass(), getBounds(), noiseValue);
                // Move towards a source of food if found.
                findFood();

                // No food found - try to move to a free location.
                Location newLocation = getField().freeAdjacentLocation(getLocation(), movementArea.getBounds(), 1);

                // See if it was possible to move.
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    // Overcrowding.
                    setDamage();
                }
            }
        }
        //sleep
    }

