private void giveBirth(List<Animal> newBears)
    {
        // New bears are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Bear young = new Bear(false, field, loc);
            newBears.add(young); 
        }
    }

private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if(organism instanceof Grass) {
                Grass grass = (Grass) organism;

                // Stage 2 Fully grown grass
                if(grass.isAlive() && grass.returnAge()>=6) { 
                    grass.setDead();
                    foodLevel = GRASS_FOOD_VALUE;
                    return where;
                }

                //Stage 1 Not fully grown Grass
                else if(grass.isAlive() && grass.returnAge()<=5)
                {
                     grass.setDead();
                    foodLevel = GRASS_FOOD_VALUE/2;
                    return where;
                }


            }
        }
        return null;
    }

