public void act(List<Organism> newSloth, boolean time, int weather)
    {
        double breedingProbability = BREEDING_PROBABILITY;
        int laziness = 5;
        age = incrementAge(MAX_AGE, age);
        foodLevel = incrementHunger(foodLevel);
        lightningKill(weather);
        boolean act = true;
        if (weather == 1){
            act = false;
            if(rand.nextInt(laziness) != 1){
                act = true;
            }
        }
        if (act == true){
            if (time == false){
                if(isAlive()) {
                    findPartner(null, newSloth, null, null, null, foodLevel, ANIMAL_FOOD_VALUE, age, BREEDING_AGE, breedingProbability, MAX_LITTER_SIZE);        
                    // Try to move into a free location.
                    //Location newLocation = findFood(foodLevel, ANIMAL_FOOD_VALUE);
                    Location newLocation = findFood();
                    if(newLocation == null) { 
                        // No food found - try to move to a free location.
                        newLocation = getField().freeAdjacentLocation(getLocation());
                    }
                    findNewLocation(newLocation);
                }
            }
        }
    }

