function:
private void setMultipler(int season)
    {
        if (season == 0){
            setSeasonName("Spring");
            setMultiplier(0.68, 0.05, 0.03);
        }
        else if (season == 1){
            setSeasonName("Summer");
            setMultiplier(0.2, 1.5, 0.01);
        }
        else if (season == 2){
            setSeasonName("Autumn");
            setMultiplier(1.1, 0.4, 0.05);
        }
        else if (season == 3){
            setSeasonName("Winter");
            setMultiplier(1.5, 0.02, 0.07); 
        }
    }

public void simulateOneStep()
    {
        step++;
        World.simulateOneStep();
        if (rand.nextDouble() < NATURAL_DISASTER_CHANCE) {
            simulateNaturalDisaster();
        }
        // Provide space for newly generated  food objects.
        List<Food> newFoods = new ArrayList<>();
        // Let all food objects act.
        for(Iterator<Food> it = foods.iterator(); it.hasNext(); ) {
            Food food = it.next();
            food.act(newFoods);
            if(! food.isAlive()) {
                it.remove();
            }
        }

        // Add the newly generated food to the main lists.
        foods.addAll(newFoods);
        // System.out.println(""+newFoods.size()); // Displays number of new food
        view.showStatus(step, field);
    }

