function:
public String getPopulationDetails(Field field, Simulator simulator)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field, simulator);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

public void actDay(List<Animal> newCoyotes)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            // Give birth if coyotes of opposite gender meet.
            if(meet()){
                giveBirth(newCoyotes);
            }

            // Try to move into a location with food.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

