public List<Location> getFreeNearbyLocations(Location location, int radius)
    {
        List<Location> free = new LinkedList<>();
        List<Location> nearby = nearbyLocations(location, radius);
        for (Location next: nearby) {
            Object object  = getObjectAt(next);
            if (object == null || object instanceof Plant) {
                free.add(next);
            }
        }
        return free;
    }

