public Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            if(animal instanceof BlueWhale) {
                BlueWhale blueWhale = (BlueWhale) animal;
                if(blueWhale.isAlive()) { 
                    blueWhale.setDead();
                    setFoodLevel( getFoodLevel() + BLUEWHALE_FOOD_VALUE);
                    if(getFoodLevel() > MAX_HEALTH)
                    {
                        setFoodLevel(MAX_HEALTH);
                    }
                    return where;
                }
            }
            else if(animal instanceof Dolphin) {
                Dolphin dolphin = (Dolphin) animal;
                if(dolphin.isAlive()) { 
                    dolphin.setDead();
                    setFoodLevel( getFoodLevel() + DOLPHIN_FOOD_VALUE);
                    if(getFoodLevel() > MAX_HEALTH)
                    {
                        setFoodLevel(MAX_HEALTH);
                    }
                    return where;
                }
            }
        }

        return null;
    }

