docstring:
Method to determine whether it is raining at the moment.
@param step The current step.
@param timeTracker A TimeTracker object to determine the season.
@return (boolean) Whether it is currently raining.

function:
public boolean isRaining(int step, TimeTracker timeTracker) {
        // reduce raining steps
        raining--;

        if (raining > 0)
            return true;

        // this is the raining cooldown, once it rained it cannot start raining again for 20 steps.
        if (raining > -20)
            return false;

        String season = timeTracker.getSeason(step);
        switch (season) {
            case "winter":
                if (rand.nextDouble() <= SNOW_CHANCE_WINTER) {
                    // make it rain for 10 steps
                    raining = DURATION_OF_RAIN;
                    return true;
                }
            case "spring":
                if (rand.nextDouble() <= RAIN_CHANCE_SPRING) {
                    raining = DURATION_OF_RAIN;
                    return true;
                }
            case "summer":
                if (rand.nextDouble() <= RAIN_CHANCE_SUMMER) {
                    raining = DURATION_OF_RAIN;
                    return true;
                }
            case "autumn":
                if (rand.nextDouble() <= RAIN_CHANCE_AUTUMN) {
                    raining = DURATION_OF_RAIN;
                    return true;
                }
        }

        return false;
    }

private void checkSeason() {
        int currentMonth = time.getMonth();

        if(Tools.isBetween(currentMonth, 3, 5)) {
            if (currentSeason == "spring") return;
            changeSeason("spring");
        } else if (Tools.isBetween(currentMonth, 6, 8)) {
            if (currentSeason == "summer") return;
            changeSeason("summer");
        } else if (Tools.isBetween(currentMonth, 9, 11)) {
            if (currentSeason == "autumn") return;
            changeSeason("autumn");
        } else if (Tools.isBetween(currentMonth, 1, 2) || currentMonth == 12) {
            if (currentSeason == "winter") return;
            changeSeason("winter");
        }
    }

