public void simulateOneStep()
    {
        step++;
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();    
        if(timestamp % 60 <= 0) //makes the animals sleep whenever the time hits 60
        {
            sleeping = true;
        }
        else {
            sleeping = false;
        }
        // Let all animals act.

        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                Animal animal = it.next();
                if(sleeping == false){
                    animal.act(newAnimals);
                    if(! animal.isAlive()) {
                        it.remove();
                    }

                }
            }    

        // Add the newly born cheetahs, lions, zebras, antelopes and hyenas to the main lists.
        animals.addAll(newAnimals);


        timestamp = time.incrementTime(step); 

        view.showStatus(step, field, timestamp);

    }

