        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals, daytime, months, newYear);
            if(! animal.isAlive()) {
                it.remove();
            }
        }     
        // Add the newly born animal to the main list.
        animals.addAll(newAnimals);
    }

