private void giveBirth(List<Animal> newOctopus)
    {
        // New octopuss are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Octopus young = new Octopus(false, field, loc, time);
            newOctopus.add(young);
        }
    }

public boolean findPairs()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Object animal = field.getObjectAt(it.next());
            if(animal instanceof Horse) {
                Horse horse = (Horse) animal;
                if(horse.isAlive() && horse.getGender()) { 
                    return true;
                }
            }
        }
        return false;
    }

