private boolean canBreed()
    {
        //2 animals of the same species and different gender are next to each other.
        Field field = getField();
        List<Location> adjacentLocations=field.adjacentLocations(getLocation());
        Iterator<Location> it= adjacentLocations.iterator();
        while (it.hasNext()){
              Location where = it.next();
              Object animal = field.getObjectAt(where);
              if (where!=null){
                if (animal instanceof Rabbit){
                    Rabbit rabbit = (Rabbit) animal;
                    if ((!(rabbit.getIsMale()) && (getIsMale()))||
                    ((rabbit.getIsMale()) && !(getIsMale()))){
                        if ((rabbit.getAge()>= BREEDING_AGE) && (getAge()>=BREEDING_AGE)){
                            return true;
                        }else{
                            return false;
                        }
                    }
                }
              }
        }
        return false;
    }

public void clearAnimal()
