        for(int row = field.getDepth()/2; row < field.getDepth(); row++) {
            for(int col = (field.getWidth()-1)/2; col < field.getWidth()-1; col++) {
                if (test == false && field.getObjectAt(row, col) == null && field.getObjectAt(row, col+1) == null)
