public List<Location> getFreeDetectedLocations(Location location, int radius)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = detectedLocations(location, radius);
        for(Location next : adjacent) {
            if(getObjectAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

