docstring:
Look for rats and blobs adjacent to the current location.
A rat fully replenished the tiger's hunger, while a blob partially replenishes it.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.detectedLocations(getLocation(),1);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Rat) {
                Rat rat = (Rat) animal;
                if(rat.isAlive()) { 
                    rat.setDead();
                    foodLevel = RAT_FOOD_VALUE;
                    return where;
                } //verifies if animal is a rat, and if so, fully replenished hunger.
            } else if (animal instanceof GreyBlob){
                GreyBlob greyBlob = (GreyBlob) animal;
                if(greyBlob.isAlive()) { 
                    greyBlob.setDead();
                    if (foodLevel + GREYBLOB_FOOD_VALUE > RAT_FOOD_VALUE){
                        foodLevel = RAT_FOOD_VALUE;
                    } else{
                        foodLevel += GREYBLOB_FOOD_VALUE;
                    } //ensures food level never exceeds max food value
                    return where;
                } //verifies if animal is a blob, and if so, partially replenishes hunger.
            }
        }
        return null;
    }

public void incrementDayCount(){
        dayCount++;
        //System.out.println("day count : " + dayCount);
        weather.createWeather();
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(true , field, location);
                    plants.add(grass);
                }
                else if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lion lion = new Lion(true, field, location);
                    animals.add(lion);
                }

                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Zebra zebra = new Zebra(true, field, location);
                    animals.add(zebra);
                }
                else if(rand.nextDouble() <= HYENA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hyena hyena = new Hyena(true, field, location);
                    animals.add(hyena);
                }
                else if(rand.nextDouble() <= HIPPO_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hippo hippo = new Hippo(true, field, location);
                    animals.add(hippo);
                }
                else if(rand.nextDouble() <= ANTELOPE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Antelope antelope = new Antelope(true, field, location);
                    animals.add(antelope);
                }
                // else leave the location empty.
            }
        }
    }

public void reset()
    {
        step = 0;
        animals.clear();
        populate();
        time = 0;
        // Show the starting state in the view.
        view.showStatus(step, field);
    }

private void incrementAge()
    {
        if(isSick()){
            age += SICK_INCREMENT_AGE;
        }
        else{
            age++;
        }
        if(age > MAX_AGE) {
            setPlantDead();
        }
    }

