public void grow(int foodLevel)
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                plantLevel[row][col] += foodLevel;
                if(plantLevel[row][col] > PLANT_MAX_LEVEL){
                    plantLevel[row][col] = PLANT_MAX_LEVEL;
                }
            }
        }
    }

