public void simulateOneStep()
    {
        step++;
        //Time past 3 hours each step.
        time = time + 3;
        //random number for weather, 0 means sunny and 1 means rainy.
        Random rand = new Random();
        weather = rand.nextInt(2);
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>(); 
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();

            if(time < 21 || time > 6){
                if (weather == 1)
                {
                    animal.rest(newAnimals);
                    weathername = "Rainy";
                }
                else
                {
                    animal.act(newAnimals);
                    weathername = "Sunny";
                }
            }
            else{
                if (weather == 1)
                {
                    animal.rest(newAnimals);
                    weathername = "Rainy";
                }
                else
                {
                    animal.sleep(newAnimals);
                    weathername = "Sunny";
                }
            }
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born animals and grass to the main lists.
        animals.addAll(newAnimals);

        view.showStatus(step, time, weathername, field);
