private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if(organism instanceof Deer){
                Deer deer = (Deer) organism;
                if(deer.isAlive()){
                    // If the deer is infected by disease the bear will also be infected.
                    if (deer.isInfected()) {
                        infect();
                    }
                    // Increase the bear's food level by the food value of deer.
                    setFoodLevel(getFoodLevel() + DEER_FOOD_VALUE);
                    // Ensure that the food level does not go over the maximum.
                    if(getFoodLevel() > MAX_FOOD_LEVEL){
                        setFoodLevel(MAX_FOOD_LEVEL);
                    }
                    deer.setDead();
                    return where;
                }
            }
        }
        return null;
    }

