private void populate()
    {
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= HYENA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hyena hyena = new Hyena(true, field, location);
                    organisms.add(hyena);
                }
                else if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lion lion = new Lion(true, field, location);
                    organisms.add(lion);
                }
                else if(rand.nextDouble() <= WILDERBEEST_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Wildebeest wildebeest = new Wildebeest(true, field, location);
                    organisms.add(wildebeest);
                }
                else if(rand.nextDouble() <= ANT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Ant ant = new Ant(true, field, location);
                    organisms.add(ant);
                }
                else if(rand.nextDouble() <= TERMITE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Termite termite = new Termite(true, field, location);
                    organisms.add(termite);
                }
                // else leave the location empty.

                if (rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(field, location);
                    organisms.add(grass);
                }
            }
        }
    }

