public void simulateOneStep()
    {
        Random rand = Randomizer.getRandom();
        step++;
        boolean timeOfDay = time.isDay(step);
        String currentWeather = weather.getRandomWeather(step);
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();
        // Provide space for newborn plants.
        List<Plant> newPlants = new ArrayList<>();
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }
        }
        // Let all plants act.
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            plant.act(newPlants);
            if(plant.isEaten()) {
                it.remove();
            }
        }     
        //Add plants to the list if there are less than 500 plants and it is clear
        if (plants.size()<500 && weather.getCurrentWeather().equals("clear")){
            for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= 0.08) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(field, location, time, weather);
                    plants.add(grass);
                }
                // else leave the location empty.
            }
        }
        }
        // Add the newly born plants and  to the main lists.
         // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);
        plants.addAll(newPlants);

        view.showStatus(step, field, timeOfDay, currentWeather);
    }

