public void simulateOneStep()
    {
        step++;

        field.changeWeather();
        field.changeTime();

        // Provide space for newborn animals.
        List<Living> newLivingThings = new ArrayList<>();        

        for(Iterator<Living> it = livingThings.iterator(); it.hasNext(); ) {
            Living livingThing = it.next();
            livingThing.live();
            if(! livingThing.isAlive()) {
                it.remove();
            }

            //When it rains increase the food value of plants
            if(livingThing instanceof Plant){
                Plant plant = (Plant) livingThing;
                if(field.getWeather().name().equals("rain")){
                    plant.boostFoodLevel();
                }
            }

            //Check if the animal can act according to the day and weather
            if(livingThing instanceof Animal){
                Animal animal = (Animal) livingThing;
                if(doesAct(animal)){
                    animal.act(newLivingThings);
                }
            }

            livingThing.act(newLivingThings);
        }

        // Add the new organisms to the main lists.
        livingThings.addAll(newLivingThings);

        view.showStatus(step, field);
    }

private Wolf searchAdjacentLocationsForMale()
    {
        Field field = getField(); 
        List<Location> locations= field.adjacentLocations(getLocation());
        for (int i = 0; i < locations.size(); i++) 
        {
            Location z = locations.get(i);
            Object creature = field.getObjectAt(z); 
            if(creature instanceof Wolf)
            {
                Wolf wolf = (Wolf) creature;
                boolean gender = wolf.getGender();
                if(!gender)
                {
                    return wolf; 
                }
            }
        }
        return null; 
    }

