public void act(List<Animal> newCheetahes)
    {
        incrementAge();
        incrementHunger();

        if(isAlive()) {
            giveBirth(newCheetahes);            
            // Move towards a source of food if found.
            if(getTime()=="night")
            {
                Location newLocation = findFood();

                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }
            if(getTime()=="day"){
                Location newLocation = getLocation();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }

        }
    }

