    {
        boolean canBreed = false; 
        Field field = getField();
        for (Location i : field.adjacentLocationsForPrey(getLocation()))
        {
            if (field.getObjectAt(i) instanceof tiger)
            {
                tiger tig = (tiger) field.getObjectAt(i);
                if ((age >= BREEDING_AGE) && (tig.getGenderMale() != getGenderMale()))
                {
                 canBreed = true;
                }
            }
