@param currentFoodLevel The animal's current food level
@param newFoodLevel The animal's new food level

@return The vegetable's location or null.

function:
protected Location findVegetable(int currentFoodLevel, int newFoodLevel)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object plant = field.getObjectAt(where);
            if(plant instanceof Vegetable ) {
                Vegetable vegetable = (Vegetable) plant;
                if(vegetable.isAlive()) { 
                    vegetable.setDead();
                    currentFoodLevel = newFoodLevel;
                    return where;
                }
            }
        }
        return null;
    }

