docstring:
Look for rabbits adjacent to the current location.
Only the first live rabbit is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (foodChain.canEat((Organism<?>) organism)) {
                // if not hungry don't eat
                if (!this.isHungry()) continue;

                Organism targetAnimal = (Organism<?>) organism;
                if (targetAnimal.isAlive()) {
                    targetAnimal.setDead();
                    this.setFoodLevel(foodLevel += targetAnimal.getFoodValue());
                    return where;
                }
            }
        }
        return null;
    }

docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(String time, String weather, int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    //Set color to given color of class
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                    //set animal color to black if diseased
                    if (animal instanceof Animal){
                        Animal ani = (Animal) animal;
                        if (ani.getDiseased()){
                            fieldView.drawMark(col, row, Color.BLACK);
                        }
                    }
                    if (animal instanceof Plant){
                        Plant plant = (Plant) animal;
                        if (plant.getDarker()){
                            fieldView.drawMark(col, row, Color.GREEN.darker());
                        }
                    }
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        //display field stats 
        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        timeLabel.setText(TIME_PREFIX + time + " ");
        weatherLabel.setText(WEATHER_PREFIX + weather);
        fieldView.repaint();
    }

