private void giveBirth(List<Animal> newAnimals)
    {
        Animal breedingAnimal = getBreedingAnimalAdjacent(breedingTypeList);        

        if (breedingAnimal != null) {
            // New Greenies are born into adjacent locations.
            // Get a list of adjacent free locations.
            Field field = getField();
            List<Location> free = field.getFreeAdjacentLocations(getLocation());
            int births = getBreedNumber(age, BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);

            if (breedingAnimal instanceof Greeny) {
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    Greeny young = new Greeny(false, field, loc);
                    newAnimals.add(young);
                }
            }
            else if (breedingAnimal instanceof Bluy) {
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    Cyany young = new Cyany(false, field, loc);
                    newAnimals.add(young);
                }
            }

            // When an nfected aniaml breeds, it can spread the disease.
            if(getIsInfected()) {
                spreadInfection(BREED_SPREAD_PROBABILITY);
            }
        }
    }

private boolean canBreed()
    {
        return age >= BREEDING_AGE && foodlevel > 45;
    }

private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        //Random worm created as backup food.
        Worm randomWorm = null;

        while (it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            if (animal instanceof Squirrel) {
                Squirrel squirrel = (Squirrel) animal;
                if (squirrel.isAlive()) {
                    squirrel.setDead();
                    this.foodLevel = MAX_FOOD_VALUE;
                    this.incrementPower(5);
                    return where;
                }
            } else if (animal instanceof Worm) {
                Worm worm = (Worm) animal;
                if (worm.isAlive()) {
                    worm.setDead();
                    this.foodLevel = MAX_FOOD_VALUE;
                    this.incrementPower(5);
                    return where;
                }
            }
        }

        if (this.foodLevel <= 3 && randomWorm != null) {
            Location where = randomWorm.getLocation();
            randomWorm.setDead();
            this.incrementFoodLevel(5);
            this.incrementPower(3);

            return where;
        }

        return null;

    }

