private void giveBirth(List<Creature> newDragonfly)
    {
        // New Dragonflyes are born into adjacent locations.
        // Get a list of adjacent free locations.
        // this method is only called by female dragonfly
        if(!getGender())
        {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext())
            {
                Location where = it.next();
                Object what = field.getObjectAt(where);
                if(what instanceof Dragonfly)
                {
                    Dragonfly dragonfly = (Dragonfly) what;
                    //only reproduce when this two dragonfly are of opposite gender
                    if(dragonfly.getGender())
                    {
                        List<Location> free = field.getFreeAdjacentLocations(getLocation());
                        int births = breed();
                        for(int b = 0; b < births && free.size() > 0; b++) {
                            Location loc = free.remove(0);
                            Dragonfly young = new Dragonfly(false, field, loc);
                            newDragonfly.add(young);
                            break;
                           }
                    }
                }
            }
        }
    }

public void simulateOneStep()
    {
        step++;
        // Update the time of the day.
        environment.timeChanger(step);
        boolean isDay = environment.getTime();
        // Illustrate the time of the day.
        view.emptyFieldColor(isDay);

        // Provide space for new species.
        List<Species> newSpecies = new ArrayList<>();        
        // Let all species act.
        for(Iterator<Species> it = species.iterator(); it.hasNext(); ) {
            Species creature = it.next();
            if(isDay) {    // During the day, all species act. 
                creature.act(newSpecies);
            }
            else { // At night, all species sleep but wolves and snakes.
                if (creature.getClass() == Wolf.class || creature.getClass() == Snake.class) {
                    creature.act(newSpecies);
                }
            }
            if(! creature.isAlive()) { //if creature is dead, remove it
                it.remove();
            }
        }

        // Add the newly produced species to the main lists.
        species.addAll(newSpecies);

        // Updates the view
        view.showStatus(step, field, environment);
    }

