public void act(List<Animal> newBlueTangs, boolean day) {
        // increments the age, hunger
        incrementAge();
        incrementHunger();
        // checks if disease is affecting it
        daysLeft();
        // check if bluetang is alive
        if (isAlive()) {
            // if it is female tries to breed, at night it is less likely that they breed
            if ((day && !isMale()) || (!isMale() && rand.nextDouble() <= 0.1))  {
                giveBirth(newBlueTangs);
            }
            // Try to find food.
            Location newLocation = findFood();
            if (newLocation == null) {
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // if it's night they move less
            if (day || (rand.nextDouble() <= 0.1)) {
                // See if it was possible to move.
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

