Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.
@param environment The current environment.

function:
public void showStatus(int step, Field field, Environment environment)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        weatherLabel.setText(WEATHER_PREFIX + environment.getWeather());
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object species = field.getObjectAt(row, col);
                if(species != null) {
                    stats.incrementCount(species.getClass());
                    fieldView.drawMark(col, row, getColor(species.getClass()));
                    if (species instanceof Lion){ // if the lion is sick -> change color
                        Lion lion= (Lion) species;
                        if (lion.getIsInfected()){
                            fieldView.drawMark(col, row, Color.MAGENTA.darker());
                        }
                    }
                }
                else {
                    fieldView.drawMark(col, row, empty_color);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

