docstring:
Check whether or not this mouse is to give birth at this step.
New births will be made into free adjacent locations.
@param newMice A list to return newly born mice.

function:
private void giveBirth(List<Organism> newMice)
    {
        // New mice are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Mouse) {
                Mouse mouse = (Mouse) animal;
                if(mouse.getIsMale() != getIsMale()) { 
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Mouse young = new Mouse(false, field, loc);
                        newMice.add(young);
                    }
                }
            }
        }
    }

protected List<Object> predatorsNearby()
    {      
        if (freeAdjacentLocations.size() > 0) {
            for (int i = 0; i < freeAdjacentLocations.size(); i++) {
                if (field.getObjectAt(freeAdjacentLocations.get(i)) instanceof Predator) {
                    nearbyPredators.add(field.getObjectAt(freeAdjacentLocations.get(i)));
                }
            }
        }
        return nearbyPredators;
    }

public void performDayBehaviour(List<Animal> newPredators) {
    incrementHunger();
    if (isAlive()) {
      giveBirth(newPredators);
      // See if it was possible to move.
      Location newLocation = getField().freeAdjacentLocation(getLocation());
      if (newLocation != null) {
        setLocation(newLocation);
      } else { // Overcrowding.
        setDead();
      }
    }
  }

