public void act(List<Animal> newSharks, boolean day) {
        // increments the age, hunger
        incrementAge();
        incrementHunger();
        // checks if disease is affecting it
        daysLeft();
        // checks if shark is alive
        if (isAlive()) {
            // if it is female tries to breed
            if (!isMale()) {
                giveBirth(newSharks);
            }
            Location newLocation;
            // if it's night there is only 0.5 chance they hunt
            if (day || rand.nextDouble() <= 0.5) {
                // Move towards a source of food if found.
                newLocation = findFood();
                if (newLocation == null) {
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
            } else {
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if (newLocation != null) {
                setLocation(newLocation);
            } else {
                // Overcrowding.
                setDead();
            }
        }
    }

