public void temperature(boolean[] weatherParam, int step) {

		if (step % heatCheckRate == 0) {
			boolean sign = rand.nextBoolean();
			if (sign) {
				currentTemp = (currentTemp + rand.nextInt(3));
			} else {
				currentTemp = (currentTemp - rand.nextInt(3));
			}
		}

		if (currentTemp > heatLimit) {
			weatherParam[1] = false;
		} else {
			weatherParam[1] = true;
		}
	}

