public void act(List<Organism> newSpiders)
    {
        incrementAge();
        incrementHunger();

        //checks if the animal has a disease (checkDisease() also checks if the animal will die from it).
        //If true, the animal is set to dead.
        if(checkDisease()){
            setDead(); 
        }

        if(isAlive()) {
            ability = getField().getWeather().getMultiplier();

            //Spiders act during the day and sleep (do nothing) at night.
            if (getField().getTime().isDay() && getRandom().nextDouble() <= ability) {
                giveBirth(newSpiders);            
                // Move towards a source of food if found.
                Location newLocation = findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }

        }
    }

