docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }
        //prints "It is autumn! Step: " when steps are 0 - 999
        if(step > 0 && step < 1000){
            STEP_PREFIX = "It is autumn! Step: ";
            stepLabel.setText(STEP_PREFIX + step);
            stats.reset();
        }
        //prints "It is winter! Step: " when steps are  1000 - 1999
        if(step > 1000 && step < 2000){
            STEP_PREFIX = "It is winter! Step: ";
            stepLabel.setText(STEP_PREFIX + step);
            stats.reset();
        }
        //prints "It is spring! Step: " when steps are 2000 - 2999
        if(step > 2000 && step < 3000){
            STEP_PREFIX = "It is spring! Step: ";
            stepLabel.setText(STEP_PREFIX + step);
            stats.reset();
        }
        //prints "It is summer! Step: " when steps are more than 3000
        if(step > 3000){
            STEP_PREFIX = "It is summer! Step: ";
            stepLabel.setText(STEP_PREFIX + step);
            stats.reset();
        }

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

docstring:
Generate a number representing the number of births,
if it can breed.
@return The number of births (may be zero).

function:
protected int breed(int currentNumberOfAnimal)
    {
        int births = 0;

        // double counterCyclical = -(1 / (1 + Math.pow(Math.E, -((currentNumberOfAnimal / 20 - 40))))) + getBreedingProbability();//See report for formula

        double counterCyclical = (2 * getBreedingProbability()) / (1 + Math.pow(Math.E, (currentNumberOfAnimal / 50) - 300));

        // double breedingProbability = (getBreedingProbability() + counteCyclical) / 2; //Counter cyclical calculations

        if(rand.nextDouble() <= counterCyclical) {
            births = rand.nextInt(getMaxLitterSize()) + 1;
        }
        return births;
    }

