private SwingWorker createWorker(Simulator simulator) {
        return new SwingWorker<Boolean, Object>() {
            @Override
            protected Boolean doInBackground() throws Exception {  
                notSimulating = false;
                for(int i = 0; i < simulator.getLongSimulationDuration() && simulator.isViable(); i++) {
                    simulator.simulateOneStep();
                }
                notSimulating = true;
                return true;
            }
        };
