protected void spreadDisease() {
        List<Location> adjacentTiles = new LinkedList<>(); //instantiates list of adjacent tiles
        adjacentTiles = forest.adjacentLocations(getLocation()); //fills list of adjacent tiles based on animal's current location
        for (Location tile: adjacentTiles) //scans adjacent tiles
        {
            if (forest.getObjectAt(tile) == null) {
                continue; //skips current iteration
            }
            else {
                Animal animal = (Animal) forest.getObjectAt(tile);
                animal.catchDisease();
            }
        }
    }

public void act(List<Entity> newEntities) {
        incrementAge();
        incrementHunger();
        checkInfection();

        // Animal may be dead at this point, so double-check
        if (isAlive()) {
            checkNeighbouringDiseasedEntities();
            toggleSleep();

            // If the animal is sleeping, we don't want it to move or give birth.
            if (isSleeping) {
                return;
            }

            giveBirth(newEntities);
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if (newLocation == null) {
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation(), getMoveRadius());
            }
            // See if it was possible to move.
            if (newLocation != null) {
                setLocation(newLocation);
            } else if (getMoveRadius() != 0){
                // Overcrowding.
                setDead();
            }
        }
    }

