docstring:
Look for grasses, fruits and ferns adjacent to the current location.
Only the first live plant is eaten.

@return Where food was found, or null if it wasn't.

function:
private Location findFood() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (organism instanceof Grass) {
                Grass grass = (Grass) organism;
                if (grass.isAlive()) {
                    grass.setDead();
                    foodLevel = Math.min(foodLevel + GRASS_FOOD_VALUE, FOOD_CAPACITY);
                    return where;
                }
            }
            if (organism instanceof Fruit) {
                Fruit fruit = (Fruit) organism;
                if (fruit.isAlive()) {
                    fruit.setDead();
                    foodLevel = Math.min(foodLevel + FRUIT_FOOD_VALUE, FOOD_CAPACITY);
                    return where;
                }
            }
            if (organism instanceof Fern) {
                Fern fern = (Fern) organism;
                if (fern.isAlive()) {
                    fern.setDead();
                    foodLevel = Math.min(foodLevel + FERN_FOOD_VALUE, FOOD_CAPACITY);
                    return where;
                }
            }
        }
        return null;
    }

public void reset()
    {
        step = 0;
