public void simulateOneStep()
    {
        step++;

        // Provide space for newborn livingThings.
        List<LivingThings> newAnimals = new ArrayList<>();        
        // Let all rabbits act.
        for(Iterator<LivingThings> it = livingThings.iterator(); it.hasNext(); ) {
            LivingThings livingThings = it.next();
            livingThings.act(newAnimals);
            if(! livingThings.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born foxes and rabbits to the main lists.
        livingThings.addAll(newAnimals);

        view.showStatus(step, field);
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= WHALE_CREATION_PROBABILITY) {
                    //create whale
                    Location location = new Location(row, col);
                    Whale whale = new Whale(true, field, location);
                    actors.add(whale);
                }
                else if(rand.nextDouble() <= SALMON_CREATION_PROBABILITY) {
                    //create salmon
                    Location location = new Location(row, col);
                    Salmon salmon = new Salmon(true, field, location);
                    actors.add(salmon);
                }
                else if(rand.nextDouble() <= SEABASS_CREATION_PROBABILITY) {
                    //create sea bnass
                    Location location = new Location(row, col);
                    SeaBass seabass = new SeaBass(true, field, location);
                    actors.add(seabass);
                }
                else if(rand.nextDouble() <= SHARK_CREATION_PROBABILITY) {
                    //create shark
                    Location location = new Location(row, col);
                    Shark shark = new Shark(true, field, location);
                    actors.add(shark);
                }
                else if(rand.nextDouble() <= SARDINE_CREATION_PROBABILITY) {
                    //create sardine
                    Location location = new Location(row, col);
                    Sardine sardine = new Sardine(true, field, location);
                    actors.add(sardine);
                }
                else if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    //create plant
                    Location location = new Location(row, col);
                    Plant plant = new Plant(true, field, location);
                    actors.add(plant);
                }
                // else leave the location empty.
            }
        }
    }

docstring:
Look for food source adjacent to the current location.
Only the first live food source is eaten.

@return Where food was found, or null if it wasn't.

function:
protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object obj = field.getObjectAt(where);
            //empty cell
            if(obj == null){
                continue;
            }
            //is not part of the diet
            if(!dietContains(obj.toString())) {
                continue;   
            }
            //is dead
            Actor food = (Actor) obj;
            if(!food.isAlive()) {
                continue;
             }
            return eat(where, food);
        }
        return null;
    }

