    }

docstring:
Look for plants adjacent to the current location.
Only the first live plant is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood(){
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());

        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Plant) {
                Plant plant = (Plant) animal;                
                if(plant.isAlive()) { 
                    // the squirrel eats the plant.
                    plant.setDead();
                    foodLevel += PLANT_FOOD_VALUE;
                    // if the squirrel reaches a food value more than it's intended
                    // max food value, it will cut off the extra, a squirrel can't eat more
                    // than what it's stomach can handle.
                    if(foodLevel>FOOD_VALUE){
                        int extraFood = Math.abs(FOOD_VALUE-foodLevel);
                        foodLevel -= extraFood;
                    }
                    return where;
                }
            }
        }

        // If there is no food.
        return null;
    }

private boolean findMate() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Lizard) {
                Lizard lizard = (Lizard) animal;

                if(isFemale() != lizard.isFemale() ) { 
                     if (lizard.isDiseased()){ 
                     setDiseased();
                 }
                 if (isDiseased()){
                   lizard.setDiseased(); 
                    }
                     return true; 
                }
            }

        }
        return false;
    }

