private int countTotalSpecies(Class species) {
        int count = 0;
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if (animal != null) {
                    if (animal.getClass().equals(species)) {
                        count++;
                    }
                }
            }
        }
        return count;
    }

docstring:
Foxes can breed if they have reached the breeding age, are near an animal of the same
species and of the opposite gender.
@return true if the fox can breed, false otherwise.

function:
private boolean canBreed()
    {
        //2 animals of the same species and different gender are next to each other.
        Field field = getField();
        List<Location> adjacentLocations=field.adjacentLocations(getLocation());
        Iterator<Location> it= adjacentLocations.iterator();
        while (it.hasNext()){
              Location where = it.next();
              Object actor = field.getObjectAt(where);
              if (where!=null){
                if (actor instanceof Fox){
                    Fox fox = (Fox) actor;
                    if ((!(fox.getIsMale()) && (getIsMale()))||
                    ((fox.getIsMale()) && !(getIsMale()))){
                        if ((fox.getAge()>= BREEDING_AGE) && (getAge()>=BREEDING_AGE)){
                            return true;
                        }else{
                            return false;
                        }
                    }
                }
              }
        }
        return false;
    }

