private void populate() {
    Random rand = Randomizer.getRandom();
    field.clear();
    for (int row = 0; row < field.getDepth(); row++) {
      for (int col = 0; col < field.getWidth(); col++) {
        if (rand.nextDouble() <= PREDATOR_CREATION_PROBABILITY) {
          Location location = new Location(row, col);
          Crocodile crocodile = new Crocodile(true, field, location);
          animals.add(crocodile);
        } else if (rand.nextDouble() <= PREDATOR_CREATION_PROBABILITY) {
          Location location = new Location(row, col);
          Lion lion = new Lion(true, field, location);
          animals.add(lion);
        } else if (rand.nextDouble() <= PREY_CREATION_PROBABILITY) {
          Location location = new Location(row, col);
          Mouse mouse = new Mouse(true, field, location);
          animals.add(mouse);
        } else if (rand.nextDouble() <= PREY_CREATION_PROBABILITY) {
          Location location = new Location(row, col);
          Zebra zebra = new Zebra(true, field, location);
          animals.add(zebra);
        } else if (rand.nextDouble() <= PREY_CREATION_PROBABILITY) {
          Location location = new Location(row, col);
          Antelope antelope = new Antelope(true, field, location);
          animals.add(antelope);
        }

        // else leave the location empty.
      }
    }
  }

