@Override
    public void act(List<Actor> newGiraffe, double weatherEffect)
    {
        super.incrementAge();
        incrementHunger();
        if(isAlive()) {
            if (super.getGender() && meet(this)){
                giveBirth(newGiraffe); 
            }
            // Move towards a source of food if found.
            Location newLocation = findFood();

            // Check if the animal has eaten a poisonous plant
            if (!isActive())
            {
                return; 
            }

            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

docstring:
Look for fish and tuna adjacent to the current location.
Only the first live fish or tuna is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Fish) {
                Fish fish = (Fish) animal;
                if(fish.isAlive()) { 
                    fish.setDead();
                    foodLevel = FISH_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Tuna){
                Tuna tuna = (Tuna) animal ;
                if(tuna.isAlive()){
                    tuna.setDead();
                    foodLevel = TUNA_FOOD_VALUE;
                }
            }
        }
        return null;
    }

