docstring:
Antelope acts differently depending on the time of the day and the weather.
@param newAntelopes The list of new born antelopes
@param timeOfDay The time of the day.
@param chanceOfDying The probability of animal dying if it is infected.
@param weather The weather type.

function:
public void act(List<Animal> newAntelopes, int timeOfDay, double chanceOfDying, int weather) {        
        if(timeOfDay == 0) {
            increaseAge(MAX_AGE);
        }

        checkDisease(chanceOfDying);

        if(isAlive()) {
            switch(weather) {
                case 2:
                // The weather is foggy, so the Antelope does not move
                switch(timeOfDay) {
                    case 0:
                    // Morning, Antelope gives birth, eats, and food level decreases
                    if(!isAnimalMale()){
                        giveBirth(newAntelopes);
                    }
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    decreaseFoodLevel(4);
                    break;

                    case 1:
                    // Afternoon, Antelope gives birth, eats, food level decreases
                    if(!isAnimalMale()) {
                        giveBirth(newAntelopes);
                    }                    
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    decreaseFoodLevel(3);
                    break;

                    case 2:
                    // Evening, Antelope gives birth, eats, food level decreases 
                    if(!isAnimalMale()) {
                        giveBirth(newAntelopes);
                    }                       
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    decreaseFoodLevel(2);
                    break;

                    case 3:
                    // Night, Antelope sleeps
                    break;
                }
                break;

                default:
                switch(timeOfDay) {

                    case 0:
                    // Morning, Antelope gives birth, eats, moves, and food level decreases 
                    if(!isAnimalMale()) {
                        giveBirth(newAntelopes);
                    }         
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(2);
                    decreaseFoodLevel(4);
                    break;

                    case 1:
                    // Afternoon, Antelope gives birth, eats, moves, and food level decreases 
                    if(!isAnimalMale()) {
                        giveBirth(newAntelopes);
                    }       
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(2);
                    decreaseFoodLevel(3);
                    break;

                    case 2:
                    // Evening, Antelope gives birth, eats, moves, and food level decreases
                    if(!isAnimalMale()) {
                        giveBirth(newAntelopes);
                    }          
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(2);
                    decreaseFoodLevel(2);
                    break;

                    case 3:
                    // Night, Antelope sleeps
                    break;
                }
                break;
            }
        }
    }

