private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                if (rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    actors.add(new Lion(true, field, location));
                    animals.add(Lion.class);
                }
                else if (rand.nextDouble() <= HYENA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    actors.add(new Hyena(true, field, location));
                    animals.add(Hyena.class);
                }
                else if (rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    actors.add(new Cheetah(true, field, location));
                    animals.add(Cheetah.class);
                }
                else if (rand.nextDouble() <= GIRAFFE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    actors.add(new Giraffe(true, field, location));
                    animals.add(Giraffe.class);
                }
                else if (rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    actors.add(new Zebra(true, field, location));
                    animals.add(Zebra.class);
                }
                else if(rand.nextDouble() <= HUNTER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    actors.add(new Hunter(field, location));
                }
                else if (rand.nextDouble() <= RANGER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    actors.add(new Ranger(field, location));
                }
                else if (rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    actors.add(new Plant(field, location));
                }
                // else leave the location empty.
            }
        }
    }

public void simulateOneStep()
    {
        step++;

        if(step % 100 == 0) {
            if(State.TIME.getValue() == Value.DAY) {
                State.TIME.setValue(Value.NIGHT);
            } else {
                State.TIME.setValue(Value.DAY);
            }
        }

        if(step % 250 == 0) {
            State.WEATHER.setValue(Value.randomWeather());
        }

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();
        // Provide space for newly grown plants.
        List<Plant> newPlants = new ArrayList<>();
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }
        }
        // Let all plants grow.
        for(Iterator<Plant> it = plants.iterator(); it.hasNext();) {
            Plant plant = it.next();
            plant.grow(newPlants);
            if(!plant.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born foxes and Deers to the main lists.
        animals.addAll(newAnimals);
        // Add newly grown plants to main lists.
        plants.addAll(newPlants);

        view.showStatus(step, field);
    }

public void act(List<Animal> newDucks)
    {
        if (!getInfected()) setInfected(rand.nextDouble() < PROBABILITY_OF_RANDOM_INFECTION);
        incrementAge(MAX_AGE);
        incrementHunger();
        if(isAlive()) {
            // If this animal has a disease, there is a small chance it will die this step
            if (getInfected() && rand.nextDouble() < PROBABILITY_OF_DEATH_FROM_INFECTION) {
                setDead();
                return;
            }
            giveBirth(newDucks);            
            // Move towards a source of food if found.
            Location newLocation = findFood(null);
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

