private void printMap()
    {
        for(int i = 0; i < depth; i++){
            for(int j = 0; j < width; j++){
                if(j == (width - 1)){
                    System.out.print("\n");
                }
                if(weatherMap[i][j] == false){
                    System.out.print(".");
                }
                else if(weatherMap[i][j] == true){
                    System.out.print("x");
                }
            }
        }
        System.out.println();
    }

