public void simulateOneStep()
    {
        step++;
        checkNight(step); // check the time of the day

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();   
        weather.randWeather(); // create the random weather
        if (!night){
            for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                Animal animal = it.next();
                if(!weather.getWeather().equals("fog")){
                    animal.act(newAnimals);
                }
                else{
                    animal.incrementHunger();
                    animal.incrementAge();
                }
                if(! animal.isAlive()) {
                    it.remove();
                }
            }
        } 
        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);

        // Provide space for newborn plants.
        List<Plant> newPlants = new ArrayList<>();  
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            plant.act(newPlants);
            if(! plant.isAlive()) {
                it.remove();
            }
        }
        // Add the newly born plants to the main lists.
        plants.addAll(newPlants);

        // Provide space for hunters to move.
        List<Hunter> newHunters = new ArrayList<>();  
        for(Iterator<Hunter> it = hunters.iterator(); it.hasNext(); ) {
            Hunter hunter = it.next();
            hunter.act(newHunters);
        }

        view.showStatus(step, field);
    }

private boolean meet()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Cheetah) {
                Cheetah cheetah = (Cheetah) animal;
                if(!isMale) { 
                    return true;
                } 
                else{
                    return false;
                }
            }
        }
        return false;
    }

