private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= JAGUAR_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Jaguar jaguar = new Jaguar(true, true, true, field, location);
                    animals.add(jaguar);
                }
                else if(rand.nextDouble() <= CAPYBARA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Capybara capybara = new Capybara(true, true, true, field, location);
                    animals.add(capybara);
                }
                else if(rand.nextDouble() <= ANACONDA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Anaconda anaconda = new Anaconda(true, true, true, field, location);
                    animals.add(anaconda);
                }
                else if(rand.nextDouble() <= RAT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Rat rat = new Rat(true, true, true, field, location);
                    animals.add(rat);
                }
                else if(rand.nextDouble() <= OWL_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Owl owl = new Owl(true, true, true, field, location);
                    animals.add(owl);
                }                
                else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(true, field, location);
                    plants.add(grass);
                }
                // else leave the location empty.
            }
        }
    }

