public Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext())
        {
            Location where = it.next();
            Object Organism = field.getObjectAt(where);
            if(Organism instanceof buffalo) 
            {
                buffalo buffalo = (buffalo) Organism;
                if(buffalo.isAlive()) 
                { 
                    //System.out.println("Buffalo eaten by tiger");
                    buffalo.setDead();
                    foodLevel = buffalo_FOOD_VALUE;
                    return where;
                }
            }
            if(Organism instanceof monkey) 
            {
                monkey monkey = (monkey) Organism;
                if(monkey.isAlive())
                { 
                    //System.out.println("Monkey eaten by tiger");
                    monkey.setDead();
                    foodLevel = monkey_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

