function:
private void giveBirth(List<Animal> newRabbits)
    {
        // New rabbits are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());

        Location curLocation = getLocation();
        boolean canBreed = false;
        List<Location> adjacentLocations = field.adjacentLocations(curLocation);
        List<Rabbit> adjacentRabbits = new ArrayList<Rabbit>();
        for (Location af : adjacentLocations)
            {
                if (field.getObjectAt(af) instanceof Rabbit) {
                    Rabbit rabbit = (Rabbit) field.getObjectAt(af);
                    adjacentRabbits.add(rabbit);
                }
            }
        for (Rabbit af : adjacentRabbits)
            {
                if ((af.getMaleGender() == false && this.getMaleGender() == true) || (af.getMaleGender() == true && this.getMaleGender() == false)) {
                    canBreed = true;
                }
            }

        int births = breed();
        if (canBreed == true) {
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Rabbit young = new Rabbit(false, field, loc);
                newRabbits.add(young);
            }
        }
    }

