docstring:
This is what the rabbit does most of the time - it runs
around. Sometimes it will breed or die of old age.
@param newRabbits A list to return newly born rabbits.

function:
public void act(List<Animal> newRabbits)
    {
        incrementAge();
        incrementHunger();

        // Check if sick and make the disease act
        if (this.isSick()) {
            this.getDisease().act();
        } 

        if(isAlive()) {
            giveBirth(newRabbits);

            // If not sick, but have luck -> get infected with a new Disease
            if (!isSick()) {
                if (rand.nextDouble() <= this.getSicknessProbability()) {
                    // Get infected by a random disease
                    this.becomeInfected();
                }
            }

            Location newLocation = findFood();

            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

public void incrementAge()
    {
        age++;
        if(age > getMaxAge()) 
        {
            setDead();
        }
    }

private boolean checkDisease()
    {
        if(hasDisease){
            TURNS_UNTIL_DEATH++; //Counter integer that tracks the number of turns since infection.
            int CHANCE_OF_SPREAD = rand.nextInt(20);
            if(CHANCE_OF_SPREAD == 20){
                Iterator<Location> it = findAnimalLocation().iterator();
                while(it.hasNext()) {
                    Location where = it.next();
                    Object animal = field.getObjectAt(where);
                    if(animal instanceof Antelope) {
                        Antelope antelope = (Antelope) animal;
                        antelope.gotDisease();
                    } else if(animal instanceof Wildebeest) {
                        Wildebeest wildebeest = (Wildebeest) animal;
                        wildebeest.gotDisease();
                    } else if(animal instanceof Snake) {
                        Snake snake = (Snake) animal;
                        snake.gotDisease();
                    } else if(animal instanceof Hyena) {
                        Hyena hyena = (Hyena) animal;
                        hyena.gotDisease();
                    } else if(animal instanceof Lion) {
                        Lion lion = (Lion) animal;
                        lion.gotDisease();
                    }
                }
            }
            if(TURNS_UNTIL_DEATH >= 20){
                return true;
            } else{
                return false;
            }
        } else{
            return false;
        }
    }

