private void giveBirth(List<Animal> newDeers)
    {
        Field field = getField();
        boolean isNeighborMale = false;
        for (Location l : field.getFilledAdjacentLocations(getLocation())){
            Object object = field.getObjectAt(l);
            if(object instanceof Deer){
                if (((Deer)object).getSex() == Sex.Male){
                    isNeighborMale = true;
                    break;
                }

            }
        }
        if(isNeighborMale) {
            List<Location> free = field.getFreeAdjacentLocations(getLocation());
            int births = breed();
            for (int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Deer young = new Deer(false, field, loc);
                newDeers.add(young);
            }
        }
    }

