public void act(List<Organism> newPredators, String weather)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) 
        {
            giveBirth(newPredators);
            hasRabies();
            checkDisease();
            // Move towards a source of food if found.
            if (!isFoggy(weather))
            {
                Location newLocation = findFood();
                checkRabies();
                if(newLocation == null) 
                { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null)
                {
                    setLocation(newLocation);
                }
                else {
                    setDead();
                }
            }
        }
    }

private void checkDisease()
    {
        Field field = getField();
        List<Location> free = field.adjacentLocations(getLocation());
        Iterator<Location> it = free.iterator();
        while(it.hasNext()) 
        {
            Location where = it.next();
            Object Organism = field.getObjectAt(where);
            if(Organism instanceof Prey) 
            {
                Prey prey = (Prey) Organism;
                if(prey.isAlive()) 
                { 
                    if (prey.checkZoonosis())
                    {
                        hasZoonosis = true;
                    }
                }
            }
        }
    }

