    {
        Random rand = Randomizer.getRandom();
        double x = rand.nextDouble();
        if (x <= 0.6){
           count = 0; 
        }
        else if (x > 0.6 && x <= 0.85){
            count = 1;
        }
        else if (x > 0.85 && x < 0.9){
            count = 2;
        }
        else{
            count = 3;
        }
        //Set final weather to whichever type of weather has been chosen
        finalWeather = weatherTypes.get(count);
    }

