public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed)
    {
        // 1)
        if (yearPassed) {
            incrementAge();
        }

        // 2)
        if(isAlive())
        {
            // i)
            checkHibernation(temperature);

            // ii)
            if (inHibernation)
            {
                // a)
                if (hiberSteps % STAY_STEPS == 0)   {
                    makeMove(newSpecies);
                    incrementHunger();
                }
                // b)
                incrementHiberSteps();
            }
            // iii)
            else if (! survivesTemperature(temperature))
            {
                setDead();
            }
            // iv)
            else
            {
                // a)
                if (isNight && isNocturnal) {
                    makeMove(newSpecies);
                }
                // b)
                else if (! isNight) {
                    makeMove(newSpecies);
                }
                if  (! isNight) {
                    incrementHunger();
                }
            }
        }
    }

