function:
public List<Location> getPlantFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getPlantAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

@Override
    public void act(List<Creature> newCreatures, int hour, Field.Weather weather)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            if(isActive(hour)) {
                giveBirth(newCreatures);
                // Move towards a source of food if found.
                Location newLocation = foodLevel < getMinFoodLevel() && weather != Field.Weather.FOG ? findFood() : null;

                if (newLocation == null) {
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation(), getLayer());
                }
                // See if it was possible to move.
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    // Overcrowding.
                    setDead();
                }
            }
            --foodLevel;
        }
    }

private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

