docstring:
Check whether or not this holf is to give birth at this step.
New births will be made into free adjacent locations.
@param newHolves A list to return newly born holf.
@param season the current season

function:
private void reproduce(List<Animal> newHolves, Season season) {
        // New holf are born into adjacent locations.
        // Get a list of adjacent free locations.
        Animal mate = super.isAdjacentMateExists(this);

        if (mate != null) {
            Field field = getField();
            List<Location> free = field.getFreeAdjacentLocations(getLocation(), EnvironmentsLayout.ANIMALS);
            int births = breed(season);
            for (int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Holf young = new Holf(super.reproduceGenes(getGenes(), mate.getGenes()), field, loc, false);
                newHolves.add(young);
            }
        }
    }

docstring:
Look for prey adjacent to the current location.
Only the first live prey is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object actor = field.getObjectAt(where);
            //The tiger will eat animals in this order of precedence if available
            if(actor instanceof Giraffe) {
                Giraffe giraffe = (Giraffe) actor;
                if(giraffe.isAlive()) { 
                    giraffe.setDead();
                    getDiseases().addAll(giraffe.getDiseases());
                    setFoodLevel(false,GIRAFFE_FOOD_VALUE);
                    return where;
                }
            }else if (actor instanceof Turtle){
                Turtle turtle= (Turtle) actor;
                if(turtle.isAlive()){
                    turtle.setDead();
                    getDiseases().addAll(turtle.getDiseases());
                    setFoodLevel(false,TURTLE_FOOD_VALUE);
                    return where;
                }
            }else if (actor instanceof Fox){
                Fox fox= (Fox) actor;
                if(fox.isAlive()){
                    fox.setDead();
                    getDiseases().addAll(fox.getDiseases());
                    setFoodLevel(false,FOX_FOOD_VALUE);
                    return where;
                }
            }else if (actor instanceof Rabbit){
                Rabbit rabbit = (Rabbit) actor;
                if (rabbit.isAlive()){
                    rabbit.setDead();
                    getDiseases().addAll(rabbit.getDiseases());
                    setFoodLevel(false,RABBIT_FOOD_VALUE);
                    return where;
                }
            }
        }
        return null;
    }

@Override
