private void generateField() {
        for (int row = 0; row < depth; row++) {

            for (int col = 0; col < width; col++) {
                field[row][col] = new Location(row, col, "Flat");
                // System.out.println("(Row " + row + " , " + " Column " + col + ")");
                //  System.out.println(field[row][col]);
            }
        }
        System.out.println("Depth : " + depth + " , Width : " + width);
        System.out.println("Depth: " + field.length);
        System.out.println("Width: " + field[0].length);

        // Let's generate a terrain with a simplex Noise generator
        OpenSimplexNoise newNoiseGenerator = new OpenSimplexNoise(rand.nextLong());

        float layerFrequency = 0.005f;
        float layerWeight = 1;
        float weightSum = 0;

        for (int octave = 0; octave < 3; octave++) {
            //Calculate single layer/octave of simplex noise, then add it to total noise
            for (int x = 0; x < width; x++) {
                for (int y = 0; y < depth; y++) {
                    float generatednumber = (float) newNoiseGenerator.eval(x * layerFrequency, y * layerFrequency) * layerWeight * 1000;
                    Location cell = getLocationFromCoords(y, x);
                    if (generatednumber > 0.6) {
                        cell.setCellType("Water");
                    } else if (generatednumber > 0.4) {
                        cell.setCellType("Shallow");
                    } else if (generatednumber < -0.6) {
                        cell.setCellType("Mountain");
                    } else {
                        cell.setCellType("Grass");
                    }
                }
            }
            //Increase variables with each incrementing octave
            layerFrequency *= 2;
            weightSum += layerWeight;
            layerWeight *= 0.04f;
        }

    }

