private void populate() {
		Random rand = Randomizer.getRandom();
		field.clear();

		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Location location = new Location(row, col);
				Actor actorAdded = null;

				if (rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
					actorAdded = new Grass(true, field, location);
				} else if (rand.nextDouble() <= TREE_CREATION_PROBABILITY) {
					actorAdded = new Tree(field, location);
				} else if (rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
					actorAdded = new Mouse(true, field, location);
				} else if (rand.nextDouble() <= HAMSTER_CREATION_PROBABILITY) {
					actorAdded = new Hamster(true, field, location);
				} else if (rand.nextDouble() <= JACKAL_CREATION_PROBABILITY) {
					actorAdded = new Jackal(true, field, location);
				} else if (rand.nextDouble() <= HAWK_CREATION_PROBABILITY) {
					actorAdded = new Hawk(true, field, location);
				} else if (rand.nextDouble() <= SNAKE_CREATION_PROBABILITY) {
					actorAdded = new Snake(true, field, location);
				}
				if (actorAdded != null)
					actors.add(actorAdded);

				// else leave the location empty.
			}
		}

	}

