    public void act() {
        Location animal_location = animal.getLocation();
        int[] lst = new int[8];
        boolean found = false;

        Location location = new Location(animal_location.getRow(), animal_location.getCol());

        for (int i=0; i<8; i++) {
            int j = rand.nextInt(8);
            while (lst[j] != 0) {
                j = rand.nextInt(8);
            }

            lst[j] = 1;

            int row = animal_location.getRow() + dRow[j],
                col = animal_location.getCol() + dCol[j];

            location = new Location(row, col);

            if (!field.inBounds(location)) 
                continue;

            if (field.getBlockAt(location).getEntity() == null) {
                found = true;
                break;
            }
        }

        if (found) {
            Location temp = animal.getLocation();
            field.setObjectAt(temp, null);
            field.setObjectAt(location, animal);
            animal.setLocation(location);
        } else {
            //animal.die();
        }
    }

@Override
    public void act(List<Actor> newActors) {
        lifetime++;

        if (field.getDayState() == DayState.NIGHT) return;

        movementBehaviour.act();
        aliveAbility.act();

        List<Entity> entities = new ArrayList<>();
        List<Location> locations = field.getAdjacentLocations(this.location);
        for (Location location : locations) {
            Entity entity = field.getBlockAt(location).getEntity();
            if (entity != null) {
                entities.add(entity);
            }
        }

        for (Entity entity : entities) {
            if (this.getID().equals(entity.getID())) {
                if (energy >= BREEDING_ENERGY) {
                    breed(newActors, entity);
                    return;
                }
            }
        }

        for (Entity entity : entities) {
            if (eats.contains(entity.getID())) {
                eat(entity);
                return;
            }
        }

        int temperature = field.getBlockAt(location).getTemperature();
        int extra_energy_loss = (int)(ENERGY_EFFICIENCY * Math.abs(temperature - OPTIMAL_TEMPERATURE));

        energy = energy - ENERGY_LOSS - extra_energy_loss; 

        if (energy <= 0) {
            die();
        }

        if (lifetime > MAX_LIFETIME) {
            die();
        }
    }

