public Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext())
        {
            Location where = it.next();
            Object Organism = field.getObjectAt(where);
            if(Organism instanceof buffalo)
            {
                buffalo buffalo = (buffalo) Organism;
                if(buffalo.isAlive()) { 
                    buffalo.setDead();
                    foodLevel = buffalo_FOOD_VALUE;
                    return where;
                }
            }
            if(Organism instanceof zebra) 
            {
                zebra zebra = (zebra) Organism;
                if(zebra.isAlive())
                { 
                    zebra.setDead();
                    foodLevel = zebra_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Wolf wolf = new Wolf(true, field, location);
                    livingThings.add(wolf);
                }
                else if(rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Deer deer = new Deer(true, field, location);
                    livingThings.add(deer);
                }
                else if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Plant plant = new Plant(field, location);
                    livingThings.add(plant);
                }
                else if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Lion lion = new Lion(true, field, location);
                    livingThings.add(lion);
                }
                else if(rand.nextDouble() <= TIGER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Tiger tiger = new Tiger(true, field, location);
                    livingThings.add(tiger);
                }
                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Zebra zebra = new Zebra(true, field, location);
                    livingThings.add(zebra);
                }  
                // else leave the location empty.
            }
        }
    }

private boolean findMate(){
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()){
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Squid){
                Squid squid = (Squid) animal;
                if(squid.isAlive() && male!= squid.getGender()){
                    return true;
                }
            }
            else{
                return false;
            }
        }
        return false;
    }

