        foodValue--;
        if(foodValue <= 0) {
            setDead();
        }
    }

private void meet(List<Animal> newMice){
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        Object animal1 = field.getObjectAt(getLocation());
        while(it.hasNext()){
            Location occupied = it.next();
            Object animal2 = field.getObjectAt(occupied);
            if (animal1 instanceof Mouse && animal2 instanceof Mouse){
                Mouse breeder = (Mouse) animal1;
                Mouse breedingMate = (Mouse) animal2;
                if((breeder.isFemale() && !breedingMate.isFemale()) 
                || (!breeder.isFemale() && breedingMate.isFemale()))
                {
                    giveBirth(newMice);
                }
            }
        }
    }

private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

