private void infectMate(Animal mate) {
        // if the disease can't be passed then return the disease can't be passed by mating
        // if it doesn't exist or if the disease's transmission type is AIR
        if (disease != null && disease.getTransmissionType() == Disease.TransmissionType.AIR) {
            return;
        }
        // if the mate exists then infect it with this animals disease
        if (mate != null) {
            mate.setDiseased(disease);
        }
    }

