public void simulateWeather() {
		switch (weather) {
		case STORMY:
			for (int i = 0; i < depth; i++)
				for (int j = 0; j < width; j++) {
					Actor actor = getActorAt(i, j);
					if (actor instanceof Plant && rand.nextDouble() < 0.1) {
						actor.setDead();
					}
					if (actor instanceof Animal && rand.nextDouble() < 0.001) {
						actor.setDead();
					}
				}

			break;
		case SUNNY:
			// NOTHING HAPPENS.
			break;
		}
		weather = Weather.getRandomWeather();
	}

