            Organism organism = it.next();
            if(organism instanceof Animal) {
                Animal animal = (Animal) organism;
                if(animal.getDiseaseStatus()){ //if the animal has disease
                    animal.resetDisease();
                }
            }
        }

        cure = false;
        disease = false;
        return organisms;
    }

