docstring:
Check whether or not this deer is to give birth at this step.
New births will be made into free adjacent locations.
@param newdeers A list to return newly born deers.

function:
private void giveBirth(List<Animal> newDeers)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                //Check if the gender of this deer is opposite of the partner deer. If is that the case than the breeding is true.
                if(deer.getGender() != this.getGender()) { 
                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
                    int births = breed();
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        boolean genderSetter = setGender();
                        boolean isSick = Randomizer.isSick();
                        Deer young = new Deer(false, field, loc, genderSetter, isSick);
                        newDeers.add(young);
                    }
                }      
            }
        }
    }

