public void simulateOneStep()
    {
        step++;
        time++;
        time = time % 24;
        infectedCounter();
        if (time == 0 )
        {
            chooseWeather();
            changeWeatherConditions();
        }

        // list for all organisms created
        List<Organism> newOrganisms = new ArrayList<Organism>();        
        // invoke live method on all organisms
        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
            Organism organisms = it.next();
            organisms.live(newOrganisms);
            if(! organisms.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born organisms to the main list.
        organisms.addAll(newOrganisms);

        view.showStatus(step, field);
    }

docstring:
Check whether or not this Deer is to give birth at this step.
New births will be made into free adjacent locations.
@param newDeers A list to return newly born Deers.

function:
private void giveBirth(List<Actor> newDeers)
    {
        // New Deers are born into adjacent locations.
        // Get a list of adjacent free locations.
        Boolean isMeet = false;
        Field field = getField();
        List<Location> adjacent = getAdjacentLocation();
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            if(where != null) {
                Object surroundingAnimal = field.getObjectAt(where);
                if(surroundingAnimal != null && surroundingAnimal instanceof Deer) {
                    Deer mate = (Deer) surroundingAnimal;
                    if(this.getGender() != mate.getGender()) {
                        int birth = breed();
                        for(int b = 0; b < birth && freeLocationList().size() > 0; b ++) {
                            if(freeLocationList().size() == 0) {
                                break;
                            }
                            Location loc = freeLocationList().remove(0);
                            Deer young = new Deer(false, field, loc);
                            generateRandomGender();
                            newDeers.add(young);
                        }
                    }
                }
            }
        }
    }

