public void showStatus(int step, Field field, String time, String isRainy, String isFoggy, int sickNumber, int tallPlantNum)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        weatherLabel.setText(WEATHER_PREFIX + isRainy + " & " + isFoggy);
        setInfoText(TIME_PREFIX + time + "   " + SICK_PREFIX + sickNumber + "   TallPlant: " + tallPlantNum);

        stats.reset();

        fieldView.preparePaint();


        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object plant = field.getObjectAt(row, col, field.getPlantLayer());
                Object animal = field.getObjectAt(row, col, field.getAnimalLayer());    

                if(plant != null) {
                    stats.incrementCount(plant.getClass());
                    fieldView.drawMark(col, row, getColor(plant.getClass()));
                }else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }

                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }

            }
        }

        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public void incrementAge(){
        if(getAge() <= MAX_AGE){
            setAge(getAge()+1);
        }
        else{
            setDead();
        }
    }

