docstring:
The main method, that will continuously run a simulation, incrementing it by
one step every 100ms.

@param args The arguments. Unused.

function:
public static void main(String[] args) {
		Simulator simulator = new Simulator(250, 250);

		while (true) {
			try {
				Thread.sleep(10);
			} catch (InterruptedException e) {
				e.printStackTrace();
			}
			simulator.simulateOneStep();
		}
	}

private static int duration(){
        Random rand = Randomizer.getRandom();
        return rand.nextInt(3) + 2;
    }

static public void weatherInfluence(String currentWeather)
    {
        String weatherNow = currentWeather;
        switch(weatherNow) {
            case "Sunny":
                BREEDING_PROBABILITY = 0.22;
                break;
            case "Raining":
                BREEDING_PROBABILITY = 0.12;
                break;            

            default: BREEDING_PROBABILITY = 0.05;
        }
    }

public List<List<Animal>> getAnimalsPerBlock()
    {
        List<List<Animal>> blocks = new ArrayList<>();
        for(int i = 0 ; i < width; i+= 20){
            for (int j = 0; j < depth; j+= 20) {
                List<Animal> animals = new ArrayList<>();
                for (int k = i; k < i + 20; k++) {
                    for(int l = j; l < j + 20; l++) {
                        Object obj = getObjectAt(l, k);
                        if(obj instanceof Animal) {
                            animals.add((Animal) obj);
                        }
                    }
                }
                blocks.add(animals);
            }
        }
        return blocks;
    }

