private String changeTimeOfDay(int step)
    {
        if (step % 3 == 0){
            return timeOfDay = "Morning";
        }
        else if (step % 3 == 1){
            return timeOfDay = "Afternoon";
        }
        else if (step % 3 == 2){
            return timeOfDay = "Evening";
        }
        return null;
    }

