public void act(List<Actor> newActors, int timeOfDay, Weather weather) 
    {
        overcrowding();
        replaceActor();

        // collects weather effect values for current weather
        this.weather = weather;
        setWeatherEffects();

        // sets time of day and determines which time function to run
        switch (timeOfDay) {
            case 0:
                day = true;
                dayAct(newActors);
            case 1:
                day = false;
                nightAct(newActors);
        }
    }

