public void act(List<Animal> newKrills, String timeOfDay)
    {
        eatPlant();
        incrementHunger();
        incrementAge();
        incrementLastBred();
        updateInfection();

        if(isAlive()) {
            if(canBreed())
                giveBirth(newKrills, timeOfDay);            
            // Try to move into a free location.
            Location newLocation = getField().freeAdjacentLocation(getLocation());
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

protected void killAnimal(Animal animal)
    {
        if(animal instanceof Rhino) {
                Rhino rhino = (Rhino) animal;
                if(rhino.isAlive()) { 
                    rhino.setDead();
                    setFoodLevel(HYENA_FOOD_VALUE);
                }
            }
            else if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if(deer.isAlive()) { 
                    deer.setDead();
                    setFoodLevel(DEER_FOOD_VALUE);
                }
            }
            else if(animal instanceof Wildebeest) {
                Wildebeest wildebeast = (Wildebeest) animal;
                if(wildebeast.isAlive()) { 
                    wildebeast.setDead();
                    setFoodLevel(WILDEBEEST_FOOD_VALUE);
                }
            }
    }

