public void simulate(int numSteps, int delay)
    {
        stepQueue+=numSteps;
        if(simActive) return;
        simActive = true;
        while(simActive && view.isViable(field) && stepQueue>0){
            simulateOneStep();
            --stepQueue;
            delay(delay);
        }
        simActive = false;
    }

