public Location spreadFire()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object plant = field.getObjectAt(where);
            if(plant instanceof Plant) {
                Plant plants = (Plant) plant;
                if(plants.isAlive() && !fire.isFired()){
                    plants.setDead();
                    fire.fired();
                    return where;
                }
                else if (fire.isFired())
                {
                    plants.setDead();
                }
            }
        }
        return null;
    }

docstring:
This is what the mouse does most of the time: it hunts for
plants. In the process, it might breed, die of hunger,
or die of old age.
@param field The field currently occupied.
@param newMice A list to return newly born Mice.

function:
public void act(List<Organism> newMice, boolean day, boolean rain)
    {
        incrementAge(MAX_AGE);
        incrementHunger(foodLevel);
        if(isAlive() ) {
            Animal mate = foundMate();
            if(mate != null)
            {
                giveBirth(newMice); 
                matedThisStep = true;
                mate.matedThisStep = true;
                if(mate.isDiseased == true)
                {   
                    this.isDiseased = true;
                }
            }           
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
                Object object = getField().getObjectAt(newLocation);
                if(object instanceof Animal)
                {
                    Animal animal = (Animal) object;
                    if(animal.isDiseased == true)
                    {   
                        this.isDiseased = true;
                    }
                }
            }
            else {
                // Overcrowding.
                setDead();
            }

            if(isDiseased)
            {
                double progress = new Random().nextDouble();
                //if(progress > 0.5){progress -= 0.5;}
                diseaseProliferation += progress;
                if(diseaseProliferation >= 0.7){setDead();}
            }
        }

    }

private void incrementHunger() {   
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

docstring:
A squirrel can breed if it has reached the breeding age and meets an squirrel of the opposite gender
that has also reached the breeding age.
@return True if they can breed, false otherwise.

function:
protected boolean canBreed()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Worm) {
                Worm a = (Worm) animal;
                return a.getGender() != this.getGender() && a.age >= BREEDING_AGE && 
                this.age >= BREEDING_AGE;
            }
        }
        return false;
    }

private void hasMeet(){
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(this.getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Kingcobra) {
                Kingcobra kingcobra = (Kingcobra) animal;
                if(kingcobra.isFemale && !this.isFemale) { 
                    kingcobra.hasMeet = true;
                }
            }

        }
    }

