public List<Location> getInfectedAdjacentLocations(Location location)
    {
        List<Location> infected = new LinkedList<>(); 
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getObjectAt(next) != null && isInfectedAt(next) == true) {
                infected.add(next);
            }
