public void act(List<Animal> newAnts, int time) {
        incrementAge(MAX_AGE);
        incrementHunger();

        if(isAlive() && ((time >= 4)&&(time <= 20)))
        {
            if (getDisease()) {
                spreadDisease();
            }
            if (giveBirth(BREEDING_AGE)) {
                Field field = getField();
                List<Location> free = field.getFreeAdjacentLocations(getLocation());
                int births = breed(BREEDING_AGE, BREEDING_PROBABILITY, MAX_LITTER_SIZE);
                for (int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    Ant young = new Ant(false, field, loc);
                    young.setGender();
                    newAnts.add(young);
                }
            }

            Location newLocation = findFood();
            if(newLocation == null) {
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                setDead();
            }
        }
    }

public void simulateOneStep()
    {
        step++; 
        showTime(step);
        changeWeather(step);
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();

        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext();) 
        {
            Animal animal = it.next();
            animal.act(step);
            animal.reproduce(newAnimals);

            if(!animal.isAlive()) 
            {
                it.remove();

            }
        }

        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);

        view.showStatus(step, showTime(step), field, weather.returnWeather());
    }

