public void showStatus(int step, Field field, Time time, Weather weather)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        weatherLabel.setText(WEATHER_PREFIX + weather);
        noDaysLabel.setText(NUMBER_DAYS_PREFIX + time.getNumberOfWholeDays());
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object organism = field.getObjectAt(row, col);
                if(organism != null) {
                    stats.incrementCount(organism.getClass());
                    fieldView.drawMark(col, row, getColor(organism.getClass()));
                }
                else { // no organism is present in this location
                    if(time.getIsDay()) {
                        fieldView.drawMark(col, row, EMPTY_DAY_COLOR);
                    } else {
                        fieldView.drawMark(col, row, EMPTY_NIGHT_COLOR);
                    }
                }
            }
        }

        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

