docstring:
This is what the dolphin does most of the time - it runs
around. Sometimes it will breed or die of old age.
@param newDolphins A list to return newly born dolphins.

function:
public void act(List<FieldObjects> newDolphins, int timeOfDay)
    {
        incrementAge();
        //The probability increases whne the healht is maximum
        if(getFoodLevel() == MAX_HEALTH) { setBreedingProbability(getBreedingProbability()*2); }
        if(getAge() > MAX_AGE) {setDead();}
        incrementHunger();
        if(isAlive() && timeOfDay>6 && timeOfDay<18) {
            giveBirth(newDolphins);
            //Eat food
            Location oldLoaction = getLocation();
            Location newLocation = findFood();
            if(!oldLoaction.equals(newLocation))
            {
                eat();
            }
            // Try to move into a free location.
            newLocation = getField().freeAdjacentLocation(getLocation());
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Hawk) {
                Hawk hawk = (Hawk) animal;
                if(hawk.isAlive()) {
                    if(this.getStrength() > hawk.getStrength()) {
                        hawk.setDead();
                        this.foodLevel += HAWK_FOOD_VALUE;
                        if(hawk.isInfected()) this.infect();
                        return where;
                    } else {
                        this.setDead();
                        hawk.setFoodLevel(50);
                        return null;
                    }
                }
            }
            if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if(deer.isAlive()) { 
                    deer.setDead();
                    this.foodLevel += DEER_FOOD_VALUE;
                    if(deer.isInfected()) this.infect();
                    return where;
                }
            }
            if(animal instanceof Mouse) {
                Mouse mouse = (Mouse) animal;
                if(mouse.isAlive()) {
                    mouse.setDead();
                    this.foodLevel += MOUSE_FOOD_VALUE;
                    if(mouse.isInfected()) this.infect();
                    return where;
                }
            }
            if(animal instanceof Plant) {
                Plant plant = (Plant) animal;
                if(plant instanceof SpecialPlant && this.isInfected()) { // If the Deer is infected, and eats a special plant, the Deer is cured.
                    this.cure();
                    plant.setDead();
                    return where;
                }
            }
        }
        return null;
    }

