private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if(deer.isAlive()) { 
                    deer.setDead();
                    foodLevel = foodLevel + deer.foodValue();
                    return where;
                }
            }
            else if(animal instanceof Cat) {
                Cat cat = (Cat) animal;
                if(cat.isAlive()) { 
                    cat.setDead();
                    foodLevel = foodLevel + cat.foodValue();
                    return where;
                }
            }
            else if(animal instanceof Owl) {
                Owl owl = (Owl) animal;
                if(owl.isAlive()) { 
                    owl.setDead();
                    foodLevel = foodLevel + owl.foodValue();
                    return where;
                }
            }
            else if(animal instanceof Mouse) {
                Mouse mouse = (Mouse) animal;
                if(mouse.isAlive()) { 
                        mouse.setDead();
                    foodLevel = foodLevel + mouse.foodValue();
                    return where;
                }
            }             
        }
        return null;
    }

protected void giveBirth(List<Animal> newAnimals)
    {
        // New animals are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field fauna = getField();
        List<Location> free = fauna.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            if (getSpeciesNo()==0){
                Marmot young = new Marmot(false, fauna, loc);
                newAnimals.add(young);
            }
            else if (getSpeciesNo()==1){
                Lynx young = new Lynx(false, fauna, loc);
                newAnimals.add(young);
            }
            else if (getSpeciesNo()==2){
                Wolf young = new Wolf(false, fauna, loc);
                newAnimals.add(young);
            }
            else if (getSpeciesNo()==3){
                Deer young = new Deer(false, fauna, loc);
                newAnimals.add(young);
            }
            else if (getSpeciesNo()==4){
                Primitive young = new Primitive(false, fauna, loc);
                newAnimals.add(young);
            }
        }
    }

