docstring:
Called when the start/stop button is pressed.
Creates a swing worker which makes a new thread for the simulation loop
@param e Action event

function:
private void startStop(ActionEvent e) {
        // If stop button was pressed
        if (worker != null && !worker.isDone()) {
            JButton startStop = (JButton) e.getSource();
            startStop.setText("Start");
            stop = true;
            return;
        }

        // If start button was pressed
        worker = new SwingWorker<>() {
            public Void doInBackground() {
                stop = false;
                JButton startStop = (JButton) e.getSource();
                startStop.setText("Stop");
                while (isViable(sim.getField())) {
                    sim.simulateOneStep();
                    if (stop) {
                        break;
                    }
                }
                return null;
            }

            public void done() {
                ((JButton) e.getSource()).setText("Start");
            }
        };
        worker.execute();
    }

