private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                boolean gender = rand.nextInt(2) == 0 ? false : true;
                if(rand.nextDouble() <= OWL_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Owl owl = new Owl(true, field, location,gender);
                    animals.add(owl);
                }
                else if(rand.nextDouble() <= SPARROW_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Sparrow sparrow = new Sparrow(true, field, location,gender);
                    animals.add(sparrow);
                }
                else if(rand.nextDouble() <= KINGCOBRA_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Kingcobra kingcobra = new Kingcobra(true, field, location,gender);
                    animals.add(kingcobra);
                }
                else if(rand.nextDouble() <= TOAD_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Toad toad = new Toad(true, field, location,gender);
                    animals.add(toad);
                }
                else if(rand.nextDouble() <= BUTTERFLY_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Butterfly butterfly = new Butterfly(true, field, location,gender);
                    animals.add(butterfly);
                }
                else if(rand.nextDouble() <= BLUEBERRIES_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Blueberries blueberries = new Blueberries(true, field, location);
                    plants.add(blueberries);
                }
                else if(rand.nextDouble() <= POKEBERRIES_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Pokeberries pokeberries = new Pokeberries(true, field, location);
                    plants.add(pokeberries);
                }
                // else leave the location empty.
            }
        }
    }

