docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        // drawing the animal locations
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    // draw the plants
                    Location location = new Location(row, col);
                    Plant plant = field.getPlantAt(location);
                    if (plant != null) {
                        // draw the plant
                        fieldView.drawMark(col, row, plant.getPlantColor());
                    } else {
                        // nothing exists at this location
                        fieldView.drawMark(col, row, EMPTY_COLOR);
                    }
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public void setDead() {
        alive = false;
        if (location != null) {
            field.clearPlant(location);
            location = null;
            field = null;
        }
    }

@Override
    public void giveBirth(List<Actor> newActors, ArrayList<Bound> bounds)
    {
        super.giveBirth(newActors, bounds);

        setCurrentlyBreeding(false);
    }

protected void act(List<Animal> newAnimals, int time, double visibility) {
        sleepSchedule(time);  

        if(isAlive() && awake) {
            incrementAge();
            incrementHunger();  

            move();   

            List<LivingThing> organisms = getNeighbouringLivingThings();

            for (LivingThing organism : organisms) {
                //Checks if the adjacent organism is consumable
                if (food.contains(organism.getName().toLowerCase())) {  
                    Location foodLocation = organism.getLocation();
                    consume(organism, visibility);
                    setLocation(foodLocation);
                    return;
                }
                //Checks if the adjacent organism can be mated with
                else if (organism.getName().toLowerCase().equals(getName())) {
                    if (organism instanceof Animal) {
                        Animal animal = (Animal) organism;
                        meet(animal, newAnimals);
                        return;
                    }
                }
            }

        }
    }

