public void incrementCount(Class organismClass) {
        Counter count = counters.get(organismClass);
        if (count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(organismClass.getSimpleName());
            counters.put(organismClass, count);
        }
        count.increment();
    }

public void actAll(int step)
    {
        List<Actor> newActors = new ArrayList<>();      
        Random rand = Randomizer.getRandom();
        // Let all actors act 
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) 
        {
            Actor actor = it.next();
            if(actor.isAlive()){
                if(clock.getDay())
                {   
                    actor.actDay(newActors);  // Let actors who act day act.
                } 
                else 
                {
                    actor.actNight(newActors);  // Let actors who act night act.
                }
            }

            else if(!actor.isAlive()) 
            {
                it.remove();
                actor.setDead(); 
            }
        }
        // Set ground, if it is raining.
        if(Weather.rain())
        {
            setGround();
        }
        actors.addAll(newActors);  // Add the new actors to the main list.
        updateViews(step);  // Update views. 
    }

