public void act(List<Animal> newWolves, int time, Weather weather)
    {
        incrementAge();
        checkSickness();
        if(time > 1 || time < 5){
            incrementHunger();
            if(isAlive()) {
                meet(newWolves, PREGNANCY_PROBABILITY); 
                switch(weather){
                    case SUNNY:
                    case RAINY:        
                        // Move towards a source of food if found.
                        Location newLocation = findFood();

                        if(newLocation == null) { 
                            // No food found - try to move to a free location.
                            newLocation = getField().freeAdjacentLocation(getLocation());
                        }
                        // See if it was possible to move.
                        if(newLocation != null) {
                        setLocation(newLocation);
                        }
                        else {
                            // Overcrowding.
                            setDead();
                        }  
                    break;

                    case STORMY:
                    case FOGGY:
                    break;
                }
            }
        }
    }

@Override
    public void act(List<Actor> newPredators)
    {
        incrementAge();

        // If night, don't do anything.
        if (isNight()) return;

        incrementHunger();
        if(isAlive()) {
            giveBirth(newPredators);

            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) {
                // No food found - look at nearby locations
                List<Location> potentialLocations = getField().adjacentLocations(getLocation());

                // If the location is empty, move to it.
                // If the location has a Plant, kill the plant and move to it.
                for (Location location : potentialLocations) {
                    Object actor = getField().getObjectAt(location);
                    if (actor == null) {
                        newLocation = location;
                        break;
                    } else if (actor instanceof Plant) {
                        ((Plant) actor).setDead();
                        newLocation = location;
                        break;
                    }
                }
            }

            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
                attemptInfection();
            } else {
                // Overcrowding.
                setDead();
            }
        }
    }

