public void ToggleField(int Tochange,int step,Field field){
        switch(Tochange){

            case 1: 
                if(AnimalField){AnimalField = false;}
                else{AnimalField = true;}
                break;
            case 2: 
                if(TerrainField){TerrainField = false;}
                else{TerrainField = true;}
                break;
            case 3: 
                if(PlantField){PlantField = false;}
