public void simulateOneStep()
    {
        step++;
        // Each step is equivalent to an hour.
        time.increaseHour();
        // Set the weather state of the simulation at this step.
        setWeather();
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();
        //provide space for newly grown plants.
        List<Plant> newPlants = new ArrayList<>();
        // Let all plant act
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            plant.act(newPlants, weather);
            if(!plant.isAlive()) {
                it.remove();
            }
        }
        // Let all animals act
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals, time.getTimeOfDay());
            if(!animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);
        // Add the newly grown plant to the main lists.
        plants.addAll(newPlants);

        view.showStatus(step, field, weather, time);
    }

private void runAction(ActionEvent event){
       SwingWorker<Void, Void> worker = new SwingWorker<Void, Void>(){
        protected Void doInBackground() throws Exception {
            delayTime = 60;
            runLongSimulation();
            try {
                Thread.sleep(100000);
            } catch (InterruptedException e1) {
                e1.printStackTrace();
            }
            return null;
        }
       };
       worker.execute();
    }

final void infect() {
