			// parameters
			// young.setFoodLevel(getFoodForBirth()); // their default food level is this
			// value
			// this.incrementHunger(getFoodForBirth());

			newOffspring.add(young);
		}
	}

docstring:
Look for prey adjacent to the current location.
Only the first live prey is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) 
        {
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            if(animal instanceof Zebra) 
            {
                Zebra zebra = (Zebra) animal;
                if(zebra.isAlive()) 
                { 
                    zebra.setDead();
                    foodLevel = ZEBRA_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Buffalo) 
            {
                Buffalo buffalo = (Buffalo) animal;

                if(buffalo.isAlive()) 
                { 
                    buffalo.setDead();
                    foodLevel = BUFFALO_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Porcupine) 
            {
                Porcupine porcupine = (Porcupine) animal;

                if(porcupine.isAlive()) 
                { 
                    porcupine.setDead();
                    foodLevel = PORCUPINE_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Rat) {
                Rat rat = (Rat) animal;
                if(rat.isAlive()) {
                    rat.setDead();
                    setFoodLevel(RAT_FOOD_VALUE);
                    return where;
                }
            }
            else if (animal instanceof Plant){
                Plant plant = (Plant) animal;
                if(plant.isAlive()) {
                    plant.setDead();
                    return where;
                }
            }
        }
        return null;
    }

