private void incrementHunger()
    {
        currentFoodValue -= FOOD_CONSUMPTION_RATE * (isActive() ? 1 : NON_ACTING_CONSUMPTION_MODIFIER);
        if (currentFoodValue <= 0) {
            setDead();
        }
    }

