        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    if(animal instanceof Hyena){
                        Hyena hyena = (Hyena) animal;
                        if(hyena.hasDisease){
                            DISEASE_COUNT++;
                        } 
                    } else if(animal instanceof Snake) {
                        Snake snake = (Snake) animal;
                        if(snake.hasDisease){
                            DISEASE_COUNT++;
                        } 
                    } else if(animal instanceof Wildebeest) {
                        Wildebeest wildebeest = (Wildebeest) animal;
                        if(wildebeest.hasDisease){
                            DISEASE_COUNT++;
                        }
                    } else if(animal instanceof Antelope) {
                        Antelope antelope = (Antelope) animal;
                        if(antelope.hasDisease){
                            DISEASE_COUNT++;
                        } 
                    } else if(animal instanceof Lion) {
                        Lion lion = (Lion) animal;
                        if(lion.hasDisease){
                            DISEASE_COUNT++;
                        } 
                    }
                }
            }
        }
        return DISEASE_COUNT;
    }

public String convertToString(){
        if(timeOfDay == 0){
            return "Day";   //indicating that the animals are active
        }

        else if(timeOfDay == 1){
            return "Night"; //indicating that the animals are asleep
        }

        return "Day";
    }

