private void thunderAct(Field field, NatureField natureField) {
        Random rand = Randomizer.getRandom();

        for (int i = 0; i < 10; i++ ) {
            int row = rand.nextInt(field.getDepth());
            int col = rand.nextInt(field.getWidth());
            Location location = new Location(row, col);
            field.clear(location);
            natureField.clear(location);

        }
    }

public Field simulateOneStep()
    {

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals);
            generateVirus(animal);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Provide space for newborn plants
        List<Plants> newPlants = new ArrayList<>();        
         // Let all plants act.
        for(Iterator<Plants> it = plants.iterator(); it.hasNext(); ) {
            Plants plant = it.next();
            plant.grow(newPlants);
            if(! plant.isAlive()) {
                 it.remove();
            }
        }

        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);

        //add new plants
        plants.addAll(newPlants);


        //update terrain atrributes
        field.FieldUpdate();

        //view.showStatus(step, field);
        return field;

    }

