private void incrementHunger() {
        if(this.isInfected()) // If the rabbit is infected, the foodLevel goes down quicker
            foodLevel -= 4;
        else
            foodLevel--;

        if(foodLevel <= 0) setDead(); // If the food level is less than or equal to 0, the rabbit dies.

    }

private void addActors() {
        int step = field.getStep();

        if (step % 50 == 0) {
            spawnActor("gnome");
        }

        if (step % 200 == 0) {
            spawnActor("slime");
            spawnActor("elk");
            spawnActor("phoenix");
        }

        if (step % 500 == 0) {
            spawnActor("cactus");
            spawnActor("frost_flower");
        }

        if (step % 400 == 0) {
            spawnActor("diseased_animal");
        }

        if (step % 500 == 0) {
            spawnActor("wolf");
            spawnActor("tall_grass");
            spawnActor("dragon");
            spawnActor("diseased_animal");
            spawnActor("diseased_plant");
        }
    }

public List<Actor> populate()
    {
        List <Actor> actors = new ArrayList<Actor>();
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= WEASEL_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Weasel weasel = new Weasel(true, field, location);
                    actors.add(weasel);   
                    // else leave the location empty.
                }
                if(rand.nextDouble() <= RODENT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Rodent rodent= new Rodent(true, field, location);
                    actors.add(rodent);   
                    // else leave the location empty.
                }
                if(rand.nextDouble() <= GOPHER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Gopher gopher = new Gopher(true, field, location);
                    actors.add(gopher);   
                    // else leave the location empty.
                }
                else if(rand.nextDouble() <=COYOTE_CREATION_PROBABILITY){
                    Location location = new Location(row, col);
                    Coyote coyote= new Coyote(true, field, location);
                    actors.add(coyote);   
                    // else leave the location empty.                    
                }
                else if(rand.nextDouble() <=BEAR_CREATION_PROBABILITY){
                    Location location = new Location(row, col);
                    Bear bear= new Bear(true, field, location);
                    actors.add(bear);   
                    // else leave the location empty.
                }
                else if(rand.nextDouble() <=PLANT_CREATION_PROBABILITY){
                    Location location = new Location(row, col);
                    Plant plant= new Grass(field, location);
                    actors.add(plant);   
                    // else leave the location empty.
                }
            }
        }
        return actors;
    }

public void act(List<Animal> newAnimals, boolean dayTime, boolean isRain,boolean isCold)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            if(isCold){
            giveBirth(newAnimals); }
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

