private void checkTimeOfDay() {
        int hour = time.getHour();

        if (Tools.isBetween(hour, 0, 4)){
            timeOfDay = "night";
        } else if (Tools.isBetween(hour, 5, 11)) {
            timeOfDay = "morning";
        } else if (Tools.isBetween(hour, 12, 20)) {
            timeOfDay = "afternoon";
        } else if (Tools.isBetween(hour, 20, 23)) {
            timeOfDay = "night";
        }
    }

