protected int breed() {
        int births = 0;
        if (rand.nextDouble() <= GROWTH_PROB) {
            births = rand.nextInt(30) + 1;
        }
        return births;
    }

private void setTimeOfDay()
    {
        if(hour >= 6 && hour < 20) {
            this.timeOfDay = TimeOfDay.DAY;
        } else {
            this.timeOfDay = TimeOfDay.NIGHT;
        }
    }

private void infect()
    {
        this.infected = true;
    }

public  void simulateOneStep()
    {
        step++;
        if(step % 5 == 0) //changing weather conditions
        {
            currentWeather = weather.get(rand.nextInt(weather.size())); 
        }
        if(time==23)

            time = -1;
        time++;
        if(!currentWeather.equals("FOGGY"))
        {
            if(step >=600 && step <604)//rabbits are being infected
            {
                if(rand.nextInt(2) ==1)
                    Rabbit.infected = true;  

            }
            if(step >=200 && step <290 || step>=500 && step <550 || step>=700 && step<780) //Wolfs are being infected
            {

                Wolf.infected = true;  

            }
            else
            {
                Wolf.infected = false;
            }
            if(step>300 && step<320 || step>500 && step <520 || step>700 && step<730) // Grass is being infected
            {
                Grass.infected = true;

            }
            else
            {
                Grass.infected = false;

            }

            // Provide space for newborn animals and plants
            List<Animal> newAnimals = new ArrayList<>();  
            List<Plant> newPlants = new ArrayList<>();

            // Let all animals act
            for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                Animal animal = it.next();
                animal.act(newAnimals);

                if(! animal.isAlive()) {
                    it.remove();

                }
            }
            for(Iterator<Animal> it = newAnimals.iterator(); it.hasNext();) {
                Animal currentAnimal = it.next();
                if(currentAnimal instanceof Rabbit)
                {
                    Rabbit rabbit = (Rabbit) currentAnimal;
                    listRabbits.add(rabbit);
                }
                if(! currentAnimal.isAlive())
                {
                    it.remove();
                }
            }
            // Let all plants act
            for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
                Plant plant= it.next();

                plant.act(newPlants);

                if(!plant.isAlive()) {
                    it.remove();
                }

            }

            // Add the newly born animals and plants to the main lists.
            animals.addAll(newAnimals);
            plants.addAll(newPlants);
        }

        view.showStatus(step, field);

    }

