public void act()
    {
        incrementAge();
        incrementHunger();
        if(alive && !Timer.isDay()) {
            giveBirth();
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) {
                // No food found - try to move to a free location.
                newLocation = field.freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
                spreadDisease();
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

private boolean checkMeet()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        String gender_meet = "";
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if (animal instanceof Hyena)
            {
                Hyena Hyena = (Hyena) animal;
                gender_meet = Hyena.getGender(); 
                if(disease = true)
                {
                    Hyena.gainDisease(0.5);
                }
            }
        }
        return (gender_meet != gender);

    }

public void act(List<Animal> newRabbits)
    {
        if (!getInfected()) setInfected(rand.nextDouble() < PROBABILITY_OF_RANDOM_INFECTION);
        incrementAge(MAX_AGE);
        if(isAlive()) {
            // If this animal has a disease, there is a small chance it will die this step
            if (getInfected() && rand.nextDouble() < PROBABILITY_OF_DEATH_FROM_INFECTION) {
                setDead();
                return;
            }
            giveBirth(newRabbits);            
            // Move towards a source of food if found.
            Location newLocation = findFood(null);
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
