docstring:
Look for hares adjacent to the current location.
Only the first live hare is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Hare) {
                Hare hare = (Hare) animal;
                if(hare.isAlive()) { 
                    hare.setDead();
                    foodLevel = HARE_FOOD_VALUE;
                    return where;
                }
            } else if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if(deer.isAlive()) {
                    deer.setDead();
                    foodLevel = DEER_FOOD_VALUE;
                    return where;
                }
            } else if(animal == null) {
                return where;
            } else if(animal instanceof Grass) {
                Grass grass = (Grass) animal;
                grass.setDead();
                return where;
            }
        }
        return null;
    }

private void giveBirth(List<Plant> newShrubs, List<Weather> weathers) {
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed(weathers);
        for (int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Shrub young = new Shrub(false, field, loc);
            newShrubs.add(young);
        }
    }

