docstring:
Check whether or not this rabbit is to give birth at this step.
New births will be made into free adjacent locations.
@param newGiraffe A list to return newly born rabbits.

function:
private void giveBirth(List<Actor> newGiraffe)
    {
        // New rabbits are born into adjacent locations.
        // Get a list of adjacent free locations.
        Boolean isMeet = false;
        Field field = getField();
        List<Location> adjacent = getAdjacentLocation();
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            if(where != null) {
                Object surroundingAnimal = field.getObjectAt(where);
                if(surroundingAnimal != null && surroundingAnimal instanceof Giraffe) {
                    Giraffe mate = (Giraffe) surroundingAnimal;
                    if(this.getGender() != mate.getGender()) {
                        int birth = breed();
                        for(int b = 0; b < birth && freeLocationList().size() > 0; b ++) {
                            if(freeLocationList().size() == 0) {
                                break;
                            }
                            Location loc = freeLocationList().remove(0);
                            Giraffe young = new Giraffe(false, field, loc);
                            generateRandomGender();
                            newGiraffe.add(young);
                        }
                    }
                }
            }
        }
    }

private void diseaseEffect()
    {
        if(hasDisease())
        {
            disease.decrementStepsBeforeDeath();
            spreadDisease();
            checkForFatalDisease();
            incrementHunger();
        }
    }

private void initialiseFileValues() {
        PropertyFileReader reader = new PropertyFileReader(getPropertyFile());
        String[] values = reader.getRow(this.getClass().getSimpleName());
        spreadChance = Double.parseDouble(reader.getValueByColumn(values, FileProperties.SPREAD_CHANCE));
        catchChance = Double.parseDouble(reader.getValueByColumn(values, FileProperties.CATCH_CHANCE));
        maxCarryTime = Integer.parseInt(reader.getValueByColumn(values, FileProperties.MAX_CARRY_TIME));
        creationProbability = Double.parseDouble(reader.getValueByColumn(values, FileProperties.CREATION_PROBABILITY));
        disappearanceProbability = Double.parseDouble(reader.getValueByColumn(values, FileProperties.DISAPPEARANCE_PROBABILITY));
    }

docstring:
Check whether or not this Tiger is to give birth at this step.
New births will be made into free adjacent locations.
@param newTigers A list to return newly born Tigers.

function:
private void giveBirth(List<Animal> newTigers)
    {
        // New Tigers are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        List<Location> adjacentLocations = field.adjacentLocations(getLocation());
        int genderOfCurrentTiger = getGender();
        for (Location next : adjacentLocations){
            Object animal = field.getObjectAt(next);
            if(animal != null && animal instanceof Tiger ) {
                Tiger matingPairTiger = (Tiger) animal;
                if(matingPairTiger.isAlive() || matingPairTiger.getGender() != genderOfCurrentTiger) { 
                     int births = breed();
                     for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Tiger young = new Tiger(false, field, loc);
                        newTigers.add(young);
                        }
                }
            }
        }
    }

