docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field, boolean day, String weather)
    {
        if(!isVisible()) {
            setVisible(true);
        }
        stepLabel.setText(STEP_PREFIX + step);
        if(day){
            timeLabel.setText(TIME_PREFIX + "Day");
        }
        else{
            timeLabel.setText(TIME_PREFIX + "Night");
        }
        weatherLabel.setText(WEATHER_PREFIX + weather);

        stats.reset();
        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object object = field.getObjectAt(row, col);
                if(object instanceof Animal ) {
                    Animal animal = (Animal) object;
                    if(animal.getSick()){
                        stats.incrementCount(object.getClass());
                        //if the animal is sick, add to the count and show the sick color
                        stats.incrementSickCount();     
                        fieldView.drawMark(col, row, SICK_COLOR, 3);            
                    }
                    else {
                        stats.incrementCount(object.getClass());
                        fieldView.drawMark(col, row, getColor(object.getClass()), 3);
                    }
                }
                else if(object instanceof Plant)
                {
                    stats.incrementCount(object.getClass());
                    fieldView.drawMark(col, row, getColor(object.getClass()), 1);
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR, 1);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

