public void act(List<FieldObjects> newDorys, int timeOfDay)
    {
        incrementAge();
        //The probability increases whne the health is maximum
        if(getFoodLevel() == MAX_HEALTH) { setBreedingProbability(getBreedingProbability()*2); }
        if(getAge() > MAX_AGE) {setDead();}
        incrementHunger();
        if(isAlive() && timeOfDay>6 && timeOfDay<18) {
            //Only the female dorys can give birth
            if(this.getIsFemale()){
                giveBirth(newDorys);
            }            
            //Eat food
            Location oldLoaction = getLocation();
            Location newLocation = findFood();
            if(!oldLoaction.equals(newLocation))
            {
                eat();
            }
            // Try to move into a free location if no food found
            if(newLocation==null){
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

