@Override
    protected Location getNewLocation() {
        Location newLocation = null; //start with no new location

        //the coyote prioritises finding mates as they work in a pack

        //iterate through the adjacent locations in the current field
        Field field = this.getField();
        List<Location> l = field.adjacentLocations(this.getLocation());
        for (int i = 0; i < l.size(); i++) {
            Object adj = field.getObjectAt(l.get(i));

            //if the adjacent animal is a coyote...
            if (adj instanceof Coyote) {

                //find a free location near it
                List<Location> free = field.getFreeAdjacentLocations(l.get(i));
                if (free.size() > 0) {
                    //return the free location near it if it exists (and therefore move that way)
                    return free.remove(0);
                }
            }
        }

        //if we could not move towards the coyote, try and find food instead
        if (newLocation == null) {
            // try and find food instead
            newLocation = findFood();
        }

        if (newLocation == null) {
            // No food found - try to move to a free location.
            newLocation = getField().freeAdjacentLocation(getLocation());
        }
        return newLocation;
    }

private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

docstring:
Look for possums adjacent to the current location.
Only the first live possum is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        // iterate through adjacent locations if the animal is hungry
        while(it.hasNext() && foodLevel<MAX_AGE) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            //Runs if the organism is a possum
            if(animal instanceof Possum) {
                Possum possum = (Possum) animal;
                if(possum.isAlive()) { 
                    possum.setDead();
                    foodLevel += POSSUM_FOOD_VALUE;
                    return where;
                }
            }
            //Runs if the organism is a otter
            else if (animal instanceof Otter) {
                Otter otter = (Otter) animal;
                if(otter.isAlive()) { 
                    otter.setDead();
                    foodLevel += OTTER_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

private void createGrass(List<Plant> newGrass)
    {


        Field field = getField();
        if(getLocation()!=null)
        {

            List<Location> free = field.getFreeAdjacentLocations(getLocation());

            for(Iterator<Location> it = free.iterator(); it.hasNext();){
                Location loc = it.next();

                if(loc.getFertility())
                {
                    Grass young = new Grass(field, loc);
                    newGrass.add(young);

                }
            }

        }

    }

protected boolean canBreed()
    {
        return age >= BREEDING_AGE;
    }

