docstring:
Look for mouses adjacent to the current location.
Only the first live prey is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Insect)
            {
                Insect insect = (Insect) animal;
                if(insect.isAlive()) { 
                    insect.setDead();
                    foodLevel = FOOD_VALUE;
                    return where;
                }
            }

            else if(animal instanceof Monkey)
            {
                Monkey monkey = (Monkey) animal;
                if(monkey.isAlive()) { 
                    monkey.setDead();
                    foodLevel = FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Mouse) {
                Mouse mouse = (Mouse) animal;
                if(mouse.isAlive()) { 
                    mouse.setDead();
                    foodLevel = FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Owl) {
                Owl owl = (Owl) animal;
                if(owl.isAlive() && rand.nextDouble() <= NOTSUCCESS_PROBABILITY ) { 
                    owl.setDead();
                    foodLevel = FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

docstring:
Look for rabbits, cows and deers adjacent to the current location.
Only the first live rabbit, cow or deer is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Hare) {
                Hare hare = (Hare) animal;
                if(hare.isAlive()) {
                    hare.setDead();
                    foodLevel = foodLevel + RABBIT_FOOD_VALUE;
                    return where;
                }
            }   else if(animal instanceof Cow) {
                Cow cow = (Cow) animal;
                if(cow.isAlive()) {
                    cow.setDead();
                    foodLevel = foodLevel + COW_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if(deer.isAlive()) {
                    deer.setDead();
                    foodLevel = foodLevel + DEER_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

