public void act()
    {
        if(waterLevel > 0){
            waterLevel--;
        }
        if(sunLevel > 0){
            sunLevel--;
        }
        if(field.getEnvironment().getClimate().getIsRaining()){
            waterLevel += 10;
        }
        if(field.getEnvironment().getClimate().getIsSunny()){
            sunLevel += 10;
        }
        if(waterLevel > 10 && sunLevel > 10){
            incrementAge();
        }
        if(waterLevel < 1 || sunLevel < 1){
            setInedible();
        }
    }

