docstring:
Look for plants adjacent to the current location.
Only the first plant is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood() {
        Field field = getField();
        // gets adjacent fields
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        // iterates through adjacent fields
        while (it.hasNext()) {
            Location where = it.next();
            Object plant = field.getObjectAt(where);
            // if occupied field is found, check if is acceptable food
            // if plant is not eaten, set it to eaten and add food value
            // if plant has disease set disease to true
            if (plant instanceof Seaweed) {
                Plant seaweed = (Plant) plant;
                if (!seaweed.isEaten()) {
                    seaweed.setEaten();
                    foodLevel = FOOD_VALUE;
                    if (seaweed.isDiseased() && (rand.nextDouble() <= seaweed.getDiseaseProbability())) {
                        disease = true;
                    }
                    return where;
                }
            }
        }
        return null;
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        forest.clear();
        for(int row = 0; row < forest.getDepth(); row++) {
            for(int col = 0; col < forest.getWidth(); col++) {
                if(rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Wolf wolf = new Wolf(true, forest, location);
                    animals.add(wolf); 
                }
                else if(rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Bear bear = new Bear(true, forest, location);
                    animals.add(bear);
                }
                else if(rand.nextDouble() <= BADGER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Badger badger = new Badger(true, forest, location);
                    animals.add(badger);
                }
                else if(rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Deer deer = new Deer(true, forest, location);
                    animals.add(deer);
                }
                else if(rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Mouse mouse = new Mouse(true, forest, location);
                    animals.add(mouse);
                }
                // else leave the location empty.
            }
        }
    }

