docstring:
Generate a number representing the number of births,
if it can breed.
@return The number of births (may be zero).

function:
private int breed()
    {
        int births = 0;
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        List<Object> neighbours = new ArrayList<>();
        for (Location loc: adjacent) {
            Object animal = (Animal) field.getObjectAt(loc);
            if (animal != null)
            {
                neighbours.add(animal); // collecting all neighbouring animals 
            }
        }

        for (Object animal: neighbours) {
            Animal species = (Animal) animal;
            if (species instanceof Salmon) // we want to try and breed only if the animals are the same species
            {
                Salmon salmon = (Salmon) species;
                boolean differentGender = salmon.getGender() != this.getGender(); // have to be different genders to breed
                if (differentGender && canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY)
                {
                    births = rand.nextInt(MAX_LITTER_SIZE) + 1;
                    return births;
                }
            }
        }

        return births;
    }

public void act(List<Animal> newFoxes)
    {
        incrementAge(MAX_AGE);
        incrementHunger();
        if(isAlive()) {
            // If this animal has a disease, there is a small chance it will die this step
            if (getInfected() && rand.nextDouble() < PROBABILITY_OF_DEATH_FROM_INFECTION) {
                setDead();
                return;
            }
            if (!isDay()) return; // Foxes sleep during the night and don't hunt or move
            giveBirth(newFoxes);            
            // Move towards a source of food if found.
            Location newLocation = findFood(preyToEat);
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

