        if (checkActivity(isDay)) {
            simulateDisease();
            incrementAge();
            incrementHunger();
            if (isAlive()) {
                giveBirth(newAnimals);
                routine(weather);
            }
        } else {
            // Animal sleeps
            incrementHunger();
        }
    }

