docstring:
Look for KangarooRats, Lizards and Tarantulas adjacent to the current location.
Only the first live KangarooRats, Lizards and Tarantulas are eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object Species = field.getObjectAt(where);
            //Uses eating probability to allow the other species to grow
            Random rand = new Random();
            int eating_prob = rand.nextInt(100);
            if(Species instanceof KangarooRat) {
                KangarooRat KangarooRat = (KangarooRat) Species;
                if(KangarooRat.isAlive() && eating_prob < 13) { 
                    KangarooRat.setDead();
                    foodLevel = KangarooRat_FOOD_VALUE;
                    return where;
                }
            }

            if(Species instanceof Lizard) {
                Lizard Lizard = (Lizard) Species;
                if(Lizard.isAlive()&& eating_prob < 12) { 
                    Lizard.setDead();
                    foodLevel = Lizard_FOOD_VALUE;
                    return where;
                }
            }
            else if(Species instanceof Tarantula) {
                Tarantula Tarantula = (Tarantula) Species;
                if(Tarantula.isAlive()&& eating_prob < 67) { 
                    Tarantula.setDead();
                    foodLevel = Tarantula_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

