public void simulateOneStep()
    {
        step++;

        // change the environment.
        environment.change();
        // Provide space for newborn life.
        ArrayList<LifeForm> newLife = new ArrayList<>();
        // Let all lifeforms act.
        for(Iterator<LifeForm> it = life.iterator(); it.hasNext(); ) {
            LifeForm animal = it.next();
            animal.act(newLife, environment);

            if(! animal.isAlive()) {
                it.remove();
            }



        }
        // Spawn plants and add to the list of Life Forms.

            pop.spawnPlants(newLife);


        // Add the newly born life-forms to the main lists.
        life.addAll(newLife);
        view.showStatus(step, field, environment.getTimeString(), getWeather());
    }

