public void act(List<Animal> newHyenas)
    {
        super.incrementAge();
        super.incrementHunger();

        if(isAlive()) {
            if(super.male==true){
                Field field = getField();
                List<Location> adjacent = field.adjacentLocations(getLocation());
                Iterator<Location> it = adjacent.iterator();
                while(it.hasNext()) {
                    Location where = it.next();
                    Object animal = field.getObjectAt(where);
                    if(animal instanceof Predator) {
                        Predator hyena = (Predator) animal;
                        if(hyena.male==false) { 
                            giveBirth(newHyenas);

                        }
                    }
                }
            }
            if(super.male==false){
                Field field = getField();
                List<Location> adjacent = field.adjacentLocations(getLocation());
                Iterator<Location> it = adjacent.iterator();
                while(it.hasNext()) {
                    Location where = it.next();
                    Object animal = field.getObjectAt(where);
                    if(animal instanceof Predator) {
                        Predator hyena = (Predator) animal;
                        if(hyena.male==true) { 
                            giveBirth(newHyenas);
                        }
                    }
                }
            } 
            if (Time.dayCycle() == true && Simulator.getStep() % 2 ==0) {//Lion moves less at night 
            }
            else{
                // Move towards a source of food if found.
                Location newLocation = super.findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

public boolean getHuntRestriction() {
