private void giveBirth(List<Animal> newSquidzino)
    {
        // New squid are born into adjacent locations.
        // Get a list of adjacent free locations.
        List<Squidzino> adjacentSquidzino = new ArrayList<>();
        Field field = getField();
        List<Location> squidCheck = field.adjacentLocations(getLocation());
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();

        for (int i = 0; i < squidCheck.size(); i++) {  

            if(field.getObjectAt(squidCheck.get(i)) instanceof Squidzino) {
                Squidzino newSquid = Squidzino.class.cast(field.getObjectAt(squidCheck.get(i)));
                adjacentSquidzino.add(newSquid);

            }
        }

        for (int j = 0; j < adjacentSquidzino.size(); j++) {            
            if (adjacentSquidzino.get(j).IS_FEMALE != this.IS_FEMALE) {
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    if(this.disease == true){
                        Squidzino young = new Squidzino(false, true, false, field, loc);
                        newSquidzino.add(young);
                    }
                    else{
                        Squidzino young = new Squidzino(false, true, true, field, loc);
                        newSquidzino.add(young);
                    }
                }    
            }
        }
    }

