public Agent spawnAgent(Agent.Descriptor descriptor, int row, int column) {
        if (this.state().inBounds(row, column)) {
            Agent agent = descriptor.spawn.apply();
            agent.row = row;
            agent.column = column;
            this.agents.add(agent);
            this.state().get(row, column).set(agent);
            return agent;
