docstring:
Girafe acts differently depending on the time of the day and the weather.
@param newGiraffes The list of new born giraffes.
@param timeOfDay The time of the day.
@param chanceOfDying The probability of animal dying if it is infected.
@param weather The weather type.

function:
public void act(List<Animal> newGiraffe, int timeOfDay, double chanceOfDying, int weather) {        
        if(timeOfDay == 0) {
            increaseAge(MAX_AGE);
        }

        checkDisease(chanceOfDying);

        if(isAlive()) {
            switch(weather) {
                case 0:
                // The weather is sunny, so the Giraffe does not move and fell hungrier.
                switch(timeOfDay) {
                    case 0:
                    // Morning, Giraffe eats, food level decrease 
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    decreaseFoodLevel(5);
                    break;

                    case 1:
                    // Afternoon, Giraffe gives birth, eats, food level decrease
                    if(!isAnimalMale()) {
                        giveBirth(newGiraffe);
                    }  
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    decreaseFoodLevel(5);
                    break;

                    case 2:
                    // Evening, Giraffe gives birth, eats, food level decreases 
                    if(!isAnimalMale()) {
                        giveBirth(newGiraffe);
                    }         
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    decreaseFoodLevel(4);
                    break;

                    case 3:
                    // Night, Giraffe sleeps, food level decreases 
                    decreaseFoodLevel(4);
                    break;
                }
                break;

                default:
                switch(timeOfDay) {

                    case 0:
                    // Morning, Giraffe eats, moves, food level decrease 
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(2);
                    decreaseFoodLevel(2);
                    break;

                    case 1:
                    // Afternoon, Giraffe gives birth, eats, food level decrease 
                    if(!isAnimalMale()) {
                        giveBirth(newGiraffe);
                    }           
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    decreaseFoodLevel(2);
                    break;

                    case 2:
                    // Evening, Giraffe gives birth, eats, moves, food level decreases 
                    if(!isAnimalMale()) {
                        giveBirth(newGiraffe);
                    }            
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(2);
                    decreaseFoodLevel(2);
                    break;

                    case 3:
                    // Night, Giraffe sleeps, food level decreases
                    decreaseFoodLevel(3);
                    break;
                }
                break;
            }
        }
    }

