protected boolean findFood()
    {
        Field field = getField();
        // Calculate how much food is needed.
        int needFood = getFoodValue() - getFoodLevel();
        if (field.getPlantLevel(getLocation()) >= needFood) {
            resetFoodLevel();
            field.consume(needFood, getLocation());
            return true;
        }
        else {
            return false;
        }
    }

