public void simulateOneStep()
    {
        step++;

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);
        growPlants(); //maintains plant growth rate
        if (isDay)
        {
            addBlobs(); //grows blobs during daytime.
        }
        DayNightCycle(); //alternates between day and night.
        WeatherCycle(); //updates whether or not it's raining.

        view.showStatus(step, NumberOfInfectedAnimals, field); //updates visible simulator status.
    }

public void simulateOneStep()
    {
        step++;
        environment.timeTick();

        // Provide space for newborn actors.
        List<Actor> newActors = new ArrayList<>();        
        // Let all actors
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            if(actor.isAlive()) {
                actor.act(newActors);
            }
            if(!actor.isAlive()) {
                it.remove();
            }
        }

        // Add the newly created actors
        actors.addAll(newActors);
        view.showStatus(step, field);
    }

public void nextStep(Integer steps)
    {
        if ((steps % dayDuration) == 0) //Every dayDuration amount of steps...
        {
            day = !day; //Change day
        }
        if ((steps % 10) == 0) //Every 10 steps
        {
            changeWeather(); //Weather is randomly chosen
        }
    }

docstring:
Look for food adjacent to the current location.
Only the first live animal is eaten.
@return Where food was found, or null if it wasn't.

function:
protected Location findFood()
    {
        //Iterate through field 
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            //Obtain object at location in field 
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            //Check what species object is, kill the animal and set food value accordingly
            if(animal instanceof Rabbit) {
                Rabbit rabbit = (Rabbit) animal;
                if(rabbit.isAlive()) { 
                    rabbit.setDead();
                    foodLevel = RABBIT_FOOD_VALUE;
                    return where;
                }
            }
           else if(animal instanceof Mouse) {
                Mouse mouse = (Mouse) animal;
                if(mouse.isAlive()) { 
                    mouse.setDead();
                    foodLevel = MOUSE_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Deer){
                Deer deer = (Deer) animal;
                if(deer.isAlive()){
                    deer.setDead();
                    foodLevel = DEER_FOOD_VALUE;
                    return where;
                }
            }

            //Animal is hungrier because it can't see and catch prey as easily
            if (!see){
                foodLevel = foodLevel / 2;
            }
        }
        return null;
    }

