public void showStatus(int step, Field field) {
        if (!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if (animal != null) {
                    stats.incrementCount(animal.getClass());
                    if (animal instanceof Animal) {
                        Animal infectionCheck = (Animal) animal;
                        if (infectionCheck.isInfected()) {
                            // Lerp between black (to indicate infection) and the animals color (to indicate animal)
                            Color newCol;

                            double percent = 0.4;
                            double inverse = 1.0 - percent;

                            Color infectionCol = Color.BLACK;
                            Color animalCol = getColor(animal.getClass());

                            // Calculate RGB values
                            int red = (int) (infectionCol.getRed() * percent + animalCol.getRed() * inverse);
                            int green = (int) (infectionCol.getGreen() * percent + animalCol.getGreen() * inverse);
                            int blue = (int) (infectionCol.getBlue() * percent + animalCol.getBlue() * inverse);

                            // New RGB color
                            newCol = new Color(red, green, blue);

                            fieldView.drawMark(col, row, newCol);
                        } else {
                            fieldView.drawMark(col, row, getColor(animal.getClass()));
                        }
                    } else {
                        fieldView.drawMark(col, row, getColor(animal.getClass()));
                    }
                } else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

