private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Wolf) {
                Wolf wolf = (Wolf) animal;
                if(wolf.isAlive()) { 
                    wolf.setDead();
                    foodLevel = WOLF_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Deer) {
                Deer deer = (Deer) animal;
                if(deer.isAlive()) { 
                    deer.setDead();
                    foodLevel = DEER_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof Fox) {
                Fox fox = (Fox) animal;
                if(fox.isAlive()) { 
                    fox.setDead();
                    foodLevel = FOX_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

private int breed() {
		int births = 0;
		if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
			births = rand.nextInt(getMaxLitterSize()) + 1;
		}
		return births;
	}

private void setWaterLevel(double waterLevel) {
        this.waterLevel += waterLevel;
        this.waterLevel = Math.min(this.waterLevel, 1000);
    }

protected void checkDisease(double chanceOfDying) {
        if(getIsInfected() && rand.nextDouble() < chanceOfDying){
            setDead();
        }
    }

protected void checkInfection() {
        if (disease != null) {
            disease.incrementAge();
            if (disease.isAlive() && rand.nextDouble() <= disease.getDeathProbability()) {
                // If disease is still alive, check probability of death
                setDead();
            } else if (!disease.isAlive()) {
                // The disease is no longer active
                disease = null;
            }
        }
    }

