docstring:
Elephant acts differently depending on the time of the day and the weather.
@param newElephants The list of new born elephants.
@param timeOfDay The time of the day.
@param chanceOfDying The probability of animal dying if it is infected.
@param weather The weather type.

function:
public void act(List<Animal> newElephants, int timeOfDay, double chanceOfDying, int weather) {        
        if(timeOfDay == 0) {
            increaseAge(MAX_AGE);
        }

        checkDisease(chanceOfDying);

        if(isAlive()) {
            switch(weather) {
                case 1:
                // The weather is rainy, Elephant's food level decreases by less
                switch(timeOfDay) {
                    case 0:
                    // Morning, Elephant gives birth, eats, moves, food level decreases
                    if(!isAnimalMale()) {
                        giveBirth(newElephants);
                    }   
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(1);
                    decreaseFoodLevel(3);
                    break;

                    case 1:
                    // Afternoon, Elephant gives birth, eats, moves
                    if(!isAnimalMale()) { 
                        giveBirth(newElephants);
                    }  
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(2);
                    break;

                    case 2:
                    // Evening, Elephant gives birth, eats, moves, food level decreases 
                    if(!isAnimalMale()) {
                        giveBirth(newElephants);
                    }                     
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(1);
                    decreaseFoodLevel(2);
                    break;

                    case 3:
                    // Night, Elphant sleeps, food level decreases 
                    decreaseFoodLevel(2);
                    break;

                }
                break;

                default:
                switch(timeOfDay) {
                    case 0:
                    // Morning, Elephant gives birth, eats, moves, food level decreases 
                    if(!isAnimalMale()) {
                        giveBirth(newElephants);
                    }                   
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(1);
                    decreaseFoodLevel(4);
                    break;

                    case 1:
                    // Afternoon, Elephant gives birth, eats, moves, food level decreases 
                    if(!isAnimalMale()) {
                        giveBirth(newElephants);
                    }                    
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(2);
                    decreaseFoodLevel(1);
                    break;

                    case 2:
                    // Evening, Elephant gives birth, eats, moves, food level decreases ]
                    if(!isAnimalMale()) {
                        giveBirth(newElephants);
                    }  
                    eat(this,plantsField, getLocation(), MAX_FOOD_LEVEL);
                    moveToInAreaLocation(1);
                    decreaseFoodLevel(3);
                    break;

                    case 3:
                    // Night, Elphant sleeps, food level decreases 
                    decreaseFoodLevel(2);
                    break;

                }
                break;

            }
        }
    }

public void populate(Field field) {
		Random rand = Randomizer.getRandom();
		field.clear();
		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Location location = new Location(row, col);

				if (rand.nextDouble() <= WEREWOLF_CREATION_PROBABILITY) {
					WereWolf wereWolf = new WereWolf(true, field, location);
					livingThings.add(wereWolf);
					if (rand.nextDouble() <= VIRUS_CREATION_PROBABILITY) {
						wereWolf.getInfected(new Virus());
					}

				} else if (rand.nextDouble() <= PHOENIX_CREATION_PROBABILITY) {
					Phoenix phoenix = new Phoenix(true, field, location);
					livingThings.add(phoenix);
					if (rand.nextDouble() <= VIRUS_CREATION_PROBABILITY) {
						phoenix.getInfected(new Virus());
					}

				} else if (rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
					Plant plant = new Plant(field, location);
					livingThings.add(plant);

				} else if (rand.nextDouble() <= SERPENT_CREATION_PROBABILITY) {
					Serpent serpent = new Serpent(true, field, location);
					livingThings.add(serpent);
					if (rand.nextDouble() <= VIRUS_CREATION_PROBABILITY) {
						serpent.getInfected(new Virus());
					}
					if (rand.nextDouble() <= HEALABLE_VIRUS_CREATION_PROBABILITY) {
						serpent.getInfected(new HealableVirus());
					}

				} else if (rand.nextDouble() <= CERBERUS_CREATION_PROBABILITY) {
					Cerberus cerberus = new Cerberus(true, field, location);
					livingThings.add(cerberus);
					cerberus.getInfected(new Rabies()); // all Cerberus carry Rabies
					if (rand.nextDouble() <= VIRUS_CREATION_PROBABILITY) {
						cerberus.getInfected(new Virus());
					}

				} else if (rand.nextDouble() <= UNICORN_CREATION_PROBABILITY) {
					Unicorn unicorn = new Unicorn(true, field, location);
					livingThings.add(unicorn);
					unicorn.getInfected(new Rabies()); // all Unicorn carry Rabies
					if (rand.nextDouble() <= VIRUS_CREATION_PROBABILITY) {
						unicorn.getInfected(new Virus());
					}
				}
				// else leave the location empty.
			}
		}
	}

