private void giveBirth(List<Organism> newLion)
    {
        // New Lions are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        Iterator<Location> it = free.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object Organism = field.getObjectAt(where);
            if(Organism instanceof Jay) {
                Lion lion = (Lion) Organism;
                boolean gender1 = genderCheck();
                boolean gender2 = lion.genderCheck();
                if(lion.isAlive() && isAlive() && (gender1 != gender2) ) { 
                    if (lion.getInfected() == true)
                    {
                        setInfected();
                    }
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Lion young = new Lion(false, field, loc);
                        newLion.add(young);
                    }
                }
            }
        }
    }

public void simulateOneStep()
    {
        step++;

        // Pass on the current step to the timer to evaluate day or night
        timer.setStep(step);
        timer.determineDay();

        // Provide space for new actors.
        List<Actor> newActors = new ArrayList<>();    

        //Randomize weather.
        if(weathers.get(0).changeWeather()){
            Collections.shuffle(plantField.getWeathers(), rand);
        }

        // Let all actors act.
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            actor.act(newActors);
            if(! actor.isActive()) {
                it.remove();
            }
        }

        // Add the new actors to the main list.
        actors.addAll(newActors);

        // Show the state of the simulationation in the view.
        view.showStatus(timer, field, weathers.get(0).getName());
        plantView.showStatus(timer, plantField, weathers.get(0).getName());
    }

docstring:
Look for rabbits adjacent to the current location.
Only the first live rabbit is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        List<Location> adjacent = getField().adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = getField().getObjectAt(where);
            if(animal instanceof Grasshopper) {
                Grasshopper grasshopper = (Grasshopper) animal;
                if(grasshopper.isAlive()) { 
                    if (grasshopper.checkDisease()){
                        this.setDisease();    
                    }
                    grasshopper.setDead();
                    foodLevel = foodLevel + GRASSHOPPER_FOOD_VALUE;
                    return where;
                }
            } else if(animal instanceof Slug) {
                Slug slug = (Slug) animal;
                if(slug.isAlive()) { 
                    if (slug.checkDisease()){
                        this.setDisease();    
                    }
                    slug.setDead();
                    foodLevel = foodLevel + SLUG_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

private Location getBestPreyLocation(int visionScope) {
        LinkedList<Location> locs = field.getNBlockAdjacentLocations(location, visionScope, visionScope);
        Optional<Location> loc = locs.stream()
                .filter(i-> field.getLandAt(i).getAnimal() != null)
                .filter(i-> Arrays.asList(requiredTypes).contains(field.getLandAt(i).getAnimal().getClass()))
                .min(Comparator.comparing(this::distance));

        return loc.orElse(null);

    }

