docstring:
Generate a number representing the number of births,
if it can breed.
@return The number of births (may be zero).

function:
private int breed()
    {
        int births = 0;
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        List<Object> neighbours = new ArrayList<>();
        for (Location loc: adjacent) {
            Object animal = (Animal) field.getObjectAt(loc);
            if (animal != null)
            {
                neighbours.add(animal); // collecting all neighbouring animals 
            }
        }

        for (Object animal: neighbours) {
            Animal species = (Animal) animal;
            if (species instanceof Shark) // we want to try and breed only if the animals are the same species
            {
                Shark shark = (Shark) species;
                boolean differentGender = shark.getGender() != this.getGender(); // have to be different genders to breed
                if (differentGender && canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY)
                {
                    births = rand.nextInt(MAX_LITTER_SIZE) + 1;
                    return births;
                }
            }
        }

        return births;
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();

        int randRow = rand.nextInt(field.getDepth());
        int randCol = rand.nextInt(field.getWidth());
        Location randLocation = new Location(randRow, randCol);
        Snake illSnake = new Snake(true, field, randLocation);
        illSnake.infect();
        actors.add(illSnake);

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(field.getObjectAt(row, col) == null) {
                    if(rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
                        Location location = new Location(row, col);
                        Wolf wolf = new Wolf(true, field, location);
                        actors.add(wolf);
                    }
                    else if(rand.nextDouble() <= GIRAFFE_CREATION_PROBABILITY) {
                        Location location = new Location(row, col);
                        Giraffe giraffe = new Giraffe(true, field, location);
                        actors.add(giraffe);
                    }
                    else if(rand.nextDouble() <= SNAKE_CREATION_PROBABILITY) {
                        Location location = new Location(row, col);
                        Snake snake = new Snake(true, field, location);
                        actors.add(snake);
                    }
                    else if(rand.nextDouble() <= TIGER_CREATION_PROBABILITY) {
                        Location location = new Location(row, col);
                        Tiger tiger = new Tiger(true, field, location);
                        actors.add(tiger);
                    }
                    else if(rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
                        Location location = new Location(row, col);
                        Deer deer = new Deer(true, field, location);
                        actors.add(deer);
                    }
                    else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                        Location location = new Location(row, col);
                        Grass grass = new Grass(field, location);
                        actors.add(grass);
                    }
                }
                // else leave the location empty.
            }
        }
    }

