public void showStatus(int step, Field field, String dayOrNight, String weather, int weatherDuration, int remainingWeatherDuration, int infections)
    {
        if(!isVisible()) {
            setVisible(true);
        }


        showTimeOfDay(dayOrNight);
        showWeather(weather, weatherDuration, remainingWeatherDuration);
        showInfected(infections);


        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public boolean canBreed()
	{
		return age >= getBreedingAge() && !isSleeping();
	}

docstring:
This is what the fox does most of the time: it hunts for
rabbits. In the process, it might breed, die of hunger,
or die of old age.
@param field The field currently occupied.
@param newFoxes A list to return newly born foxes.

function:
public void act(List<Actor> newFoxes,Simulator.time dayTime,
    Simulator.weather dayWeather,Simulator.season daySeason)
    {
        incrementAge();

        if(isAlive()) {
            if (dayWeather != dayWeather.FOGGY&&daySeason!=daySeason.WINTER){
                if (findMate()){
                    giveBirth(newFoxes);
                }
            }
            float randomFloat= rand.nextFloat();
            if(this.hasDisease() && randomFloat>=0.95){
                setDead();
                System.out.println("fox died from disease");
            }
            // Move towards a source of food if found.
            else{
                Location newLocation = findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }

            }
            incrementHunger(); 
            //if night, sleep, nothing happens, only age still increment
        }
    }

