@param timeOfDay The current time of the day (i.e. day or night)

function:
public void act(List<Animal> newSnakes, TimeOfDay timeOfDay)
    {
        incrementAge(MAX_AGE);
        incrementHunger();
        if (this.getIllnessStatus() && rand.nextDouble() <= ILLNESS_DEATH_PROBABILITY){
            setDead();
        }

        if(isAlive()) {
            if(!sleep(timeOfDay, getSleepTime(), SLEEP_PROBABILITY)) {
                giveBirth(newSnakes);
                // Move towards a source of food if found.
                Location newLocation = findFood();
                if (newLocation == null) {
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAnimalAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if (newLocation != null) {
                    setLocation(newLocation);
                } else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

public void updateTime(int step)
    {
        hour = step % 24;//24 hours from 0 - 23
        if(hour == 0){day++; }//whenever the time reaches midnight (0hrs), a new day begins
        if(day == 28){month++; }//whenever the 28th day is reached, a month has passed
    }

