public void act(List<Actor> newLynxes)
    {
        incrementAge();
        incrementHunger();

        Location newLocation = null;
        //Chances of dying if Lynx infected.
        if(isAlive() && !myDiseases.isEmpty())
        {
           if((rand.nextDouble())<= 0.05)
           {
               this.setDead();
           }
        }

        if(isAlive()) {
            // Reproduce.
            reproduce(newLynxes, (Actor) this);            
            //If hungry enough, move towards a source of food if found.

            if(foodLevel <= (MAX_FOOD_LEVEL/2))
            {
            if(!getField().getIsDay())
                {
                    if((rand.nextDouble() <= 0.75))
                    {newLocation = findFood();}

                }
                else
                {newLocation = findFood();}
            }
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = findGrass(this);
            }
            else if(newLocation == null)
            {newLocation = getField().freeAdjacentLocation(getLocation());}
              // See if it was possible to move toan empty location.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

public String getWeather(){        
        String weather = "";
        for (HashMap.Entry<Conditions,Boolean> entry : conditions.entrySet()) {     
            String key = entry.getKey().toString();
            boolean value = entry.getValue();
            if(value){
                weather = weather + key;
                break;
            }
        }
        if (!weather.equals("")){
            return weather;
        } else {
            return weatherEnum.SUNNY.toString();
        }
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= EAGLE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Eagle eagle = new Eagle(true, field, location);
                    animals.add(eagle);
                }
                else if(rand.nextDouble() <= OWL_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Owl owl = new Owl(true, field, location);
                    animals.add(owl);
                }
                else if(rand.nextDouble() <= SQUIRREL_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Squirrel squirrel = new Squirrel(true, field, location);
                    animals.add(squirrel);
                }
                else if(rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Mouse mouse = new Mouse(true, field, location);
                    animals.add(mouse);
                }
                else if(rand.nextDouble() <= WORM_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Worm worm = new Worm(true, field, location);
                    animals.add(worm);
                }
                // else leave the location empty.
            }
        }
        field.growPlants();
    }

private void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }

public void incrementMinute()
