public void act(List<Actor> newPlants)
    {
        weather.rain();
        boolean isRaining = weather.getIsRaining();
        decreaseWaterLevel();
        increasePlantFoodLevel();

        //spread out into the free adjacent locations
        if(isAlive() && isRaining){
            List<Location> freeAdjacent = getField().getFreeAdjacentLocations(getLocation());
            Iterator<Location> it = freeAdjacent.iterator();
            while(it.hasNext()) {
                Location location = it.next();
                Grass grass = new Grass(getField(), location);
                newPlants.add(grass);
            }
            increaseWaterLevel();
        }
    }

private void warnNeighboringZebra(Animal animal)
    {   
        //Moves the zebra one step.
        Location newLocation = moveOneStep(animal.getLocation());
        if(newLocation != null && rand.nextDouble() <= DEFENSE_PROBABILITY)
        {   
            //Moves the zebra a second step.
            newLocation = moveOneStep(newLocation);
            if(newLocation != null)
