public void checkWeather()
    {
        //All animals sleep until snow stops
        if (weather.getWeather() == "snow"){
            for(int i = 0; i < animals.size(); i++ ) {
                animals.get(i).sleepLong();
            } 
        }

        //Plants grow faster in the rain
        else if (weather.getWeather() == "rain"){
            fastGrowPlant();
            normalActAnimal();
        }

        //Predators have less visibility in the fog
        else if (weather.getWeather() == "fog"){
            for (int i = 0; i < animals.size(); i++){
                animals.get(i).canNotSee();
            }
            normalActAnimal();
        }

        //Normal actions when weather is clear
        else{
            normalActAnimal();
        }
    }

public void simulateOneStep()
    {
        step++;
        Random rand = new Random();

        if(rand.nextDouble() <= WEATHER_PROBABILLITY){
            field.setWeather();
        }

        if(rand.nextDouble() <= DISEASE_PROBABILLITY){
            field.setDisease();
        }

        // Provide space for newborn animals.
        List<Organisms> newAnimals = new ArrayList<>();        
        // Let all organisms act.
        for(Iterator<Organisms> it = animals.iterator(); it.hasNext(); ) {
            Organisms animal = it.next();
            if (checkIfNight() && checkOrganism(animal)){
                continue;
            }
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }

        }

        // Add the newly born foxes and rabbits to the main lists.
        animals.addAll(newAnimals);

        view.showStatus(step, field);
    }

private void setInfected(boolean infect)
    {
        infected = infect; 
    }

public void tryAct(SimulationContext context)
    {
        // Nocturnal species only act at night, all others only act at day.
        if (context.getTime() < convertTime(6, 00) || context.getTime() > convertTime(21, 00)) {
            if (getData().IS_NOCTURNAL) {
                act(context);
            }
        }
        else if (!getData().IS_NOCTURNAL) {
            act(context);
        }
    }

private void incrementAge() {
        age++;
        if (age > MAX_AGE) {
            setDead();
        }
    }

private void infectOthers()
    {
        List<Location> notFree = getField().adjacentLocations(getLocation());

        Iterator<Location> iterator = notFree.iterator();

        while(iterator.hasNext())
        {
            Location next = iterator.next();
            if(next == null) continue;
            Object nextLocation = field.getObjectAt(next);
            if(nextLocation instanceof Animal) ((Animal)nextLocation).infect();
        }
    }

