public void showStatus(int step, boolean time, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        String timeString;
        if (time) {
            timeString = "Day";
        }
        else {
            timeString = "Night";
        }

        timeLabel.setText(TIME_PREFIX + timeString + " Weather: " + field.getCurrentWeather());
        stepLabel.setText(STEP_PREFIX + step);

        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());

                    if(animal instanceof Antelope){
                        Antelope ant = (Antelope) animal;
                        if (ant.getInfected()){
                            fieldView.drawMark(col, row, getColor(animal.getClass()).darker().darker());
