private double getDisplacement(Location location)
    {
        Location loc = getLocation(); //Gets the location of this animal

        return Math.sqrt(
            Math.pow((loc.getRow() - location.getRow()), 2) + 
            Math.pow((loc.getCol() - location.getRow()), 2)
            );
    }

