public void act(List<Actor> newActors) {
        incrementAge();
        incrementHunger();
        incrementDiseaseCount();
        if (getDiseaseCount() > 3) {
            setDead();
        }
        if(isAlive()) {
            if (!isScared()) {
                giveBirth(newActors); 
            }
            if (diseasedNearby()) {
                setIsDiseased();
            }
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            } else {
                // Overcrowding.
                setDead();
            }
        }
    }

public void simulateOneStep(LocalTime currentTime) {
    step++;

    // Provide space for newborn animals.
    List<Animal> newAnimals = new ArrayList<>();
    // Let all rabbits act.
    for (Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
      Animal animal = it.next();
      animal.act(newAnimals, currentTime, sunrise, sunset);
      if (!animal.isAlive()) {
        it.remove();
      }
    }

    // Add the newly born foxes and rabbits to the main lists.
    animals.addAll(newAnimals);

    view.showStatus(step, field);
  }

public void simulateOneStep()
    {
        step++;
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all the animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        List<Plants> newPlants = new ArrayList<>();        
        // Let all the plants act.
        for(Iterator<Plants> it1 = plants.iterator(); it1.hasNext(); ) {
            Plants plants = it1.next();
            plants.act(newPlants);
            if(! plants.isAlive()) {
                it1.remove();
            }
        }
        // Add the newly born animals  to the main animal list.
        animals.addAll(newAnimals);
        // Add the new grown plants  to the main plant list.
        plants.addAll(newPlants);
        view.showStatus(step, field);
    }

