protected boolean animalFood(Object actor)
    {
        if(actor instanceof Rat) {
            Rat rat = (Rat) actor;
            if(rat.isActive()) { 
                rat.setInactive();
                if (getFoodLevel() < MAX_FOOD_LEVEL - RAT_FOOD_VALUE) {
                    setFoodLevel(RAT_FOOD_VALUE);
                }
                return true;
            }
        }
        else if(actor instanceof Plant) {
            Plant plant = (Plant) actor;
            if (plant.isActive()) {
                plant.setInactive();
                return true;
            }
        }
        return false;
    }

