protected int breed(int breadingAge, double probability, int maxLitterSize)
    {
        if(getField() == null){
            return 0;
        }
        int births = super.breed(breadingAge, probability, maxLitterSize);
        if(getField().getWeather() == Weather.RAIN) {
            births += births;
        }
        return births;
    }

