public void simulate(int numSteps) {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            //One cycle (day and night) is 8 steps, therefore day/night lasts for 4 steps
            if (step % 4 == 0){
                isDay = !(isDay());
