public void incrementCount(Class animalClass, boolean gender, boolean infected)
    {
        String counterKey = animalClass + " " + (gender ? "Female" : "Male") + " " + (infected ? "Infected" : "Healthy");
        Counter count = counters.get(counterKey);
        if(count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(counterKey);
            counters.put(counterKey, count);
        }
        count.increment();
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    Lion animal = new Lion(true, field, location);
                    animals.add(animal);
                }
                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
                    Zebra animal = new Zebra(true, field, location);
                    animals.add(animal);
                }
