docstring:
Return a shuffled list of locations adjacent to the given one.
The list will not include the location itself.
All locations will lie within the grid.
@param range how big you want your range of adjacent locations to cover.
@param location from which to generate adjacent locations.
@return A list of locations adjacent to that given.

function:
public List<Location> adjacent2Locations(Location location, int range)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -range; roffset <= range; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -range; coffset <= range; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

private void move() {
        for(int steps = 0; steps < MAX_STEPS; steps++) {
            Location newLocation = findFood();

            if(newLocation == null) { 
                // No food found - try to move to a free location or on top of a plant.
                List<Location> adjLoc = getField().adjacentLocations(getLocation());
                for(Location options : adjLoc) {
                    if (getField().getObjectAt(options) == null) {
                        newLocation = options;
                        break;
                    }
                    else if(getField().getObjectAt(options) instanceof Plant) {
                        getField().clear(options);
                        newLocation = options;
                        break;
                    }
                }
            } else {
                break;
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
                break;
            }
        }
    }

private int breed(Jaguar partner)
    {
        int births = 0;
        if(canBreed() && rand.nextDouble() <= breedingProbability && partner.isMale() != this.isMale()) {
            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
        }
        return births;
    }

