private boolean canBreed()
    {
        Field field = getField();
        Seal currentSeal = (Seal) field.getObjectAt(getLocation());
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Seal) {
                Seal matingSeal = (Seal) animal;
                if(currentSeal.isMale != matingSeal.isMale){
                    if(currentSeal.age >= BREEDING_AGE && matingSeal.age >= BREEDING_AGE){
                        return true;
                    }
                }
            }
        }
        return false;
    }

