private Location findFood()
     {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object tempPlant = field.getObjectAt(where);
            if(tempPlant instanceof Plant) {
                Plant plant = (Plant) tempPlant;
                if(plant.isAlive()) { 
                    if(plant.getHeight() == 3){
                    plant.setDead();
                    foodLevel = PLANT_FOOD_VALUE+2;
                    return where;
                }
                else {
                    plant.setDead();
                    foodLevel = PLANT_FOOD_VALUE;
                    return where;
                }
                }
            }

        }
        return null;
    }

private boolean canBreed()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        if(age >= BREEDING_AGE)
        {
            while(it.hasNext()) 
            {
                Location where = it.next();
                Object animal = field.getObjectAt(where);
                if(animal instanceof Fish && this.isOppositeGender((Fish)animal)) // Check if there are any opposite gendered fish around
                {
                    return true;
                }
            }
        }
        return false;
    }

