private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        //Random mice created as backup food
        Mice randomMice = null;

        while (it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            if (animal instanceof Worm) {
                Worm worm = (Worm) animal;
                if (worm.isAlive()) {
                    worm.setDead();
                    this.foodLevel = MAX_FOOD_VALUE;
                    this.incrementPower(5);
                    return where;
                }
            } else if (animal instanceof Mice) {
                Mice mice = (Mice) animal;
                if (mice.isAlive()) {
                    mice.setDead();
                    this.foodLevel = MAX_FOOD_VALUE;
                    this.incrementPower(5);
                    return where;
                }
            }
        }

        if (this.foodLevel <= 4 && randomMice != null) {
            Location where = randomMice.getLocation();
            randomMice.setDead();
            this.incrementFoodLevel(6);
            this.incrementPower(3);

            // Remove the dead mice from the field.
            return where;
        }

        return null;

    }

