docstring:
Look for animals adjacent to the current location.
Only the first live animal is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {   
        int counter = -1;
        int eatLocation = 0;
        boolean isTiger = false;
        boolean isWildDog = false;
        boolean isAntelope = false;
        boolean isZebra = false;
        boolean isPlant = false;
        int FOOD_VALUE = 0;

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            counter++;
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Tiger) {
                eatLocation = counter;
                FOOD_VALUE = TIGER_FOOD_VALUE;
                isTiger = true;
            }else if(animal instanceof Antelope && !isTiger) {
                eatLocation = counter;
                FOOD_VALUE = ANTELOPE_FOOD_VALUE;
                isAntelope = true;
            } else if (animal instanceof Zebra && !isAntelope && !isTiger) {
                eatLocation = counter;
                FOOD_VALUE = ZEBRA_FOOD_VALUE;
                isZebra = true;
            } else if (animal instanceof WildDog && !isTiger && !isAntelope && !isZebra) {
                eatLocation = counter;
                FOOD_VALUE = WILDDOG_FOOD_VALUE;
                isWildDog = true;
            } else if (animal instanceof Plant && !isAntelope && !isTiger && !isWildDog && !isZebra){
                eatLocation = counter;
                FOOD_VALUE = PLANT_FOOD_VALUE;
                isPlant = true;
            }
        }

        if(isTiger || isWildDog || isZebra || isAntelope || isPlant){
            eat((Animal) field.getObjectAt(adjacent.get(eatLocation)), FOOD_VALUE);
            return adjacent.get(eatLocation);
        }
        return null;
    }

