public void showStatus(int step, Field field, boolean day, int dayCount, int time)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step + " Day= " + day + " Days: "+ dayCount + " Time: " + time + ":00");

        stats.reset();

        fieldView.preparePaint();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object weather = field.getWeatherObjectAt(row, col);
                Object animal = field.getObjectAt(row, col);
                Object plant = field.getPlantObjectAt(row,col);
                if(weather!=null){
                    if(animal != null) { 
                        stats.incrementCount(animal.getClass());
                        stats.incrementCount(weather.getClass()); 
                        fieldView.drawMark(col, row, (getColor(weather.getClass())).darker().darker().darker());
                    }
                    else{
                        fieldView.drawMark(col, row, getColor(weather.getClass()));
                        stats.incrementCount(weather.getClass());
                    }
                } 

                else if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else if(plant != null) {
                    stats.incrementCount(plant.getClass());
                    fieldView.drawMark(col, row, getColor(plant.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

