public void act(List<Creature> newCheetahs)
    {

        incrementAge();
        if(Simulator.isDay==true){
        incrementHunger();
        if(isAlive()) {
            giveBirth(newCheetahs);            
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }
    }

public void simulateOneStep() 
    {
        step++;
        // Check special conditions.
        if (view.isSelectedFog() && step % 20 == 0) {
            view.switchFog();
        }
        if (!view.isSelectedFog()) {
            view.setFog(false);
        }
        if (!view.isSelectedRain()) {
            view.setRain(false);
        }
        if (step % 100 == 0) {
            view.switchTimeofDay();
        }
        if (view.isSelectedRain() && step % 5 == 0) {
            view.switchRain();
        }
        // Provide space for new plants.
        List<Plant> newPlants = new ArrayList<>();
        // Let all plants act.
        for (Iterator<Plant> it = plants.iterator(); it.hasNext();) {
            Plant plant = it.next();
            if (view.isRain()) {
                // Plants can act when it rains.
                plant.act(newPlants);
            }
            else {
                // Do nothing.
            }
            if (!plant.isAlive()) {
                it.remove();
            }
        }
        // Add the newly born/grown plants to the main lists.
        plants.addAll(newPlants);
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();
        // Let all animals act.
        for (Iterator<Animal> it = animals.iterator(); it.hasNext();) {
            Animal animal = it.next();
            if (view.isFog() && !view.isNight()) {
                // No animals can act when it is foggy.
                animal.incrementAge();
            }
            if (view.isFog() && view.isNight()) {
                // No animals can act when it is foggy.
                animal.incrementAge();
            }
            if (!view.isFog() && !view.isNight()) {
                // All animals can act.
                animal.act(newAnimals);
            }
            if (!view.isFog() && view.isNight()) {
                // Only predators can act at night.
                if (animal instanceof Predator) {
                    animal.act(newAnimals);
                }
            }
            if (!animal.isAlive()) {
                it.remove();
            }
        }
        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);
        view.showStatus(step, field);
        delay(60);
    }

public void setWeather()
    {
        Random rand = Randomizer.getRandom();
        int WEATHER_GENERATOR = rand.nextInt(5);
        if(WEATHER_GENERATOR <= 1){
            isRaining = true;
            isSunny = false;
            isFoggy = false;
        } else if(WEATHER_GENERATOR > 2){
            isSunny = true;
            isRaining = false;
            isFoggy = false;
        } else if(WEATHER_GENERATOR == 2){
            isFoggy = true;
            isRaining = false;
            isSunny = false;
        }
    }

