        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        for(int b = 0; b < GROWTH_RATE && free.size() > 0; b++) {
            if(free.get(0) != null){
                if (field.getObjectAt(free.get(0)) instanceof Grass){
