private void addNewProducers(FieldCell cell, ListSet<Class<? extends Producer>> simulatedProducers) {
        for (Class<? extends Producer> producer : simulatedProducers) {
            try {
                // Create a new instance of Producer using the dynamic class's constructor.
                Producer newProducer = producer
                        .getDeclaredConstructor()
                        .newInstance();
                if (Randomizer.getRandom().nextDouble() <= newProducer.getCreationChance(currentWeather.getClass())) {
                    cell.getProducersOccupying().add(newProducer);
                }
            }
            catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
                e.printStackTrace();
            }
        }
    }

public void act(List<Organism> newCheetahs)
    {
        incrementAge(); // age the cheetah
        incrementHunger(); // make the cheetah more hungry
        if (5<=currentSimulation.getHour() && currentSimulation.getHour()<=21) // if it is daytime
        {
            if(isAlive()) {
                infectOthers(); // pass disease to other animals
                newCheetahs = super.giveBirth(newCheetahs, currentSimulation, this);     
                if (currentSimulation.getWeather().equals("Fire")){
                    // If there is a fire, randomly kill some cheetahs.
                    if(rand.nextFloat() < 0.25){
                        setDead();
                    }
                }
                else if(!currentSimulation.getWeather().equals("Rain")){
                    // Move towards a source of food if found and if it is not raining.
                    Location newLocation = findFood();
                    if(newLocation == null) { 
                        // No food found - try to move to a free location.
                        newLocation = getField().freeAdjacentLocation(getLocation());
                    }
                    // See if it was possible to move.
                    if(newLocation != null) {
                        setLocation(newLocation);
                    }
                    else {
                        // Overcrowding.
                        setDead();
                    }
                }
            }
        }
    }

