docstring:
Look for food adjacent to the current location.
Only the first live animal/plant is eaten.
@return Where food was found, or null if it wasn't.

function:
protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof SeaLion) {
                SeaLion sealion = (SeaLion) animal;
                if(sealion.isAlive()) { 
                    if(sealion.isInfected()){
                        infected = true;
                        age += 50;
                    }
                    sealion.setDead();
                    foodLevel = SEA_LION_FOOD_VALUE;
                    return where;
                }
            }
            else if(animal instanceof SeaWeed) {
                SeaWeed weeds = (SeaWeed) animal;
                if(weeds.isAlive()) { 
                    weeds.setDead();
                    foodLevel = SEA_WEED_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

docstring:
Look for prey animals adjacent to the current location.
Only the first live prey animal is eaten.
@param preyToEat Set of animals a predator can eat.
@return Where food was found, or null if it wasn't.

function:
public Location findFood(Set<String> preyToEat)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            // Looking for food is harder in foggy weather
            if (field.getWeather().equals("Foggy") && rand.nextDouble() < PREDATOR_MISSES_PREY_IN_FOGGY) continue;
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Duck && canEat("Duck", preyToEat) && getFoodLevel() < Duck.FOOD_VALUE) {
                Duck duck = (Duck) animal;
                if(duck.isAlive()) { 
                    if (duck.getInfected()) setInfected(true);
                    duck.setDead();
                    setFoodLevel(Duck.FOOD_VALUE);
                    return where;
                }
            }
            else if(animal instanceof Rabbit && canEat("Rabbit", preyToEat) && getFoodLevel() < Duck.FOOD_VALUE) {
                Rabbit rabbit = (Rabbit) animal;
                if(rabbit.isAlive()) { 
                    if (rabbit.getInfected()) setInfected(true);
                    rabbit.setDead();
                    setFoodLevel(Rabbit.FOOD_VALUE);
                    return where;
                }
            }
            else if(animal instanceof Mouse && canEat("Mouse", preyToEat) && getFoodLevel() < Duck.FOOD_VALUE) {
                Mouse mouse = (Mouse) animal;
                if(mouse.isAlive()) { 
                    if (mouse.getInfected()) setInfected(true);
                    mouse.setDead();
                    setFoodLevel(Mouse.FOOD_VALUE);
                    return where;
                }
            }

        }
        return null;
    }

docstring:
Check whether or not this shark is to give birth at this step.
New births will be made into free adjacent locations.
@param newSharks A list to return newly born sharks.

function:
private void giveBirth(List<Animal> newSharks)
    {
        // New sharks are born into adjacent locations.
        // Get a list of adjacent free locations.
        List<Shark> adjacentSharks = new ArrayList<>();
        Field field = getField();
        List<Location> sharkCheck = field.adjacentLocations(getLocation());
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();

        for (int i = 0; i < sharkCheck.size(); i++) {  
            if(field.getObjectAt(sharkCheck.get(i)) instanceof Shark) {
                Shark newShark = Shark.class.cast(field.getObjectAt(sharkCheck.get(i)));
                adjacentSharks.add(newShark);
            }
        }

        for (int j = 0; j < adjacentSharks.size(); j++) {            
            if (adjacentSharks.get(j).IS_FEMALE != this.IS_FEMALE) {
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    if(this.disease == true){
                        Shark young = new Shark(false, true, false, field, loc);
                        newSharks.add(young);
                    }
                    else{
                        Shark young = new Shark(false, true, true, field, loc);
                        newSharks.add(young);
                    }
                }    
            }
        }
    }

