function:
public void showStatus(int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getAnimalAt(row, col);
                Object plant = field.getPlantAt(row, col);
                if (plant != null && animal != null) 
                {
                    stats.incrementCount(plant.getClass());
                    stats.incrementCount(animal.getClass());

                    fieldView.drawPlant(col, row, getColor(plant.getClass()));
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else if (animal != null)
                {
                    stats.incrementCount(animal.getClass());

                    fieldView.drawPlant(col, row, EMPTY_COLOR);
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else if (plant != null)
                {
                    stats.incrementCount(plant.getClass());

                    fieldView.drawPlant(col, row, getColor(plant.getClass()));
                }
                else
                {
                    fieldView.drawPlant(col, row, EMPTY_COLOR);
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= MONKEY_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Monkey monkey = new Monkey(true, field, location);
                    actors.add(monkey);
                }
                else if(rand.nextDouble() <= BIRD_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Bird bird = new Bird(true, field, location);
                    actors.add(bird);
                }

                else if(rand.nextDouble() <= PREDATOR_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Predator predator = new Predator(true, field, location);
                    actors.add(predator);
                }
                else if(rand.nextDouble() <= TIGER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Tiger tiger = new Tiger(true, field, location);
                    actors.add(tiger);
                } else if (rand.nextDouble() <= plantGrowthRate) {
                    Location location = new Location(row, col);
                    Plant plant = new Plant(field, location);
                    actors.add(plant);

                } else if (rand.nextDouble() <= ANTEATER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Anteater anteater = new Anteater(true, field, location);
                    actors.add(anteater);

                }

                // else leave the location empty.
            }
        }
    }

public int waterLevelChange() {
        String weather = getWeather();
        Random ran = new Random();
        switch(weather){
            case "rain":
                return ran.nextInt(MAX_RAIN_FALL)+1;
            case "sunny":
                return - (ran.nextInt(MAX_WATER_DECREASE) +1);
            case "foggy":
                return ran.nextInt(MAX_FOG_PRECIPITATION +1);
            default:
                return 0;
        }
    }

