public void act(List<Animal> newAnimals, boolean daytime, int months, boolean newYear)
    {
        if(isAlive()) {
            incrementHunger();
            if(!isAlive()){return;}
            diseaseEffects();
            if(!isAlive()){return;}
            adjustToWeather(); 
            if(!isAlive()){ return;} //animal can die due to weather
            if(isMale){giveBirth(newAnimals); }
            for(int i =0; i<howManyMoves; i++){
                if(!alive){return;}
                move();
            }
        }
        if(newYear){
