docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.
@param time the time of day
@param weather The current weather on the field.
@param diseasedAnimals The number of diseased animals on the field.

function:
public void showStatus(int step, Field field, boolean time, int weather,
    int diseasedAnimals)
    {
        if(!isVisible()) {
            setVisible(true);
        }
        //Changes the text shown after the timeLabel prefix
        if(time){
            tod = "Day";
        }
        else{
            tod = "Night";
        }
        //WEATHER
        if (weather == 0) {
            weatherDisplay = "Sunny";
        } 
        else if (weather == 1) {
            weatherDisplay = "Rainy";
        }
        else if (weather == 2) {
            weatherDisplay = "Cold";
        }

        stepLabel.setText(STEP_PREFIX + step);
        timeLabel.setText(DAYNIGHT_PREFIX + tod);
        weatherLabel.setText(WEATHER_PREFIX + weatherDisplay);
        diseaseLabel.setText(DISEASE_PREFIX + diseasedAnimals);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

