private boolean findMate() 
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocationsVar(getLocation(), mate_distance);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (organism instanceof Snake) {
                Snake potentialMate = (Snake) organism;
                if(potentialMate.isAlive() && potentialMate.canBreed()) {
                    if(potentialMate.getIsMale() != this.isMale) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

public void simulateOneStep()
    {
        step++;
        //Increment time.
        Time.timeTick();
        //Change weather if necessary.
        WeatherState.changeWeather();


        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();
        List<HabitatFood> newPlants = new ArrayList<>();
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }
        }
        //Let all the habitat food act.
        for(Iterator<HabitatFood> it = habitatfood.iterator(); it.hasNext(); ) {
            HabitatFood food = it.next();
            food.act(newPlants);
            if(! food.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born animals and habitat foods to the field.
        animals.addAll(newAnimals);
        habitatfood.addAll(newPlants);

        view.showStatus(step, field);
    }

