private void giveBirth(List<Animal> newAntelopes)
    {
        // New Antelopes are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        List<Location> adjacent = field.adjacentLocations(getLocation());
        boolean animalNearby = false;
        for(int i = 0; i < adjacent.size(); i++){
            Location loc = adjacent.get(i);
            if(field.getObjectAt(loc) != null){
                Object animal = field.getObjectAt(loc);
                if(animal instanceof Antelope){
                    Antelope Antelope = (Antelope) animal; 
                    if(Antelope.getIsMale() != this.getIsMale()){
                        animalNearby = true;
                    }
                    /*//Infection spreads through contact.
                    if((this.getIsInfected() == true) || Antelope.getIsInfected()) {
                         setInfected();
                         Antelope.setInfected();
                    } */        
                }
            }
        }
        int births = breed();
        // if another Antelope is nearby, give birth.
        if(animalNearby == true){
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Antelope young = new Antelope(false, field, loc);
                if(getIsInfected() == true) {
                    young.setInfected(); //Infected adults offspring will also carry the disease.
                }
                newAntelopes.add(young);
            }
        }
    }

