private void giveBirth(List<Organism> newCheetahs)
    {
        // New Cheetahs are born into adjacent locations.


        Field field = getField();

        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        List<Location> full = field.getFullAdjacentLocations(getLocation());

        int births = breed();

        for (Location location: full) {
            if ( field.getObjectAt(location) instanceof Cheetah
                    && ((Cheetah) field.getObjectAt(location)).getGender() != getGender()){

                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);

                    Cheetah young = new Cheetah(false, field, loc);
                    newCheetahs.add(young);
                }
                break;
            }

        }
    }

private void incrementAge() {
        age++;
        if (age > MAX_AGE && isAlive()) {
            setDead();
        }
    }

protected Animal findOppositeGender() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        ArrayList<Animal> partnerList = new ArrayList<>();

        while(it.hasNext()) {
            Location where = it.next();
            Object actor = field.getObjectAt(where);
            //if animals have the same class 
            if(actor != null && actor.getClass().equals(this.getClass())){
                Animal animal = (Animal) actor;
                // if animals have the same class and gender they will breed
                if((this.getGender() != animal.getGender() && animal.canBreed())){
                    partnerList.add(animal);
                }
            }
        }
        if(!partnerList.isEmpty()){
            Animal choosePartner = partnerList.get(rand.nextInt(partnerList.size()));
            return choosePartner;
        }
        return null;
    }

