        // New wolfs are born into adjacent locations.
        Field field = getField();
        Animal animalA;
        // Get a list of adjacent free locations.
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        // Get a list of adjacent locations.
        List<Location> adjacentLocations = field.adjacentLocations(getLocation());
        for(int i = 0; i < adjacentLocations.size(); i++){
         Object animal = field.getObjectAt(adjacentLocations.get(i));
         if(animal != null){
            Object isAnimal = animal.getClass().getSuperclass();
            if(isAnimal != null && (isAnimal.toString().equals("class Animal"))){
               animalA = (Animal) animal;
              if(animalA instanceof Wolf && (animalA.getGender() != this.getGender())){  
                    int births = breed();
                    for(int b = 0; b < births && free.size() > 0; b++) {
                            Location loc = free.remove(0);
                            Wolf young = new Wolf(false, field, loc);
