protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Fallen) {
                Fallen fallen = (Fallen) animal;
                if(fallen.isAlive()) { 
                    fallen.setDead();
                    setFoodLevel(FALLEN_FOOD_VALUE);
                    if(fallen.isInfected()) {
                        setInfected(true);
                    }
                    return where;
                }
            }
            if(animal instanceof Cabal){
                Cabal cabal = (Cabal) animal;
                if(cabal.isAlive()){
                    cabal.setDead();
                    setFoodLevel(CABAL_FOOD_VALUE);
                    if(cabal.isInfected()) {
                        setInfected(true);
                    }
                    return where;
                }
            }
            if(animal instanceof Vex){
                Vex vex = (Vex) animal;
                if (vex.isAlive()) {
                    vex.setDead();
                    setFoodLevel(VEX_FOOD_VALUE);
                    if(vex.isInfected()) {
                        setInfected(true);
                    }
                    return where;
                }
            }
        }
        return null;
    }

