public void simulateOneStep()
    {
        step++;
        WEATHER_GENERATOR++;
        countTime();
        getWeatherStatus();

        // Provide space for newborn animals.    
        List<Animal> newAnimals = new ArrayList<>();  

        if(WEATHER_GENERATOR == 10){
            generateWeather();
            WEATHER_GENERATOR = 0;
        }

        if(!isDayTime){
            view.changeBackground(Color.BLACK);
            TURNS_UNTIL_MOVEMENT++;

            // Let all animals act.
            if(sun){
                for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                    Animal animal = it.next();
                    //animal.incrementAge();
                    if(TURNS_UNTIL_MOVEMENT % 2 == 0){
                        animal.act(newAnimals);
                        TURNS_UNTIL_MOVEMENT = 0;
                    }
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }   
            } else if(rain){
                for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                    Animal animal = it.next();
                    //animal.incrementAge();
                    if(TURNS_UNTIL_MOVEMENT % 6 == 0){
                        animal.act(newAnimals);
                        TURNS_UNTIL_MOVEMENT = 0;
                    }
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }   
            } else if(fog){
                for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                    Animal animal = it.next();
                    //animal.incrementAge();
                    if(TURNS_UNTIL_MOVEMENT % 8 == 0){
                        animal.act(newAnimals);
                        TURNS_UNTIL_MOVEMENT = 0;
                    }
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }   
            }

            // Add the newly born animals to the main lists.
            animals.addAll(newAnimals);

            view.showStatus(step, field);
        } else{
            view.changeBackground(Color.WHITE);
            TURNS_UNTIL_MOVEMENT++;

            // Let all animals act.
            if(sun){
                for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                    Animal animal = it.next();
                    animal.act(newAnimals);
                    TURNS_UNTIL_MOVEMENT = 0;
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }   
            } else if(rain){
                for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                    Animal animal = it.next();
                    animal.incrementAge();
                    if(TURNS_UNTIL_MOVEMENT % 3 == 0){
                        animal.act(newAnimals);
                        TURNS_UNTIL_MOVEMENT = 0;
                    }
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }   
            } else if(fog){
                for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
                    Animal animal = it.next();
                    animal.incrementAge();
                    if(TURNS_UNTIL_MOVEMENT % 5 == 0){
                        animal.act(newAnimals);
                        TURNS_UNTIL_MOVEMENT = 0;
                    }
                    if(! animal.isAlive()) {
                        it.remove();
                    }
                }   
            }

            // Add the newly born animals to the main lists.
            animals.addAll(newAnimals);

            view.showStatus(step, field);
        }
    }

