protected void giveBirth(List<Animal> newRabbits)
    {
        // New rabbits are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());

        // Summer is mating season for rabbits, so their breeding probability increases by BREEDING_PROBABILITY_MODIFIER;
        double adjustedBreedingProbability = getField().getSeason() == 3 ? (BREEDING_PROBABILITY * MATING_SEASON_BREEDING_PROBABILITY_MODIFIER) : BREEDING_PROBABILITY;
        if (adjustedBreedingProbability > 1) adjustedBreedingProbability = 1;

        int births = breed(BREEDING_AGE, MAX_LITTER_SIZE, adjustedBreedingProbability);

        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Rabbit young = new Rabbit(false, field, loc);
            newRabbits.add(young);
        }
    }

