public void determineFog()
    {
        if(!fogPresent)
        {
            chanceOfFog();
        }
        else
        {
            // Set the blind probability of predators to 0.5
            setProbability(0.5);
            // Gets rid of fog in the simulation if maxTime is less than or equal to 0.
            if(getMaxTime() <= 0)
            {
                fogPresent = false;
                setProbability(0);
            }
            else
            {
                decrementMaxTime(); 
            }
        }
    }

