public void showStatus(int step, Field field, boolean isSunny, boolean isRainy)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object obj = field.getObjectAt(row, col);
                if(obj != null) {
                    stats.incrementCount(obj.getClass());
                    var temp1 = obj.getClass();
                    if(obj instanceof Animal) {
                        Animal ani = (Animal) obj;
                        if(ani.hasDeezZeezH) {
                            temp1 = Infected.class;
                        }
                    }
                    fieldView.drawMark(col, row, getColor(temp1));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        if((step % 50) < 25) {
            daystatus.setText(DAY_PREFIX);
            if(isSunny) {
                daystatus.setText(DAY_PREFIX + SUNNY_SUFFIX);
            }
        } else {
            daystatus.setText(NIGHT_PREFIX);
        }

        if(isRainy) {
            daystatus.setText(daystatus.getText() + RAIN_SUFFIX);
        }

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public void simulateOneStep()
    {
        time.incrementTime();
        weather.decrementDuration();

        step++;

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();

        // Let all plants grow.
        for (Plant plant : plants) {
            plant.grow(weather.isRaining());
        }

        boolean isFoggy = weather.isFoggy();
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals, foodWeb, rand, isFoggy, time);
            if (!animal.isAlive()) {
                it.remove();
            }
        }
        // We pick a random animal on the field and randomize
        // the chance of it getting a new disease.
        if (rand.nextDouble() <= Disease.getProbability()) {
            Animal diseasedAnimal = animals.get(rand.nextInt(animals.size()));
            diseasedAnimal.setDisease(new Disease());
        }

        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);
        updateViews();
    }

