public void showStatus(int step, int day, boolean isDayTime, Weather weather, Field field) {
        if (!isVisible()) {
            setVisible(true);
        }

        String stepText = STEP_PREFIX + step;
        stepLabel.setText(stepText);

        String dayText = DAY_PREFIX + day;
        String timeText = "(Day Time)";
        if (!isDayTime) timeText = "(Night Time)";
        String weatherText = "";
        if (weather != null) weatherText = WEATHER_PREFIX + weather.getName();

        infoLabel.setText(dayText + " " + timeText + " " + weatherText);
        stats.reset();

        fieldView.preparePaint();

        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Actor actor = (Actor) field.getObjectAt(row, col);
                if (actor != null) {
                    stats.incrementCount(actor.getSpecies());
                    fieldView.drawMark(col, row, getColor(actor.getSpecies()));
                } else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

