public void act(List<Animal> newDeers, boolean isDay, String weather)
    {
        // adjusted the characteristics according to the weather.
        weatherImpact(weather);
        incrementAge(MAX_AGE);

        contagion();
        if (isSleep (isDay)){
            return;
        }
        if (isRest(weather)){
            return;
        }
        incrementHunger();
        illness();
        suddenDeath(ADJUSTED_DEATH_RATE);
        if(isAlive()){
            if(findMate()){
