docstring:
Crocodile acts differently depending on the time of the day and the weather.
@param newCrocodiles The list of new born crocodiles
@param timeOfDay The time of the day.
@param chanceOfDying The probability of animal dying if it is infected.
@param weather The weather type.

function:
public void act(List<Animal> newCrocodiles, int timeOfDay, double chanceOfDying, int weather) {        
        if(timeOfDay == 0) {
            increaseAge(MAX_AGE);
        }

        checkDisease(chanceOfDying);

        double huntProbability;

        if(isAlive()) {
            //If the weather is rainy, the hunting probability for crocodiles is lower.
            if(weather == 1) {
                huntProbability = 0.75;
            }
            else{
                huntProbability = 1;
            }

            switch(timeOfDay) {     
                case 0:
                // Morning, Crocodile hunts, food level decreases
                hunt(this, getField(), MAX_FOOD_LEVEL, CAN_EAT, huntProbability, 2);
                decreaseFoodLevel(2);
                break;

                case 1:
                // Afternoon, Crocodile gives birth, hunts, food level decreases
                if(!isAnimalMale()) {
                    giveBirth(newCrocodiles);
                }               
                hunt(this, getField(), MAX_FOOD_LEVEL, CAN_EAT, huntProbability, 1);
                decreaseFoodLevel(2);
                break;

                case 2:
                // Evening, Crocodile gives birth, hunts, food level decreases
                if(!isAnimalMale()) {
                    giveBirth(newCrocodiles);
                }          
                hunt(this, getField(), MAX_FOOD_LEVEL, CAN_EAT, huntProbability, 2);
                decreaseFoodLevel(2);
                break;

                case 3:
                // Night,  Crocodile gives birth, hunts, food level decreases
                if(!isAnimalMale()) {
                    giveBirth(newCrocodiles);
                }         
                hunt(this, getField(), MAX_FOOD_LEVEL, CAN_EAT, huntProbability, 2);
                decreaseFoodLevel(2);
                break;
            }
        }
    }

