public void showStatus(int step, Field field, String statusData)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step + "] " + statusData);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());

                    Entity currentEntity = (Entity) animal;
                    boolean entityInfected = currentEntity.isInfected();

                    Color currentColor = getColor(animal.getClass());
                    if (entityInfected == true) {
                        currentColor = new Color(0, 0, 0);
                    }

                    fieldView.drawMark(col, row, currentColor);
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

