Look for prey/animal adjacent to the current location.
Only the first live prey is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object food = field.getObjectAt(where);
            // Can move to plants and kill them but gains no foodlevel from it
            if(food instanceof Plant || food instanceof Mice || food instanceof Giraffe || food instanceof Zebra || food instanceof InfectedMice) {
                Animal animal = (Animal) food;
                if(animal.isAlive()) { 
                    animal.setDead();
                    if(!(food instanceof Plant)){
                        this.foodLevel += animal.FOOD_VALUE;
                    }
                    return where;
                }
            }
        }
        return null;
    }

private void populate() {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                boolean created = false;
                Set keys = creationProbabilites.keySet();
                Iterator<Actor> it = keys.iterator();
                while (it.hasNext() && !created) {
                    Actor actor = it.next();
                    if (rand.nextDouble() <= creationProbabilites.get(actor)) {
                        Location location = new Location(row,col);
                        // animal actors breed so a new animal is created
                        if (actor.moves()) {
                            Animal animal = (Animal) actor;
                            actors.add(animal.getNewAnimalObject(true,field,location));   
                        }
                        else {
                            Plant plant = (Plant) actor;
                            actors.add(plant.getNewPlantObject(field,location));
                        }

                        created = true;
                    }
                }
                //else leave the location empty.
            }
        }

    }

