public void incrementTime() {
		int prevDay = getDay();
		this.time++;
		if (getDay() != prevDay) { // new day
			float value = rand.nextFloat();
			float x = 0;
			for (Weather w : Weather.values()) {
				x += w.getOdds();
				if (value < x) {
					weather = w;
					break;
				}
			}
		}

		else if (weather == Weather.THUNDER && rand.nextFloat() < THUNDERSTIKE_ODDS) {
			doThunderstrike();
		}
	}

