        Field field = getField();
        List<Location> adjacent = field.adjacentLocationsWBorder(getLocation(),4);
        //If weather is foggy reduce the surrounding area the hyenas can mate in.
        if(weather.equals("fog")){
            adjacent = field.adjacentLocationsWBorder(getLocation(),1);
        }
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Hyena) {
                Hyena hyena = (Hyena) animal;
                if(hyena.getSex() != sex) { 
