        if(animal instanceof Sheep) {
            Sheep sheep = (Sheep) animal;
            if(sheep.isAlive()) { 
                sheep.setDead();
                foodLevel += SHEEP_FOOD_VALUE;
                return true;
            }
        }
        return false;
    }

