public void act(List<Actor> actors, int step) {
        fieldView.preparePaint();
        stats.reset();
        for (Actor actor : actors) {
            stats.incrementCount(actor.getClass());
            if (actor.isActive()) {
                if (actor instanceof Drawable) {
                    Drawable drawable = (Drawable) actor;
                    Location location = drawable.getLocation();
                    if (actor instanceof Animal) {
                        fieldView.drawMark(location.getCol(), location.getRow(), drawable.getDrawColor(), ((Animal) actor).isInfected());
