@param competingSpecies, hashMap that has animals as keys and their
food level as values.
@return the key of the min value

function:
private Animal compareFoodResource(HashMap<Animal,Integer> competingSpecies)
    {
        int min = Integer.MAX_VALUE;

        for (int value : competingSpecies.values()) {
            if (value <=  min){
                min = value;
            }
            //System.out.println("Value "+value);
        } 

        for (Map.Entry <Animal, Integer> entry : competingSpecies.entrySet()){
            if(entry.getValue() == min){
                //System.out.println("key value: " + entry.getKey());
                return entry.getKey();
            }
        }
        return null;
    }

public void act(List<Animal> newRats)
    {

        if (Simulator.instance.isDay) {
            incrementAge();
            incrementHunger();
        } //metabolism and aging during night are slowed enough to be negligible.

        if(isAlive()) {
            giveBirth(newRats); 
            spreadDisease();
            cureDisease();

            if (Simulator.instance.isDay == false){
                return;
            } //Rat is sleeping at night.

            // Try to move into a free location.
            Location newLocation = findFood();
            if(newLocation == null) {
                newLocation = getField().freeAdjacentLocation(getLocation());
            } //move towards food if it is adjacent to Rat.

            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

