private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object foodSource = field.getObjectAt(where);
            if(foodSource instanceof Seal) {
                Seal seal = (Seal) foodSource;
                if(seal.isAlive()) { 
                    seal.setDead();
                    foodLevel += SEAL_FOOD_VALUE;
                    return where;
                }
            }
            if(foodSource instanceof SeaTurtle) {
                SeaTurtle seaTurtle = (SeaTurtle) foodSource;
                if(seaTurtle.isAlive()) { 
                    seaTurtle.setDead();
                    foodLevel += SEAL_FOOD_VALUE;
                    return where;
                }
            }
            if(foodSource instanceof Shrimp) {
                Shrimp shrimp = (Shrimp) foodSource;
                if(shrimp.isAlive()) { 
                    shrimp.setDead();
                    foodLevel += SHRIMP_FOOD_VALUE;
                    return where;
                }
            }
            if(foodSource instanceof SeaWeed) {
                SeaWeed seaWeed = (SeaWeed) foodSource;
                if(seaWeed.isAlive()) { 
                    seaWeed.setDead();
                    foodLevel += SEA_WEED_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

