@param count radius of search
@param adjacent list of locations around the current location
@param previous list of the lcoations that have been checked

function:
protected Location findFood(int count, List<Location>  adjacent, List<Location> previous)
    {
        if (count < 0){
            return null;
        }

        List<Location> previousLocations = previous;

        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = getField().getObjectAt(where);

            if(organism instanceof Grass) {
                killGrass((Grass) organism);
                return where;
            }


            if(previousLocations.contains(where)){continue;}

            previousLocations.add(where);

            if (findFood(count - 1, getField().adjacentLocations(where), previousLocations)!= null){
                return where;
            }
        }
        return null;
    }

private boolean checkNeighbourGender(List<Animal> surroundingAnimals, boolean ownGender)
    {
        boolean differentGenderMatch = false;

        // for all surrounding animals of the same type, it checks that there is at least one with a differnt gender
        for(Iterator<Animal> it = surroundingAnimals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            if(animal.getGender() != ownGender) {
                differentGenderMatch = true;
            }
        }

        return differentGenderMatch;
    }

docstring:
Look for Monkeys and Sloths adjacent to the current location.
Only the first live Monkey or Sloth is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if(organism instanceof Monkey) {
                Monkey monkey = (Monkey) organism;
                if(monkey.isAlive()) { 
                    monkey.setDead();
                    foodLevel = ANIMAL_FOOD_VALUE;
                    return where;
                }
            }
            else if(organism instanceof Sloth) {
                Sloth sloth = (Sloth) organism;
                if(sloth.isAlive()) { 
                    sloth.setDead();
                    foodLevel = ANIMAL_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

