private void infect(){
        Field field = getField();
        List<Location> adjacentLocations=field.adjacentLocations(getLocation());
        Iterator<Location> it= adjacentLocations.iterator();
        while (it.hasNext()){
            Location where = it.next();
            Object actor = field.getObjectAt(where);
            if (where!=null){
                if (actor instanceof Turtle){
                    Turtle turtle = (Turtle) actor;
                    //Chance that nearby turtles will be infected.
                    if (rand.nextDouble()>IMMUNITY){
                        turtle.getDiseases().addAll(getDiseases());
                    }
                }
            }
        }
    }

public void simulateOneStep()
    {
        step++;

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);
        time.dayNightCycle(step);

        view.showStatus(step, field, time.currentTime(), time.currentSeason());
    }

