public void act(List<Animal> newBears)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            giveBirth(newBears);            
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

public void act () {
        String weather = getField().getWeather();
        switch(weather){
            case "rainy":
                spread();
                break;
            case "snowy":
                life -= RNG.nextInt(2);
                break;
            case "sunny":
                life++;
                break;
            case "clear":
                break;
        }     
        if (life <= 0) {
            setDead();
        }
        else if (life > MAX_LIFE) {
            life = MAX_LIFE;
        }
    }

