public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;

            }
            // if no grass remains program ends
            if(info.getName().equals("Grass") && info.getCount() <= 0 ) {
                nonZero = nonZero - 999;

            }
        }
        return nonZero > 1;
    }

