private void giveBirth(OrganismList newGrasshoppers)
    {
        // New grasshoppers are born into adjacent locations.
        // Get a list of adjacent occupied locations.
        List<Location> occupied = getField().adjacentLocations(getLocation());
        int births = breed();
        Iterator<Location> it = occupied.iterator();
        while(it.hasNext()) {
            // Find nearby grasshoppers
            Location where = it.next();
            Object animal = getField().getObjectAt(where);
            if(animal instanceof Grasshopper) {
                // If grasshopper is of opposite gender, breed.
                Grasshopper grasshopper = (Grasshopper) animal;
                if(oppGender(grasshopper)) {
                    //Get list of free locations to place new grasshoppers
                    List<Location> free = getField().getFreeAdjacentLocations(getLocation());
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Grasshopper young = new Grasshopper(false, new WorldInterface(getField(), loc, getEnvironment()));
                        newGrasshoppers.add(young);
                    }    
                }
            }
        }
    }

