        }
        stats.countFinished();

        animal.setText(ANIMAL_PREFIX + stats.getAnimalPopulationDetails(field));
        plant.setText(PLANT_PREFIX + stats.getPlantPopulationDetails(field));

        fieldView.repaint();
    }

