public void act(List<Animal> newSharks, int time)
    {
        if (getLocation() != null) {
            checkForDisease();
        }
        incrementAge();
        incrementHunger();      
        if(isAlive()) {
            giveBirth(newSharks); 
            Location newLocation = null;
            // Move towards a source of food if it is a day and source was found.
            if (4 < time && time < 20) {
                newLocation = findFood();
            }

            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

