protected void giveBirth(List<Animal> newAnimals)
    {
        // New predators are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Animal newAnimal = AnimalType.createChild(animalType, false, field, loc);
            if (animalIsDiseased()) {
                // if the disease is transmited by birth then infect the offspring
                if (this.disease.getTransmissionType() == Disease.TransmissionType.BIRTH) {
                    newAnimal.setDiseased(this.disease);
                }
            }
            newAnimals.add(newAnimal);        
        }
    }

