final boolean canBreed() {
    boolean mateFound = false;
    findNearbyAnimals();
    for (Animal mate : nearbyAnimals) {
      if ((mate.getClass() == this.getClass())
          && (mate.isOfAge() && this.isOfAge())
          && (!mate.isFemale && this.isFemale)) {
        mateFound = true;
        break;
      }
    }
    return mateFound;
  }

