docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        // Increament of count for every 32 teps.
        if(step % 32 == 0){
            CountNum++;
        }
        stepLabel.setText(STEP_PREFIX + step);
        // If count modula divide by 2 is 0, time is night.
        // Otherwise, time is daytime.
        if (CountNum % 2 == 0){
            timeLabel.setText(TIME_PREFIX + "Night");
        }
        else{
            timeLabel.setText(TIME_PREFIX + "Daytime");
        }
        // If count modula divide by 3 is 0, the weather is rainy.
        //Otherwise, the weather is sunny 
        if (CountNum % 3 == 0){
            weatherLabel.setText(WEATHER_PREFIX + "Rainy");
        }
        else{
            weatherLabel.setText(WEATHER_PREFIX + "Sunny");
        }

        diseaseLabel.setText(DISEASE_PREFIX + "0");
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    Class<?> cls = animal.getClass();
                    stats.incrementCount(cls);
                    fieldView.drawMark(col, row, getColor(cls));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public Environment getForestEnvironment() {
        return forestEnvironment;
    }

protected void setDead()
    {
        active = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                int randomPredatorNum = ThreadLocalRandom.current().nextInt(1, 4);
                int randomPreyNum = ThreadLocalRandom.current().nextInt(1, 3);
                if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY){
                    Location location = new Location(row, col);
                    Plants plant = new Plants(field, location, t, currentWeather);
                    plants.add(plant);
                }
                else if(rand.nextDouble() <= PREY_CREATION_PROBABILITY) {
                    if(randomPreyNum == 1){
                        Location location = new Location(row, col);
                        Fish fish = new Fish(true, field, location, t, currentWeather, disease);
                        animals.add(fish);
                    }
                    else if(randomPreyNum == 2){
                        Location location = new Location(row, col);
                        SeaBird seaBird = new SeaBird(true, field, location, t, currentWeather, disease);
                        animals.add(seaBird);
                    }
                }
                else if(rand.nextDouble() <= PREDATOR_CREATION_PROBABILITY) {
                    if(randomPredatorNum == 1) {
                        Location location = new Location(row, col);
                        Penguin penguin = new Penguin(true, field, location, t, currentWeather, disease);
                        animals.add(penguin);
                    }
                    else if(randomPredatorNum == 2) {
                        Location location = new Location(row, col);
                        Seal seal = new Seal(true, field, location, t, currentWeather, disease);
                        animals.add(seal);
                    }
                    else if(randomPredatorNum == 3) {
                        Location location = new Location(row, col);
                        Whale whale = new Whale(true, field, location, t, currentWeather, disease);
                        animals.add(whale);
                    }
                }
                // else leave the location empty.
            }
        }
    }

@Override
