@param weatherGenerator

function:
public void act(List<Organism> newCod, WeatherGenerator weatherGenerator) {
        if (isAlive()) {
            giveBirth(newCod);
            // Try to move into a free location.
            Location newLocation = getField().freeAdjacentLocation(getLocation());
            if (newLocation != null && (newLocation.getCellType().equals("Shallow") ||
                    newLocation.getCellType().equals("Water"))) {
                setLocation(newLocation);
            }
        }
    }

docstring:
Check whether or not this eagle is to give birth at this step.
New births will be made into free adjacent locations.
@param newEagle A list to return newly born eagle.

function:
private void giveBirth(List<Creature> newEagle)
    {
        // New eagle are born into adjacent locations.
        // Get a list of adjacent free locations.
        // This method is called by female eagle
        if(!getGender())
        {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext())
            {
                Location where = it.next();
                Object what = field.getObjectAt(where);
                if(what instanceof Eagle)
                {
                    Eagle eagle = (Eagle) what ;
                    //only reproduce when two eagle are of opposite gender
                    if(eagle.getGender())
                    {
                        List<Location> free = field.getFreeAdjacentLocations(getLocation());
                        int births = breed();
                        for(int b = 0; b < births && free.size() > 0; b++) 
                        {
                            Location loc = free.remove(0);
                            Eagle young = new Eagle(false, field, loc);
                            newEagle.add(young);
                            break;
                        }
                    }
                }
            }
        }
    }

docstring:
Look for animals adjacent to the current location.
Only the first live animal is eaten.
@return Where food was found, or null if it wasn't.

function:
protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object object = field.getObjectAt(where);
            if(object instanceof Actor && getDiet().contains(object.getClass())) {
                Actor prey = (Actor) object;
                if(prey.isAlive()) {
                    eat(prey);
                    prey.setDead();
                    return where;
                }
            }
        }
        return null;
    }

