docstring:
Look for actors adjacent to the current location.
Only the first live desirable food is eaten.

@return Where food was found, or null if it wasn't.

function:
private Location findFood() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object o = field.getObjectAt(where);
            if (desirable(o)) {
                Killable foodSource = (Killable) o;
                Actor actor = (Actor) o;
                if (foodSource.isAlive()) {
                    foodSource.setDead();

                    foodLevel += foodSource.getFoodValue();

                    if (actor.hasDisease == true) transmitInfection(this, actor.getDisease());
                    return where;
                }
            }
        }
        return null;
    }

private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            if(animal instanceof Badger) {
               Badger badger = (Badger) animal;

               if(badger.isAlive()) { 
                    if (badger.isDiseased()){ 
                        setDiseased();
                    }
                    badger.setDead();
                    foodLevel = foodLevel + BADGER_FOOD_VALUE;

                    return where; 
                }
            } 

            if (animal instanceof Snake) {
                Snake snake = (Snake) animal; 
                if (snake.isAlive()){
                   if (snake.isDiseased()){ 
                        setDiseased();
                    }
                    snake.setDead();
                    foodLevel =foodLevel + SNAKE_FOOD_VALUE;
                    return where; 
                }
            }

            // If a wildcat is next to a lizard, it is assumed that the wildcat steps on the lizard
            // and hence the lizard will die.
            if (animal instanceof Lizard) {
                Lizard lizard = (Lizard) animal;
                if (lizard.isAlive()){
                    lizard.setDead();
                }
            }
      }
        return null;
    }

