public void Disease(double disease){
        if(disease < diseaseProbability){
            double deathProbability = 0.001;
            double die = rand.nextDouble();
            counter++;

            if(die < deathProbability){
                this.setDead();
            } else{
                this.BREEDING_PROBABILITY = 0;
                this.MAX_AGE = MAX_AGE/2;
            }
        }
    }

