        count.increment();
    }

public void incrementCount(Class objClass)
    {
        Counter count = counters.get(objClass);
        if(count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(objClass.getName());
            counters.put(objClass, count);
        }
        count.increment();
    }

