public void simulateOneStep()
    {
        incrementStep();

        // Provide space for newborn animals and plants.
        List<Actor> newActors = new ArrayList<>();        
        // Let all animals and plants act.
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            actor.act(newActors);
            if(actor instanceof Animal) {
                Animal animal = (Animal) actor;
                if(! animal.isAlive()) {
                    it.remove();
                }
            }
            else if(actor instanceof Plants) {
                Plants plants =(Plants) actor;
                if(! plants.isAlive()) {
                    it.remove();
                }
            }
        }

        // Add the newly born animals and plants to the main lists.
        actors.addAll(newActors);

        view.showStatus(step, time, weather.getWeatherString(), field);
    }

