docstring:
Finds competing species and puts them and their food level in a hashMap
If there are diseased competing animals near the pig,it gets infected aswell
@param foodResource, plant found in findFood method.

function:
private void competeForfood(Plant foodResource)
    {
        Field field = foodResource.getField();
        List<Location> adjacentPredator = field.adjacentLocations(getLocation());
        Iterator<Location> itPredator = adjacentPredator.iterator();

        HashMap<Animal,Integer> competingSpecies = new HashMap();

        while(itPredator.hasNext()) {
            Location wherePredator = itPredator.next();
            Object predator = field.getObjectAt(wherePredator);
            competingSpecies.put(this, foodLevel);
            //Object predater2 = field.getObjectAt(adjacentPredator.get(i));
            if(predator instanceof Cow){
                Cow cow = (Cow) predator;
                if(cow.getDisease()){
                    this.setDisease(true);
                }
                int cowFoodLevel =cow.getFoodLevel();
                competingSpecies.put(cow,cowFoodLevel);
                }

            else if(predator instanceof Sheep){
                Sheep sheep = (Sheep) predator;
                if(sheep.getDisease()){
                    this.setDisease(true);
                }
                int sheepFoodLevel = sheep.getFoodLevel();
                competingSpecies.put(sheep,sheepFoodLevel);
            }
        }

        Animal winner = compareFoodResource(competingSpecies);
        winner.addFoodLevel(foodResource.getBite());
        }

