docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        // This is where the time is recorded, every 10 steps is 12 hours.
        int number = step;
        int firstDigit = Integer.parseInt(Integer.toString(number).substring(0, 1));
        ArrayList<Integer> half = new ArrayList<>();
        half.add(0);
        half.add(2);
        half.add(4);
        half.add(6);
        half.add(8);
        if(step <100)
        {
            if (step <= 10 || half.contains(firstDigit))
            {
                day = true;
                weatherCondition();
            }
            else
            {
                day = false;
                weatherCondition();
            }
        }
        else if(step < 1000)
        {
            int num = step;
            int secondDigit = Integer.parseInt(Integer.toString(num).substring(1, 2));
            if (half.contains(secondDigit))
            {
                day = true;
                weatherCondition();
            }
            else
            {
                day = false;
                weatherCondition();
            }
        }
        else
        {
            int num = step;
            int thirdDigit = Integer.parseInt(Integer.toString(num).substring(2, 3));
            if (half.contains(thirdDigit))
            {

                day = true;
                weatherCondition();
            }
            else
            {

                day = false;
                weatherCondition();
            }
        }

        if(day)
        {
            time.setText(TIME_PREFIX + "Day  ");
        }
        else
        {
            time.setText(TIME_PREFIX + "Night");
        }
        if(rain)
        {
            weather.setText(WEATHER_PREFIX + "raining");
        }
        else
        {
            weather.setText(WEATHER_PREFIX + "sunny  ");
        }


        fieldView.repaint();
    }

