docstring:
Look for octopus or small fish adjacent to the current location.
Only the first live octopus or fish is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Octopus) {
                Octopus octopus = (Octopus) animal;
                if(octopus.isAlive() && octopus.isAwake()){
                    if (octopus.getPlasticStatus()){
                        plasticIntake++;
                        //incremented the amount octopus with plastic it's eaten
                    }
                    octopus.setDead();
                    foodLevel = OCTOPUS_FOOD_VALUE;
                    return where;
                }

            }
            else if(animal instanceof SmallFish){  
                    SmallFish smallFish = (SmallFish) animal;
                    if(smallFish.isAlive() && smallFish.isAwake()) {
                        smallFish.setDead();
                        foodLevel = SMALLFISH_FOOD_VALUE;;
                        return where;
                    }
            }
        }
        return null;
    }

private Location findFood() {
        Field field = getField();
        Location loc = getLocation();
        if (loc == null) {
            System.out.println(loc);
            System.exit(0);
        }
        List<Location> adjacent = field.adjacentLocations(loc);
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            Random random = new Random();
            int randomFood = random.nextInt(3);
            if (animal instanceof Squirrel && isHungry() && randomFood == 1) {
                Squirrel squirrel = (Squirrel) animal;
                if (squirrel.isAlive()) {
                    squirrel.setDead();
                    foodLevel = foodLevel+SQUIRREL_FOOD_VALUE;
                    return where;
                }
            } else if (animal instanceof Duck && isHungry() && randomFood == 0) {
                Duck duck = (Duck) animal;
                if (duck.isAlive()) {
                    duck.setDead();
                    foodLevel = foodLevel+DUCK_FOOD_VALUE;
                    return where;
                }
            } else if (animal instanceof Deer && isHungry() && randomFood == 2) {
                Deer deer = (Deer) animal;
                if (deer.isAlive()) {
                    deer.setDead();
                    foodLevel = foodLevel+DEER_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

