docstring:
Look for grass or mushroom adjacent to the current location.
Only the first plant found is eaten.

@return Where food was found, or null if it wasn't.

function:
public Location findFood()
     {
         // Only look for food if hungry, the animal just roam around when full
         if(getHunger() / MAX_FOOD_CONSUMPTION * 100 <= 80) {
             Field field = getField();
             List<Location> adjacent = field.adjacentLocations(getLocation());
             Iterator<Location> it = adjacent.iterator();
             while(it.hasNext()) {
                 Location where = it.next();
                 Object plant = field.getPlantAt(where);
                 if(plant instanceof Grass) {
                     Grass grass = (Grass) plant;
                     if(grass.isAlive() && grass.resetGrowthLevel()) {
                         setHunger(getHunger() + GRASS_FOOD_VALUE, MAX_FOOD_CONSUMPTION);
                         return where;
                     }
                 } else if(plant instanceof Mushroom) {
                     Mushroom mushroom = (Mushroom) plant;
                     if(mushroom.isAlive() && mushroom.resetGrowthLevel()) {
                         setHunger(getHunger() + MUSHROOM_FOOD_VALUE, MAX_FOOD_CONSUMPTION);
                         return where;
                     }
                 }
             }
         }
         return null;
     }

private boolean findMate() 
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocationsVar(getLocation(), mate_distance);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (organism instanceof Frog) {
                Frog potentialMate = (Frog) organism;
                if(potentialMate.isAlive() && potentialMate.canBreed()) {
                    if(potentialMate.getIsMale() != this.isMale) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

