public List<Location> findEmptyLocationAtEdge()
    {
        List<Location> locations = new LinkedList<>();
        for(int row = 0; row < depth; row++) {
            Location target = new Location(row,0);
            Location target1 = new Location(row,width - 1);
            if(getObjectAt(target) == null) {
                locations.add(target);
            }
            if(getObjectAt(target1) == null) {
                locations.add(target1);
            }
        }
        for(int col = 0; col < width; col++) {
            Location target = new Location(0,col);
            Location target1 = new Location(depth - 1,col);
            if(getObjectAt(target) == null) {
                locations.add(target);
            }
            if(getObjectAt(target1) == null) {
                locations.add(target1);
            }
        }
        // Shuffle the list. Several other methods rely on the list
        // being in a random order.
        Collections.shuffle(locations, rand);
        return locations;
    }

