private int generateInfectedCounts(Field field)
    {
        //Counter count = new Counter("infected");
        int infected = 0;
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object organism = field.getObjectAt(row, col);
                if(organism != null && organism instanceof Animal) {
                    Animal animal = (Animal) organism;
                    if(animal.getIsInfected()){
                        infected++;
                    }
                }
            }
        }
        return infected;
    }

