private void project(float[] velocX, float[] velocY, float[] p, float[] div) {
        for (int j = 1; j < N - 1; j++) {
            for (int i = 1; i < N - 1; i++) {
                div[weatherGrid(i, j)] = -0.5f*(
                        velocX[weatherGrid(i+1, j)]
                                -velocX[weatherGrid(i-1, j)]
                                +velocY[weatherGrid(i, j+1)]
                                -velocY[weatherGrid(i, j-1)]
                )/N;
                p[weatherGrid(i, j)] = 0;
            }
        }

        setBoundary(0, div);
        setBoundary(0, p);
        linearSolver(0, p, div, 1, 4);

        for (int j = 1; j < N - 1; j++) {
            for (int i = 1; i < N - 1; i++) {
                velocX[weatherGrid(i, j)] -= 0.5f * (  p[weatherGrid(i+1, j)]
                        -p[weatherGrid(i-1, j)]) * N;
                velocY[weatherGrid(i, j)] -= 0.5f * (  p[weatherGrid(i, j+1)]
                        -p[weatherGrid(i, j-1)]) * N;
            }
        }
        setBoundary(1, velocX);
        setBoundary(2, velocY);
    }

