docstring:
Run the simulation from its current state for the given number of steps.
Stop before the given number of steps if it ceases to be viable.

@param numSteps (int) The number of steps to run for.

function:
public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            delay(DEFAULT_DELAY);
            simulateOneStep();
            // delay(200);   // uncomment this to run more slowly
        }
    }

public void simulateOneStep()
    {
        Random rand = Randomizer.getRandom();
        Time timer = new Time();
        step++;

        // Increment the cycle of weathers.
        weather.increment();

        // Random disease generator
        if (rand.nextDouble() <= DISEASE_PROBABILITY){
            Random random = new Random();
            int val = random.nextInt(animals.size());
            Animal animal = animals.get(val);
            Disease disease = new Disease();
            disease.spreadDisease(animal);
        }

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all rabbits act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            // Check whether the animal is active at the step.
            if(animal.getDiurnality() == timer.getTime(step)){
                if(animal instanceof Herbivore || weather.getWeather() != Weather.FOG){
                    animal.act(newAnimals);
                }
            }
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born foxes and rabbits to the main lists.
        animals.addAll(newAnimals);

        // Grow the plants in this step.
        if(weather.getWeather() == Weather.RAIN){
            field.grow(7);
        }
        else if(weather.getWeather() != Weather.DRAUGHT){
            field.grow(5);
        }

        view.showStatus(step, field);
    }

