        List<Location> adjacentAnimal = field.perimeterLocations
            (getLocation(), -1, 1);
        Iterator<Location> it = adjacentAnimal.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object actor = field.getObjectAt(where);
            if(actor instanceof Animal){
