private void giveBirth(List<Animal> newMice)
    {
        // New mice are born into adjacent locations.
        // Get a list of adjacent free locations.
        if(searchAdjacentLocationsForMale() != null)
        {
            Field field = getField();
            List<Location> free = field.getFreeAdjacentLocations(getLocation());
            int births = breed();
            for(int b = 0; b < births && free.size() > 0; b++) 
            {
                Location loc = free.remove(0);
                Mouse young = new Mouse(false, field, loc);
                newMice.add(young);
            }
        }
    }

public double distanceTo(Location otherLocation) {
        return Math.sqrt(
            Math.pow((getX() - otherLocation.getX()), 2) + 
            Math.pow((getY() - otherLocation.getY()), 2) + 
            Math.pow((getZ() - otherLocation.getZ()), 2)
        );
    }

private Location findFood() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            Random random = new Random();
            int randomFood = random.nextInt(2);
            if (animal instanceof Squirrel && isHungry() && randomFood == 1) {
                Squirrel squirrel = (Squirrel) animal;
                if (squirrel.isAlive()) {
                    squirrel.setDead();
                    foodLevel = foodLevel + SQUIRREL_FOOD_VALUE;
                    return where;
                }
            } else if (animal instanceof Duck && isHungry() && randomFood == 0) {
                Duck duck = (Duck) animal;
                if (duck.isAlive()) {
                    duck.setDead();
                    foodLevel = foodLevel + DUCK_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

