private int breed()
    {
        int births = 0;
        if(canBreed() && rand.nextDouble() <= BREEDING_PROBABILITY && foodLevel > 9) 
        {
            births = rand.nextInt(MAX_LITTER_SIZE) + 1;//inclusive
