public void updateInteractions() {
        Field field = mainHost.getField();
        if(field != null){
            List<Location> potentialVictim  = field.getNotNullAdjacentLocations(mainHost.getLocation());
            for(Location victim : potentialVictim){
                Organism organism = (Organism) field.getObjectAt(victim);
                if(numOfInteractions.get(organism) == null){
                    numOfInteractions.put(organism, 0);
                }else{
                    numOfInteractions.put(organism, numOfInteractions.get(organism) +1 );
                }

            }
        }
    }

public String getWeather()
    {
        if(Randomizer.getRandom().nextDouble() <= 0.5) {
            weather = "sunny";  // Sunny day has no influence, it is just a normal day.
        }
        else if(Randomizer.getRandom().nextDouble() > 0.5 && Randomizer.getRandom().nextDouble() <= 0.9) {
            weather = "rainny";  // Rainny day causes grass grow at a faster rate.
        }
        else if(Randomizer.getRandom().nextDouble() > 0.9) {
            weather = "foggy";  // Foggy day makes predators less likely to pery successfully.
        }
        return weather;
    }

@Override
    public void act(List<Species> newDeers)
    {
        newAge = incrementAge(age, getMaxAge());
        if (newAge != -1) {
            age = newAge; }
        incrementHunger();
        if(isAlive()) {
            reproduce(newDeers);            
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead("Hunger");
        }
    }

