public void act(List<Animal> newLeopards)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            passInfection();
            attemptRecovery();
            if(!((hour >=0) && (hour <= 10))){//leopards will be awake outside of these times
                if((hour >= 11) && (hour  <= 18)){ 
                    //between 14:00 and 18:00, leopards will breed
                    meet(newLeopards);
                }

                // Move towards a source of food if found.
                Location newLocation = findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            }
        }
    }

