@Override
	public void affect(Animal animal) {
		if (stepsWithVirus < 10 && rand.nextDouble() <= .05) {
			animal.setDead();
		} else if (stepsWithVirus >= 10) {
			animal.getCured(this);
		}
		stepsWithVirus++;
	}

