        }
    }

docstring:
Tries to find a prey in one of the neighboring cell. If a prey is found, it is eaten and its location is returned.

@param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
@return (Location) the location of the eaten prey, null if no prey was found.

function:
private Location findFoodAndEat(ArrayList<Animal> neighboringAnimals)
    {
        for (Animal animal : neighboringAnimals) {
            if(!(animal instanceof Predator)){
                animal.setDead();
                foodLevel += animal.getNutritionalValue();
                return animal.getLocation();
            }
        }
        // No food found
        return null;
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();

        ArrayList<Whale> spawnedWhales= new ArrayList<>();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= WHALE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Whale whale = new Whale(true, field, location);
                    animals.add(whale);
                    spawnedWhales.add(whale);
                } else if(rand.nextDouble() <= SQUID_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Squid squid = new Squid(true, field, location);
                    animals.add(squid);
                } else if(rand.nextDouble() <= SHARK_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Shark shark = new Shark(true, field, location);
                    animals.add(shark);
                } else if(rand.nextDouble() <= PLANT_GROWTH_PROBABILITY) {
                    Location location = new Location(row, col);
                    Plant algae = new Plant(field, location);
                    plants.add(algae);
                } else if(rand.nextDouble() <= COD_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Cod cod = new Cod(true, field, location);
                    animals.add(cod);
                } else if(rand.nextDouble() <= TROUT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Trout trout = new Trout(true, field, location);
                    animals.add(trout);
                }

                // else leave the location empty.
            }
        }

        for (Whale whale : spawnedWhales) {
            if(rand.nextDouble() <= DISEASE_SPAWN_PROBABILITY) {
                whale.setInfected();
            }
        }
    }

docstring:
This method makes the plants spread around the field/ reproduce.
@param List of plants.
@return List type Plants list of all plants.

function:
private List<Plant> grow(List<Plant> newPlants)
    {
        if(!isAlive()){return null;}
        Field plantfield = getField();
        // New plants are spawned into adjacent locations.
        // Get a list of adjacent free locations.
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        //sow each seed
        if(free.size()==0){
            return newPlants;
        }
        for(int i = 0; i< MAX_SEEDS && free.size() > 0; i++){
            //if random growth rate< GROWTH_RATE, spawn a new plant
            if(rand.nextDouble() <= GROWTH_RATE){
                Location loc = free.remove(0);
                //plantfield.clear(loc);
                Plant seedling = new Plant(plantfield, loc, weather);
                newPlants.add(seedling);
            }
            //else don't spawn a new plant
        }
        return newPlants;
    }

