public void showStatus(int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object squareContents = field.getObjectAt(row, col);
                // This condition also checks for null
                if(squareContents instanceof Actor) {
                    // Add to the counter
                    Actor actor = (Actor) squareContents;
                    stats.incrementCount(actor.getClass());

                    // If it is an animal, cast to Animal and check for diseases
                    if(actor instanceof Animal) {
                        Animal animal = (Animal) squareContents;
                        if (animal.hasInfection()) {
                            // Infected animals show up darker
                            fieldView.drawMark(col, row, getColor(animal.getClass()).darker());
                        } else {
                            fieldView.drawMark(col, row, getColor(animal.getClass()));
                        }
                    }else {
                        fieldView.drawMark(col, row, getColor(actor.getClass()));
                    }
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

