protected int breed(int breadingAge, double probability, int maxLitterSize)
    {
        int births = 0;
        if(canBreed(breadingAge) && rand.nextDouble() <= probability) {
            births = rand.nextInt(maxLitterSize) + 1;
        }
        return births;
    }

