private boolean canBreed()
    {
        Field field = getField();
        boolean gender = isMale();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()){
           Location loc = it.next();
           Object animal = field.getObjectAt(loc);
           if(animal instanceof Octopus){
               Octopus octopus = (Octopus) animal ;
               if(gender != octopus.isMale() && octopus.isAlive() && age >= BREEDING_AGE){
                   return true;
                }
            }

        }
        return false;
    }

docstring:
Look for grass adjacent to the current location.
Only the first live grass is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        if(foodLevel<5){
        Field field = getField();
        // Get nearby locations.
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            // Check what is in each neighbouring cell.
            Object plant = field.getObjectAt(where);
            if(plant instanceof Grass) { // if there is grass nearby
                Grass grass = (Grass) plant;
                if(grass.isAlive()) { 
                    grass.setDead();
                    foodLevel = GRASS_FOOD_VALUE; // eat the grass
                    return where;
                }
            }
        }
    }
        return null;
    }

private void simulateWeather() {
        field.decrementWeatherTimer();
        //Random chance for a weather effect to be set
        if (rand.nextDouble() <= 0.005) {
            field.setWeatherEffect(Field.Weather.SUN, 50);
        } else if (rand.nextDouble() <= 0.05) {
            field.setWeatherEffect(Field.Weather.STORM, 50);
        }
        //Sets weather back to normal after the weather timer is 0
        if (field.getWeatherTimer() <= 0) {
            field.setCurrentWeather(Field.Weather.NONE);
        }
    }

public String getPopulationDetails(Field field, Class animalKey)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field);
        }

        int temp=0;
        for(Class key: counters.keySet()) {
            if(key==animalKey) {
                Counter info = counters.get(key);
                buffer.append(info.getCount());
                temp++;
            }
        }   
        if(temp == 0) {
            buffer.append(0);
        }
        temp = 0;

        return buffer.toString();
    }

