private void giveBirth(List<Animal> newShark)
    {
        Field field = getField();
        // Get a list of adjacent locations.
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> iterator = adjacent.iterator();
        while(iterator.hasNext()) {
            Object animal = field.getObjectAt(iterator.next());
            if(animal != null) {
                if (animal instanceof Shark) {
                    Shark adjacentShark = (Shark)animal;
                    // Checks whether the gender of the adjacent tuna is of the opposite
                    if (adjacentShark.isMale() != isMale()) {
                        // Get a list of adjacent free locations.
                        List<Location> free = field.getFreeAdjacentLocations(getLocation());
                        int births = breed();
                        // New sharks are born into adjacent locations.
                        for(int b = 0; b < births && free.size() > 0; b++) {
                            Location loc = free.remove(0);
                            Shark young = new Shark(false, field, loc);
                            newShark.add(young);
                        }
                    }
                }
            }
        }
    }

