public void act(List<Animal> newWolf)
    {
        incrementAge();
        incrementHunger();

        // Check if sick and make the disease act
        if (this.isSick()) {
            this.getDisease().act();
        } 

        /**
         * Check if it's still alive after all the
         * cruel stuff in this simulation's world
         */
        if(isAlive()) {
            // Make the wolf sleep at night
            String currentTimeOfDay = Weather.getTimeOfDay();
            if (currentTimeOfDay == "night") {
                return;
            }

            // Give birth if possible
            giveBirth(newWolf);

            // If not sick, but have luck -> get infected with a new Disease
            if (!isSick()) {
                if (rand.nextDouble() <= this.getSicknessProbability()) {
                    // Get infected by a random disease
                    this.becomeInfected();
                }
            }

            // Move towards a source of food if found.
            Location newLocation = findFood();

            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeMovementLocation(getLocation());
            }

            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            } else {
                // Overcrowding.
                setDead();
            }
        }
    }

