public void showStatus(int step, String time, String weatherType, int animalsDieOfDisease, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        timeLabel.setText(TIME_PREFIX + time);
        weatherLabel.setText(WEATHER_PREFIX + weatherType);
        diseaseLabel.setText(ANIMALS_DIE_OF_DISEASE_PREFIX + animalsDieOfDisease);
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

docstring:
Return a shuffled list of {@link Location Locations} adjacent to the given
one. The list will not include the location itself. All locations will lie
within the grid.

@param location The location from which to generate adjacencies.
@return A list of locations adjacent to that given.

function:
public List<Location> adjacentLocations(Location location) {
		assert location != null : "Null location passed to adjacentLocations";
		// The list of locations to be returned.
		List<Location> locations = new LinkedList<>();

		int x = location.getX();
		int y = location.getY();
		for (int xOffset = -1; xOffset <= 1; xOffset++) {
			int nextX = x + xOffset;
			if (nextX >= 0 && nextX < width) {
				for (int yOffset = -1; yOffset <= 1; yOffset++) {
					int nextY = y + yOffset;
					// Exclude invalid locations and the original location.
					if (nextY >= 0 && nextY < depth && (xOffset != 0 || yOffset != 0)) {
						locations.add(new Location(nextX, nextY));
					}
				}
			}
		}

		// Shuffle the list. Several other methods rely on the list
		// being in a random order.
		Collections.shuffle(locations, rand);

		return locations;
	}

