private void populatePlant()
    {
        field.clearPlant();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                int probability = rand.nextInt(PlantCreationProbability.getTotal());
                if(probability >= PlantCreationProbability.GRASS.getLowerBound() && 
                probability < PlantCreationProbability.GRASS.getUpperBound()) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(true, field, location);
                    plants.add(grass);
                }
                else if(probability >= PlantCreationProbability.MUSHROOM.getLowerBound() && 
                probability < PlantCreationProbability.MUSHROOM.getUpperBound()) {
                    Location location = new Location(row, col);
                    Mushroom mushRoom = new Mushroom(true, field, location);
                    plants.add(mushRoom);
                }
                // else leave the location empty.
            }
        }
    }

private boolean canBreed()
    {
        if( age >= BREEDING_AGE)
        {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            Location where = it.next();
            Object animal = field.getObjectAt(where);

            if(animal instanceof Lion)
            {
                Lion lion2= (Lion) animal;
                if(lion2.getAge() >= BREEDING_AGE)
                {

                    if(lion2.getGender()!= gender){

                        return true;
                    }

                }

            }
        }
        return false;

    }

