function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if(organism instanceof Deer) {
                Deer deer = (Deer) organism;
                if(deer.isAlive()) { 
                    deer.setDead();
                    foodLevel = DEER_FOOD_VALUE;
                    return where;
                }
            }
            else if(organism instanceof Mice) {
                Mice mice = (Mice) organism;
                if(mice.isAlive()) { 
                    mice.setDead();
                    foodLevel = MICE_FOOD_VALUE;
                    return where;
                }
            }
            else if(organism instanceof Snake) {
                Snake snake = (Snake) organism;
                if(snake.isAlive()) {
                    snake.setDead();
                    foodLevel = SNAKE_FOOD_VALUE;
                    return where;
                }
        }
    }
    return null;
    }

private void eatRandomWeed()
    {
        Field field = getField();
        Location where = field.randomAdjacentLocation(getLocation());
        Object nature = natureField.getObjectAt(where);
        Object animal = field.getObjectAt(where);
        if(nature instanceof Weed && animal == null) {
            Weed weed = (Weed) nature;
            if(weed.getIsAlive()) { 
                weed.setDead();
                foodLevel = BLUY_FOOD_VALUE;
            }
        }
    }

