public List<Location> getFreeAdjacentLocations(Location location, int layer)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getObjectAt(next,layer) == null) {
                free.add(next);
            }
        }
        return free;
    }

