protected int breed()
    {
        int newEntities = 0;
        if(canBreed() && rand.nextDouble() <= currentBreedingProbability)
            newEntities = rand.nextInt(getMaxLitterSize()) + 1;
        return newEntities;
    }

private void move() {
        for(int steps = 0; steps < MAX_STEPS; steps++) {
            Location newLocation = findFood();

            if(newLocation == null) { 
                // No food found - try to move to a free location or on top of a plant.
                List<Location> adjLoc = getField().adjacentLocations(getLocation());
                for(Location options : adjLoc) {
                    if (getField().getObjectAt(options) == null) {
                        newLocation = options;
                        break;
                    }
                    else if(getField().getObjectAt(options) instanceof Plant) {
                        getField().clear(options);
                        newLocation = options;
                        break;
                    }
                }
            } else {
                break;
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
                break;
            }
        }
    }

