private void giveBirth(List<Species> newLions)
    {
        // New lions are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) {
            Object animal = field.getObjectAt(getLocation());
            Location where = it.next();
            Object nextAnimal = field.getObjectAt(where);

            if(nextAnimal instanceof Lion) {
                Lion lion = (Lion) animal;
                Lion nextLion = (Lion) nextAnimal;
                if(lion.getSex() != nextLion.getSex()) {
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Lion young = new Lion(false, field, loc, false);
                        newLions.add(young);
                    }   
                }
            }
        } 
    }

protected Animal findMale()
    {
        AnimalField animalField = getField();
        List<Location> adjacent = animalField.inAreaLocations(getLocation(),1);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = animalField.getObjectAt(where);
            if(animal instanceof Giraffe) {
                Giraffe giraffe = (Giraffe) animal;
                if(giraffe.isAnimalMale()) { 
                    return giraffe;
                }
            }
        }
        return null;
    }

