docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);

        int time = step % 100;

        if (time <= 35) {
            timeLabel.setText(TIME_PREFIX + "MORNING");
        } else if (time >= 35 && time < 70) {
            timeLabel.setText(TIME_PREFIX + "AFTERNOON");
        } else if(time > 70 && time <= 100) {
            timeLabel.setText(TIME_PREFIX + "NIGHT");
        }

        int seasons = step % 100;

        if (seasons <= 25) {
            seasonsLabel.setText(SEASONS_PREFIX + "SPRING");
        } else if(seasons > 25 && seasons <= 50) {
            seasonsLabel.setText(SEASONS_PREFIX + "SUMMER");
        } else if(seasons > 50 && seasons <= 75) {
            seasonsLabel.setText(SEASONS_PREFIX + "WINTER");
        } else if(seasons > 75 && seasons <= 100) {
            seasonsLabel.setText(SEASONS_PREFIX + "AUTUMN");
        }

        currentWeather();
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                if(animal != null) {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

