docstring:
Check whether or not this Prey is to give birth at this step.
New births will be made into free adjacent locations.
@param newPreys A list to return newly born Preys.

function:
protected void giveSexualBirth(List<Organism> newPrey)
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        ArrayList<Location> free = new ArrayList<>(field.getFreeAdjacentLocations(location));
        Object mate1 = field.getObjectAt(location);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object mate2 = field.getObjectAt(where);
            // determines if mates are of the same species
            if (mate1.equals(mate2)){
                // determines if both mates are capable of breeding
                if (((Prey)mate1).canBreed() && ((Prey)mate2).canBreed()){
                    // determines if mates are of different genders
                    if (((Organism) mate1).getGender() != ((Organism) mate2).getGender()){
                        // only female prey can procreate
                        // prevents repeated reproduction by the same couple in same instance
                        if (((Organism) mate1).getGender() == false){ 
                            // if either are infected, they will not give birth
                            if (!(((Organism)mate1).getInfected() || ((Organism)mate2).getInfected())){
                                int births = breed();
                                for(int b = 0; b < births && free.size() > 0; b++) {
                                   if (Twill.class.isInstance(mate1)){
                                       Location loc = free.remove(0);
                                       Twill young = new Twill(false, field, loc);
                                       newPrey.add(young);}
                                   else if (Zwill.class.isInstance(mate1)){
                                       Location loc = free.remove(0);
                                       Zwill young = new Zwill(false, field, loc);
                                       newPrey.add(young);}
                                   else if (Qwill.class.isInstance(mate1)){
                                       Location loc = free.remove(0);
                                       Qwill young = new Qwill(false, field, loc);
                                       newPrey.add(young);}
                                }
                            }
                        }
                    }
                }
            }

        }
    }

