public void act(List<Animal> newFrogs)
    {
        incrementAge();
        if(isAlive()) {
            giveBirth(newFrogs);            
            // Try to move into a free location.
            Location newLocation = getField().freeAdjacentLocation(getLocation());
            if(newLocation != null) {
