public void setRandomArea(List<Location> List){
        // A HashSet that stores those locations that we have put into the list
        // and a set can reduce repetitions from happening.
        HashSet<Location> pastLocations = new HashSet<>();
        // How many we wish to iterate the process(how big the area we wish to have )
        int counter = 0;
        // Get a random depth.
        int randomX = rand.nextInt(depth);
        // Get a random width.
        int randomY = rand.nextInt(width);  
        // Get a random location in the field.
        Location randomLocation = new Location(randomX,randomY);
        // Add this location to the HashSet.
        pastLocations.add(randomLocation);
        // This moves all the adjacent locations around that random location to a list
        List<Location> l = adjacentLocations(randomLocation);
        combineList(List,l);
        while(counter  < 10){
            // This is the next location we are looking at.
            Location next = l.get(rand.nextInt(l.size()));
            // Check if we are going into a corner where we don't have adjacent locations.
            if(pastLocations.contains(next)){
                l.remove(next);
                continue;
            }else if(l.isEmpty()){
                break;
            }

            l = adjacentLocations(next);
            if(l.isEmpty()){
                break;
            }
            combineList(List,l);
            counter++;
        }
    }

