private void advect(int b, float[] d, float[] d0, float[] velocX, float[] velocY, float dt) {
        float i0, i1, j0, j1;

        float dtx = dt * (N - 2);
        float dty = dt * (N - 2);

        float s0, s1, t0, t1;
        float tmp1, tmp2, x, y;

        float Nfloat = N;
        float ifloat, jfloat;
        int i, j;

        for (j = 1, jfloat = 1; j < N - 1; j++, jfloat++) {
            for (i = 1, ifloat = 1; i < N - 1; i++, ifloat++) {
                tmp1 = dtx * velocX[weatherGrid(i, j)];
                tmp2 = dty * velocY[weatherGrid(i, j)];
                x    = ifloat - tmp1;
                y    = jfloat - tmp2;

                if (x < 0.5f) x = 0.5f;
                if (x > Nfloat + 0.5f) x = Nfloat + 0.5f;
                i0 = floor(x);
                i1 = i0 + 1.0f;
                if (y < 0.5f) y = 0.5f;
                if (y > Nfloat + 0.5f) y = Nfloat + 0.5f;
                j0 = floor(y);
                j1 = j0 + 1.0f;

                s1 = x - i0;
                s0 = 1.0f - s1;
                t1 = y - j0;
                t0 = 1.0f - t1;

                int i0i = PApplet.parseInt(i0);
                int i1i = PApplet.parseInt(i1);
                int j0i = PApplet.parseInt(j0);
                int j1i = PApplet.parseInt(j1);

                d[weatherGrid(i, j)] =
                        s0 * (t0 * d0[weatherGrid(i0i, j0i)] + t1 * d0[weatherGrid(i0i, j1i)]) +
                                s1 * (t0 * d0[weatherGrid(i1i, j0i)] + t1 * d0[weatherGrid(i1i, j1i)]);
            }
        }

        setBoundary(b, d);
    }

