private void simulateWeather() {
        Random rand = Randomizer.getRandom();
        if (rand.nextInt(5) == 0){
            weather = "rain";
        }
        else if (rand.nextInt(5) == 1){
            weather = "flood";
        }
        else if (rand.nextInt(5) == 2){
            weather = "drought";
        }
        else if (rand.nextInt(5) == 3){
