docstring:
Show the current status of the field.

@param step  Which iteration step it is.
@param field The field whose status is to be displayed.

function:
public void showStatus(int step, Field field, boolean isDay, boolean isRaining, String season) {
        if (!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        rainingLabel.setText(RAINING_PREFIX + isRaining);
        timeLabel.setText(TIME_PREFIX + (isDay ? "Day" : "Night"));
        seasonLabel.setText(SEASON_PREFIX + ": " + season);
        stats.reset();

        fieldView.preparePaint();

        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                Object plant = field.getPlantAt(row, col);
                if (animal != null) {
                    String key = animal.getClass() + (((Animal) animal).getGender() ? "female" : "male");
                    if (((Animal) animal).isInfected()) {
                        // color infected animals in red
                        fieldView.drawMark(col, row, Color.RED);
                    } else {
                        fieldView.drawMark(col, row, getColor(key));
                    }
                    stats.incrementCount(animal.getClass(), ((Animal) animal).getGender(), ((Animal) animal).isInfected());
                } else if (plant instanceof Plant) {
                    // color plants green
                    fieldView.drawMark(col, row, Color.GREEN);
                } else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText("<html>" + POPULATION_PREFIX + "<br>" + stats.getPopulationDetails(field) + "</html>");
        fieldView.repaint();
    }

