docstring:
Look for lions adjacent to the current location.
Only the first live lion is eaten.
@return Where food was found, or null if it wasn't.

function:
protected Location findFood()
    {
        if(!isFull()){
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext()) {
                Location where = it.next();
                Object animal = field.getObjectAt(where);
                //checks if there is a zebra in an adjacent location
                if(animal instanceof Zebra ) {
                    Zebra zebra = (Zebra) animal;
                    if(zebra.isAlive()) { 
                        zebra.setDead();
                        foodLevel = ZEBRA_FOOD_VALUE;
                        return where;
                    }
                }
                else if (animal instanceof Iguana) {
                    Iguana iguana = (Iguana) animal;
                    //checks if there is an iguana in an adjacent location
                    if (iguana.isAlive()) { 
                        iguana.setDead();
                        foodLevel = IGUANA_FOOD_VALUE;
                        return where;
                    }
                }
            }
        }
        return null;
    }

private boolean canBreed()
    {
        return age >= BREEDING_AGE;
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                // if the next random double that is produced by rand is less than
                // or greater to the wolf creation probability, create a wolf at that location.
                if(rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Wolf wolf = new Wolf(true, field, location);
                    actors.add(wolf);
                }
                else if(rand.nextDouble() <= HARE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hare hare = new Hare(true, field, location);
                    actors.add(hare);
                }
                else if(rand.nextDouble() <= CAT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Cat cat= new Cat(true, field, location);
                    actors.add(cat);
                }
                else if(rand.nextDouble() <= FROG_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Frog frog = new Frog(true, field, location);
                    actors.add(frog);
                }
                else if(rand.nextDouble() <= SQUIRREL_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Squirrel squirrel = new Squirrel(true, field, location);
                    actors.add(squirrel);
                }
                else if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Plant plant = new Plant(true, field, location);
                    actors.add(plant);
                }
                // else leave the location empty.
            }
        }
    }

public boolean canBreed()
    {
        //Plants behave differently, dont need mate
        if (this instanceof Plant) {
            return true;
        }

        if(!getSex() && age >= BREEDING_AGE) {
            Field field = getField();
            List<Location> free = field.adjacentLocations(getLocation());
            for(Location var : free) {
                //Check if animal in adjacent location is of the same species
                if(this.getClass().isInstance(field.getObjectAt(var))) {
                    //Casting is safe as the object is guranteed to be an animal from above
                    Animal mate = (Animal) field.getObjectAt(var);
                    //System.out.println("TRUE");
                    return mate.getSex(); //Return true if mate is male
                }
            }
        }
        //System.out.println("FALSE");
        return false;
    }

