docstring:
Show the current status of the field.
@param step Which iteration step it is.
@param field The field whose status is to be displayed.
@param time The TimeCounter object that determines time

function:
public void showStatus(int step, Field field, TimeCounter time)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();
        timeLabel.setText(TIME_OF_DAY_PREFIX + time.getPeriod());
        weatherLabel.setText(WEATHER_PREFIX + time.getWeatherObject().getCurrentWeather());
        dayLabel.setText(DAY_PREFIX + time.getDay());
        diseaseLabel.setText(DISEASE_PREFIX + time.getDiseaseObject().isDiseaseDay());
        rainInterval.setText("" + time.getWeatherObject().getRainInterval());
        diseaseInterval.setText("" + time.getDiseaseObject().getDiseaseInterval());

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object organism = field.getObjectAt(row, col);
                if(organism != null) {
                    stats.incrementCount(organism.getClass());

                    if(organism instanceof Animal) {
                        Animal animal = (Animal) organism;
                        if(animal.isDiseased()) {
                            fieldView.drawMark(col, row, Color.BLACK); //Black boxes indicate diseased animals
                        } else {
                            fieldView.drawMark(col, row, getColor(organism.getClass()));
                        }
                    } else {
                        fieldView.drawMark(col, row, getColor(organism.getClass()));
                    }

                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public void reset()
    {
        step = 0;
        animals.clear();
        populate();

        // Show the starting state in the view.
        view.showStatus(step, field, timeStatus);
    }

