private void giveBirth(List<Organism> newWolves)
    {
        boolean currentFemale = this.isFemale;
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if(organism instanceof Wolf) {
                Wolf wolf = (Wolf) organism;
                if(currentFemale != wolf.isFemale) {
                    for(int b = 0; b < births && free.size() > 0; b++) {
                        Location loc = free.remove(0);
                        Wolf young = new Wolf(false, field, loc, true);
                        newWolves.add(young);
                    }
                }
            }
        }
    }

