public boolean checkTimeIsBetween(int start, int end)
    {
        if (start < end) {
            if (start <= returnHour() && end > returnHour()){
                return true;
            }
        }else if (end < start) {
            if (start <= returnHour() || end > returnHour()) {
                return true;
            }
        }
        return false;
    }

