public void simulateOneStep()
    {
        step++;
        if (step % 4 == 0) day++;
        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>(); 
        // If it rains, all animals don't act.
        Random rand = Randomizer.getRandom();
        if(rand.nextDouble() > RAIN_PROBABILITY) {
            // Let all animals act.
            for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {

                Animal animal = it.next();

                if (!animal.hasDisease()) {
                    animal.act(newAnimals, step % 4);
                }
                else {
                    if (animal.getStepsWithDisease() <= 2)
                        animal.spreadDisease();

                    animal.incrementStepsWithDisease();    
                }

                if(! animal.isAlive()) {
                    it.remove();
                }

            }
        }
        else {
            delay(60);
        }

        field.growAllPlants();

        // Add the newly born foxes and rabbits to the main lists.
        animals.addAll(newAnimals);

        view.showStatus(step, field);
    }

public void loadPreviousStep() {
        step--;
        field.loadPrevious();
        nextEntities.push(entities);
        entities = previousEntities.pop();
        view.showStatus(step, field);
        mapView.showStatus(field);
    }

