public void act(List<Animal> newShrimp, String currentTimeOfDay, int currentTemprature)
    {
        incrementAge();
        incrementHunger();
        if(isAlive() && currentTimeOfDay != "Night") {
            if (currentTemprature<=MAX_TEMP && currentTemprature>=MIN_TEMP){
                giveBirth(newShrimp); 
            } 
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

