private boolean doesAct(Animal animal){
        boolean result = true;
        //if the weather is foggy nobody acts, return false
        if(field.getWeather().name().equals("fog")){
            return false;
        }

        //checking if an animal is acting at night or day
        if(animal.getDoesActAtNight() && field.getTime().name().equals("night") || (!animal.doesActAtNight && field.getTime().name().equals("day"))){
            result = true;
        }

        return result;
    }

