public void act(List<Organism> newAnaconda, boolean time, int weather)
    {
        double breedingProbability = BREEDING_PROBABILITY;

        age = incrementAge(MAX_AGE, age);
        foodLevel = incrementHunger(foodLevel);
        diseaseKill();
        lightningKill(weather);
        if(time) {
            if(isAlive()) {
                findPartner(null, null, null, newAnaconda, null, foodLevel, ANIMAL_FOOD_VALUE, age, BREEDING_AGE, breedingProbability, MAX_LITTER_SIZE);            
                // Move towards a source of food if found.
                Location newLocation = findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                findNewLocation(newLocation);
            }
        }
    }

