private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object occupied = field.getObjectAt(where);
            if(occupied instanceof Plant){
                Plant plant = (Plant) occupied;
                if(plant.plantIsToxic()){
                    setDead();
                }
                else{
                    foodLevel = PLANT_FOOD_VALUE + (plant.trackNutrients()/2);
                    plant.killPlant();
                }
                return where;
            }
        }
        return null;
    }

