public void act(List<FieldObjects> newOrcaes, int timeOfDay)
    {
        incrementAge();
        if(getFoodLevel() == MAX_HEALTH) { setBreedingProbability(getBreedingProbability()*2); }
        if(getAge() > MAX_AGE) {setDead();}
        incrementHunger();
        if(isAlive() && timeOfDay>6 && timeOfDay<18) {
            giveBirth(newOrcaes);            
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.

            if(newLocation != null) {
                setLocation(newLocation);
            }
        }
    }

private boolean findMate() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Badger) {
                Badger badger = (Badger) animal;

                if(isFemale() != badger.isFemale() ) { 
                   //If either animal is diseased it will spread    
                       if (badger.isDiseased()){ 
                     setDiseased();
                 }
                 if (isDiseased()){
                   badger.setDiseased(); 
                    } 

                     return true; 
                }
            }

        }
        return false;
    }

