function:
private void giveBirth(List<Creature> newGrasshopper)
    {
        // New Dragonflyes are born into adjacent locations.
        // Get a list of adjacent free locations.
        // This method is called by female fragonfly
        if(!getGender())
        {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext())
            {
                Location where = it.next();
                Object what = field.getObjectAt(where);
                if(what instanceof Grasshopper)
                {
                    Grasshopper grasshopper = (Grasshopper) what;
                    //only reproduce when two grasshopper are of opposite gender
                    if(grasshopper.getGender())
                    {
                        List<Location> free = field.getFreeAdjacentLocations(getLocation());
                        int births = breed();
                        for(int b = 0; b < births && free.size() > 0; b++) 
                        {
                            Location loc = free.remove(0);
                            Grasshopper young = new Grasshopper(false, field, loc);
                            newGrasshopper.add(young);
                            break;
                        }
                    }
                }
            }
        }
    }

