private boolean canBreed()
    {
        Field field = getField();
        SeaTurtle currentSeaTurtle = (SeaTurtle) field.getObjectAt(getLocation());
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof SeaTurtle) {
                SeaTurtle matingSeaTurtle = (SeaTurtle) animal;
                if(currentSeaTurtle.isMale != matingSeaTurtle.isMale){
                    if(currentSeaTurtle.age >= BREEDING_AGE && matingSeaTurtle.age >= BREEDING_AGE){
                        return true;
                    }
                }
            }
        }
        return false;
    }

