protected void giveBirth(List<Organism> newHerbivores)
    {
        // New termite are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        //returns a list of surrounding free locations
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        //returns a list of surrounding full locations - not necessarily animals 
        List<Location> full = field.getFullAdjacentLocations(getLocation());
        // Current class name as string

        boolean canGiveBirth = false;
        for(Iterator<Location> it = full.iterator(); it.hasNext(); ) {
            Location location = it.next();
            // gets the object at the location
            Object object = field.getObjectAt(location);

            //checks they are the same type of animals and different genders in oder to give birth
            String currentAnimal = getClass().getName();
            String neighbour = object.getClass().getName();
            if (currentAnimal.equals(neighbour)){ 
                Termite partner = (Termite) object;
                if (partner.getGender() != getGender()){
                    canGiveBirth = true;
                }
            }
        }

        // gives birth once necessary checks are approved
        if(canGiveBirth){
            int births = breed();
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Termite young = new Termite(false, field, loc);
                newHerbivores.add(young);
            }
        }
    }

public void simulateOneStep()
    {
        step++;
        //sets the weather every 2 steps.
        if(step % 2 == 0)
            setWeather();

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();

        //changes the time with each step.
        dayOrNight();

        // Let all rabbits act.
        for(Iterator<Species> it = species.iterator(); it.hasNext(); ) {
            Species specie = it.next();
            if(specie instanceof Plants)
            {
                Plants plant = (Plants) specie;
                plant.incrementAge();
            }
            else if(specie instanceof Animal)
            {
                Animal animal = (Animal) specie;
                animal.incrementAge(); 
                animal.incrementHunger();
                // Animals' behaviour varies from animal type, weather, and time.
                if((animal instanceof Lion || animal instanceof Tiger) && isDay && isClear)
                {
                    animal.act(newAnimals);
                }
                else if(animal instanceof Fox && !isDay)
                {
                    animal.act(newAnimals);
                }
                else if((animal instanceof Rabbit || animal instanceof Deer) && rand.nextInt(2) == 1 && isClear)
                {
                    animal.act(newAnimals);
                }

                if(! animal.isAlive()) 
                    it.remove();
            }
        }


        // Add the newly born foxes and rabbits to the main lists.
        species.addAll(newAnimals);
        if(!isClear)
            species.addAll(makePlants());

        //updates the simulator view labels
        view.updateWeather(weatherString());
        view.updateTime(timeString());
        view.updateInfectedSpecies(FieldStats.getInfectionNumber());
        view.showStatus(step, field);
    }

docstring:
Look for rabbits/frogs adjacent to the current location.
Only the first live rabbit/frog is eaten.

@return Where food was found, or null if it wasn't.

function:
private Location findFood() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if (animal instanceof Rabbit) {
                Rabbit rabbit = (Rabbit) animal;
                if (rabbit.isAlive() && nightTime) {
                    rabbit.setDead();
                    foodLevel = RABBIT_FOOD_VALUE;
                    return where;
                }
            }
            if (animal instanceof Frog) {
                Frog frog = (Frog) animal;
                if (frog.isAlive() && !nightTime) {
                    frog.setDead();
                    foodLevel = FROG_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

