public void act(List<Animal> newMice, boolean isDay) {
        incrementAge();
        diseaseCheck();
        incrementHunger();
        if (diseased){
            spreadDisease();
        }
        if(isAlive()) {
            //Mouse has different behavior depending on time of day.
            if (isDay) { 
                // Move towards a source of food if found.
                Location newLocation = findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }
                else {
                    // Overcrowding.
                    setDead();
                }
            } else {
                giveBirth(newMice); 
            }
        }
    }

