docstring:
Look for grass adjacent to the current location.
Only the first live piece of grass is eaten.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Iterator<Location> it = findAnimalLocation().iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Grass) {
                Grass grass = (Grass) animal;
                if(grass.isAlive()) { 
                    grass.setDead();
                    foodLevel = GRASS_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

private boolean findMate() 
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocationsVar(getLocation(), mate_distance);
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (organism instanceof Insect) {
                Insect potentialMate = (Insect) organism;
                if(potentialMate.isAlive() && potentialMate.canBreed()) {
                    if(potentialMate.getIsMale() != this.isMale) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

