This is what the Cougar does most of the time: it hunts for
pheasants and coyotes. In the process, it might breed, die of hunger, die of disease
or die of old age.
@param eventManager Object to check occuring events.
@param newCougars A list to return newly born Cougars.

function:
public void act(List<Animal> newCougars, EventManager eventManager)
    {
        checkDisease();
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            findMate(newCougars);
            // Move towards a source of food if found.
            if(!eventManager.isFoggy() && !eventManager.isDay()){
                Location newLocation = findFood();

                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    List<Location> free = getField().getFreeAdjacentLocations(getLocation());
                    for(int i = 0; i < free.size() && newLocation == null; i++){
                        if(eventManager.isHabitableLocation(free.get(i))){
                            newLocation = free.get(i);
                        }//end of if is habitable
                    }//end of for loop of free locations
                }//end of if location is null

                // See if it was possible to move.
                if(newLocation != null) {
                    setLocation(newLocation);
                }//end if new location is not null
                else {
                    // Overcrowding.
                    setDead();
                    death[1]++;
                }//end of else location is null
            }//end of if is not foggy and is not a day
        }//end of if alive
    }

private void increaseDisease(){
        diseaseLevel++;
        if(diseaseLevel>diseaseValue){
            setDead();
        }
    }

