private Location findFood() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while (it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (organism instanceof Raccoon) {
                Raccoon raccoon = (Raccoon) organism;
                if (raccoon.isAlive()) {
                    raccoon.setDead();
                    foodLevel = Math.min(foodLevel + RACCOON_FOOD_VALUE, FOOD_CAPACITY);
                    return where;
                }
            }
            if (organism instanceof Deer) {
                Deer deer = (Deer) organism;
                if (deer.isAlive()) {
                    deer.setDead();
                    foodLevel = Math.min(foodLevel + DEER_FOOD_VALUE, FOOD_CAPACITY);
                    return where;
                }
            }
        }
        return null;
    }

protected void multiplyActor(List<Actor> plants, Class plantClass){
        List<Location> free = getField().getFreeAdjacentLocations(getLocation());
        int births = multiply(plantClass);
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Actor young;
            if(plantClass == Grass.class) {
                young = new Grass(false,getField(), loc);
                plants.add(young);
            }
        }
    }

