@Override
	public List<? extends Animal> act(Weather currentWeather)
	{
		if (currentWeather == Weather.FOGGY && getCurrentViewRange() == getNormalViewRange()) {
			setCurrentViewRange(getNormalViewRange() / 2); // see half as far in fog
		}
		else if (getCurrentViewRange() != getNormalViewRange() && currentWeather != Weather.FOGGY) {
			setCurrentViewRange(getNormalViewRange());
		}

		return super.act(currentWeather);
	}

public String getPopulationDetails(Field field)
