            if(organism instanceof Frog || organism instanceof Slug) {
                Animal prey = (Animal) organism;
                if(prey.isAlive()) { 
                    if(prey instanceof Frog) {
                        prey.setDead();
                        foodlevel += FROG_FOOD_VALUE;
                        return where;
                    } 
                    else if(prey instanceof Slug) {
                        prey.setDead();
                        foodlevel += SLUG_FOOD_VALUE;
                        return where;
                    }
                }
            }
        }
        return null;
    }

protected double getBreedingProbability()
    {
        return BREEDING_PROBABILITY;
    }

private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Rabbit) {
                Rabbit rabbit = (Rabbit) animal;
                if(rabbit.isAlive()) { 
                    rabbit.setDead();
                    foodLevel = RABBIT_FOOD_VALUE;
                    return where;
                }
            }

            if(animal instanceof Squirrel) {
                Squirrel squirrel = (Squirrel) animal;
                if(squirrel.isAlive()) { 
                    squirrel.setDead();
                    foodLevel = SQUIRREL_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;

    }

public void getInfectedOfNeighbour()
    {
        Field field = getField();
        if(!isInfected()) 
        {
            Infection neighboursInfection = field.hasInfectedNeighbour(this);
            if(neighboursInfection == null) {
                return;
            }
            if(neighboursInfection.checkInfectionProbability(rand.nextDouble())) {
                this.setInfection(neighboursInfection); 
            }
        }
    }

