public void simulate(int numSteps)
    {
        // set up the step counter with time 
        int step = 1;
        while(step <= numSteps && view.isViable(field)){
            int timeTrack = step % 24;
            if(timeTrack > 0 && timeTrack <= 12){
                simulateOneDayStep();
            }
            else{
                simulateOneNightStep();
            }
            step++;
        }
    }

protected boolean isNocturnal()
    {
        return false;
    }

public void simulateOneStep()
    {
        step++;

        //change between day and night every 50 steps
        if(step%50 == 0){ dayTime = !dayTime; }
        // move slower at night
        if(!dayTime && step%2==0) {
            delay(50);
            view.showStatus(step, field, dayTime);
            return;
        }
            // Provide space for newborn actors.
            List<Actor> newActors = new ArrayList<>();
            // Let all actors act.

            for (Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
                Actor actor = it.next();
                actor.act(newActors);
                if (!actor.isAlive()) {
                    it.remove();
                }
            }
            // Add the newly born actors to the main lists.
            actors.addAll(newActors);

            view.showStatus(step, field, dayTime);
    }

