        fillDrawables();
        HashMap<Class<?>, Color> drawable = new HashMap<>(getMap());
        drawable.forEach((key,value)->
        {
            for(SimulatorView view : views)
            {
                view.setColor(key, value);
            }
        });
    }

private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        double[] probs = {FOX_CREATION_PROBABILITY,RABBIT_CREATION_PROBABILITY,DUCK_CREATION_PROBABILITY,EAGLE_CREATION_PROBABILITY,BEAR_CREATION_PROBABILITY,MOUSE_CREATION_PROBABILITY};
        double probsSum = 0;
        for (int i = 0; i < probs.length; i++) probsSum += probs[i];
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {

                double r = rand.nextDouble() * probsSum * 1.5; // 1.5 there to leave some empty space (using 1.5 means that, on average, 66% of the field is populated)
                double sum = 0;
                int i = 0;
                for (i = 0; i < probs.length; i++) {
                    sum += probs[i];
                    if (r <= sum) break;
                }
                if(i == 0) {
                    Location location = new Location(row, col);
                    Fox fox = new Fox(true, field, location);
                    animals.add(fox);
                }
                else if(i == 1) {
                    Location location = new Location(row, col);
                    Rabbit rabbit = new Rabbit(true, field, location);
                    animals.add(rabbit);
                }
                else if(i == 2) {
                    Location location = new Location(row, col);
                    Duck duck = new Duck(true, field, location);
                    animals.add(duck);
                }
                else if(i == 3) {
                    Location location = new Location(row, col);
                    Eagle eagle = new Eagle(true, field, location);
                    animals.add(eagle);
                }
                else if(i == 4) {
                    Location location = new Location(row, col);
                    Bear bear = new Bear(true, field, location);
                    animals.add(bear);
                }
                else if(i == 5) {
                    Location location = new Location(row, col);
                    Mouse mouse = new Mouse(true, field, location);
                    animals.add(mouse);
                }

                if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    field.placePlant(new Plant(),row,col);
                }
            }
        }
    }

private void spreadNewPlants(List<Actor> newPlants)
    {
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int saplings = spread();
        for(int b = 0; b < saplings && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Tree young = new Tree(false,field,loc,false);
            //Chance that young trees will get infected.
            if (rand.nextDouble()>IMMUNITY){
                young.getDiseases().add(Disease.CANKER);
            }
            newPlants.add(young);
        }
    }

