public void act(List<Animal> newSheep)
    {
        incrementAge();
        incrementHunger();
        //check whether the animal has disease.
        //after 4 days they will die.
        if(rand.nextDouble() <= getDiseaseRate() && !HasDisease) {
             HasDisease = true;
        }
        if(HasDisease){
             DaysAfterDisease ++;
             if(DaysAfterDisease >= 5){
             setDead();
             }
        }
        if(isAlive()) {
            //check whether neigbour of female has male animal and birth if so.
            //check whether neigbour of animal can be infected.
            if(gender == "female"){
                Field field = getField();
                List<Location> adjacent = field.adjacentLocations(getLocation());
                Iterator<Location> it = adjacent.iterator();
                while(it.hasNext()) {
                   Location where = it.next();
                   Object animal = field.getObjectAt(where);
                   if(animal instanceof Sheep) {
                       Sheep sheep = (Sheep) animal;
                       if(sheep.gender == "male"){
                           giveBirth(newSheep);
                       }if(HasDisease){
                           sheep.HasDisease = true;
                       }
                   }
                }
            }
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
            // No food found - try to move to a free location.
            newLocation = getField().freeAdjacentLocation(getLocation());
            }
            // See if it was possible to move.
            if(newLocation != null) {
            setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

