docstring:
Look for prey adjacent to the current location.
Only the first live prey is eaten. If the prey has a disease, it will be passed onto the predator.
@return Where food was found, or null if it wasn't.

function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if(animal instanceof Rabbit) {
                Rabbit rabbit = (Rabbit) animal;
                if(rabbit.isAlive()) { 
                    rabbit.setDead();
                    //Any diseases the prey has is passed onto the animal;
                    getDiseases().addAll(rabbit.getDiseases());
                    setFoodLevel(false,RABBIT_FOOD_VALUE);
                    return where;
                }
            }
            else if(animal instanceof Snake){
               Snake snake = (Snake) animal;
               if (snake.isAlive()){
                   snake.setDead();
                   getDiseases().addAll(snake.getDiseases());
                   setFoodLevel(false,SNAKE_FOOD_VALUE);
                   return where;
               }
            }
        }
        return null;
    }

private void eat(Entity entity) {
        if (entity instanceof Edible) {
            Edible food = (Edible)entity;
            energy += food.getNutrition();
            energy = Math.min(energy, MAX_ENERGY);
        }

        Location toMove = entity.getLocation();
        entity.die();

        field.setObjectAt(toMove, this);
        field.setObjectAt(location, null);
        setLocation(toMove);
    }

private void incrementAge() {
        age++;
        if (age > MAX_AGE) {
            setDead();
        }
    }

