function:
private Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if(organism instanceof Seal) {
                Seal seal = (Seal) organism;
                if(seal.isAlive()) { 
                    seal.setDead();
                    foodLevel = PREY_FOOD_VALUE;
                    return where;
                }
            }
            else if(organism instanceof Seabird) {
                Seabird seabird = (Seabird) organism;
                if(seabird.isAlive()) { 
                    seabird.setDead();
                    foodLevel = PREY_FOOD_VALUE;
                    return where;
                }
            }
        }
        return null;
    }

