public void showStatus(int step, Field field, String displayWeather)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + step);
        stats.reset();

        weatherLabel.setText(WEATHER_PREFIX + displayWeather);

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Animal animal = (Animal) field.getObjectAt(row, col);
                if(animal != null) {
                     Color c = getColor(animal.getClass());
                     if(animal.isInfected()){
                        stats.incrementCount(animal.getInfection().getClass());
                        c = Color.BLACK;

                    }
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, c);
                }
                else {
                    fieldView.drawMark(col, row, EMPTY_COLOR);
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

public void populate(List<LifeForm> life){
        field.clear();
        // loop through every location in the field.
        for(int row = 0; row<field.getDepth();row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                LifeForm lifeForm = null;
                if (rand.nextDouble() <= TIGER_CREATION_PROBABILITY) {
                    lifeForm = new Tiger(true, field, location);
                }
                else if (rand.nextDouble() <= LION_CREATION_PROBABILITY) {
                    lifeForm = new Lion(true, field, location);
                }
                else if (rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    lifeForm= new Plant(true, field, location);
                }
                else if (rand.nextDouble() <= HYENA_CREATION_PROBABILITY) {
                    lifeForm= new Hyena(true, field, location);
                }
                else if (rand.nextDouble() <= ANTELOPE_CREATION_PROBABILITY) {
                    lifeForm = new Antelope(true, field, location);
                }
                else if (rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
                    lifeForm =  new Zebra(true, field, location);
                }
                // check there is a lifeForm created and add to the list.
                if(lifeForm != null) {
                    life.add(lifeForm);
                }
                // else leave the location empty.
            }
        }
    }

@Override
    protected void breed(List<Actor> newActors, Entity entity) {
        if (entity instanceof Dragon) {
            Dragon dragon = (Dragon)entity;
            if (!this.sex.equals(dragon.sex) && rand.nextDouble() <= BREEDING_PROBABILITY) {
                Location loc = breedingBehaviour.act(location);
                if (loc != null) {
                    Dragon a = new Dragon(location);
                    field.setObjectAt(location, a);
                    newActors.add(a);
                    energy -= 200;
                }
            }
        } else {
            System.out.println("ERROR - breeding with different species");
        }
    }

