private Color CalculateColour(Terrain data){


        int[] Colorset = {222,192,11};
        if(data.getSnow()){
            return Color.WHITE;
        }


        switch (data.getElevation()) {


                case 1:  
                    Colorset[0]=181;
                    Colorset[1]=146;
                    Colorset[2]=4;
                    break;
                case 2:
                    Colorset[0]=222;
                    Colorset[1]=192;
                    Colorset[2]=11;
                break;
                case 3:
                    Colorset[0]=232;
                    Colorset[1]=239;
                    Colorset[2]=35;
                    break;
                default: 
                    break;
        }
            // add light to color

        for(int i=0;i< data.getLight(); i++){

            Colorset[0] *= 0.75;
            Colorset[1] *=0.75;
            Colorset[2] *=0.75;

        }


        Color test = new Color(Colorset[0],Colorset[1],Colorset[2]);

        return test;
    }

