@Override
    public void act() {
        super.act();

        int row = random.nextInt(field.getRows());
        int col = random.nextInt(field.getCols());

        Location location = new Location(row, col);
        Location temp = animal.getLocation();

        Entity e = field.getBlockAt(location).getEntity();

        if (e != null) {
            e.die();
        }

        field.setObjectAt(location, animal);
        field.setObjectAt(temp, null);

        animal.setLocation(location);
    }

private boolean canBreed()
    {
        boolean canBreed = false ; 

        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location neighbour = it.next();
            Object animal = field.getObjectAt(neighbour);
            // Checks if there is an animal of opposite gender
            if(getPartner(animal)) { 
                Animal partner = (Animal) animal;
                if(partner.getGender() != getGender() ) { 
                    canBreed = true ;
                }
                else{
                    canBreed = false ;
                }
            }
        }

        if (age >= getBreedingAge()){
            canBreed = true;
        }

        return canBreed; 
    }

