public void setBREEDING_PROBABILITY(double probability){
        this.BREEDING_PROBABILITY = probability;
    }

public void simulateOneStep()
    {
        step++;

        for(Weather weatherEvent : weather){
            weatherEvent.returnDuration();
            if(weatherEvent.isActive() == true){
                weatherEvent.effect();
            }
            else if(weatherEvent.isActive() == false){
                Random rand = Randomizer.getRandom();
                if(rand.nextDouble() <= RAIN_PROBABILITY){
                    weatherEvent.activateWeather();
                    // System.out.println("Raining again"); for testing rain
                }
                // else{System.out.println("fail"); } for testing rain
            }
        }


        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            animal.updateTime(step);
            animal.act(newAnimals);
            if(! animal.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);

        // Separate loop for plants, due to reliance on the weather
        List<Plant> newPlants = new ArrayList<>();
        // Let all plants act.
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            boolean[][] weatherMap = weather.get(0).returnWeatherMap();
            plant.act(newPlants, weatherMap);
            if(! plant.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born animals to the main lists.
        plants.addAll(newPlants);

        view.showStatus(step, field);
    }

private void findPlant(){
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object creature = field.getObjectAt(where);
            infectDisease(creature);//spread disease.
            if(creature instanceof Plant){
                Plant plant = (Plant) creature;
                if(plant.isAlive()) { 
                    plant.setDead();
                    foodLevel = PLANT_FOOD_VALUE;

                }
            }

        }

    }

