public void simulate(int numSteps)
    { 
        // reset button values
        SimulatorView.pause = false;
        SimulatorView.speed = 0;

        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            if (SimulatorView.pause == false){
                simulateOneStep(); 
                delay(SimulatorView.speed);
            }
            else{
                //pauses the program until user plays
                while (SimulatorView.pause == true){  
                    delay(10);
                }
                runLongSimulation();
            }
        }
    }

