public void simulateOneStep()
    {
        //Change weather after its length is finished.
        weatherLength--;
        if(weatherLength <= 0){
            currentWeather = weather.returnWeatherType();
            weatherLength = weather.returnWeatherLength();
        }

        // Reset the total number of infected animals in the Habitat.
        // To keep it updated.
        disease.resetInfected();

        //Calculate total number of steps.
        step++;
        //Regulate day and night.
        daySteps++;

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();
        List<Plant> newPlants = new ArrayList<>();

        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            if(animal.ifInfected()){
                animal.infected();
                if(disease.probabilityKilled()){
                    animal.setDead();
                    disease.decrementNumInfected();
                }
                disease.incrementNumInfected();
            }

            if(day){
                animal.actDay(newAnimals);
            }
            else if(!day){
                animal.actNight(newAnimals);
            }

            if(! animal.isAlive()) {
                it.remove();
            }

            animal.dicrementDisease();
        }

        //Let all plants grow and act.
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            if(day){
                plant.act(newPlants, currentWeather);
            }
            else if(!day){
                plant.act(newPlants, currentWeather);
            }

            if(! plant.isAlive()) {
                it.remove();
            }
        }

        // Change between days and nights when required.
        if (daySteps>=dayLength){
            day = !day;
            daySteps=0;
        }

        // Add the newly born plants and animals to the main lists.
        animals.addAll(newAnimals);
        plants.addAll(newPlants);
        view.showStatus(step, field, day, currentWeather, disease.getNumInfected());
    }

