public void findInfect()
    {
        Iterator<Location> it = adjacentIterator();
        while(it.hasNext()) 
        {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if( rand.nextDouble() <= ILL_PROBABILITY &&isIll() && animal instanceof Grasshopper)
            {
                Grasshopper grasshopper = (Grasshopper) animal;
                if(grasshopper.isAlive())
                {
                    grasshopper.setIll();
                }
            }
        }
    }

private boolean canBreed()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        boolean flag = false;
        while(it.hasNext()){
            Location where = it.next();
            Object organism = field.getObjectAt(where);
            if (organism instanceof Animal){
                Animal animal = (Animal) organism;
                //runs if the adjacent animal is the same species(otter), their genders are opposite and both their current age's are higher than breeding age
                if (animal instanceof Otter && (animal.getGender()^ getGender()) && animal.getAge() >= BREEDING_AGE && age >= BREEDING_AGE ){
                    flag = true;
                }
            }
        }
        return flag;
    }

