private int breed()
    {
        int births = 0;

        // Calculate breeding probability
        double breedingProbability = calculateBreedingProbability();

        if(canBreed() && (rand.nextDouble() <= breedingProbability) && match()) {
            births = rand.nextInt(MAX_LITTER_SIZE) + 1;
        }
        return births;
    }

protected boolean canBreed()
    {
        if(age < BREEDING_AGE){
            return false;
        }
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object object = field.getObjectAt(where);
            Actor actor = (Actor) object;
            // If the adjacent object is an anteater and of opposite gender then they can breed.
            if(object instanceof Anteater && actor.getGender() != gender){
                return true;
            }
        }
        return false;
    }

