public String getPopulationDetails(Field field)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field);
        }

        // Iterates over the counters and displays population information.
        for(String key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            int currentCount = info.getCount();
            buffer.append(currentCount);

            if (!info.getName().endsWith("Diseased")) {
                if (currentCount <= 1000 && currentCount > 400) {
                    buffer.append(" GOING EXTINCT ");
                } 
                if(currentCount <= 400 && currentCount > 0) {
                    buffer.append(" NEARLY EXTINCT ");
                }
                if (currentCount == 0) {

                    buffer.append(" EXTINCT ");
                }
            }
            buffer.append(' ');
        }
        return buffer.toString();
    }

