public void act(List<Actor> newTurtles, int timeOfDay,Weather weather)
    {
        increaseAge();
        incrementHunger();
        if ((timeOfDay>10 && timeOfDay<21)|| getFoodLevel()<10){
            if(isAlive()) {
                //Infect nearby turtles.
                infect();
                //Reproduce
                giveBirth(newTurtles);            
                // Try to move into a free location.
                Location newLocation = findFood();
                if(newLocation == null) { 
                    // No food found - try to move to a free location.
                    newLocation = getField().freeAdjacentLocation(getLocation());
                }
                // See if it was possible to move. If it was not the animal stays where it is.
                if(newLocation != null) {
                    setLocation(newLocation);
                }else{
                    // Overcrowding.
                    setDead();
                }

            }
        }
