public void setBlack(){
        EMPTY_COLOR = Color.black;
    }

public void simulateOneStep()
    {
        step++;

        //increment the step counter in time class
        time.incrementStep();

        view.changeDayNightColor();

        // Provide space for newborn animals and plants.
        List<Animal> newAnimals = new ArrayList<>();
        List<Plant> newPlants = new ArrayList<>();

        //changeWeather();
        checkTimeHasChanged();

        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            if (time.isDay()){
                animal.actDay(newAnimals);
            }
            else{
                animal.actNight(newAnimals);
            }

            if(! animal.isAlive()) {
                it.remove();
            }
        }

        //let all the plants act
        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = it.next();
            if (time.isDay()){
                plant.actDay(newPlants,currentWeatherMultiplier());
            }
            else{
                plant.actNight(newPlants,currentWeatherMultiplier());
            }

            if(! plant.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born animals and plants to the main lists.
        animals.addAll(newAnimals);
        plants.addAll(newPlants);

        //show the state of the view
        view.showStatus(step, field);
    }

public void simulateOneStep()
    {
        step++;

        // Provide space for newborn animals.
        List<Animal> newAnimals = new ArrayList<>();        
        // Let all animals act.
        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
            Animal animal = it.next();
            if(animal.isNocturnal() && isNight() || !animal.isNocturnal() && !isNight())
            {
                animal.act(newAnimals, weather);
                if(!animal.isAlive()) {
                    it.remove();
                }
            }
        }
        // Add the newly born animals to the main lists.
        animals.addAll(newAnimals);
        // Checks the probability of being sunny, windy or rainy.
        weather.checkWeatherProbability();

        view.showStatus(step, field, weather.weatherDescription());
    }

private void makeDisease()
    {
        if(step % DISEASE_PER_STEP == 0) {
            diseaseStartStep = step;
            if(rand.nextDouble() <= blackDeath.getProbability()) {
                isDisease = true;
                currentDisease = blackDeath;
            }
        }
        if(isDisease) {
            if(diseaseStartStep + currentDisease.getDuration() <= step) {
                isDisease = false;
            }
        }
    }

