public void showStatus(int step, Field field, Field landscape)
    {
        if(!isVisible()) {
            setVisible(true);
        }
        String timeStr;
        if (events.isDay()) //If it is day...
        {
            timeStr = "  Time: Day"; //Show this string.
        }
        else //If it is night...
        {
            timeStr = "  Time: Night"; //Show this.
        }
        stepLabel.setText(STEP_PREFIX + step + timeStr); //Sets the text for the steps
        weatherLabel.setText("WEATHER:" + events.getWeather()); //Sets the text for weather
        stats.reset();

        fieldView.preparePaint();

        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col); //The animal at that cell
                if(animal != null) { //If there is an animal...
                    stats.incrementCount(animal.getClass()); //Increase the count...
                    fieldView.drawMark(col, row, getColor(animal.getClass())); //And draw it.
                }
                else {
                    Object plant = landscape.getObjectAt(row, col);
                    if (plant != null) { //If there is a plant...
                        stats.incrementCount(plant.getClass());
                        if (plant instanceof MagicMushroom) //Which is a magic mushroom...
                        {
                            fieldView.drawMark(col, row, Color.YELLOW); //Draw it
                        }
                        else //Otherwise...
                        {
                            fieldView.drawMark(col, row, Color.MAGENTA); //Draw a mushroom
                        }
                    }
                    else //If thecell is empty
                    {
                        fieldView.drawMark(col, row, EMPTY_COLOR); //Draw nothing
                    }
                }
            }
        }
        stats.countFinished();

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

