public void incrementCount(Object livingOrganism)
    {
        if(livingOrganism instanceof Animal) {
            Class animalClass = livingOrganism.getClass();
            Counter count = animalCounters.get(animalClass);
            if(count == null) {
                // We do not have a counter for this animal yet.
                // Create one.
                count = new Counter(animalClass.getName());
                animalCounters.put(animalClass, count);
            }
            count.increment();
        }

        if(livingOrganism instanceof Plant) {
            Class plantClass = livingOrganism.getClass();
            Counter count = plantCounters.get(plantClass);
            if(count == null) {
                // We do not have a counter for this plant yet.
                // Create one.
                count = new Counter(plantClass.getName());
                plantCounters.put(plantClass, count);
            }
            count.increment();
        }
    }

