public void act(List<Animal> newHyenas, Field grass)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            // Check all adjacent locations for hyenaes of the opposite sex
            // Within a certain block radius
            Boolean breed = false;
            List<Location> adjacent = getField().adjacentLocationsRadius(getLocation(), 20);
            Iterator<Location> it = adjacent.iterator();
            breed = false;
            while (it.hasNext() && breed != true) {
                Object animal = getField().getObjectAt(it.next());
                if(animal instanceof Hyena) {
                    Hyena adjHyena = (Hyena) animal;
                    if (adjHyena.getSex() != getSex()) {
                        breed = true;
                    }
                }
            }
            // Breed if there are sheeps of the opposite sex at adjacent cells
            if (breed) {
                giveBirth(newHyenas); 
            }
            // Move towards a source of food if found.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            mutate();
            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

