private boolean canBreed()
    {
        Field field = getField();
        List<Location> occupied = field.adjacentLocations(getLocation());
        for(int i = 0 ; i<occupied.size() ; i++){
            Object aroundAni = field.getObjectAt(occupied.get(i));
            if(aroundAni instanceof Wolf) {
                Wolf wolf = (Wolf) aroundAni;
                if(wolf.getGender() == this.getGender()){  //check gender around
                    return false;        
                }
                else{
                    if(age >= BREEDING_AGE){
                        return true;
                    }                 
                }
            }
        }
        return false;
    }

