public boolean isMate(Object object) {
        boolean result = false;

        if (object instanceof Lion) {
            Lion lion = (Lion) object;

            if (lion.isAlive() && lion.canBreed(BREEDING_AGE) && !(lion.getGender().getName().equals(this.getGender().getName()))) {
                result = true;
            }
        }

        return  result;
    }

