private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Wolf wolf = new Wolf(true, field, location);
                    animals.add(wolf);
                }
                else if(rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Deer deer = new Deer(true, field, location);
                    animals.add(deer);
                }
                else if(rand.nextDouble() <= SNAKE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Snake snake = new Snake(true, field, location);
                    animals.add(snake);
                    // else leave the location empty.
                }
                else if(rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Mouse mouse = new Mouse(true, field, location);
                    animals.add(mouse);
                    // else leave the location empty.
                }
                else if(rand.nextDouble() <= HAWK_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hawk hawk = new Hawk(true, field, location);
                    animals.add(hawk);
                    // else leave the location empty.
                } else if(rand.nextDouble() <= GRASS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Grass grass = new Grass(field, location);
                    plants.add(grass);
                }
            }
        }
    }

private void giveBirth(List<Organism> newMices)
    {
         // New Mices are born into adjacent locations.
         // Get a list of adjacent free locations.
         Mice mate = null;

         Field field = getField();
         List<Object> potentialMate = field.getMate(getLocation());
         for(Object next : potentialMate){
           if (next.getClass().getName().equals("Mice"))
                {
                    Mice temp = (Mice) next;

                    if (temp.getGender() == 0)
                    {
                       mate = temp;
                    }
                }
            }

          if (mate != null){
          List<Location> free = field.getFreeAdjacentLocations(getLocation());
          int births = breed();

          for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Mice young = new Mice(false, field, loc);
            newMices.add(young);
          }
         }
    }

