    {
        return age >= BREEDING_AGE;
    }

private void populate() {
    Random rand = Randomizer.getRandom();
    field.clear();
    SpeciesCreation creation =
        new SpeciesCreation() {

          @Override
          public void createRabbit() {
            for (int row = 0; row < field.getDepth(); row++) {
              for (int col = 0; col < field.getWidth(); col++) {
                if (rand.nextDouble() <= RABBIT_CREATION_PROBABILITY) {
                  Location location = new Location(row, col);
                  Rabbit rabbit = new Rabbit(true, field, location);
                  animals.add(rabbit);
                }
              }
            }
          }

          @Override
          public void createFox() {
            for (int row = 0; row < field.getDepth(); row++) {
              for (int col = 0; col < field.getWidth(); col++) {
                if (rand.nextDouble() <= FOX_CREATION_PROBABILITY) {
                  Location location = new Location(row, col);
                  Fox fox = new Fox(true, field, location);
                  animals.add(fox);
                }
              }
            }
          }

          @Override
          public void createWolf() {
            for (int row = 0; row < field.getDepth(); row++) {
              for (int col = 0; col < field.getWidth(); col++) {
                if (rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
                  Location location = new Location(row, col);
                  Wolf wolf = new Wolf(true, field, location);
                  animals.add(wolf);
                }
              }
            }
          }

          @Override
          public void createDeer() {
            for (int row = 0; row < field.getDepth(); row++) {
              for (int col = 0; col < field.getWidth(); col++) {
                if (rand.nextDouble() <= DEER_CREATION_PROBABILITY) {
                  Location location = new Location(row, col);
                  Deer deer = new Deer(true, field, location);
                  animals.add(deer);
                }
              }
            }
          }

          @Override
          public void createPlant() {
            for (int row = 0; row < field.getDepth(); row++) {
              for (int col = 0; col < field.getWidth(); col++) {
                if (rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                  Location location = new Location(row, col);
                  Plant plant = new Plant(field, location);
                  plants.add(plant);
                }
              }
            }
          }

          @Override
          public void createDisease() {
            for (int row = 0; row < field.getDepth(); row++) {
              for (int col = 0; col < field.getWidth(); col++) {
                if (rand.nextDouble() <= DISEASE_CREATION_PROBABILITY) {
                  Location location = new Location(row, col);
                  Disease disease = new Disease(field, location);
                  diseases.add(disease);
                }
              }
            }
          }
        };
    creation.createWolf();
    creation.createRabbit();
    creation.createPlant();
    creation.createFox();
    creation.createDisease();
    creation.createDeer();
  }

docstring:
Increase this animal's food level (Feed this animal)
@param inc How much to increase the animal's food
level by (usually the food value of the entity eaten by the animal)

function:
private void increaseFoodLevel(int inc)
	{
		foodLevel += inc;
		if (foodLevel > maxFoodLevel) {
			foodLevel = maxFoodLevel;
		}
	}
